package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonSyntaxException;
import com.fatelocked.rules.ChunkPermissionSnapshot;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RulesSnapshot;
import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;
import java.util.zip.GZIPOutputStream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class FateLockedBundleTest
{
    private FateLockedBundle fixture(String name) throws Exception
    {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(name))
        {
            assertNotNull("missing fixture " + name, in);
            String json = new String(in.readAllBytes(), StandardCharsets.UTF_8);
            return FateLockedBundle.loadFromJson(new Gson(), json);
        }
    }

    @Test
    public void legacyBundleStillUsesContinentUnlocks() throws Exception
    {
        FateLockedBundle bundle = fixture("bundles/v1-legacy.json");

        assertEquals(FateLockedBundle.LockState.UNLOCKED,
            bundle.lockStateAt(new CanonicalChunk(46, 52)));
    }

    @Test
    public void standardBundleUsesSubAreaAndBankState() throws Exception
    {
        FateLockedBundle bundle = fixture("bundles/v3-standard.json");

        assertEquals(FateLockedBundle.LockState.UNLOCKED,
            bundle.lockStateAt(new CanonicalChunk(46, 52)));
        assertTrue(bundle.isBankUnlocked(new CanonicalChunk(46, 52)));
        assertEquals(FateLockedBundle.LockState.UNLOCKED,
            bundle.lockStateAt(new CanonicalChunk(50, 50)));
    }

    @Test
    public void emptyChunkedBundleStillUnlocksTheStartChunk() throws Exception
    {
        FateLockedBundle bundle = fixture("bundles/v3-chunked-empty.json");

        assertTrue(bundle.isChunkedBundle());
        assertEquals(FateLockedBundle.LockState.UNLOCKED,
            bundle.lockStateAt(FateLockedBundle.CHUNKED_START));
    }

    @Test
    public void parsesV4PermissionRows() throws Exception
    {
        FateLockedBundle bundle = fixture("bundles/v4-rules.json");
        ChunkPermissionSnapshot chunk = bundle
            .permissionsAt(new CanonicalChunk(50, 50)).get();

        assertEquals(PermissionStatus.ALLOWED, chunk.getEntry());
        assertEquals("Lumbridge General Store",
            chunk.getCategories().get("SHOPS").get(0).getName());
        assertTrue(!bundle.isLegacyRules());
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsFutureBundle() throws Exception
    {
        fixture("bundles/v5-future.json");
    }
    /** The web app's compressed form: "FLGZ:" + base64 of the gzip bytes. */
    private static String compressed(byte[] json) throws Exception
    {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (GZIPOutputStream gzip = new GZIPOutputStream(bytes))
        {
            gzip.write(json);
        }
        return "FLGZ:" + Base64.getEncoder().encodeToString(bytes.toByteArray());
    }

    private static byte[] fixtureBytes(String name) throws Exception
    {
        try (InputStream in = FateLockedBundleTest.class.getClassLoader().getResourceAsStream(name))
        {
            assertNotNull("missing fixture " + name, in);
            return in.readAllBytes();
        }
    }

    private static byte[] spaces(int count)
    {
        byte[] json = new byte[count];
        Arrays.fill(json, (byte) ' ');
        return json;
    }

    @Test
    public void readsTheCompressedFormLikePlainJson() throws Exception
    {
        FateLockedBundle bundle = FateLockedBundle.loadFromJson(new Gson(),
            compressed(fixtureBytes("bundles/v3-standard.json")));

        assertEquals(FateLockedBundle.LockState.UNLOCKED,
            bundle.lockStateAt(new CanonicalChunk(46, 52)));
        assertTrue(bundle.isBankUnlocked(new CanonicalChunk(46, 52)));
    }

    @Test
    public void acceptsACompressedBundleUpToTheInflatedLimit() throws Exception
    {
        // A real bundle padded with trailing whitespace to exactly the limit.
        byte[] json = fixtureBytes("bundles/v3-standard.json");
        byte[] padded = Arrays.copyOf(json, FateLockedBundle.MAX_INFLATED_BYTES);
        Arrays.fill(padded, json.length, padded.length, (byte) ' ');

        FateLockedBundle bundle = FateLockedBundle.loadFromJson(new Gson(), compressed(padded));

        assertEquals(FateLockedBundle.LockState.UNLOCKED,
            bundle.lockStateAt(new CanonicalChunk(46, 52)));
    }

    @Test
    public void refusesTextThatIsNotABundle()
    {
        // Each of these used to parse as an empty bundle and wipe the rules.
        for (String notABundle : new String[] {
            null, "", "   ", "null", "{}", "{\"version\":3}", "{\"version\":3,\"chunks\":{}}",
            "{\"profile\":\"x\"}" })
        {
            try
            {
                FateLockedBundle.loadFromJson(new Gson(), notABundle);
                fail("expected " + notABundle + " to be refused");
            }
            catch (JsonSyntaxException expected)
            {
                assertTrue(expected.getMessage(), expected.getMessage().contains("no chunk data"));
            }
        }
    }

    @Test
    public void readsBundleFilesAsUtf8() throws Exception
    {
        String json = new String(fixtureBytes("bundles/v3-standard.json"), StandardCharsets.UTF_8)
            .replaceFirst("\\{", "{\"profileName\":\"Mid·Run\",");
        java.nio.file.Path file = java.nio.file.Files.createTempFile("fate-locked-bundle", ".json");
        try
        {
            java.nio.file.Files.write(file, json.getBytes(StandardCharsets.UTF_8));
            assertEquals("Mid·Run",
                FateLockedBundle.loadFromFile(new Gson(), file).getProfileName());
        }
        finally
        {
            java.nio.file.Files.deleteIfExists(file);
        }
    }

    @Test
    public void exposesWhenTheTrackerExportedTheRules() throws Exception
    {
        assertEquals(java.time.Instant.parse("2026-07-24T10:00:00Z"),
            fixture("bundles/v4-rules.json").exportedAt());
        assertEquals(null, fixture("bundles/v3-standard.json").exportedAt());

        com.google.gson.JsonObject root = new Gson().fromJson(
            new String(fixtureBytes("bundles/v4-rules.json"), StandardCharsets.UTF_8),
            com.google.gson.JsonObject.class);
        root.getAsJsonObject("rules").addProperty("exportedAt", "yesterday");
        assertEquals(null, FateLockedBundle.loadFromJson(new Gson(), root.toString()).exportedAt());
    }

    @Test
    public void refusesACompressedBundleThatInflatesPastTheLimit() throws Exception
    {
        // A few KiB of gzip that would inflate one byte past the limit.
        String payload = compressed(spaces(FateLockedBundle.MAX_INFLATED_BYTES + 1));
        assertTrue("payload should be small", payload.length() < 64 * 1024);

        try
        {
            FateLockedBundle.loadFromJson(new Gson(), payload);
            fail("expected an oversized bundle to be refused");
        }
        catch (JsonSyntaxException expected)
        {
            assertTrue(expected.getMessage(), expected.getMessage().contains("larger than 8 MiB"));
        }
    }

    /**
     * E7 (R6): Stage 2 rules name the mode's free areas under their
     * capability, ahead of the root copy; the items that aren't names are
     * skipped, and an empty list frees nothing.
     */
    @Test
    public void theRulesNameTheFreeAreasUnderTheirCapability() throws Exception
    {
        JsonArray named = strings("Tutorial Island");
        named.add(7);
        FateLockedBundle tracker = withFreeAreas(strings("someFutureSection", "freeAreas"), named);
        assertTrue(tracker.isUnlocked("Tutorial Island"));
        assertFalse("the root copy is the older one", tracker.isUnlocked("Karamja"));

        FateLockedBundle none = withFreeAreas(strings("freeAreas"), new JsonArray());
        assertFalse(none.isUnlocked("Tutorial Island"));
        assertFalse(none.isUnlocked("Karamja"));
    }

    /** Without the capability, or as anything but a list, the root copy still decides. */
    @Test
    public void olderRulesKeepTheRootFreeAreas() throws Exception
    {
        for (FateLockedBundle older : Arrays.asList(
            withFreeAreas(null, strings("Tutorial Island")),
            withFreeAreas(strings("banks"), strings("Tutorial Island")),
            withFreeAreas(new JsonPrimitive("freeAreas"), strings("Tutorial Island")),
            withFreeAreas(strings("freeAreas"), new JsonPrimitive("Tutorial Island")),
            withFreeAreas(strings("freeAreas"), null)))
        {
            assertTrue(older.isUnlocked("Karamja"));
            assertFalse(older.isUnlocked("Tutorial Island"));
        }
    }

    /**
     * E7 (R15): rulesVersion is informational. A newer tracker's rules, with
     * a later version and a section this plugin doesn't know, give the same
     * answers everywhere the golden pins one.
     */
    @Test
    public void aLaterRulesVersionAndAnUnknownSectionKeepTheAnswers() throws Exception
    {
        Gson gson = new Gson();
        JsonObject wire = gson.fromJson(GoldenBundleContractTest.gunzip(
            GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz")), JsonObject.class);
        FateLockedBundle today = FateLockedBundle.loadFromJson(gson, wire.toString());
        JsonObject rules = wire.getAsJsonObject("rules");
        rules.addProperty("rulesVersion", "2");
        rules.getAsJsonArray("capabilities").add("someFutureSection");
        rules.add("someFutureSection", gson.fromJson("{\"50,50\": \"LOCKED\"}", JsonObject.class));
        FateLockedBundle newer = FateLockedBundle.loadFromJson(gson, wire.toString());

        assertEquals("1", today.getRulesVersion());
        assertEquals("2", newer.getRulesVersion());
        DecisionService before = DecisionService.create(RulesSnapshot.of(today), null, null);
        DecisionService after = DecisionService.create(RulesSnapshot.of(newer), null, null);
        JsonObject expected = GoldenBundleContractTest.json("vanilla-mid.expect.json");
        assertTrue(expected.getAsJsonObject("chunks").size() > 100);
        for (String key : expected.getAsJsonObject("chunks").keySet())
        {
            CanonicalChunk chunk = GoldenBundleContractTest.chunk(key);
            assertEquals(key, today.lockStateAt(chunk), newer.lockStateAt(chunk));
            assertEquals(key, before.chunk(chunk), after.chunk(chunk));
        }
        for (String area : expected.getAsJsonObject("areas").keySet())
        {
            assertEquals(area, today.isUnlocked(area), newer.isUnlocked(area));
        }
        assertEquals(PermissionStatus.ALLOWED, after.chunk(new CanonicalChunk(50, 50)).getStatus());
    }

    /** The v4 fixture with root freeAreas [Karamja], and these capabilities and rules freeAreas (none when null). */
    private FateLockedBundle withFreeAreas(JsonElement capabilities, JsonElement named) throws Exception
    {
        JsonObject root = new Gson().fromJson(
            new String(fixtureBytes("bundles/v4-rules.json"), StandardCharsets.UTF_8), JsonObject.class);
        root.add("freeAreas", strings("Karamja"));
        JsonObject rules = root.getAsJsonObject("rules");
        if (capabilities != null) rules.add("capabilities", capabilities);
        if (named != null) rules.add("freeAreas", named);
        return FateLockedBundle.loadFromJson(new Gson(), root.toString());
    }

    private static JsonArray strings(String... values)
    {
        JsonArray array = new JsonArray();
        for (String value : values) array.add(value);
        return array;
    }
}

package com.fatelocked;

import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;

import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Menu clicks as RuneLite gives them (see MenuFactsTest), for tests that go
 * through the plugin: the spellbook, inventory and worn items are interface
 * components, and a spell's book comes from the client's SPELLBOOK varbit,
 * which a mocked client reads as 0, the standard book.
 */
public final class TravelClicks
{
    private TravelClicks()
    {
    }

    /** Cast on a spell in the spellbook. */
    public static MenuOptionClicked cast(String spell)
    {
        return spell("Cast", spell);
    }

    /** An option on a spell in the spellbook. */
    public static MenuOptionClicked spell(String option, String spell)
    {
        return widget(option, "<col=00ff00>" + spell + "</col>", InterfaceID.MAGIC_SPELLBOOK, -1);
    }

    /** An option on an item in the inventory. */
    public static MenuOptionClicked item(int itemId, String option, String name)
    {
        return widget(option, "<col=ff9040>" + name + "</col>", InterfaceID.INVENTORY, itemId);
    }

    public static MenuOptionClicked npc(int npcId, String option, String name)
    {
        MenuOptionClicked click = click(MenuAction.NPC_FIRST_OPTION, option, name);
        NPC npc = mock(NPC.class);
        when(npc.getId()).thenReturn(npcId);
        when(click.getMenuEntry().getNpc()).thenReturn(npc);
        return click;
    }

    public static MenuOptionClicked object(int objectId, String option, String name)
    {
        MenuOptionClicked click = click(MenuAction.GAME_OBJECT_FIRST_OPTION, option, name);
        when(click.getMenuEntry().getIdentifier()).thenReturn(objectId);
        return click;
    }

    /** A click whose entry keeps the target set on it, as a menu tag sets it. */
    public static MenuOptionClicked click(MenuAction type, String option, String target)
    {
        MenuEntry entry = mock(MenuEntry.class);
        String[] current = { target };
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenAnswer(call -> current[0]);
        doAnswer(call -> {
            current[0] = call.getArgument(0);
            return entry;
        }).when(entry).setTarget(anyString());
        when(entry.getType()).thenReturn(type);
        when(entry.getItemId()).thenReturn(-1);
        MenuOptionClicked click = mock(MenuOptionClicked.class);
        when(click.getMenuEntry()).thenReturn(entry);
        return click;
    }

    private static MenuOptionClicked widget(String option, String target, int group, int itemId)
    {
        MenuOptionClicked click = click(MenuAction.CC_OP, option, target);
        when(click.getMenuEntry().getParam1()).thenReturn(WidgetUtil.packComponentId(group, 1));
        when(click.getMenuEntry().getItemId()).thenReturn(itemId);
        return click;
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.EventListener;
import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import okhttp3.mockwebserver.SocketPolicy;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TrackerConnectionControllerTest
{
    private static final String INITIAL_CODE =
        "0123456789abcdef0123456789abcdef";

    private final Gson gson = new Gson();
    private final Map<String, String> configuration =
        new ConcurrentHashMap<>();
    private final List<String> unsetKeys = new CopyOnWriteArrayList<>();
    private final List<Request> pluginRequests = new CopyOnWriteArrayList<>();
    /** Every relay request, and those that have ended, however they ended. */
    private final List<Call> sentCalls = new CopyOnWriteArrayList<>();
    private final List<Call> endedCalls = new CopyOnWriteArrayList<>();
    private final RecordingDispatcher dispatcher =
        new RecordingDispatcher();
    private final ConcurrentLinkedQueue<Runnable> clientTasks =
        dispatcher.tasks();
    private final RecordingImporter importer = new RecordingImporter();
    private final RecordingListener listener = new RecordingListener();
    private final MutableClock clock = new MutableClock(
        Instant.parse("2026-07-27T10:00:00Z"));

    private MockWebServer server;
    private OkHttpClient http;
    private TrackerConnectionSettings settings;
    private TrackerConnectionController controller;

    @Before
    public void setUp() throws Exception
    {
        configuration.put(TrackerConnectionSettings.PAIRING_CODE_KEY,
            INITIAL_CODE);
        configuration.put(FateLockedConfig.NETWORK_ACCESS_KEY, "true");
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString()))
            .thenAnswer(invocation ->
                configuration.get(invocation.getArgument(1)));
        doAnswer(invocation -> {
            configuration.put(
                invocation.getArgument(1), invocation.getArgument(2));
            return null;
        }).when(configManager).setConfiguration(
            anyString(), anyString(), anyString());
        doAnswer(invocation -> {
            String key = invocation.getArgument(1);
            configuration.remove(key);
            unsetKeys.add(key);
            return null;
        }).when(configManager).unsetConfiguration(anyString(), anyString());
        settings = new TrackerConnectionSettings(configManager);

        server = new MockWebServer();
        server.start();
        Interceptor redirectToServer = chain -> {
            Request original = chain.request();
            pluginRequests.add(original);
            return chain.proceed(original.newBuilder()
                .url(server.url(original.url().encodedPath()))
                .build());
        };
        http = new OkHttpClient.Builder()
            .addInterceptor(redirectToServer)
            .eventListenerFactory(call -> {
                sentCalls.add(call);
                return new EventListener()
                {
                    @Override
                    public void callEnd(Call ended)
                    {
                        endedCalls.add(ended);
                    }

                    @Override
                    public void callFailed(Call failed, IOException error)
                    {
                        endedCalls.add(failed);
                    }
                };
            })
            .build();
        controller = new TrackerConnectionController(
            http, gson, settings, clock, dispatcher,
            importer, listener);
    }

    @After
    public void tearDown() throws Exception
    {
        controller.stop();
        server.shutdown();
    }

    @Test
    public void savedPairingAndLegacyOptInCannotSendRequestsWithoutNewConsent()
        throws Exception
    {
        configuration.remove(FateLockedConfig.NETWORK_ACCESS_KEY);
        configuration.put("onlineSync", "true");

        controller.poll();
        controller.pollIfDue();

        assertNull(server.takeRequest(200, TimeUnit.MILLISECONDS));
        assertTrue(pluginRequests.isEmpty());
        assertEquals(INITIAL_CODE, settings.pairingCode());
        assertEquals(TrackerConnectionState.DISCONNECTED, controller.snapshot().getState());
    }

    @Test(expected = IllegalStateException.class)
    public void pairingCannotBypassConsent()
    {
        configuration.remove(FateLockedConfig.NETWORK_ACCESS_KEY);
        controller.beginPairing();
    }

    @Test
    public void aStoppedControllerRefusesToPair() throws Exception
    {
        controller.stop();

        // A Connect queued before the plugin was turned off runs after it.
        assertThrows(IllegalStateException.class, controller::beginPairing);
        controller.pollIfDue();

        assertEquals(INITIAL_CODE, settings.pairingCode());
        assertEquals(TrackerConnectionState.DISCONNECTED,
            controller.snapshot().getState());
        assertNull(server.takeRequest(200, TimeUnit.MILLISECONDS));
        assertTrue(pluginRequests.isEmpty());
    }

    @Test
    public void acceptingConsentResumesAnExistingPairing() throws Exception
    {
        configuration.remove(FateLockedConfig.NETWORK_ACCESS_KEY);
        controller.pollIfDue();
        settings.allowNetworkAccess();
        controller.networkAccessChanged();
        server.enqueue(relayResponse(6, validV4Payload(), "\"6\""));

        controller.pollIfDue();
        assertEquals("/r/" + INITIAL_CODE, takeRelay().getPath());
        waitFor(() -> clientTasks.size() == 1);
        runClientTasks();

        assertEquals(TrackerConnectionState.CONNECTED, controller.snapshot().getState());
    }

    @Test
    public void revokingConsentBlocksRequestsAndDiscardsQueuedImports() throws Exception
    {
        server.enqueue(relayResponse(6, validV4Payload(), "\"6\""));
        controller.poll();
        takeRelay();
        waitFor(() -> clientTasks.size() == 1);

        configuration.put(FateLockedConfig.NETWORK_ACCESS_KEY, "false");
        controller.networkAccessChanged();
        controller.poll();
        controller.pollIfDue();
        // Re-enabling must not revive a response from before revocation.
        settings.allowNetworkAccess();
        controller.networkAccessChanged();
        runClientTasks();

        assertNull(server.takeRequest(200, TimeUnit.MILLISECONDS));
        assertTrue(importer.acceptedPayloads().isEmpty());
        assertNull(controller.snapshot().getLastSync());
        assertNull(controller.snapshot().getAcceptedVersion());
    }

    @Test
    public void aFirstPairingSavesItsCodeAtOnceAndReturnsTheBrowserUrl()
    {
        configuration.remove(TrackerConnectionSettings.PAIRING_CODE_KEY);

        String url = controller.beginPairing();

        assertTrue(settings.pairingCode().matches("[0-9a-f]{32}"));
        assertEquals(PairingSupport.trackerPairingUrl(
            settings.pairingCode()), url);
        assertEquals(SyncReason.CONFIRM_IN_BROWSER, listener.last().getReason());
        assertNull(listener.last().getAcceptedVersion());
        assertNull(listener.last().getLastSync());
        assertEquals(0, importer.acceptedPayloads().size());
        assertEquals(0, clientTasks.size());
    }

    @Test
    public void connectingAgainDuringAFirstPairingStartsOver()
    {
        configuration.remove(TrackerConnectionSettings.PAIRING_CODE_KEY);
        controller.beginPairing();
        String first = settings.pairingCode();

        // Its code has never worked, so there is nothing to keep.
        controller.beginPairing();

        assertNotEquals(first, settings.pairingCode());
        assertEquals(settings.pairingCode(), controller.activeCode());
        assertEquals(SyncReason.CONFIRM_IN_BROWSER, controller.snapshot().getReason());
    }

    @Test
    public void aCodeTheOwnerDisconnectedSaysSoAndConnectingPairsAfresh() throws Exception
    {
        connect(5, "\"5\"");
        server.enqueue(new MockResponse().setResponseCode(404)
            .addHeader("Content-Type", "application/json")
            .setBody("{\"gone\":true}"));
        controller.poll();
        takeRelay();
        waitFor(() -> !controller.pollInFlight());

        assertEquals(SyncReason.GONE, controller.snapshot().getReason());
        assertNull(controller.snapshot().getAcceptedVersion());

        // Nothing to keep: the new pairing replaces the gone one at once.
        controller.beginPairing();
        assertNotEquals(INITIAL_CODE, settings.pairingCode());
        assertEquals(settings.pairingCode(), controller.activeCode());
    }

    @Test
    public void aPlain404IsNotGone() throws Exception
    {
        connect(5, "\"5\"");
        server.enqueue(new MockResponse().setResponseCode(404).setBody("<html>Not Found</html>"));
        controller.poll();
        takeRelay();
        waitFor(() -> !controller.pollInFlight());

        assertEquals(SyncReason.NO_RECENT_UPDATE, controller.snapshot().getReason());
    }

    @Test
    public void theStatusCarriesOnlyTheEndOfTheCodeInUse() throws Exception
    {
        assertEquals("cdef", controller.snapshot().getPairingEnding());

        connect(5, "\"5\"");
        controller.beginPairing();
        String newCode = controller.activeCode();

        // A re-pairing shows the new code's end, as the browser's dialog does.
        assertEquals(newCode.substring(28), controller.snapshot().getPairingEnding());
    }

    @Test
    public void rePairingKeepsTheWorkingPairingUntilTheNewOneDelivers() throws Exception
    {
        connect(5, "\"5\"");
        Instant syncedAt = controller.snapshot().getLastSync();

        String url = controller.beginPairing();
        String newCode = controller.activeCode();

        // The saved pairing, and the rules' sync time, stay until the new one delivers.
        assertNotEquals(INITIAL_CODE, newCode);
        assertEquals(PairingSupport.trackerPairingUrl(newCode), url);
        assertEquals(INITIAL_CODE, settings.pairingCode());
        assertEquals(SyncReason.CONFIRM_REPAIR, controller.snapshot().getReason());
        assertEquals(syncedAt, controller.snapshot().getLastSync());

        // The browser hasn't published yet.
        server.enqueue(new MockResponse().setResponseCode(404));
        controller.pollIfDue();
        assertEquals("/r/" + newCode, takeRelay().getPath());
        waitFor(() -> !controller.pollInFlight());
        assertEquals(SyncReason.CONFIRM_REPAIR, controller.snapshot().getReason());
        assertEquals(INITIAL_CODE, settings.pairingCode());

        // Now it has.
        clock.advanceSeconds(SyncMachine.WAITING_POLL_SECONDS);
        server.enqueue(relayResponse(7, validV4Payload(), "\"7\""));
        controller.pollIfDue();
        assertEquals("/r/" + newCode, takeRelay().getPath());
        waitFor(() -> clientTasks.size() == 1);
        runClientTasks();

        assertEquals(TrackerConnectionState.CONNECTED, controller.snapshot().getState());
