 * say what the sidebar says. On a golden bundle a Guard in a locked chunk is
 * tagged, while not ready, allowed and ocean chunks aren't; another
 * character, or nobody logged in, sees no tags; an older export tags as it
 * did.
 */
public class MenuTagTest
{
    private static final Gson GSON = new Gson();
    private static final String TAG = " <col=f87171>(Locked)</col>";
    /** vanilla-mid: Seers' Village is LOCKED, Glarial's Tomb NOT_READY, Lumbridge Castle ALLOWED. */
    private static final CanonicalChunk SEERS = new CanonicalChunk(42, 54);
    private static final CanonicalChunk GLARIALS_TOMB = new CanonicalChunk(39, 53);
    private static final CanonicalChunk LUMBRIDGE = new CanonicalChunk(50, 50);
    /** Sea west of Kandarin: in the tracker's map, not in its rules (R4). */
    private static final CanonicalChunk OCEAN = new CanonicalChunk(40, 41);
    /** In Zeah: LOCKED in the rules, but outside the areas older exports carry. */
    private static final CanonicalChunk ZEAH = new CanonicalChunk(16, 44);

    private final FateLockedPlugin plugin = new FateLockedPlugin();
    private final FateLockedConfig config = mock(FateLockedConfig.class);
    private final Client client = mock(Client.class);

    @Before
    public void setUp() throws Exception
    {
        when(config.tagLockedOptions()).thenReturn(true);
        set("config", config);
        set("client", client);
    }

    @Test
    public void aGoldenNpcInALockedChunkIsTagged() throws Exception
    {
        FateLockedBundle mid = golden("vanilla-mid");
        assertEquals(PermissionStatus.LOCKED, mid.permissionsAt(SEERS).get().getEntry());
        assertEquals(PermissionStatus.NOT_READY, mid.permissionsAt(GLARIALS_TOMB).get().getEntry());
        assertEquals(PermissionStatus.ALLOWED, mid.permissionsAt(LUMBRIDGE).get().getEntry());
        assertEquals(false, mid.permissionsAt(OCEAN).isPresent());
        assertEquals(PermissionStatus.LOCKED, mid.permissionsAt(ZEAH).get().getEntry());
        assertEquals(FateLockedBundle.LockState.UNAUTHORED, mid.lockStateAt(ZEAH));
        playing(mid, "Iron Example");

        assertEquals("Guard" + TAG, npcTarget(SEERS));
        assertEquals("the rules decide, not the old areas", "Guard" + TAG, npcTarget(ZEAH));
        assertEquals("NOT_READY never tags", "Guard", npcTarget(GLARIALS_TOMB));
        assertEquals("Guard", npcTarget(LUMBRIDGE));
        assertEquals("the sea is locked without Sailing (R1)", "Guard" + TAG, npcTarget(OCEAN));
    }

    /** E1: the tag is the word players read everywhere, and every reader of menu text removes it. */
    @Test
    public void theTagIsTheWordPlayersRead()
    {
        assertEquals(com.fatelocked.ui.Terms.LOCKED_TAG, " " + MenuFacts.LOCKED_MARK);
    }

    /** E1: the tag takes the palette's locked colour, including a player's own. */
    @Test
    public void theTagTakesThePalettesLockedColour() throws Exception
    {
        playing(golden("vanilla-mid"), "Iron Example");
        when(config.colourPreset()).thenReturn(FateLockedConfig.ColourPreset.CUSTOM);
        when(config.unlockedColor()).thenReturn(new java.awt.Color(0, 128, 255, 110));
        when(config.frontierColor()).thenReturn(new java.awt.Color(255, 255, 0, 100));
        when(config.lockedColor()).thenReturn(new java.awt.Color(128, 0, 128, 110));
        GearDecisionTest.configChanged(plugin, "lockedColor");

        assertEquals("Guard <col=800080>(Locked)</col>", npcTarget(SEERS));
    }

    @Test
    public void anotherCharacterOrNobodySeesNoTags() throws Exception
    {
        playing(golden("vanilla-mid"), "Someone Else");
        assertEquals("Guard", npcTarget(SEERS));

        playing(golden("vanilla-mid"), null);
        assertEquals("Guard", npcTarget(SEERS));
    }

    /** An older export still tags from its own areas, but only for its character now. */
    @Test
    public void anOlderExportTagsAsBeforeForItsCharacter() throws Exception
    {
        FateLockedBundle legacy = legacyWithSeersLocked();
        assertEquals(FateLockedBundle.LockState.LOCKED, legacy.lockStateAt(SEERS));

        playing(legacy, "Nubles");
        assertEquals("Guard" + TAG, npcTarget(SEERS));
        assertEquals("Guard", npcTarget(LUMBRIDGE));

        playing(legacy, "Zezima");
        assertEquals("Guard", npcTarget(SEERS));
    }

    /**
     * vanilla-mid's travel table locks Ardougne Teleport: one place, locked (F4). One setting
     * tags both travel and what stands in a locked chunk (D1), and a tag is added once.
     */
    @Test
    public void theSettingChoosesWhetherToTagAndATagIsAddedOnce() throws Exception
    {
        playing(golden("vanilla-mid"), "Iron Example");

        assertEquals("<col=00ff00>Ardougne Teleport</col>" + TAG, target(ardougneTeleport()));
        assertEquals("Guard" + TAG, npcTarget(SEERS));

        when(config.tagLockedOptions()).thenReturn(false);
        assertEquals("<col=00ff00>Ardougne Teleport</col>", target(ardougneTeleport()));
        assertEquals("Guard", npcTarget(SEERS));

        when(config.tagLockedOptions()).thenReturn(true);
        MenuEntry tagged = npcEntry(SEERS);
        tagged.setTarget("Guard" + TAG);
        assertEquals("Guard" + TAG, target(tagged));
    }

    /**
     * F1: an option that could never be tagged is passed over before anything is read, the
     * setting included; one that could be has its text read once, by one reader.
     */
    @Test
    public void optionsThatCouldNeverBeTaggedReadNothing() throws Exception
    {
        playing(golden("vanilla-mid"), "Iron Example");
        MenuFactsReader reader = spy(new MenuFactsReader(client));
        set("menuFactsReader", reader);
        clearInvocations(config);

        for (MenuAction type : new MenuAction[] {MenuAction.WALK, MenuAction.CANCEL, MenuAction.EXAMINE_NPC,
            MenuAction.EXAMINE_OBJECT, MenuAction.PLAYER_FIRST_OPTION, MenuAction.RUNELITE})
        {
            MenuEntry entry = entry("Walk here", "Guard", type);
            plugin.onMenuEntryAdded(new MenuEntryAdded(entry));
            verify(entry, never()).getOption();
            verify(entry, never()).getTarget();
        }
        verify(reader, never()).read(any());
        verify(config, never()).tagLockedOptions();

        MenuEntry guard = npcEntry(SEERS);
        plugin.onMenuEntryAdded(new MenuEntryAdded(guard));
        verify(reader, times(1)).read(guard);
        verify(guard, times(1)).getOption();
        assertEquals("Guard" + TAG, guard.getTarget());
    }

    /** The rules in force, for a character logged in (or nobody), as the plugin refreshes them. */
    private void playing(FateLockedBundle rules, String name) throws Exception
    {
        set("active", new ActiveRules(rules, FateLockedPlugin.RulesSource.RELAY));
        Player player = name == null ? null : mock(Player.class);
        if (player != null) when(player.getName()).thenReturn(name);
        when(client.getLocalPlayer()).thenReturn(player);
        Method refresh = FateLockedPlugin.class.getDeclaredMethod("refreshDecisions");
        refresh.setAccessible(true);
        refresh.invoke(plugin);
    }

    private static MenuEntry ardougneTeleport()
    {
        return TravelClicks.cast("Ardougne Teleport").getMenuEntry();
    }

    private String npcTarget(CanonicalChunk chunk)
    {
        return target(npcEntry(chunk));
    }

    private String target(MenuEntry entry)
    {
        plugin.onMenuEntryAdded(new MenuEntryAdded(entry));
        return entry.getTarget();
    }

    private MenuEntry npcEntry(CanonicalChunk chunk)
    {
        NPC guard = mock(NPC.class);
        TestWorld.standAt(client, guard,
            new WorldPoint((chunk.getCx() << 6) + 20, (chunk.getCy() << 6) + 20, 0));
        MenuEntry entry = entry("Talk-to", "Guard", MenuAction.NPC_FIRST_OPTION);
        when(entry.getNpc()).thenReturn(guard);
        return entry;
    }

    /** A menu entry whose target keeps what is set on it. */
    private static MenuEntry entry(String option, String target, MenuAction type)
    {
        MenuEntry entry = mock(MenuEntry.class);
        String[] current = { target };
        when(entry.getOption()).thenReturn(option);
        when(entry.getType()).thenReturn(type);
        when(entry.getTarget()).thenAnswer(call -> current[0]);
        doAnswer(call -> {
            current[0] = call.getArgument(0);
            return entry;
        }).when(entry).setTarget(anyString());
        return entry;
    }

    private static FateLockedBundle golden(String id) throws Exception
    {
        return FateLockedBundle.loadFromJson(GSON,
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz")));
    }

    /** The v3 fixture (bound to Nubles), with Seers' Village added and not unlocked. */
    private static FateLockedBundle legacyWithSeersLocked() throws Exception
    {
        String text;
        try (InputStream in = MenuTagTest.class.getClassLoader().getResourceAsStream("bundles/v3-standard.json"))
        {
            text = new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
        JsonObject json = GSON.fromJson(text, JsonObject.class);
        JsonArray seers = GSON.fromJson("[{\"cx\":42,\"cy\":54}]", JsonArray.class);
        json.getAsJsonObject("chunks").add("Kandarin", seers);
        json.getAsJsonObject("subAreaChunks").add("Seers' Village", seers.deepCopy());
        json.getAsJsonObject("regionGroups").add("Kandarin", GSON.fromJson("[\"Seers' Village\"]", JsonArray.class));
        return FateLockedBundle.loadFromJson(GSON, json.toString());
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.fatelocked.FateLockedPlugin.RulesSource;
import com.fatelocked.rules.Trust;
import com.fatelocked.sidebar.CardAction;
import com.fatelocked.sidebar.StatusCardModel;
import com.fatelocked.ui.Palette.Tone;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.EnumSet;
import java.util.Set;
import org.junit.Test;

/**
 * Stage 3's done-when: a presenter test covers every row of the status table in the UX
 * report (U-ux.md "Proposed target UX"). Rows 9 and 11 are the Here card's
 * (HerePresenterGoldenTest); the status card must stay "up to date" through them.
 */
public class StatusTableTest
{
    private static final Instant NOW = Instant.parse("2026-10-01T12:00:00Z");
    private static final String RUN = "Iron Example";

    private static StatusFacts.StatusFactsBuilder facts()
    {
        return StatusFacts.builder()
            .connection(TrackerConnectionSnapshot.disconnected())
            .source(RulesSource.NONE)
            .trust(Trust.NO_RULES)
            .now(NOW)
            .zone(ZoneOffset.UTC);
    }

    private static StatusFacts.StatusFactsBuilder synced(Duration ago, boolean fresh)
    {
        return facts()
            .connection(TrackerConnectionSnapshot.connected(NOW.minus(ago), "41"))
            .source(RulesSource.RELAY)
            .arrival(RulesPrecedence.Arrival.RELAY)
            .arrivedAt(NOW.minus(Duration.ofHours(1)))
            .trust(Trust.TRUSTED)
            .bound(true)
            .boundAccount(RUN)
            .loggedInAs(RUN)
            .paired(true)
            .fresh(fresh);
    }

    @Test
    public void row1And2FirstRunAsksToConnectLoggedInOrOut()
    {
        for (String player : new String[]{null, RUN})
        {
            StatusCardModel card = StatusCardPresenter.present(facts().loggedInAs(player).build());
            assertCard(card, Tone.NEUTRAL, "Not connected", CardAction.CONNECT, CardAction.USE_BACKUP);
            assertEquals("Connect the tracker to load your run's rules.", card.getDetail());
        }
    }

    @Test
    public void row3WaitingForTheBrowserOffersToOpenThePageAgainOrCancel()
    {
        StatusCardModel card = StatusCardPresenter.present(facts().paired(true)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING, null, null,
                SyncReason.CONFIRM_IN_BROWSER, null)).build());
        assertCard(card, Tone.PENDING, "Waiting for confirmation", CardAction.OPEN_PAGE_AGAIN,
            CardAction.CANCEL_PAIRING);
        assertTrue(card.getDetail(), card.getDetail().contains("browser tab RuneLite opened"));
    }

    @Test
    public void row4ConnectedSaysHowLongAgoAndForWhom()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(2), true).build());
        assertCard(card, Tone.GOOD, "Rules up to date", null, null);
        assertEquals("Synced 2 min ago for Iron Example.", card.getDetail());
    }

    @Test
    public void row5StaleRulesSayStrictModeWaitsAndOfferACheck()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(32), false)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE, NOW.minus(Duration.ofMinutes(32)),
                "41", SyncReason.UNREACHABLE, NOW.plus(Duration.ofMinutes(3))))
            .build());
        assertCard(card, Tone.PENDING, "Rules may be out of date", CardAction.CHECK_NOW, null);
        assertEquals("Last synced 32 min ago. RuneLite couldn't reach the tracker; next check at 12:03."
            + " Strict Mode is inactive until the rules refresh.", card.getDetail());
    }

    @Test
    public void row5AFailedCheckWhileStillFreshStaysUpToDate()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(4), true)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE, NOW.minus(Duration.ofMinutes(4)),
                "41", SyncReason.BUSY, NOW.plus(Duration.ofMinutes(1))))
            .build());
        assertCard(card, Tone.GOOD, "Rules up to date", null, null);
        assertTrue(card.getDetail(), card.getDetail().endsWith("check less often; next check at 12:01."));
    }

    @Test
    public void row6ALapsedTrackerCopyAsksToOpenTheTracker()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofHours(30), false)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING, NOW.minus(Duration.ofHours(30)),
                null, SyncReason.NO_RECENT_UPDATE, null))
            .build());
        assertCard(card, Tone.PENDING, "Tracker copy expired", CardAction.OPEN_TRACKER, null);
        assertTrue(card.getDetail(), card.getDetail().endsWith("Your current rules stay in use."));
    }

    @Test
    public void row7ABackupSaysWhereItCameFromAndWhenStrictModeUsesIt()
    {
        StatusCardModel card = StatusCardPresenter.present(facts()
            .source(RulesSource.IMPORT)
            .arrival(RulesPrecedence.Arrival.IMPORT)
            .exportedAt(NOW.minus(Duration.ofMinutes(2)))
            .trust(Trust.TRUSTED).bound(true).boundAccount(RUN).loggedInAs(RUN)
            .fresh(true)
            .build());
        assertCard(card, Tone.NEUTRAL, "Using a backup", null, CardAction.CONNECT);
        assertEquals("Rules from the clipboard, exported at 11:58. Strict Mode uses them for 15 minutes after"
            + " the tracker exported them.", card.getDetail());

        StatusCardModel old = StatusCardPresenter.present(facts()
            .source(RulesSource.FILE)
            .exportedAt(NOW.minus(Duration.ofDays(3)))
            .trust(Trust.TRUSTED)
            .paired(true)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING, null, null, SyncReason.CHECKING,
                null))
            .build());
        assertEquals("Rules from a backup file, exported at Mon 12:00. They're more than 15 minutes old, so"
            + " Strict Mode doesn't use them. The tracker's copy replaces them at its next check.",
            old.getDetail());
        assertNull("paired, so nothing to do", old.getSecondary());
    }

    @Test
    public void row8AnotherCharacterNamesBothAndSaysWhatIsOff()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(2), true)
            .trust(Trust.WRONG_CHARACTER).loggedInAs("Zezima").build());
        assertCard(card, Tone.BAD, "Different character", null, null);
        assertEquals("This run belongs to Iron Example, and you're logged in as Zezima. Warnings and Strict Mode"
            + " are off.", card.getDetail());
    }

    @Test
    public void rows9To11LeaveTheStatusCardUpToDate()
    {
        // A locked area, a paused Strict Mode and an instance are the Here card's and Strict Mode's to show.
        assertEquals("Rules up to date",
            StatusCardPresenter.present(synced(Duration.ofSeconds(20), true).build()).getTitle());
    }

    @Test
    public void savedRulesAtStartupWaitForTheTrackersFirstAnswer()
    {
        Instant saved = NOW.minus(Duration.ofHours(20));
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofHours(21), false)
            .arrival(RulesPrecedence.Arrival.SAVED).arrivedAt(saved)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING, NOW.minus(Duration.ofHours(21)),
                null, SyncReason.CHECKING, null))
            .build());
        assertCard(card, Tone.NEUTRAL, "Checking with the tracker", null, null);
        assertEquals("Rules saved at Wed 16:00 are in use until the tracker answers.", card.getDetail());
    }

    @Test
    public void aNewPairingWithNoRulesYetIsCheckingNotDisconnected()
    {
        StatusCardModel card = StatusCardPresenter.present(facts().paired(true)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING, null, null, SyncReason.CHECKING,
                null)).build());
        assertCard(card, Tone.PENDING, "Checking with the tracker", null, null);
        assertEquals("RuneLite is asking the tracker for your run's rules.", card.getDetail());
    }

    @Test
    public void rulesNamingNoCharacterSayStrictModeStaysOff()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(1), true).bound(false).build());
        assertEquals("Synced 1 min ago. These rules name no character, so Strict Mode stays off.", card.getDetail());
    }

    @Test
    public void anOldBackupFromAnOlderTrackerSaysStrictModeIgnoresIt()
    {
        StatusCardModel card = StatusCardPresenter.present(facts().source(RulesSource.FILE).legacy(true)
            .trust(Trust.TRUSTED).fresh(true).exportedAt(NOW).build());
        assertTrue(card.getDetail(), card.getDetail().contains("older tracker, so Strict Mode doesn't use it"));
    }

    @Test
    public void syncOffOffersToTurnItBackOn()
    {
        TrackerConnectionSnapshot off = TrackerConnectionSnapshot.of(TrackerConnectionState.DISCONNECTED, null, null,
            SyncReason.SYNC_OFF, null);
        assertCard(StatusCardPresenter.present(facts().connection(off).build()), Tone.NEUTRAL, "Online sync is off",
            CardAction.TURN_ON_SYNC, CardAction.USE_BACKUP);
        StatusCardModel saved = StatusCardPresenter.present(synced(Duration.ofHours(2), false).paired(false)
            .connection(off).exportedAt(NOW.minus(Duration.ofHours(3))).build());
        assertCard(saved, Tone.NEUTRAL, "Using saved rules", CardAction.TURN_ON_SYNC, null);
    }

    @Test
    public void everySyncReasonHasACardWithADetailAndNoRawStatus()
    {
        Set<SyncReason> seen = EnumSet.noneOf(SyncReason.class);
        for (SyncReason reason : SyncReason.values())
        {
            for (TrackerConnectionState state : TrackerConnectionState.values())
            {
                for (RulesSource source : RulesSource.values())
                {
                    StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(20), false)
                        .source(source)
                        .connection(TrackerConnectionSnapshot.of(state, NOW.minus(Duration.ofMinutes(20)), "41",
                            reason, null))
                        .build());
                    assertNotNull(reason + " " + state + " " + source, card.getTitle());
                    assertNotNull(reason + " " + state + " " + source, card.getDetail());
                    assertTrue(card.getDetail(), !card.getDetail().contains("null"));
                    seen.add(reason);
                }
            }
        }
        assertEquals(EnumSet.allOf(SyncReason.class), seen);
    }

    @Test
    public void aFailedImportOffersACheck()
    {
        StatusCardModel card = StatusCardPresenter.present(synced(Duration.ofMinutes(5), true)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.IMPORT_FAILED, NOW, "41",
                SyncReason.NONE, null)).build());
        assertCard(card, Tone.BAD, "Couldn't apply the tracker's rules", CardAction.CHECK_NOW, null);
        StatusCardModel future = StatusCardPresenter.present(synced(Duration.ofMinutes(5), true)
            .connection(TrackerConnectionSnapshot.of(TrackerConnectionState.IMPORT_FAILED, NOW, "41",
                SyncReason.FUTURE_FORMAT, null)).build());
        assertCard(future, Tone.BAD, "Plugin update needed", null, null);
        assertTrue(future.getDetail().contains("Restart RuneLite"));
    }

    private static void assertCard(StatusCardModel card, Tone tone, String title, CardAction primary,
        CardAction secondary)
    {
        assertEquals(title, card.getTitle());
        assertEquals(tone, card.getTone());
        assertEquals(primary, card.getPrimary());
        assertEquals(secondary, card.getSecondary());
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SavedRulesStoreTest
{
    private static final String CODE = "0123456789abcdef0123456789abcdef";

    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    private final Gson gson = new Gson();

    @Test
    public void savedRulesComeBackAsTheSameRules() throws Exception
    {
        Path path = folder.getRoot().toPath().resolve(SavedRulesStore.FILE_NAME);
        String bundle = fixture("bundles/v4-rules.json");
        Instant savedAt = Instant.parse("2026-09-25T14:05:00Z");
        new SavedRulesStore(gson, path).save(new SavedRules(bundle,
            FateLockedPlugin.RulesSource.RELAY, savedAt, "41", PairingSupport.tag(CODE)));

        SavedRules loaded = new SavedRulesStore(gson, path).load();

        assertNotNull(loaded);
        assertEquals(FateLockedPlugin.RulesSource.RELAY, loaded.getSource());
        assertEquals(savedAt, loaded.getSavedAt());
        assertEquals("41", loaded.getRelayVersion());
        assertEquals(PairingSupport.tag(CODE), loaded.getPairingTag());
        FateLockedBundle original = FateLockedBundle.loadFromJson(gson, bundle);
        FateLockedBundle restored = FateLockedBundle.loadFromJson(gson, loaded.getPayload());
        assertEquals(original.getRunId(), restored.getRunId());
        assertEquals(original.getRegionChunks(), restored.getRegionChunks());
        assertEquals(original.getUnlockedRegions(), restored.getUnlockedRegions());
    }

    @Test
    public void theFileKeepsTheBundleCompressedAndNeverTheCode() throws Exception
    {
        Path path = folder.getRoot().toPath().resolve(SavedRulesStore.FILE_NAME);
        new SavedRulesStore(gson, path).save(new SavedRules(fixture("bundles/v4-rules.json"),
            FateLockedPlugin.RulesSource.RELAY, Instant.now(), "41", PairingSupport.tag(CODE)));

        String written = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);

        assertTrue(written.contains("\"payload\":\"FLGZ:"));
        assertFalse(written.contains(CODE));
        assertFalse(written.contains("Lumbridge"));
    }

    @Test
    public void noFileMeansNoSavedRules()
    {
        Path path = folder.getRoot().toPath().resolve(SavedRulesStore.FILE_NAME);

        assertNull(new SavedRulesStore(gson, path).load());
    }

    @Test
    public void aDamagedFileIsMovedAsideAndNeverStopsTheStart() throws Exception
    {
        File dir = folder.newFolder("damaged");
        Path path = dir.toPath().resolve(SavedRulesStore.FILE_NAME);
        Files.write(path, "{\"format\":1,\"source\":".getBytes(StandardCharsets.UTF_8));

        assertNull(new SavedRulesStore(gson, path).load());

        assertFalse(Files.exists(path));
        File[] kept = dir.listFiles((parent, name) ->
            name.startsWith(SavedRulesStore.FILE_NAME + ".corrupt-"));
        assertEquals(1, kept == null ? 0 : kept.length);
    }

    @Test
    public void aFileFromANewerPluginIsLeftAlone() throws Exception
    {
        Path path = folder.getRoot().toPath().resolve(SavedRulesStore.FILE_NAME);
        Files.write(path, "{\"format\":2,\"somethingNew\":true}"
            .getBytes(StandardCharsets.UTF_8));

        assertNull(new SavedRulesStore(gson, path).load());
        assertTrue(Files.exists(path));
    }

    @Test
    public void compressingKeepsAnAlreadyCompressedBundle() throws Exception
    {
        String compressed = SavedRulesStore.compress(fixture("bundles/v4-rules.json"));

        assertTrue(compressed.startsWith("FLGZ:"));
        assertEquals(compressed, SavedRulesStore.compress(compressed));
    }

    @Test
    public void aPairingTagNamesThePairingWithoutRevealingIt()
    {
        String tag = PairingSupport.tag(CODE);

        assertTrue(tag.matches("[0-9a-f]{16}"));
        assertEquals(tag, PairingSupport.tag(CODE));
        assertFalse(tag.equals(PairingSupport.tag("fedcba9876543210fedcba9876543210")));
        assertFalse(CODE.contains(tag));
        assertNull(PairingSupport.tag(""));
        assertNull(PairingSupport.tag(null));
    }

    private static String fixture(String name) throws Exception
    {
        try (InputStream in = SavedRulesStoreTest.class.getClassLoader().getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.fatelocked.SceneEdges.Kind;
import com.fatelocked.SceneEdges.Run;
import com.fatelocked.SceneEdges.Zone;
import com.fatelocked.TintPolicy.Tint;
import java.util.Arrays;
import java.util.List;
import java.util.function.BiFunction;
import org.junit.Test;

/** U3: where the scene's chunk lines run, worked out from its 8-tile zones. */
public class SceneEdgesTest
{
    /** 104 tiles across, as RuneLite loads the scene. */
    private static final int ZONES = 13;
    /** A scene whose chunk lines fall on its tiles 64 across and up. */
    private static final int LINE = 64;

    @Test
    public void aLockedChunkBesideAnUnlockedOneIsOneLockedRunOnTheChunkLine()
    {
        List<Run> runs = SceneEdges.of(scene((zx, zy) -> new Zone(
            zx < 8 ? Tint.UNLOCKED : Tint.LOCKED, surface(zx, zy)))).edges();

        assertEquals(Arrays.asList(
            new Run(true, LINE, 0, 104, Kind.LOCKED, 1),
            new Run(false, LINE, 0, 104, Kind.PLAIN, 0)), runs);
    }

    @Test
    public void lockedBesideLockedIsPlainAndAnUndecidedPlaceDrawsNothing()
    {
        assertEquals(Arrays.asList(
                new Run(true, LINE, 0, 104, Kind.PLAIN, 0),
                new Run(false, LINE, 0, 104, Kind.PLAIN, 0)),
            SceneEdges.of(scene((zx, zy) -> new Zone(Tint.LOCKED, surface(zx, zy)))).edges());

        assertEquals(Arrays.asList(new Run(false, LINE, 0, 64, Kind.PLAIN, 0)),
            SceneEdges.of(scene((zx, zy) -> zx < 8 ? new Zone(Tint.UNLOCKED, surface(zx, zy))
                : new Zone(Tint.UNKNOWN, null))).edges());
    }

    /** An instance is copied zone by zone, so one locked zone is edged on all four sides. */
    @Test
    public void anInstanceBreaksAtItsZones()
    {
        CanonicalChunk tomb = new CanonicalChunk(39, 53);
        List<Run> runs = SceneEdges.of(scene((zx, zy) -> zx == 5 && zy == 5
            ? new Zone(Tint.LOCKED, tomb) : new Zone(Tint.UNLOCKED, new CanonicalChunk(50, 50)))).edges();

        assertEquals(Arrays.asList(
            new Run(true, 40, 40, 48, Kind.LOCKED, 1),
            new Run(true, 48, 40, 48, Kind.LOCKED, -1),
            new Run(false, 40, 40, 48, Kind.LOCKED, 1),
            new Run(false, 48, 40, 48, Kind.LOCKED, -1)), runs);
    }

    @Test
    public void theScenesOwnBorderIsNeverAnEdge()
    {
        assertTrue(SceneEdges.of(scene((zx, zy) -> new Zone(Tint.UNLOCKED, new CanonicalChunk(50, 50)))).edges().isEmpty());
        assertTrue(SceneEdges.of(scene((zx, zy) -> new Zone(Tint.LOCKED, new CanonicalChunk(46, 52)))).edges().isEmpty());
    }

    @Test
    public void aRunBreaksWhereTheLockedSideChanges()
    {
        List<Run> runs = SceneEdges.of(scene((zx, zy) ->
            new Zone((zx < 8) == (zy < 8) ? Tint.UNLOCKED : Tint.LOCKED, surface(zx, zy)))).edges();

        assertEquals(Arrays.asList(
            new Run(true, LINE, 0, 64, Kind.LOCKED, 1),
            new Run(true, LINE, 64, 104, Kind.LOCKED, -1),
            new Run(false, LINE, 0, 64, Kind.LOCKED, 1),
            new Run(false, LINE, 64, 104, Kind.LOCKED, -1)), runs);
    }

    /** Locked land is kept per row of zones, joined where locked zones touch. */
    @Test
    public void lockedLandIsOneBlockPerRunOfLockedZones()
    {
        CanonicalChunk tomb = new CanonicalChunk(39, 53);
        List<SceneEdges.Block> locked = SceneEdges.of(scene((zx, zy) -> zy == 2 && zx >= 3 && zx <= 5 || zy == 7 && zx == 12
            ? new Zone(Tint.LOCKED, tomb) : new Zone(zx == 0 ? Tint.UNKNOWN : Tint.UNLOCKED, new CanonicalChunk(50, 50))))
            .locked();

        assertEquals(Arrays.asList(new SceneEdges.Block(24, 16, 48, 24), new SceneEdges.Block(96, 56, 104, 64)), locked);
        assertTrue(SceneEdges.NONE.locked().isEmpty());
        assertTrue(SceneEdges.NONE.edges().isEmpty());
    }

    /** The surface chunk a zone of this scene lies in: four chunks, split 64 tiles in. */
    private static CanonicalChunk surface(int zx, int zy)
    {
        return new CanonicalChunk(50 + zx / 8, 50 + zy / 8);
    }

    private static Zone[][] scene(BiFunction<Integer, Integer, Zone> zone)
    {
        Zone[][] zones = new Zone[ZONES][ZONES];
        for (int zx = 0; zx < ZONES; zx++)
        {
            for (int zy = 0; zy < ZONES; zy++)
            {
                zones[zx][zy] = zone.apply(zx, zy);
            }
        }
        return zones;
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

/** D2, U11: each player's settings from before Stage 3 carry over to the merged ones. */
public class SettingsMigrationTest
{
    /** Every setting the release before Stage 3 declared. */
    private static final List<String> BEFORE_STAGE_3 = Arrays.asList(
        FateLockedConfig.NETWORK_ACCESS_KEY, "reimportHotkey", "chatOnEnter", "warnOnLocked", "warnLockedBank",
        "flashOnLocked", "warnAccountMismatch", "tagLockedMenus", "tagLockedTeleports", "showHud", "showNearest",
        "showChunkContentBox", "useNotifier", "warnLockedSlayer", "warnOverTierGear", "showInfoBoxes", "rollNudges",
        "strictMode", "pauseStrictModeHotkey", "drawWorldMap", "drawScene", "drawMinimap", "highlightLockedBorders",
        "shadeNearbyLocked", "worldMapMarkers", "worldMapTooltip", "worldMapTooltipContent", "unlockedColor",
        "frontierColor", "lockedColor", "unauthoredColor");

    /** A profile's stored settings, recording each write in order. */
    private static final class Profile implements SettingsMigration.ConfigStore
    {
        final Map<String, String> stored = new HashMap<>();
        final List<String> writes = new ArrayList<>();

        /** A new player: RuneLite has stored every declared setting at its default. */
        static Profile fresh()
        {
            Profile profile = new Profile();
            profile.stored.putAll(newDefaults());
            return profile;
        }

        /** A player from before Stage 3, who also had every old setting stored, with these changes. */
        static Profile existing(String... changes)
        {
            Profile profile = fresh();
            profile.stored.putAll(SettingsMigration.OLD_DEFAULTS);
            for (int i = 0; i < changes.length; i += 2)
            {
                profile.stored.put(changes[i], changes[i + 1]);
            }
            return profile;
        }

        Profile migrated()
        {
            SettingsMigration.migrate(this);
            return this;
        }

        @Override
        public String get(String key)
        {
            return stored.get(key);
        }

        @Override
        public void set(String key, String value)
        {
            writes.add(key);
            stored.put(key, value);
        }
    }

    @Test
    public void everyOldSettingIsKeptCarriedOverOrRetired()
    {
        Set<String> kept = new HashSet<>(BEFORE_STAGE_3);
        kept.removeAll(SettingsMigration.OLD_DEFAULTS.keySet());
        assertTrue(BEFORE_STAGE_3.containsAll(SettingsMigration.OLD_DEFAULTS.keySet()));
        assertEquals(13, kept.size());
        assertTrue("a kept setting is still declared", newDefaults().keySet().containsAll(kept));
    }

    @Test
    public void aNewPlayerStartsWithEveryNewDefault()
    {
        Profile player = Profile.fresh();
        Map<String, String> before = new HashMap<>(player.stored);

        player.migrated();

        assertEquals(Collections.singletonList(SettingsMigration.VERSION_KEY), player.writes);
        assertEquals("2", player.stored.remove(SettingsMigration.VERSION_KEY));
        assertEquals(before, player.stored);
    }

    /** Old defaults can't be told from choices, so a player who kept them gets the new ones. */
    @Test
    public void aPlayerWhoKeptTheOldDefaultsGetsTheNewOnes()
    {
        Profile player = Profile.existing().migrated();

        assertEquals(Collections.singletonList(SettingsMigration.VERSION_KEY), player.writes);
        assertEquals("LOCKED_EDGES", player.stored.get("chunkBorders"));
        assertEquals("COMPACT", player.stored.get("hudMode"));
    }

    @Test
    public void theLockedAreaAlertKeepsWhatThePlayerHad()
    {
        assertEquals("CHAT_FADE", alert("warnOnLocked", "false"));
        assertEquals("CHAT_SOUND", alert("flashOnLocked", "false"));
        assertEquals("CHAT", alert("warnOnLocked", "false", "flashOnLocked", "false"));
        assertEquals("OFF", alert("chatOnEnter", "false", "warnOnLocked", "false", "flashOnLocked", "false"));
        // Every alert level has its chat line; the sound and fade the player kept decide the level.
        assertEquals("CHAT_SOUND_FADE", alert("chatOnEnter", "false"));
        assertEquals("CHAT_FADE", alert("chatOnEnter", "false", "warnOnLocked", "false"));
    }

    @Test
    public void routineAnnouncementsFollowTheOldChatSetting()
    {
        assertEquals("false", setting("announceAreaChanges", "chatOnEnter", "false"));
        assertFalse(Profile.existing("warnOnLocked", "false").migrated().writes.contains("announceAreaChanges"));
    }

    @Test
    public void ruleWarningsStayOnUnlessEveryOneWasOff()
    {
        assertEquals("true", setting("ruleWarnings", "warnLockedBank", "false"));
        assertEquals("true", setting("ruleWarnings", "warnLockedSlayer", "false", "warnOverTierGear", "false"));
        assertEquals("true", setting("ruleWarnings", "warnLockedBank", "false", "warnLockedSlayer", "false"));
        assertEquals("false", setting("ruleWarnings",
            "warnLockedBank", "false", "warnLockedSlayer", "false", "warnOverTierGear", "false"));
    }

    @Test
    public void taggingStaysOnUnlessBothKindsWereOff()
    {
        assertEquals("true", setting("tagLockedOptions", "tagLockedMenus", "false"));
        assertEquals("true", setting("tagLockedOptions", "tagLockedTeleports", "false"));
        assertEquals("false", setting("tagLockedOptions", "tagLockedMenus", "false", "tagLockedTeleports", "false"));
    }

    @Test
    public void theHudKeepsItsDetail()
    {
        assertEquals("DETAILED", setting("hudMode", "showChunkContentBox", "true"));
        assertEquals("DETAILED", setting("hudMode", "showHud", "false", "showChunkContentBox", "true"));
        assertEquals("OFF", setting("hudMode", "showHud", "false"));
        assertEquals("COMPACT", setting("hudMode", "showNearest", "false"));
    }

    @Test
    public void theWorldMapKeepsItsLayers()
    {
        assertEquals("OFF", setting("worldMapMode", "drawWorldMap", "false"));
        assertEquals("SHADING", setting("worldMapMode", "worldMapTooltip", "false"));
        assertEquals("SHADING_TOOLTIP", setting("worldMapMode", "worldMapTooltipContent", "false"));
    }

    @Test
    public void chunkBordersKeepWhatWasDrawn()
    {
        assertEquals("ALL_EDGES", setting("chunkBorders", "highlightLockedBorders", "false"));
        assertEquals("LOCKED_EDGES", setting("chunkBorders", "drawScene", "false"));
        assertEquals("OFF", setting("chunkBorders", "drawScene", "false", "highlightLockedBorders", "false"));
    }

    @Test
    public void aChangedColourSwitchesToCustomColours()
    {
        String purple = SettingsMigration.rgb(new Color(128, 0, 128, 110));
        assertEquals("CUSTOM", setting("colourPreset", "unlockedColor", purple));
        assertEquals("CUSTOM", setting("colourPreset", "frontierColor", purple));
        assertEquals("CUSTOM", setting("colourPreset", "lockedColor", purple));
        // Places the rules don't decide aren't tinted any more, so their colour has no successor.
        assertEquals("DEFAULT", setting("colourPreset", "unauthoredColor", purple));
    }

    /**
     * The old pickers saved a picked colour fully solid, which hid the map under it (a player's
     * solid red world map, 27 Sept). Such a colour keeps its hue and gets its default's
     * transparency back; a see-through one is kept as it is.
     */
    @Test
    public void aColourSavedSolidGetsItsTransparencyBack()
    {
        Profile player = Profile.existing("lockedColor", SettingsMigration.rgb(new Color(255, 0, 0)),
            "frontierColor", SettingsMigration.rgb(new Color(0, 0, 255)));

        player.migrated();

        assertEquals(SettingsMigration.rgb(new Color(255, 0, 0, 110)), player.stored.get("lockedColor"));
        assertEquals(SettingsMigration.rgb(new Color(0, 0, 255, 100)), player.stored.get("frontierColor"));
        assertEquals("CUSTOM", player.stored.get("colourPreset"));

        String purple = SettingsMigration.rgb(new Color(128, 0, 128, 110));
        Profile seeThrough = Profile.existing("lockedColor", purple).migrated();
        assertEquals(purple, seeThrough.stored.get("lockedColor"));
        assertFalse(seeThrough.writes.contains("lockedColor"));
    }

    /** RuneLite replaces a colour it can't read before the plugin starts; the migration leaves it. */
    @Test
    public void anUnreadableColourIsLeftAlone()
    {
        assertEquals("red", setting("lockedColor", "lockedColor", "red"));
    }

    /**
     * On a profile switch RuneLite may store that profile's defaults after the plugin has run,
     * so a colour that isn't stored yet is still the default one.
     */
    @Test
    public void aColourNotStoredYetIsTheDefault()
    {
        Profile player = Profile.existing("showHud", "false");
        player.stored.keySet().removeAll(Arrays.asList("unlockedColor", "frontierColor", "lockedColor", "colourPreset"));

        player.migrated();

        assertFalse(player.writes.contains("colourPreset"));
        assertEquals("OFF", player.stored.get("hudMode"));
    }

    /** Decision 10: another character's line always shows, so its old switch has no successor. */
    @Test
    public void theAccountMismatchSwitchIsRetired()
    {
        assertEquals(Collections.singletonList(SettingsMigration.VERSION_KEY),
            Profile.existing("warnAccountMismatch", "false").migrated().writes);
    }

    /** A player who started on an older release never had some settings; each counts as its default. */
    @Test
    public void aSettingThePlayerNeverHadCountsAsItsOldDefault()
    {
        Profile player = Profile.fresh();
        player.stored.put("chatOnEnter", "false");

        player.migrated();

        assertEquals("CHAT_SOUND_FADE", player.stored.get("lockedAreaAlert"));
        assertEquals("false", player.stored.get("announceAreaChanges"));
        assertEquals(Arrays.asList("lockedAreaAlert", "announceAreaChanges", SettingsMigration.VERSION_KEY),
            player.writes);
    }

    /** Written last, so a start that stops part-way carries the settings over again next time. */
    @Test
    public void theVersionIsWrittenLastAndTheOldSettingsStay()
    {
        Profile player = Profile.existing("warnOnLocked", "false", "showHud", "false", "drawWorldMap", "false",
            "drawScene", "false", "tagLockedMenus", "false", "warnLockedBank", "false");
        Map<String, String> old = new HashMap<>();
        for (String key : SettingsMigration.OLD_DEFAULTS.keySet())
        {
            old.put(key, player.stored.get(key));
        }

        player.migrated();

        assertEquals(7, player.writes.size());
        assertEquals(SettingsMigration.VERSION_KEY, player.writes.get(6));
        for (Map.Entry<String, String> setting : old.entrySet())
        {
            assertEquals("kept for one release: " + setting.getKey(), setting.getValue(),
                player.stored.get(setting.getKey()));
        }
    }

    @Test
    public void eachProfileIsCarriedOverOnce()
    {
        Profile player = Profile.existing("showHud", "false").migrated();
        player.writes.clear();
        player.stored.put("hudMode", "DETAILED");

        player.migrated();

        assertTrue(player.writes.isEmpty());
        assertEquals("the player's own choice since stays", "DETAILED", player.stored.get("hudMode"));

        Profile later = Profile.existing("showHud", "false");
        later.stored.put(SettingsMigration.VERSION_KEY, "3");
        assertTrue("a later release's profile is left alone", later.migrated().writes.isEmpty());
    }

    @Test
    public void anUnreadableVersionIsCarriedOverAgain()
    {
        Profile player = Profile.existing("showHud", "false");
        player.stored.put(SettingsMigration.VERSION_KEY, "two");

        player.migrated();

        assertEquals("OFF", player.stored.get("hudMode"));
        assertEquals("2", player.stored.get(SettingsMigration.VERSION_KEY));
    }

    /** One merged setting after carrying over a player with these old changes. */
    private static String setting(String key, String... changes)
    {
        return Profile.existing(changes).migrated().stored.get(key);
    }

    /** The alert level, which RuneLite must be able to read back as the setting's type. */
    private static String alert(String... changes)
    {
        return FateLockedConfig.LockedAreaAlert.valueOf(setting("lockedAreaAlert", changes)).name();
    }

    /** What RuneLite stores for each declared setting before the plugin starts. */
    private static Map<String, String> newDefaults()
    {
        FateLockedConfig defaults = new FateLockedConfig() { };
        Map<String, String> stored = new HashMap<>();
        for (Method method : FateLockedConfig.class.getDeclaredMethods())
        {
            ConfigItem item = method.getAnnotation(ConfigItem.class);
            if (item == null)
            {
                continue;
            }
            try
            {
                Object value = method.invoke(defaults);
                stored.put(item.keyName(), value instanceof Color ? SettingsMigration.rgb((Color) value)
                    : value instanceof Enum ? ((Enum<?>) value).name() : String.valueOf(value));
            }
            catch (ReflectiveOperationException e)
            {
                throw new AssertionError(e);
            }
        }
        return stored;
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import net.runelite.api.WorldType;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.EnumSet;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DetectionGateTest
{
    private static final Gson GSON = new Gson();

    @Test
    public void countsForTheBoundCharacterOnANormalWorld() throws Exception
    {
        FateLockedBundle rules = rulesBoundTo("Nubles");

        assertTrue(DetectionGate.allows(rules, "Nubles", EnumSet.of(WorldType.MEMBERS)));
        assertTrue(DetectionGate.allows(rules, " nubles ", EnumSet.noneOf(WorldType.class)));
        // PvP and high-risk worlds save to the account like any other.
        assertTrue(DetectionGate.allows(rules, "Nubles",
            EnumSet.of(WorldType.MEMBERS, WorldType.PVP, WorldType.HIGH_RISK)));
    }

    @Test
    public void notForAnotherCharacterOrAnUnboundProfile() throws Exception
    {
        assertFalse(DetectionGate.allows(rulesBoundTo("Nubles"), "Zezima",
            EnumSet.of(WorldType.MEMBERS)));
        assertFalse(DetectionGate.allows(rulesBoundTo("Nubles"), null,
            EnumSet.of(WorldType.MEMBERS)));
        assertFalse(DetectionGate.allows(rulesBoundTo(null), "Nubles",
            EnumSet.of(WorldType.MEMBERS)));
    }

    @Test
    public void notOnAWorldWhoseProgressIsNotTheAccountsOwn() throws Exception
    {
        FateLockedBundle rules = rulesBoundTo("Nubles");
        for (WorldType other : EnumSet.of(WorldType.SEASONAL, WorldType.DEADMAN,
            WorldType.TOURNAMENT_WORLD, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE,
            WorldType.FRESH_START_WORLD, WorldType.QUEST_SPEEDRUNNING,
            WorldType.LAST_MAN_STANDING, WorldType.PVP_ARENA))
        {
            assertFalse(other.name(), DetectionGate.allows(rules, "Nubles",
                EnumSet.of(WorldType.MEMBERS, other)));
        }
    }

    @Test
    public void notWithoutRulesForARun()
    {
        assertFalse(DetectionGate.allows(null, "Nubles", EnumSet.of(WorldType.MEMBERS)));
    }

    /** The v4 fixture, bound to this account, or to none. */
    private static FateLockedBundle rulesBoundTo(String account) throws Exception
    {
        JsonObject root;
        try (InputStream in = DetectionGateTest.class.getClassLoader()
            .getResourceAsStream("bundles/v4-rules.json"))
        {
            root = GSON.fromJson(new String(in.readAllBytes(), StandardCharsets.UTF_8),
                JsonObject.class);
        }
        if (account == null)
        {
            root.getAsJsonObject("rules").add("account", JsonNull.INSTANCE);
        }
        else
        {
            root.getAsJsonObject("rules").addProperty("account", account);
        }
        return FateLockedBundle.loadFromJson(GSON, root.toString());
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.fatelocked.sidebar.HereModel;
import com.fatelocked.sidebar.HerePresenter;
import com.fatelocked.ui.Palette.Tone;
import com.google.gson.Gson;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

/** The Here card from the golden runs (C3; U13, U16, U21). */
public class HerePresenterGoldenTest
{
    private static final Gson GSON = new Gson();
    private static final HerePresenter PRESENTER = new HerePresenter();

    @Test
    public void everyRowKeepsItsReasonAndSaysItsStatusInAWord() throws Exception
    {
        HereModel here = here("vanilla-mid", "iron example", 50, 50);
        assertEquals("Lumbridge Castle", here.getPlace());
        assertEquals("Unlocked", here.getWord());
        assertEquals(Tone.GOOD, here.getTone());
        assertNull("an unlocked place needs no reason", here.getReason());
        assertEquals("Lumbridge · Misthalin · 50, 50", here.getWhere());
        // Six rows the tracker leaves undecided, the caves' monsters, count as not ready: logged out,
        // the game can't say The Lost Tribe is started.
        assertEquals(List.of(14, 26, 35),
            here.getCounts().stream().map(HereModel.Count::getValue).collect(Collectors.toList()));
        assertEquals(List.of("Can do", "Not ready", "Locked"),
            here.getCounts().stream().map(HereModel.Count::getLabel).collect(Collectors.toList()));

        HereModel.Group skilling = group(here, "SKILLING");
        HereModel.Row deadTree = skilling.getRows().get(0);
        assertEquals("Dead tree", deadTree.getName());
        assertEquals("Not ready", deadTree.getWord());
        assertEquals("Woodcutting 1/1 · cap 0", deadTree.getReason());

        // U13: quests, banks and shops kept no reason before Stage 3.
        HereModel.Row shop = group(here, "SHOPS").getRows().get(0);
        assertEquals("Locked", shop.getWord());
        assertNotNull(shop.getName() + " says why", shop.getReason());
        assertTrue(group(here, "QUESTS").getRows().stream().anyMatch(row -> row.getReason() != null));
        HereModel.Row guard = group(here, "COMBAT").getRows().stream()
            .filter(row -> row.getName().equals("Cave goblin guard")).findFirst().orElseThrow(AssertionError::new);
        assertEquals("Not ready", guard.getWord());
        assertEquals("The Lost Tribe started", guard.getReason());
    }

    /** The owner's review, 28 Sept: no row of any golden, anywhere, is left without a status. */
    @Test
    public void everyRowHasAStatus() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            DecisionService playing = decisions(id, "iron example");
            for (CanonicalChunk chunk : playing.mappedChunks())
            {
                for (HereModel.Group group : PRESENTER.present(playing, chunk).getGroups())
                {
                    for (HereModel.Row row : group.getRows())
                    {
                        assertTrue(id + " " + chunk + " " + row.getName() + ": " + row.getWord(),
                            List.of("Can do", "Not ready", "Locked").contains(row.getWord()));
                    }
                }
            }
        }
    }

    /** Skilling splits by skill, each with the level and cap the tracker gives; rows keep the level they need. */
    @Test
    public void skillingSplitsBySkill() throws Exception
    {
        HereModel.Group skilling = group(here("vanilla-mid", "iron example", 50, 50), "SKILLING");
        List<String> skills = skilling.getSubgroups().stream().map(HereModel.Subgroup::getTitle)
            .collect(Collectors.toList());
        assertEquals(List.of("Fishing", "Mining", "Woodcutting"), skills);
        HereModel.Subgroup woodcutting = skilling.getSubgroups().get(2);
        assertEquals("SKILLING/Woodcutting", woodcutting.getKey());
        assertEquals("Woodcutting", woodcutting.getSkill());
        assertEquals("Level 1 · cap 0", woodcutting.getNote());
        HereModel.Row yew = woodcutting.getRows().stream().filter(row -> row.getName().equals("Yew tree")).findFirst()
            .orElseThrow(AssertionError::new);
        assertEquals("Level 60", yew.getReason());
        assertEquals("every row, in one skill or another", skilling.getRows().size(),
            skilling.getSubgroups().stream().mapToInt(subgroup -> subgroup.getRows().size()).sum());
    }

    @Test
    public void aLockedPlaceSaysWhyOnceAndItsRowsDontRepeatIt() throws Exception
    {
        HereModel here = here("vanilla-fresh", "iron example", 46, 52);
        assertEquals("West Falador", here.getPlace());
        assertEquals("Locked", here.getWord());
        assertEquals(Tone.BAD, here.getTone());
        assertEquals("Unlock Falador", here.getReason());
        for (HereModel.Group group : here.getGroups())
        {
            for (HereModel.Row row : group.getRows())
            {
                assertTrue(row.getName() + ": " + row.getReason(),
                    row.getReason() == null || !row.getReason().contains("Location locked"));
            }
        }
        assertEquals("Woodcutting 1/15 · cap 0", group(here, "SKILLING").getRows().get(0).getReason());
    }

    @Test
    public void anInteriorIsNamedByItsPlace() throws Exception
    {
        HereModel here = here("vanilla-interiors", "iron example", 18, 143);
        assertEquals("Kurask Lair", here.getPlace());
        assertEquals("Locked", here.getWord());
        assertEquals("18, 143", here.getWhere());
    }

    @Test
    public void theSeaIsNamedAsTheTrackersPlacesNameIt() throws Exception
    {
        HereModel here = here("vanilla-mid", "iron example", 40, 41);
        assertEquals("Ocean", here.getPlace());
        assertEquals("Locked", here.getWord());
    }

    @Test
    public void anotherCharacterSeesThePlaceButNothingChecked() throws Exception
    {
        HereModel here = here("vanilla-mid", "zezima", 50, 50);
        assertEquals("Lumbridge Castle", here.getPlace());
        assertNull(here.getWord());
        assertEquals(Tone.NEUTRAL, here.getTone());
        assertTrue(here.getReason(), here.getReason().contains("another character"));
        assertTrue(here.getGroups().isEmpty());
        assertTrue(here.getCounts().isEmpty());
    }

    @Test
    public void loggedOutThereIsNoPlace() throws Exception
    {
        DecisionService decisions = decisions("vanilla-mid", "iron example");
        HereModel here = PRESENTER.present(decisions, null);
        assertNull(here.getPlace());
        assertTrue(here.getMessage(), here.getMessage().startsWith("Log in"));
    }

    @Test
    public void aGroupShowsFiveRowsUntilOpened() throws Exception
    {
        HereModel.Group shops = group(here("vanilla-mid", "iron example", 50, 50), "SHOPS");
        assertEquals(21, shops.getRows().size());
        assertEquals(HereModel.ROWS_SHOWN, shops.shown(false).size());
        assertEquals(16, shops.hidden());
        assertEquals(21, shops.shown(true).size());
    }

    @Test
    public void rowNamesShowTheirVariantInBrackets() throws Exception
    {
        List<String> names = group(here("vanilla-mid", "iron example", 50, 50), "SHOPS").getRows().stream()
            .map(HereModel.Row::getName).collect(Collectors.toList());
        assertTrue(names.toString(), names.contains("Culinaromancer's Chest (Food)"));
        assertTrue(names.stream().noneMatch(name -> name.contains("#")));
    }

    /**
     * What the card could point at in a place, for remembering where each is seen: the rows of
     * the categories it points in, named as it shows them; none for another character.
     */
    @Test
    public void theCardKnowsWhatItCouldPointAt() throws Exception
    {
        CanonicalChunk lumbridge = new CanonicalChunk(50, 50);
        List<String> rows = HerePresenter.pointable(decisions("vanilla-mid", "iron example"), lumbridge).stream()
            .map(target -> target.getCategory() + ": " + target.getLabel()).collect(Collectors.toList());

        assertTrue(rows.toString(), rows.contains("SKILLING: Dead tree"));
        assertTrue(rows.contains("COMBAT: Cave goblin guard"));
        assertTrue(rows.contains("SHOPS: Culinaromancer's Chest (Food)"));
        assertEquals("every Skilling row, pointable or not by status",
            group(here("vanilla-mid", "iron example", 50, 50), "SKILLING").getRows().size(),
            rows.stream().filter(row -> row.startsWith("SKILLING: ")).count());
        assertTrue("no quest or journey is one thing", rows.stream()
            .noneMatch(row -> row.startsWith("QUESTS") || row.startsWith("TRAVEL")));
        assertTrue(HerePresenter.pointable(decisions("vanilla-mid", "someone else"), lumbridge).isEmpty());
        assertTrue(HerePresenter.pointable(decisions("vanilla-mid", "iron example"), null).isEmpty());
    }

    /** An older export lists what's in a place without statuses; the card can still point at it. */
    @Test
    public void anOlderExportsContentCanBePointedAt()
    {
        CanonicalChunk lumbridge = new CanonicalChunk(50, 50);
        DecisionService older = org.mockito.Mockito.mock(DecisionService.class);
        org.mockito.Mockito.when(older.trust()).thenReturn(com.fatelocked.rules.Trust.TRUSTED);
        org.mockito.Mockito.when(older.details(lumbridge)).thenReturn(java.util.Optional.empty());
        java.util.Map<String, List<String>> content = new java.util.LinkedHashMap<>();
        content.put("mon", List.of("Goblin"));
        content.put("shop", List.of("Bob's Brilliant Axes"));
        content.put("farm", List.of("Herb patch"));
        content.put("poi", List.of("Fountain"));
        org.mockito.Mockito.when(older.legacyContent(lumbridge)).thenReturn(content);

        List<String> rows = HerePresenter.pointable(older, lumbridge).stream()
            .map(target -> target.getCategory() + ": " + target.getLabel()).collect(Collectors.toList());

        assertEquals(List.of("COMBAT: Goblin", "SHOPS: Bob's Brilliant Axes", "FARMING: Herb patch",
            "ACTIVITIES: Fountain"), rows);
    }

    private static HereModel.Group group(HereModel here, String category)
    {
        return here.getGroups().stream().filter(group -> group.getCategory().equals(category)).findFirst()
            .orElseThrow(() -> new AssertionError("no " + category));
    }

    private static HereModel here(String scenario, String player, int x, int y) throws Exception
    {
        return PRESENTER.present(decisions(scenario, player), new CanonicalChunk(x, y));
    }

    private static DecisionService decisions(String scenario, String player) throws Exception
    {
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(scenario + ".bundle.json.gz"));
        return DecisionService.create(RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), "iron example",
            player);
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.junit.Test;

import java.awt.Color;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * B7: the scene and minimap tints, from the decision service. Over every
 * golden bundle each chunk tints as the tracker decides it (NOT_READY as
 * unlocked), the sea the rules don't cover and another character's rules
 * tint as unknown, and an older export tints as before.
 */
public class TintPolicyTest
{
    private static final Gson GSON = new Gson();

    @Test
    public void everyGoldenChunkTintsAsTheTrackerDecides() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
            JsonObject wire = GSON.fromJson(json, JsonObject.class);
            JsonObject chunks = wire.getAsJsonObject("rules").getAsJsonObject("chunks");
            JsonElement bound = wire.getAsJsonObject("rules").get("account");
            String account = bound == null || bound.isJsonNull() ? null : AccountBinding.normalize(bound.getAsString());
            RulesSnapshot rules = RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json));
            DecisionService playing = DecisionService.create(rules, account, account);
            DecisionService other = DecisionService.create(rules, account, "someone else");

            List<String> mismatches = new ArrayList<>();
            for (Map.Entry<String, JsonElement> entry : chunks.entrySet())
            {
                CanonicalChunk chunk = GoldenBundleContractTest.chunk(entry.getKey());
                TintPolicy.Tint want = tint(entry.getValue().getAsJsonObject().get("entry").getAsString());
                TintPolicy.Tint got = TintPolicy.at(playing, chunk);
                boolean otherQuiet = account == null || TintPolicy.at(other, chunk) == TintPolicy.Tint.UNKNOWN;
                if (want != got || !otherQuiet) mismatches.add(entry.getKey() + " want " + want + " got " + got);
            }
            // The sea without a snapshot tints as the rules' chunk entries say (R1).
            JsonObject entries = GoldenBundleContractTest.json(id + ".expect.json").getAsJsonObject("entries");
            for (String key : GoldenBundleContractTest.json(id + ".expect.json").getAsJsonObject("chunks").keySet())
            {
                if (chunks.has(key)) continue;
                TintPolicy.Tint want = tint(entries.get(key).getAsString());
                TintPolicy.Tint sea = TintPolicy.at(playing, GoldenBundleContractTest.chunk(key));
                if (sea != want) mismatches.add(key + " is not in the rules' chunks and tints " + sea + ", not " + want);
            }
            assertTrue(id, chunks.size() > 600);
            assertEquals(id, List.of(), mismatches);
        }
    }

    @Test
    public void anOlderExportTintsAsBefore() throws Exception
    {
        FateLockedBundle v3;
        try (InputStream in = getClass().getClassLoader().getResourceAsStream("bundles/v3-standard.json"))
        {
            v3 = FateLockedBundle.loadFromJson(GSON, new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
        DecisionService nubles = DecisionService.create(RulesSnapshot.of(v3), "nubles", "nubles");

        assertEquals(TintPolicy.Tint.UNLOCKED, TintPolicy.at(nubles, new CanonicalChunk(46, 52)));
        assertEquals(TintPolicy.Tint.UNLOCKED, TintPolicy.at(nubles, new CanonicalChunk(50, 50)));
        assertEquals(TintPolicy.Tint.UNKNOWN, TintPolicy.at(nubles, new CanonicalChunk(1, 1)));
        assertEquals(TintPolicy.Tint.UNKNOWN,
            TintPolicy.at(DecisionService.create(RulesSnapshot.of(v3), "nubles", "zezima"), new CanonicalChunk(46, 52)));
    }

    /**
     * Until B17's boundary test covers every surface: the game view and the minimap draw from
     * one scene, tinted through TintPolicy (U3). Neither fills a chunk, and the game view's
     * corners are never tile centres.
     */
    @Test
    public void theSceneAndMinimapTintThroughThePolicy() throws Exception
    {
        assertTrue(source("SceneEdgesCache.java").contains("TintPolicy.at("));
        for (String overlay : new String[] { "FateLockedSceneOverlay.java", "FateLockedMinimapOverlay.java" })
        {
            String source = source(overlay);
            assertFalse(overlay, source.contains("lockStateAt("));
            assertFalse(overlay, source.contains("fillPolygon("));
            assertTrue(overlay, source.contains("plugin.sceneEdges("));
        }
        assertFalse(source("FateLockedSceneOverlay.java").contains("LocalPoint.fromWorld("));
        assertFalse("the minimap's ids are gameval's", source("FateLockedMinimapOverlay.java").contains("ComponentID"));
    }

    private static String source(String name) throws Exception
    {
        return new String(Files.readAllBytes(Paths.get("src", "main", "java", "com", "fatelocked", name)),
            StandardCharsets.UTF_8);
    }

    private static TintPolicy.Tint tint(String entry)
    {
        switch (entry)
        {
            case "ALLOWED":
            case "NOT_READY":
                return TintPolicy.Tint.UNLOCKED;
            case "LOCKED":
                return TintPolicy.Tint.LOCKED;
            default:
                return TintPolicy.Tint.UNKNOWN;
        }
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
