/**
 * The owner's review, 28 Sept: a clicked Here row's nearest thing, in the loaded scene, in
 * the player's chunk, on their floor first. A 16-tile scene: zone (0, 1), north of the
 * player, is another chunk.
 */
public class SceneSearchTest
{
    private static final CanonicalChunk HERE = new CanonicalChunk(50, 50);
    private static final CanonicalChunk NEXT_DOOR = new CanonicalChunk(51, 50);
    private static final int OAK = 10820;
    private static final int PATCH = 8550;

    private final Client client = mock(Client.class);
    private final ChunkLocator locator = mock(ChunkLocator.class);
    private final WorldView view = mock(WorldView.class);
    private final Player player = mock(Player.class);
    private final Tile[][][] tiles = new Tile[4][16][16];
    private final List<NPC> npcs = new ArrayList<>();

    @Before
    public void setUp()
    {
        Scene scene = mock(Scene.class);
        when(client.getTopLevelWorldView()).thenReturn(view);
        when(client.getLocalPlayer()).thenReturn(player);
        when(player.getWorldView()).thenReturn(view);
        when(player.getLocalLocation()).thenReturn(at(3, 6));
        when(view.getScene()).thenReturn(scene);
        when(scene.getTiles()).thenReturn(tiles);
        when(view.getSizeX()).thenReturn(16);
        when(view.getSizeY()).thenReturn(16);
        IndexedObjectSet<NPC> set = mock(IndexedObjectSet.class);
        when(set.iterator()).thenAnswer(ask -> npcs.iterator());
        doReturn(set).when(view).npcs();
        when(locator.sceneZone(anyInt(), anyInt())).thenReturn(HERE);
        when(locator.sceneZone(0, 1)).thenReturn(NEXT_DOOR);
        ObjectComposition oak = composition("Oak tree", "Chop down");
        when(client.getObjectDefinition(OAK)).thenReturn(oak);
    }

    @Test
    public void theNearestOnTheFloorInTheChunk()
    {
        GameObject far = object(OAK, 0, 3, 1);
        GameObject near = object(OAK, 0, 6, 6);
        object(OAK, 0, 3, 8);   // Next door, closer still.
        object(OAK, 1, 3, 7);   // Upstairs, closer still.

        SceneSearch.Found found = SceneSearch.nearest(client, locator, HERE, PointTarget.of("SKILLING", "Oak tree"));

        assertSame(near.getLocalLocation(), found.getPoint());
        assertNull(found.getNpc());
        assertTrue(found.isSameFloor());
        assertEquals(3 * 128, found.getDistance());
        assertFalse(far.getLocalLocation() == found.getPoint());
    }

    @Test
    public void onAnotherFloorWhenThatIsAllThereIs()
    {
        GameObject upstairs = object(OAK, 2, 3, 3);
        SceneSearch.Found found = SceneSearch.nearest(client, locator, HERE, PointTarget.of("SKILLING", "Oak tree"));
        assertSame(upstairs.getLocalLocation(), found.getPoint());
        assertFalse(found.isSameFloor());
    }

    /** A fishing spot that offers what the row says, not the nearer one that doesn't; none next door. */
    @Test
    public void anNpcByItsNameAndOptions()
    {
        npc("Fishing spot", HERE, 3, 2, "Net", "Bait");
        NPC lure = npc("Fishing spot", HERE, 7, 7, "Lure", "Bait");
        npc("Fishing spot", NEXT_DOOR, 2, 3, "Lure", "Bait");

        SceneSearch.Found found = SceneSearch.nearest(client, locator, HERE,
            PointTarget.of("SKILLING", "Fishing spot (lure, bait)"));

        assertSame(lure, found.getNpc());
        assertTrue(found.isSameFloor());
    }

    /** A patch shows another object as it grows: it's found by the one it shows now. */
    @Test
    public void anObjectByWhatItShowsNow()
    {
        ObjectComposition base = composition("null");
        when(base.getImpostorIds()).thenReturn(new int[] {8551, 8552});
        ObjectComposition grown = composition("Herb patch", "Rake");
        when(base.getImpostor()).thenReturn(grown);
        when(client.getObjectDefinition(PATCH)).thenReturn(base);
        GameObject patch = object(PATCH, 0, 4, 4);

        SceneSearch.Found found = SceneSearch.nearest(client, locator, HERE, PointTarget.of("FARMING", "Herb patch"));
        assertSame(patch.getLocalLocation(), found.getPoint());
    }

    /** A 2x2 tree sits on four tiles; it's looked at once. */
    @Test
    public void anObjectOnSeveralTilesIsLookedAtOnce()
    {
        GameObject tree = object(OAK, 0, 4, 4);
        for (int[] tile : new int[][] {{5, 4}, {4, 5}, {5, 5}})
        {
            tileAt(0, tile[0], tile[1]);
            when(tiles[0][tile[0]][tile[1]].getGameObjects()).thenReturn(new GameObject[] {tree});
        }
        SceneSearch.nearest(client, locator, HERE, PointTarget.of("SKILLING", "Oak tree"));
        verify(tree, times(1)).getId();
    }

    @Test
    public void nothingWhereThereIsNoneOrNoOneOnTheLand()
    {
        object(OAK, 0, 4, 4);
        assertNull(SceneSearch.nearest(client, locator, HERE, PointTarget.of("SKILLING", "Yew tree")));
        assertNull(SceneSearch.nearest(client, locator, HERE, null));
        assertNull(SceneSearch.nearest(client, locator, null, PointTarget.of("SKILLING", "Oak tree")));

        when(player.getWorldView()).thenReturn(mock(WorldView.class));
        assertNull("on a boat's deck", SceneSearch.nearest(client, locator, HERE,
            PointTarget.of("SKILLING", "Oak tree")));
    }

    private GameObject object(int id, int plane, int x, int y)
    {
        GameObject object = mock(GameObject.class);
        when(object.getId()).thenReturn(id);
        when(object.getPlane()).thenReturn(plane);
        LocalPoint point = at(x, y);
        when(object.getLocalLocation()).thenReturn(point);
        tileAt(plane, x, y);
        when(tiles[plane][x][y].getGameObjects()).thenReturn(new GameObject[] {null, object});
        return object;
    }

    private void tileAt(int plane, int x, int y)
    {
        if (tiles[plane][x][y] == null)
        {
            tiles[plane][x][y] = mock(Tile.class);
        }
    }

    private NPC npc(String name, CanonicalChunk chunk, int x, int y, String... actions)
    {
        NPC npc = mock(NPC.class);
        NPCComposition shown = mock(NPCComposition.class);
        when(shown.getName()).thenReturn(name);
        when(shown.getActions()).thenReturn(actions);
        when(npc.getTransformedComposition()).thenReturn(shown);
        when(npc.getLocalLocation()).thenReturn(at(x, y));
        when(locator.actor(npc)).thenReturn(chunk);
        npcs.add(npc);
        return npc;
    }

    private static ObjectComposition composition(String name, String... actions)
    {
        ObjectComposition composition = mock(ObjectComposition.class);
        when(composition.getName()).thenReturn(name);
        when(composition.getActions()).thenReturn(actions);
        return composition;
    }

    private static LocalPoint at(int x, int y)
    {
        return new LocalPoint(x * 128 + 64, y * 128 + 64, -1);
    }
}

package com.fatelocked;

import com.fatelocked.rules.Decision;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RulesSnapshot;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * B11 and E6: Slayer tasks through the decision service. Under the
 * slayerTasks capability the tracker decides each task per master (R16).
 * For older rules a task is LOCKED only when every chunk its monsters live
 * in is locked, and a known master's own list decides first: in
 * vanilla-mid, abyssal demons are owned for most masters but Krystilia's
 * are all in the locked Wilderness.
 */
public class SlayerDecisionTest
{
    private static final Gson GSON = new Gson();

    /** Every task key in every golden bundle reads the tracker's pinned status. */
    @Test
    public void everyGoldenTaskIsTheTrackers() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
            DecisionService service = DecisionService.create(
                RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), null, null);
            JsonObject pinned = GoldenBundleContractTest.json(id + ".expect.json").getAsJsonObject("slayer");
            List<String> mismatches = new ArrayList<>();
            for (Map.Entry<String, JsonElement> task : pinned.entrySet())
            {
                String[] asked = asAsked(task.getKey());
                PermissionStatus got = service.slayerTask(asked[0], asked[1], asked[2]).getStatus();
                if (!task.getValue().getAsString().equals(got.name())) mismatches.add(task.getKey() + " want " + task.getValue() + " got " + got);
            }
            assertTrue(id + " has tasks", pinned.size() > 500);
            assertEquals(id, List.of(), mismatches);
        }
    }

    /**
     * A task key as a game message would give it: master, task and place.
     * A key drops one trailing "s", so one is added back where it ends.
     */
    private static String[] asAsked(String key)
    {
        String master = key.contains(":") ? key.substring(0, key.indexOf(':')) : null;
        String name = key.contains(":") ? key.substring(key.indexOf(':') + 1) : key;
        String location = null;
        if (name.contains(" - "))
        {
            location = name.substring(name.indexOf(" - ") + 3) + "s";
            name = name.substring(0, name.indexOf(" - "));
        }
        else
        {
            name = name + "s";
        }
        return new String[] { master, name, location };
    }

    @Test
    public void theTrackerDecidesPerMasterWithItsReason() throws Exception
    {
        DecisionService interiors = trackerPlaying("vanilla-interiors");

        assertEquals(new Decision(PermissionStatus.LOCKED, "bears", "Area locked", Decision.Source.SLAYER),
            interiors.slayerTask("krystilia", "bears", null));
        assertEquals("anyone else's bears", PermissionStatus.ALLOWED, interiors.slayerTask(null, "bears", null).getStatus());
        assertEquals("a master with none of their own falls back to anyone's",
            PermissionStatus.ALLOWED, interiors.slayerTask("mortimer", "bears", null).getStatus());
        assertEquals(new Decision(PermissionStatus.LOCKED, "aberrant spectres", "Master: Mount Karuulm", Decision.Source.SLAYER),
            interiors.slayerTask(SlayerAssignment.KONAR, "aberrant spectres", "Catacombs of Kourend"));
        assertEquals("a task the tracker doesn't list falls back to the chunks",
            PermissionStatus.UNKNOWN, interiors.slayerTask(null, "not a monster", null).getStatus());
    }

    @Test
    public void theTrackersTasksAreReadLeniently() throws Exception
    {
        JsonObject json;
        try (java.io.InputStream in = getClass().getClassLoader().getResourceAsStream("bundles/v4-rules.json"))
        {
            json = GSON.fromJson(new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8), JsonObject.class);
        }
        json.add("slayerChunks", GSON.fromJson("{\"spider\": [{\"cx\": 50, \"cy\": 50}]}", JsonObject.class));
        json.getAsJsonObject("rules").add("slayerTasks", GSON.fromJson(
            "{\"krystilia:spider\": {\"status\": \"A_NEWER_STATUS\"}, \"goblin\": {\"reason\": \"no status\"},"
                + " \"spider\": \"not a task\"}", JsonObject.class));
        JsonObject named = json.deepCopy();
        named.getAsJsonObject("rules").add("capabilities", GSON.fromJson("[\"slayerTasks\"]", JsonArray.class));
        DecisionService nubles = DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, named.toString())), "nubles", "nubles");

        assertEquals(PermissionStatus.UNKNOWN, nubles.slayerTask("krystilia", "spiders", null).getStatus());
        assertEquals(Decision.Source.SLAYER, nubles.slayerTask("krystilia", "spiders", null).getSource());
        assertEquals("a skipped task falls back to its chunks", PermissionStatus.ALLOWED, nubles.slayerTask(null, "spiders", null).getStatus());
        assertEquals("a task without a status is skipped", Decision.Source.UNMAPPED, nubles.slayerTask(null, "goblins", null).getSource());

        DecisionService older = DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json.toString())), "nubles", "nubles");
        assertEquals("without the capability, the chunks decide", PermissionStatus.ALLOWED,
            older.slayerTask("krystilia", "spiders", null).getStatus());
    }

    @Test
    public void aKnownMastersOwnListDecides() throws Exception
    {
        DecisionService mid = playing("vanilla-mid");

        assertEquals(PermissionStatus.ALLOWED, mid.slayerTask(null, "abyssal demons", null).getStatus());
        Decision krystilia = mid.slayerTask("krystilia", "abyssal demons", null);
        assertEquals(PermissionStatus.LOCKED, krystilia.getStatus());
        assertEquals(Decision.Source.SLAYER, krystilia.getSource());
        assertEquals("a master with no list of their own falls back to the merged list",
            PermissionStatus.ALLOWED, mid.slayerTask("mortimer", "abyssal demons", null).getStatus());
        assertEquals(PermissionStatus.ALLOWED, mid.slayerTask(null, "goblins", null).getStatus());
    }

    /** A master's own list decides even when it located nothing: other masters' places don't count. */
    @Test
    public void anEmptyListOfTheMastersOwnIsUnknown() throws Exception
    {
        JsonObject json;
        try (java.io.InputStream in = getClass().getClassLoader().getResourceAsStream("bundles/v4-rules.json"))
        {
            json = GSON.fromJson(new String(in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8), JsonObject.class);
        }
        json.add("slayerChunks", GSON.fromJson(
            "{\"krystilia:spider\": [], \"spider\": [{\"cx\": 50, \"cy\": 50}]}", JsonObject.class));
        DecisionService nubles = DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json.toString())), "nubles", "nubles");

        assertEquals(PermissionStatus.ALLOWED, nubles.slayerTask(null, "spiders", null).getStatus());
        assertEquals(PermissionStatus.UNKNOWN, nubles.slayerTask("krystilia", "spiders", null).getStatus());
    }

    @Test
    public void konarsPlaceDecides() throws Exception
    {
        DecisionService mid = playing("vanilla-mid");

        for (String place : new String[] { "Catacombs of Kourend", "Slayer Tower", "Stronghold Slayer Cave" })
        {
            assertEquals(place, PermissionStatus.LOCKED,
                mid.slayerTask(SlayerAssignment.KONAR, "aberrant spectres", place).getStatus());
        }
    }

    @Test
    public void unknownTasksAndOtherCharactersGetNoAnswer() throws Exception
    {
        DecisionService mid = playing("vanilla-mid");
        assertEquals(PermissionStatus.UNKNOWN, mid.slayerTask(null, "not a monster", null).getStatus());
        assertEquals(PermissionStatus.UNKNOWN, mid.slayerTask(null, " ", null).getStatus());

        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz"));
        DecisionService other = DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), "iron example", "someone else");
        Decision theirs = other.slayerTask("krystilia", "abyssal demons", null);
        assertEquals(PermissionStatus.UNKNOWN, theirs.getStatus());
        assertEquals(Decision.Source.TRUST, theirs.getSource());
    }

    /** Older rules, every task key in every golden bundle: owned anywhere, else locked everywhere, else unknown. */
    @Test
    public void everyGoldenTaskFollowsItsChunks() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            JsonObject wire = withoutSlayerTasks(id);
            String json = wire.toString();
            JsonObject chunks = wire.getAsJsonObject("rules").getAsJsonObject("chunks");
            DecisionService service = DecisionService.create(
                RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), null, null);
            List<String> mismatches = new ArrayList<>();
            int locked = 0;
            for (Map.Entry<String, JsonElement> task : wire.getAsJsonObject("slayerChunks").entrySet())
            {
                String key = task.getKey();
                String master = key.contains(":") ? key.substring(0, key.indexOf(':')) : null;
                String name = key.contains(":") ? key.substring(key.indexOf(':') + 1) : key;
                String location = null;
                if (name.contains(" - "))
                {
                    location = name.substring(name.indexOf(" - ") + 3);
                    name = name.substring(0, name.indexOf(" - "));
                }
                JsonArray where = (JsonArray) task.getValue();
                // A plain task the index located nowhere falls back to the monster lists.
                if (where.size() == 0 && master == null && location == null) continue;
                PermissionStatus want = expected(where, chunks);
                if (want == PermissionStatus.LOCKED) locked++;
                PermissionStatus got = service.slayerTask(master, name, location).getStatus();
                if (want != got) mismatches.add(key + " want " + want + " got " + got);
            }
            assertTrue(id + " locks some tasks", locked > 0);
            assertEquals(id, List.of(), mismatches);
        }
    }

    private static PermissionStatus expected(JsonArray where, JsonObject chunks)
    {
        if (where.size() == 0) return PermissionStatus.UNKNOWN;
        boolean allLocked = true;
        for (JsonElement element : where)
        {
            JsonObject at = element.getAsJsonObject();
            JsonObject snapshot = chunks.getAsJsonObject(at.get("cx").getAsInt() + "," + at.get("cy").getAsInt());
            String entry = snapshot == null ? "UNKNOWN" : snapshot.get("entry").getAsString();
            if ("ALLOWED".equals(entry) || "NOT_READY".equals(entry)) return PermissionStatus.ALLOWED;
            if (!"LOCKED".equals(entry)) allLocked = false;
        }
        return allLocked ? PermissionStatus.LOCKED : PermissionStatus.UNKNOWN;
    }

    /** The golden's own character, with older rules: the chunks decide (B11). */
    private static DecisionService playing(String id) throws Exception
    {
        String json = withoutSlayerTasks(id).toString();
        return DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), "iron example", "iron example");
    }

    /** A golden bundle as older rules send it: without the slayerTasks capability. */
    private static JsonObject withoutSlayerTasks(String id) throws Exception
    {
        JsonObject wire = GSON.fromJson(
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz")), JsonObject.class);
        JsonArray capabilities = new JsonArray();
        for (JsonElement capability : wire.getAsJsonObject("rules").getAsJsonArray("capabilities"))
        {
            if (!"slayerTasks".equals(capability.getAsString())) capabilities.add(capability);
        }
        wire.getAsJsonObject("rules").add("capabilities", capabilities);
        return wire;
    }

    /** The golden's own character, with the tracker's Slayer decisions. */
    private static DecisionService trackerPlaying(String id) throws Exception
    {
        return DecisionService.create(RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON,
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz")))),
            "iron example", "iron example");
    }
}

package com.fatelocked;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Scene;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Puts actors on a plain top-level scene the way ChunkLocator reads them
 * (B14): through the actor's world view and local point. The scene is based
 * at 0,0, so a local point is simply the world tile times 128.
 */
final class TestWorld
{
    private TestWorld()
    {
    }

    /** The client's top-level world view, made on first use. */
    static WorldView topLevel(Client client)
    {
        WorldView existing = client.getTopLevelWorldView();
        if (existing != null) return existing;
        WorldView view = mock(WorldView.class);
        Scene scene = mock(Scene.class);
        when(view.isTopLevel()).thenReturn(true);
        when(view.getId()).thenReturn(WorldView.TOPLEVEL);
        when(view.getScene()).thenReturn(scene);
        when(view.getSizeX()).thenReturn(104);
        when(view.getSizeY()).thenReturn(104);
        when(client.getTopLevelWorldView()).thenReturn(view);
        when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(view);
        return view;
    }

    /** Stand an actor (the player, an NPC) on a world tile. */
    static void standAt(Client client, Actor actor, WorldPoint tile)
    {
        WorldView view = topLevel(client);
        LocalPoint point = new LocalPoint(tile.getX() * 128 + 64, tile.getY() * 128 + 64, WorldView.TOPLEVEL);
        when(actor.getWorldView()).thenReturn(view);
        when(actor.getLocalLocation()).thenReturn(point);
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Point;
import java.awt.Rectangle;
import org.junit.Test;

/** U18: world map tiles placed with RuneLite's own maths, so what's drawn lines up with the pins. */
public class WorldMapProjectionTest
{
    private static final float[] ZOOMS = {1.5f, 2f, 3f, 4f, 6f, 8f};
    /** Odd and even sizes, anywhere on the canvas. */
    private static final Rectangle[] MAPS = {
        new Rectangle(35, 60, 700, 470), new Rectangle(8, 11, 701, 471), new Rectangle(0, 0, 517, 333)};
    private static final int[][] CENTRES = {{3200, 3200}, {3201, 3203}, {2999, 3456}};

    /** Exactly where RuneLite puts a pin, and inside its tile, or on the tile's line at a fractional zoom. */
    @Test
    public void everyPinIsWhereRuneLitePutsItOnItsTile()
    {
        for (float zoom : ZOOMS)
        {
            for (Rectangle map : MAPS)
            {
                for (int[] centre : CENTRES)
                {
                    WorldMapProjection projection = new WorldMapProjection(map, zoom, centre[0], centre[1]);
                    for (int tx = centre[0] - 70; tx <= centre[0] + 70; tx += 3)
                    {
                        for (int ty = centre[1] - 70; ty <= centre[1] + 70; ty += 3)
                        {
                            String where = zoom + " " + map + " tile " + tx + "," + ty;
                            Point pin = projection.pin(tx, ty);
                            assertEquals(where, runelite(map, zoom, centre[0], centre[1], tx, ty), pin);
                            assertTrue(where, projection.lineX(tx) <= pin.x && pin.x <= projection.lineX(tx + 1));
                            assertTrue(where, projection.lineY(ty + 1) <= pin.y && pin.y <= projection.lineY(ty));
                        }
                    }
                }
            }
        }
    }

    /** Hovering: the tile under a pixel is the one whose lines hold it, all across the map. */
    @Test
    public void theTileUnderAPixelIsTheOneWhoseLinesHoldIt()
    {
        for (float zoom : ZOOMS)
        {
            for (Rectangle map : MAPS)
            {
                WorldMapProjection projection = new WorldMapProjection(map, zoom, 3201, 3203);
                for (int x = map.x; x < map.x + map.width; x++)
                {
                    int tile = projection.tileX(x);
                    assertTrue(zoom + " x " + x, projection.lineX(tile) <= x && x < projection.lineX(tile + 1));
                }
                for (int y = map.y; y < map.y + map.height; y++)
                {
                    int tile = projection.tileY(y);
                    assertTrue(zoom + " y " + y, projection.lineY(tile + 1) <= y && y < projection.lineY(tile));
                }
            }
        }
    }

    @Test
    public void theChunksInViewCoverTheMap()
    {
        for (float zoom : ZOOMS)
        {
            for (Rectangle map : MAPS)
            {
                WorldMapProjection projection = new WorldMapProjection(map, zoom, 2999, 3456);
                int left = projection.tileX(map.x) >> 6;
                int right = projection.tileX(map.x + map.width - 1) >> 6;
                int top = projection.tileY(map.y) >> 6;
                int bottom = projection.tileY(map.y + map.height - 1) >> 6;
                String where = zoom + " " + map;
                assertTrue(where, projection.westChunk() <= left && right <= projection.eastChunk());
                assertTrue(where, projection.southChunk() <= bottom && top <= projection.northChunk());
            }
        }
    }

    /** RuneLite 1.12.39's WorldMapOverlay.mapWorldPointToGraphicsPoint, transcribed from its bytecode. */
    private static Point runelite(Rectangle worldMapRect, float pixelsPerTile, int positionX, int positionY,
        int worldX, int worldY)
    {
        int widthInTiles = (int) Math.ceil(worldMapRect.getWidth() / pixelsPerTile);
        int heightInTiles = (int) Math.ceil(worldMapRect.getHeight() / pixelsPerTile);
        int yTileMax = positionY - heightInTiles / 2;
        int yTileOffset = (yTileMax - worldY - 1) * -1;
        int xTileOffset = worldX + widthInTiles / 2 - positionX;
        int xGraphDiff = (int) (xTileOffset * pixelsPerTile);
        int yGraphDiff = (int) (yTileOffset * pixelsPerTile);
        yGraphDiff -= pixelsPerTile - Math.ceil(pixelsPerTile / 2);
        xGraphDiff += pixelsPerTile - Math.ceil(pixelsPerTile / 2);
        yGraphDiff = worldMapRect.height - yGraphDiff;
        yGraphDiff += (int) worldMapRect.getY();
        xGraphDiff += (int) worldMapRect.getX();
        return new Point(xGraphDiff, yGraphDiff);
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.fatelocked.SpotMemory.Spot;
import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** The owner's review, 28 Sept: where the Here card's things were seen, kept on this computer. */
public class SpotMemoryTest
{
    private static final Gson GSON = new Gson();
    private static final CanonicalChunk LUMBRIDGE = new CanonicalChunk(50, 50);
    private static final Spot STANDING = new Spot(3205, 3205, 0);

    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    /** A shopkeeper wanders the shop: within three tiles it's the one already known. */
    @Test
    public void aSpotWithinThreeTilesIsTheSameOne()
    {
        SpotMemory spots = new SpotMemory();

        assertTrue(spots.see(LUMBRIDGE, "SHOPS", "Bob's Brilliant Axes", new Spot(3230, 3203, 0)));
        assertFalse(spots.see(LUMBRIDGE, "SHOPS", "Bob's Brilliant Axes", new Spot(3232, 3206, 0)));
        assertTrue(spots.see(LUMBRIDGE, "SHOPS", "Bob's Brilliant Axes", new Spot(3234, 3203, 0)));
        assertTrue("upstairs is another", spots.see(LUMBRIDGE, "SHOPS", "Bob's Brilliant Axes",
            new Spot(3230, 3203, 1)));
    }

    @Test
    public void theNearestIsOnYourFloorFirst()
    {
        SpotMemory spots = new SpotMemory();
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3230, 3230, 0));
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3206, 3206, 1));
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3210, 3200, 0));

        assertEquals(new Spot(3210, 3200, 0), spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
        assertEquals(new Spot(3206, 3206, 1),
            spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3205, 3205, 1)));
        assertEquals("on no floor of the player's, the nearest", new Spot(3206, 3206, 1),
            spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3205, 3205, 2)));
    }

    /** Each chunk and row is its own: an oak here isn't the way to one elsewhere, or to a willow. */
    @Test
    public void eachChunkAndRowIsItsOwn()
    {
        SpotMemory spots = new SpotMemory();
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3210, 3200, 0));

        assertNull(spots.nearest(new CanonicalChunk(51, 50), "SKILLING", "Oak tree", STANDING));
        assertNull(spots.nearest(LUMBRIDGE, "SKILLING", "Willow tree", STANDING));
        assertNull(spots.nearest(LUMBRIDGE, "FARMING", "Oak tree", STANDING));
        assertNull(spots.nearest(null, "SKILLING", "Oak tree", STANDING));
        assertNull(spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", null));
    }

    /** A row keeps the eight spots found last. */
    @Test
    public void aRowKeepsTheLastEightFound()
    {
        SpotMemory spots = new SpotMemory();
        for (int i = 0; i <= SpotMemory.PER_ROW; i++)
        {
            spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3200 + 10 * i, 3200, 0));
        }

        assertEquals("the first found has gone", new Spot(3210, 3200, 0),
            spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3200, 3200, 0)));
        assertEquals(new Spot(3280, 3200, 0), spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree",
            new Spot(3290, 3200, 0)));
    }

    @Test
    public void whatIsSavedIsThereNextTime() throws Exception
    {
        Path file = folder.getRoot().toPath().resolve(SpotMemory.FILE);
        SpotMemory spots = new SpotMemory();
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3210, 3200, 0));
        spots.see(LUMBRIDGE, "BANKS", "Bank booth", new Spot(3208, 3220, 2));
        assertTrue(spots.changed());

        spots.save(GSON, file);
        assertFalse(spots.changed());

        SpotMemory next = new SpotMemory();
        next.load(GSON, file);
        assertEquals(new Spot(3210, 3200, 0), next.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
        assertEquals(new Spot(3208, 3220, 2), next.nearest(LUMBRIDGE, "BANKS", "Bank booth", STANDING));
        assertFalse("reading isn't a change", next.changed());
    }

    /** Two RuneLites on one computer keep each other's spots. */
    @Test
    public void savingKeepsWhatAnotherRuneLiteSaved() throws Exception
    {
        Path file = folder.getRoot().toPath().resolve(SpotMemory.FILE);
        SpotMemory one = new SpotMemory();
        SpotMemory two = new SpotMemory();
        one.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3210, 3200, 0));
        two.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3240, 3240, 0));

        one.save(GSON, file);
        two.save(GSON, file);

        SpotMemory next = new SpotMemory();
        next.load(GSON, file);
        assertEquals(new Spot(3210, 3200, 0), next.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
        assertEquals(new Spot(3240, 3240, 0), next.nearest(LUMBRIDGE, "SKILLING", "Oak tree",
            new Spot(3245, 3245, 0)));
        assertEquals("and the second knows the first's now", new Spot(3210, 3200, 0),
            two.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
    }

    /** A spot found empty is forgotten, and stays forgotten: the file loses it at the next save. */
    @Test
    public void aForgottenSpotStaysForgotten() throws Exception
    {
        Path file = folder.getRoot().toPath().resolve(SpotMemory.FILE);
        SpotMemory spots = new SpotMemory();
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3210, 3200, 0));
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3240, 3240, 0));
        spots.save(GSON, file);

        spots.forget(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3211, 3201, 0));
        assertTrue(spots.changed());
        assertEquals(new Spot(3240, 3240, 0), spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
        spots.load(GSON, file);
        assertEquals("the file doesn't bring it back", new Spot(3240, 3240, 0),
            spots.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
        spots.save(GSON, file);

        SpotMemory next = new SpotMemory();
        next.load(GSON, file);
        assertEquals(new Spot(3240, 3240, 0), next.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));

        next.forget(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3240, 3240, 0));
        next.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3240, 3240, 0));
        next.save(GSON, file);
        SpotMemory last = new SpotMemory();
        last.load(GSON, file);
        assertEquals("seen again after, it's back", new Spot(3240, 3240, 0),
            last.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
    }

    /** A damaged file is set aside, as the plugin's other files are, and nothing is lost by it. */
    @Test
    public void aDamagedFileIsSetAside() throws Exception
    {
        Path file = folder.getRoot().toPath().resolve(SpotMemory.FILE);
        Files.write(file, "not the spots".getBytes(StandardCharsets.UTF_8));
        SpotMemory spots = new SpotMemory();

        spots.load(GSON, file);

        assertFalse(Files.exists(file));
        try (Stream<Path> kept = Files.list(folder.getRoot().toPath()))
        {
            assertTrue(kept.anyMatch(path -> path.getFileName().toString().startsWith(SpotMemory.FILE + ".corrupt-")));
        }
        spots.see(LUMBRIDGE, "SKILLING", "Oak tree", new Spot(3210, 3200, 0));
        spots.save(GSON, file);
        SpotMemory next = new SpotMemory();
        next.load(GSON, file);
        assertEquals(new Spot(3210, 3200, 0), next.nearest(LUMBRIDGE, "SKILLING", "Oak tree", STANDING));
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import com.fatelocked.ui.Palette;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import org.junit.Before;
import org.junit.Test;

/** U20: the fade frames the view once, in the palette's locked colour, and is gone after it ends. */
public class FateLockedFlashOverlayTest
{
    private final Client client = mock(Client.class);
    private final FateLockedPlugin plugin = mock(FateLockedPlugin.class);
    /** The fade began at 5 s on the test's own clock. */
    private static final long BEGAN = 5_000_000_000L;
    private long now = BEGAN;
    private final FateLockedFlashOverlay overlay = new FateLockedFlashOverlay(client, plugin, () -> now);

    @Before
    public void setUp()
    {
        when(client.getCanvasWidth()).thenReturn(200);
        when(client.getCanvasHeight()).thenReturn(150);
        when(plugin.palette()).thenReturn(Palette.defaults());
    }

    @Test
    public void noFadeOrAnEndedOneDrawsNothing()
    {
        Graphics2D graphics = mock(Graphics2D.class);
        when(plugin.getLockedFadeAt()).thenReturn(FateLockedPlugin.NO_FADE);
        assertNull(overlay.render(graphics));
        when(plugin.getLockedFadeAt()).thenReturn(BEGAN);
        now = BEGAN + FlashFade.DURATION_MS * 1_000_000;
        assertNull(overlay.render(graphics));
        verifyNoInteractions(graphics);
    }

    @Test
    public void aFreshFadeFramesTheViewInThePalettesLockedColour()
    {
        Palette custom = Palette.of(Palette.Preset.CUSTOM, new Color(0, 128, 255, 110),
            new Color(255, 255, 0, 100), new Color(128, 0, 128, 110));
        when(plugin.palette()).thenReturn(custom);
        when(plugin.getLockedFadeAt()).thenReturn(BEGAN);
        BufferedImage image = new BufferedImage(200, 150, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        Composite before = graphics.getComposite();

        overlay.render(graphics);

        Color edge = new Color(image.getRGB(3, 75), true);
        assertTrue("the palette's locked colour, give or take compositing: " + edge,
            Math.abs(edge.getRed() - 128) <= 1 && edge.getGreen() <= 1 && Math.abs(edge.getBlue() - 128) <= 1);
        assertTrue("its strongest at the start: " + edge.getAlpha(), Math.abs(edge.getAlpha() - FlashFade.MAX_ALPHA) <= 1);
        assertEquals("the view itself is untouched", 0, image.getRGB(100, 75) >>> 24);
        assertSame("the composite is put back", before, graphics.getComposite());
        graphics.dispose();
    }
}

package com.fatelocked;

import org.junit.Test;

import java.lang.reflect.Field;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * The diary tiers are read through RuneLite's gameval ids. Their numbers must
 * stay the ones the deprecated Varbits constants had, in the order the tier
 * names use.
 */
public class DiaryVarbitIdsTest
{
    @Test
    public void diaryTiersKeepTheirVarbitIds() throws Exception
    {
        assertArrayEquals(new int[] {
            4458, 4459, 4460, 4461, // Ardougne
            4483, 4484, 4485, 4486, // Desert
            4462, 4463, 4464, 4465, // Falador
            4491, 4492, 4493, 4494, // Fremennik
            4475, 4476, 4477, 4478, // Kandarin
            3578, 3599, 3611, 4566, // Karamja
            7925, 7926, 7927, 7928, // Kourend & Kebos
            4495, 4496, 4497, 4498, // Lumbridge & Draynor
            4487, 4488, 4489, 4490, // Morytania
            4479, 4480, 4481, 4482, // Varrock
            4471, 4472, 4473, 4474, // Western Provinces
            4466, 4467, 4468, 4469, // Wilderness
        }, (int[]) staticField("DIARY_VARBITS"));
    }

    @Test
    public void eachTierIdNamesItsOwnTier() throws Exception
    {
        @SuppressWarnings("unchecked")
        Map<Integer, String> names = (Map<Integer, String>) staticField("DIARY_VARBIT_NAMES");
        assertEquals(48, names.size());
        assertEquals("Ardougne Easy", names.get(4458));
        assertEquals("Karamja Easy", names.get(3578));
        assertEquals("Karamja Elite", names.get(4566));
        assertEquals("Lumbridge & Draynor Easy", names.get(4495));
        assertEquals("Wilderness Elite", names.get(4469));
    }

    /**
     * Events name each tier by the tracker's id, the keys of DIARIES in the
     * web app's data/diaryData.ts; three regions there are shorter than
     * their full names. Tiers named otherwise matched no tracker task.
     */
    @Test
    public void eventsUseTheTrackersTierIds() throws Exception
    {
        @SuppressWarnings("unchecked")
        Map<Integer, String> ids = (Map<Integer, String>) staticField("DIARY_TIER_IDS");
        Set<String> tracker = new HashSet<>();
        for (String region : new String[] {"Ardougne", "Desert", "Falador", "Fremennik",
            "Kandarin", "Karamja", "Kourend", "Lumbridge", "Morytania", "Varrock", "Western",
            "Wilderness"})
        {
            for (String tier : new String[] {"Easy", "Medium", "Hard", "Elite"})
            {
                tracker.add(region + " " + tier);
            }
        }

        assertEquals(tracker, new HashSet<>(ids.values()));
        assertEquals("Lumbridge Easy", ids.get(4495));
        assertEquals("Kourend Elite", ids.get(7928));
        assertEquals("Western Hard", ids.get(4473));
    }

    private static Object staticField(String name) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(null);
    }
}

package com.fatelocked.panel;

import org.junit.Test;

import java.time.Instant;
import java.time.ZoneId;

import static org.junit.Assert.assertEquals;

public class LocalTimeTextTest
{
    private static final ZoneId LONDON = ZoneId.of("Europe/London");
    /** Saturday 26 September 2026, 18:00 in London (BST). */
    private static final Instant NOW = Instant.parse("2026-09-26T17:00:00Z");

    @Test
    public void todayIsJustTheTimeOnThePlayersClock()
    {
        assertEquals("17:03", LocalTimeText.of(Instant.parse("2026-09-26T16:03:00Z"), NOW, LONDON));
        assertEquals("16:03", LocalTimeText.of(
            Instant.parse("2026-09-26T16:03:00Z"), NOW, ZoneId.of("UTC")));
    }

    @Test
    public void withinAWeekTheDayIsNamed()
    {
        assertEquals("Wed 09:15", LocalTimeText.of(Instant.parse("2026-09-23T08:15:00Z"), NOW, LONDON));
        // A check due just after midnight.
        assertEquals("Sun 00:05", LocalTimeText.of(Instant.parse("2026-09-26T23:05:00Z"), NOW, LONDON));
    }

    @Test
    public void furtherOffTheDateIsShown()
    {
        assertEquals("27 Jul 15:05", LocalTimeText.of(Instant.parse("2026-07-27T14:05:06Z"), NOW, LONDON));
        assertEquals("19 Sep 18:00", LocalTimeText.of(Instant.parse("2026-09-19T17:00:00Z"), NOW, LONDON));
