package com.fatelocked;

import com.google.gson.Gson;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * B11: what the Slayer task messages tell the plugin. Konar's place is kept,
 * the master comes from SLAYER_MASTER only for values RuneLite relies on
 * (7 Krystilia, 10 Mortimer), and the warning follows the decision service:
 * in vanilla-mid Krystilia's abyssal demons warn, anyone else's don't.
 */
public class SlayerChatTest
{
    private static final String GEM_CHECK = "You're assigned to kill bears; only 42 more to go.";
    private static final String KONAR_CHECK =
        "You're assigned to kill aberrant spectres in the Catacombs of Kourend; only 105 more to go.";

    private final FateLockedPlugin plugin = new FateLockedPlugin();
    private final FateLockedConfig config = mock(FateLockedConfig.class);
    private final Client client = mock(Client.class);
    private final Player player = mock(Player.class);
    private final ChatMessageManager chat = mock(ChatMessageManager.class);

    @Test
    public void theMessageGivesTheTaskAndKonarsPlace()
    {
        SlayerAssignment goblins = SlayerAssignment.fromChat("You're assigned to kill goblins; only 20 more to go.", 0);
        assertEquals(new SlayerAssignment("goblins", null, null), goblins);
        assertEquals(new SlayerAssignment("aberrant spectres", "Catacombs of Kourend", SlayerAssignment.KONAR),
            SlayerAssignment.fromChat(KONAR_CHECK, 0));
        assertEquals(new SlayerAssignment("aberrant spectres", "Slayer Tower", SlayerAssignment.KONAR),
            SlayerAssignment.fromChat("Your new task is to kill 105 aberrant spectres in the Slayer Tower.", 0));
        assertEquals("Kalphite Queen",
            SlayerAssignment.fromChat("You're assigned to kill the Kalphite Queen; only 3 more to go.", 0).getTask());
        assertNull(SlayerAssignment.fromChat("Welcome to Old School RuneScape.", 0));
        assertNull(SlayerAssignment.fromChat(null, 0));
    }

    @Test
    public void onlyVerifiedMasterValuesNameAMaster()
    {
        assertEquals("krystilia", SlayerAssignment.fromChat(GEM_CHECK, 7).getMaster());
        assertEquals("mortimer", SlayerAssignment.fromChat(GEM_CHECK, 10).getMaster());
        for (int unverified : new int[] { 0, 1, 3, 6, 8, 9, 11 })
        {
            assertNull(String.valueOf(unverified), SlayerAssignment.fromChat(GEM_CHECK, unverified).getMaster());
        }
    }

    @Before
    public void setUp() throws Exception
    {
        when(config.ruleWarnings()).thenReturn(true);
        when(player.getName()).thenReturn("Iron Example");
        when(client.getLocalPlayer()).thenReturn(player);
        set("config", config);
        set("client", client);
        set("chatMessageManager", chat);
        set("notifier", mock(Notifier.class));
        set("active", new ActiveRules(FateLockedBundle.loadFromJson(new Gson(),
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-interiors.bundle.json.gz"))),
            FateLockedPlugin.RulesSource.RELAY));
        refreshDecisions();
    }

    @Test
    public void krystiliasTaskWarnsAndTheSameTaskFromAnyoneElseDoesNot() throws Exception
    {
        assertEquals(List.of(), say(GEM_CHECK, 0));
        assertNull(plugin.getSlayerTaskWarn());

        // In vanilla-interiors Krystilia's bears are all in the locked Wilderness; anyone else's aren't (R16).
        List<String> lines = say(GEM_CHECK, 7);
        assertEquals(1, lines.size());
        assertTrue(lines.get(0), lines.get(0).contains("bears") && lines.get(0).contains("is locked: Area locked."));
        assertEquals("bears", plugin.getSlayerTaskWarn());

        // Not ready (Slayer 85) never alerts.
        assertEquals(List.of(), say("You're assigned to kill abyssal demons; only 42 more to go.", 0));
        assertNull(plugin.getSlayerTaskWarn());
    }

    @Test
    public void konarsPlaceDecides() throws Exception
    {
        List<String> lines = say(KONAR_CHECK, 0);
        assertEquals(1, lines.size());
        assertTrue(lines.get(0), lines.get(0).contains("is locked: Master: Mount Karuulm."));
        assertEquals("aberrant spectres", plugin.getSlayerTaskWarn());
    }

    @Test
    public void anotherCharacterGetsNoWarningAndForgetsTheLastOnesTask() throws Exception
    {
        say(GEM_CHECK, 7);
        assertEquals("bears", plugin.getSlayerTaskWarn());

        // A different account logs in: the last character's task goes with it.
        when(player.getName()).thenReturn("Someone Else");
        when(client.getAccountHash()).thenReturn(99L);
        GameStateChanged loggedIn = new GameStateChanged();
        loggedIn.setGameState(GameState.LOGGED_IN);
        plugin.onGameStateChanged(loggedIn);
        assertNull(plugin.getSlayerTaskWarn());

        refreshDecisions();
        assertEquals(List.of(), say(GEM_CHECK, 7));
        assertNull(plugin.getSlayerTaskWarn());
    }

    /**
     * D3: with rule warnings off, a locked task gets no line. Turning them on works the task
     * out again and warns once.
     */
    @Test
    public void theRuleWarningsSwitchDecidesTheSlayerWarning() throws Exception
    {
        when(config.ruleWarnings()).thenReturn(false);
        assertEquals(List.of(), say(GEM_CHECK, 7));
        assertNull(plugin.getSlayerTaskWarn());

        when(config.ruleWarnings()).thenReturn(true);
        GearDecisionTest.configChanged(plugin, "ruleWarnings");
        assertEquals("bears", plugin.getSlayerTaskWarn());
        assertEquals(1, queued().size());

        when(config.ruleWarnings()).thenReturn(false);
        GearDecisionTest.configChanged(plugin, "ruleWarnings");
        assertNull(plugin.getSlayerTaskWarn());
    }

    /** The chat lines queued since the last clear. */
    private List<String> queued()
    {
        ArgumentCaptor<QueuedMessage> queued = ArgumentCaptor.forClass(QueuedMessage.class);
        verify(chat, atLeast(0)).queue(queued.capture());
        List<String> lines = new ArrayList<>();
        for (QueuedMessage line : queued.getAllValues()) lines.add(line.getRuneLiteFormattedMessage());
        return lines;
    }

    /** A game message with this SLAYER_MASTER value; the chat lines it queued. */
    private List<String> say(String message, int master)
    {
        clearInvocations(chat);
        when(client.getVarbitValue(VarbitID.SLAYER_MASTER)).thenReturn(master);
        ChatMessage event = new ChatMessage();
        event.setType(ChatMessageType.GAMEMESSAGE);
        event.setMessage(message);
        plugin.onChatMessage(event);
        return queued();
    }

    private void refreshDecisions() throws Exception
    {
        Method refresh = FateLockedPlugin.class.getDeclaredMethod("refreshDecisions");
        refresh.setAccessible(true);
        refresh.invoke(plugin);
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/** U18, decision 4: the world map shades what's locked, fills the frontier, and outlines the rest. */
public class WorldMapModelTest
{
    private static final Gson GSON = new Gson();

    /** WorldMapChunks.fill stays the oracle: the runs are its locked land and frontier, nothing else. */
    @Test
    public void everyGoldensLockedLandAndFrontierIsDrawnAndItsUnlockedLandIsClear() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            DecisionService playing = playing(id);
            WorldMapModel model = WorldMapModel.of(playing);

            Map<CanonicalChunk, WorldMapChunks.Fill> fills = new HashMap<>();
            Map<CanonicalChunk, WorldMapChunks.Fill> want = new HashMap<>();
            for (CanonicalChunk chunk : playing.mappedChunks())
            {
                WorldMapChunks.Fill fill = WorldMapChunks.fill(playing, chunk);
                if (fill == null) continue;
                fills.put(chunk, fill);
                if (fill != WorldMapChunks.Fill.UNLOCKED) want.put(chunk, fill);
            }
            Map<CanonicalChunk, WorldMapChunks.Fill> drawn = new HashMap<>();
            WorldMapModel.Run previous = null;
            for (WorldMapModel.Run run : model.runs())
            {
                for (int cx = run.getCx0(); cx <= run.getCx1(); cx++)
                {
                    assertNull(id + " drawn once", drawn.put(new CanonicalChunk(cx, run.getCy()), run.getFill()));
                }
                assertFalse(id + " touching runs of one fill are joined", previous != null
                    && previous.getCy() == run.getCy() && previous.getCx1() + 1 == run.getCx0()
                    && previous.getFill() == run.getFill());
                previous = run;
            }
            assertEquals(id, want, drawn);
            assertEquals(id + " outlines its unlocked land", outline(fills), units(model));
        }
    }

    @Test
    public void anotherCharacterGetsAClearMap() throws Exception
    {
        DecisionService other = DecisionService.create(playing("vanilla-mid").rules(), "iron example", "someone else");
        WorldMapModel model = WorldMapModel.of(other);
        assertTrue(model.runs().isEmpty());
        assertTrue(model.outline().isEmpty());
    }

    /** The map is clipped as RuneLite clips it: never over the overview or the surface selector. */
    @Test
    public void theOverviewAndTheSelectorAreLeftOutWhereShown()
    {
        Rectangle map = new Rectangle(0, 0, 700, 470);
        Area clip = WorldMapClip.of(map, new Rectangle(500, 320, 200, 150), new Rectangle(0, 0, 150, 40));
        assertFalse("the overview", clip.contains(600, 400));
        assertFalse("the surface selector", clip.contains(20, 20));
        assertTrue(clip.contains(300, 200));

        Area hidden = WorldMapClip.of(map, null, null);
        assertTrue(hidden.contains(600, 400));
        assertTrue(hidden.contains(20, 20));
    }

    /**
     * Tutorial Island is free but off the tracker's map, so the map leaves it clear. The line
     * still goes all the way round the unlocked land, along Wizards' Tower's south side.
     */
    @Test
    public void theOutlineClosesWhereTheTrackersMapStops() throws Exception
    {
        DecisionService playing = playing("vanilla-fresh");
        CanonicalChunk wizardsTower = new CanonicalChunk(48, 49);
        CanonicalChunk tutorialIsland = new CanonicalChunk(48, 48);
        assertEquals(WorldMapChunks.Fill.UNLOCKED, WorldMapChunks.fill(playing, wizardsTower));
        assertNull("off the tracker's map", WorldMapChunks.fill(playing, tutorialIsland));

        assertTrue(units(WorldMapModel.of(playing)).contains("H49,48"));
    }

    /** Each unit of outline wanted: every side where unlocked land meets land that isn't unlocked. */
    private static Set<String> outline(Map<CanonicalChunk, WorldMapChunks.Fill> fills)
    {
        Set<String> units = new HashSet<>();
        for (Map.Entry<CanonicalChunk, WorldMapChunks.Fill> chunk : fills.entrySet())
        {
            if (chunk.getValue() != WorldMapChunks.Fill.UNLOCKED) continue;
            int cx = chunk.getKey().getCx();
            int cy = chunk.getKey().getCy();
            if (!unlocked(fills, cx - 1, cy)) units.add("V" + cx + "," + cy);
            if (!unlocked(fills, cx + 1, cy)) units.add("V" + (cx + 1) + "," + cy);
            if (!unlocked(fills, cx, cy - 1)) units.add("H" + cy + "," + cx);
            if (!unlocked(fills, cx, cy + 1)) units.add("H" + (cy + 1) + "," + cx);
        }
        return units;
    }

    private static boolean unlocked(Map<CanonicalChunk, WorldMapChunks.Fill> fills, int cx, int cy)
    {
        return fills.get(new CanonicalChunk(cx, cy)) == WorldMapChunks.Fill.UNLOCKED;
    }

    /** The model's outline, cut back into units; stretches that meet are joined. */
    private static Set<String> units(WorldMapModel model)
    {
        Set<String> units = new HashSet<>();
        WorldMapModel.Edge previous = null;
        for (WorldMapModel.Edge edge : model.outline())
        {
            assertFalse("stretches that meet are joined: " + edge, previous != null
                && previous.isVertical() == edge.isVertical() && previous.getLine() == edge.getLine()
                && previous.getTo() == edge.getFrom());
            previous = edge;
            for (int at = edge.getFrom(); at < edge.getTo(); at++)
            {
                assertTrue("each unit once", units.add((edge.isVertical() ? "V" : "H") + edge.getLine() + "," + at));
            }
        }
        return units;
    }

    private static DecisionService playing(String id) throws Exception
    {
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
        JsonElement bound = GSON.fromJson(json, JsonObject.class).getAsJsonObject("rules").get("account");
        String account = bound == null || bound.isJsonNull() ? null : AccountBinding.normalize(bound.getAsString());
        return DecisionService.create(RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), account, account);
    }
}

