package com.fatelocked;

import com.fatelocked.rules.TravelTable;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * F4 (G14): the " (Locked)" tag on a travel option is the tracker's exact
 * decision, the one Strict Mode reads. On every golden, every option of
 * every method in the travel table, clicked as the game gives it, is tagged
 * exactly when the tracker locks it and it goes to one place: networks and
 * boats too, which Strict Mode never blocks. So every trip Strict Mode
 * blocks was tagged first. Another character sees no tags.
 */
@RunWith(Parameterized.class)
public class TagConsistencyTest
{
    private static final Gson GSON = new Gson();
    private static final String TAG = " <col=f87171>(Locked)</col>";

    @Parameterized.Parameters(name = "{0}")
    public static List<Object[]> scenarios() throws IOException
    {
        return GoldenBundleContractTest.scenarios();
    }

    private final String id;
    private final FateLockedBundle bundle;
    private final JsonObject travel;
    private final FateLockedPlugin plugin = new FateLockedPlugin();
    private final Client client = mock(Client.class);

    public TagConsistencyTest(String id) throws Exception
    {
        this.id = id;
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
        bundle = FateLockedBundle.loadFromJson(GSON, json);
        travel = GSON.fromJson(json, JsonObject.class).getAsJsonObject("rules").getAsJsonObject("travel");
        FateLockedConfig config = mock(FateLockedConfig.class);
        when(config.tagLockedOptions()).thenReturn(true);
        set("config", config);
        set("client", client);
        set("active", new ActiveRules(bundle, FateLockedPlugin.RulesSource.RELAY));
    }

    @Test
    public void aTravelTagIsAnExactLockedDecision() throws Exception
    {
        playing("Iron Example");
        List<String> want = new ArrayList<>();
        for (Map.Entry<String, JsonElement> method : travel.entrySet())
        {
            JsonObject row = method.getValue().getAsJsonObject();
            addLocked(method.getKey(), row.getAsJsonObject("options"), false, want);
            if (row.has("codes")) addLocked(method.getKey(), row.getAsJsonObject("codes"), true, want);
        }
        assertTrue(id + " locks some trip", !want.isEmpty());
        assertEquals(id, want, tagged());
    }

    @Test
    public void anotherCharacterSeesNoTravelTags() throws Exception
    {
        if (bundle.getRules().getAccount() == null) return;
        playing("Someone Else");
        assertEquals(id, List.of(), tagged());
    }

    private static void addLocked(String method, JsonObject options, boolean codes, List<String> into)
    {
        for (Map.Entry<String, JsonElement> option : options.entrySet())
        {
            JsonObject decided = option.getValue().getAsJsonObject();
            if ("LOCKED".equals(decided.get("status").getAsString()) && decided.getAsJsonArray("to").size() == 1)
            {
                into.add(method + "|" + (codes ? "Last-destination (" + option.getKey() + ")" : option.getKey()));
            }
        }
    }

    /** Every option of every method, clicked on its first id; those the plugin tagged. */
    private List<String> tagged()
    {
        List<String> tagged = new ArrayList<>();
        for (TravelTable.Method method : bundle.getRules().getTravel().methods())
        {
            for (String option : GoldenBundleContractTest.texts(method))
            {
                MenuEntry entry = entry(method, option);
                String before = entry.getTarget();
                plugin.onMenuEntryAdded(new MenuEntryAdded(entry));
                if (entry.getTarget().equals(before + TAG)) tagged.add(method.getId() + "|" + option);
            }
        }
        return tagged;
    }

    /** The option as the game gives it: a spell with its book active, or the method's first id. */
    private MenuEntry entry(TravelTable.Method method, String option)
    {
        int first = method.getIds().isEmpty() ? -1 : method.getIds().iterator().next();
        switch (method.getMatch())
        {
            case SPELL:
                when(client.getVarbitValue(VarbitID.SPELLBOOK))
                    .thenReturn(TravelTable.SPELLBOOKS.indexOf(method.getSpellbook()));
                return TravelClicks.spell(option, method.getSpell()).getMenuEntry();
            case ITEMS:
                return TravelClicks.item(first, option, method.getLabel()).getMenuEntry();
            case OBJECTS:
                return TravelClicks.object(first, option, method.getLabel()).getMenuEntry();
            default:
                return TravelClicks.npc(first, option, method.getLabel()).getMenuEntry();
        }
    }

    private void playing(String name) throws Exception
    {
        Player player = mock(Player.class);
        when(player.getName()).thenReturn(name);
        when(client.getLocalPlayer()).thenReturn(player);
        Method refresh = FateLockedPlugin.class.getDeclaredMethod("refreshDecisions");
        refresh.setAccessible(true);
        refresh.invoke(plugin);
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;

/**
 * The golden bundles with one root field changed, to prove that a v4
 * bundle's answers come from its rules and not from leftover root fields.
 */
@RunWith(Parameterized.class)
public class GoldenBundleMutationTest
{
    private static final Gson GSON = new Gson();

    @Parameterized.Parameters(name = "{0}")
    public static List<Object[]> scenarios() throws IOException
    {
        return GoldenBundleContractTest.scenarios();
    }

    private final String id;
    private final JsonObject wire;
    private final JsonObject expected;

    public GoldenBundleMutationTest(String id) throws IOException
    {
        this.id = id;
        wire = GSON.fromJson(GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz")),
            JsonObject.class);
        expected = GoldenBundleContractTest.json(id + ".expect.json");
    }

    /**
     * R10: the mere presence of a root unlockedChunks list used to turn any
     * v4 run into a Chunked one. Only the rules decide that now.
     */
    @Test
    public void strayRootUnlockedChunksChangeNothing()
    {
        FateLockedBundle original = FateLockedBundle.loadFromJson(GSON, wire.toString());
        JsonObject mutated = wire.deepCopy();
        mutated.add("unlockedChunks", new JsonArray());
        FateLockedBundle stray = FateLockedBundle.loadFromJson(GSON, mutated.toString());

        assertEquals(id, original.isChunkedBundle(), stray.isChunkedBundle());
        List<String> changed = new ArrayList<>();
        for (String key : expected.getAsJsonObject("chunks").keySet())
        {
            CanonicalChunk chunk = GoldenBundleContractTest.chunk(key);
            if (original.lockStateAt(chunk) != stray.lockStateAt(chunk)) changed.add(key);
        }
        assertEquals(id + " chunks", List.of(), changed);
        assertEquals(id + " areas", original.getUnlockedAreas(), stray.getUnlockedAreas());
        assertEquals(id + " area total", original.getTotalAreas(), stray.getTotalAreas());
    }
}

package com.fatelocked.storage;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class LocalFileMergeTest
{
    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    @Test
    public void eachUpdateMergesIntoTheFileAsItIsNow() throws Exception
    {
        Path file = folder.getRoot().toPath().resolve("state.json");

        LocalFileMerge.update(file, current -> {
            assertNull(current);
            return bytes("a");
        });
        LocalFileMerge.update(file, current -> bytes(text(current) + "b"));

        assertEquals("ab", text(Files.readAllBytes(file)));
    }

    @Test
    public void aMergeWithNothingToWriteLeavesTheFile() throws Exception
    {
        Path file = folder.getRoot().toPath().resolve("state.json");
        LocalFileMerge.update(file, current -> bytes("kept"));

        LocalFileMerge.update(file, current -> null);

        assertEquals("kept", text(Files.readAllBytes(file)));
    }

    @Test
    public void aFailedWriteLeavesTheFileAsItWasAndNoTempFileBehind() throws Exception
    {
        Path dir = folder.getRoot().toPath();
        Path file = dir.resolve("state.json");
        LocalFileMerge.update(file, current -> bytes("kept"));

        try
        {
            LocalFileMerge.update(file, current -> bytes("new"),
                (target, contents) -> { throw new IOException("disk full"); });
            fail("the write should fail");
        }
        catch (IOException expected)
        {
            // The update reports it.
        }

        assertEquals("kept", text(Files.readAllBytes(file)));
        assertEquals(Set.of("state.json", "state.json.lock"), names(dir));
    }

    @Test
    public void aMoveThatFailsLeavesNoTempFileBehind() throws Exception
    {
        Path dir = folder.getRoot().toPath();
        // A directory with something in it can't be replaced by a file.
        Path file = Files.createDirectory(dir.resolve("state.json"));
        Files.write(file.resolve("inside"), bytes("x"));

        try
        {
            LocalFileMerge.replace(file, bytes("new"));
            fail("the move should fail");
        }
        catch (IOException expected)
        {
            // The write reports it.
        }

        assertEquals(Set.of("state.json"), names(dir));
    }

    @Test
    public void aDamagedFileIsKeptAside() throws Exception
    {
        Path dir = folder.getRoot().toPath();
        Path file = dir.resolve("state.json");
        Files.write(file, bytes("{damaged"));

        LocalFileMerge.moveAside(file);

        Set<String> names = names(dir);
        assertEquals(1, names.size());
        String kept = names.iterator().next();
        assertTrue(kept, kept.startsWith("state.json.corrupt-"));
        assertEquals("{damaged", text(Files.readAllBytes(dir.resolve(kept))));
    }

    private static Set<String> names(Path dir) throws IOException
    {
        try (Stream<Path> files = Files.list(dir))
        {
            return files.map(path -> path.getFileName().toString()).collect(Collectors.toSet());
        }
    }

    private static byte[] bytes(String text)
    {
        return text.getBytes(StandardCharsets.UTF_8);
    }

    private static String text(byte[] bytes)
    {
        return new String(bytes, StandardCharsets.UTF_8);
    }
}

package com.fatelocked;

import org.junit.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * B14: ChunkLocator is the one reader of where the player and menu targets
 * are, so instances and boats are placed the same way everywhere. No other
 * production class reads a raw world location or the client's deprecated
 * scene calls, which ignore world views.
 */
public class LocationBoundaryTest
{
    private static final String[] FORBIDDEN = {
        "getWorldLocation(",
        "WorldChunks.of(",
        "WorldPoint.fromScene(client",
        "LocalPoint.fromWorld(client",
        "client.getPlane(",
        "client.getBaseX(",
        "client.getBaseY(",
    };

    @Test
    public void onlyTheChunkLocatorReadsWhereThingsAre() throws IOException
    {
        List<String> offenders = new ArrayList<>();
        List<Path> sources = sources();
        for (Path source : sources)
        {
            String name = source.getFileName().toString();
            if (name.equals("ChunkLocator.java") || name.equals("WorldChunks.java")) continue;
            String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);
            for (String call : FORBIDDEN)
            {
                if (text.contains(call)) offenders.add(name + ": " + call);
            }
        }
        assertTrue("the production sources are found", sources.size() > 50);
        assertEquals(new ArrayList<String>(), offenders);
    }

    private static List<Path> sources() throws IOException
    {
        try (Stream<Path> paths = Files.walk(Paths.get("src", "main", "java")))
        {
            return paths.filter(path -> path.toString().endsWith(".java")).sorted().collect(Collectors.toList());
        }
    }
}

