package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.Test;

public class NoticesTest
{
    private static final Instant NOW = Instant.parse("2026-10-01T12:00:00Z");

    @Test
    public void aNoticeSaysWhatHappenedAndWhenNeverACountOfRegions()
    {
        assertEquals("Imported rules from the clipboard, exported at 11:58.",
            Notices.imported(NOW.minusSeconds(120), NOW, ZoneOffset.UTC));
        assertEquals("Loaded the newest backup file, exported at Mon 12:00.",
            Notices.loadedBackupFile(NOW.minusSeconds(3 * 24 * 3600), NOW, ZoneOffset.UTC));
        assertEquals("Loaded the newest backup file.", Notices.loadedBackupFile(null, NOW, ZoneOffset.UTC));
        assertEquals("Restored the rules saved at 09:15.",
            Notices.restored(Instant.parse("2026-10-01T09:15:00Z"), NOW, ZoneOffset.UTC));
    }

    @Test
    public void everyNoticeIsASentence() throws Exception
    {
        for (Field field : Notices.class.getDeclaredFields())
        {
            if (!Modifier.isStatic(field.getModifiers()) || field.getType() != String.class)
            {
                continue;
            }
            field.setAccessible(true);
            String notice = (String) field.get(null);
            assertTrue(notice, Character.isUpperCase(notice.charAt(0)));
            assertTrue(notice, notice.endsWith("."));
            assertFalse(notice, notice.contains("\u2014"));
            assertFalse(notice, notice.contains("regions"));
        }
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import com.fatelocked.ui.Palette;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import org.junit.Before;
import org.junit.Test;

/**
 * E6: the HUD draws the plugin's model on RuneLite's own panel, labels plain and values in the
 * palette's tones, and builds the panel again only when the model or the palette changes.
 */
public class FateLockedHudOverlayTest
{
    private final FateLockedPlugin plugin = mock(FateLockedPlugin.class);
    private final FateLockedHudOverlay overlay = new FateLockedHudOverlay(plugin);
    private final Palette palette = Palette.defaults();

    private static final HudModel COMPACT = new HudModel(Arrays.asList(
        new HudModel.Line("Here", "Lumbridge", null),
        new HudModel.Line("Status", "Locked", Palette.Tone.BAD),
        HudModel.Line.heading("Quests"),
        new HudModel.Line("+2 more", null, Palette.Tone.NEUTRAL)), false);

    @Before
    public void setUp()
    {
        when(plugin.palette()).thenReturn(palette);
        when(plugin.hudModel()).thenReturn(COMPACT);
    }

    @Test
    public void theModelsLinesAreDrawnInThePalettesColours() throws Exception
    {
        render();

        List<LayoutableRenderableEntity> children = overlay.getPanelComponent().getChildren();
        assertEquals("the title and one per line", 5, children.size());
        TitleComponent title = (TitleComponent) children.get(0);
        assertEquals("Fate Locked", field(title, "text"));
        assertEquals(Palette.ACCENT, field(title, "color"));

        assertLine(children.get(1), "Here", Palette.TITLE, "Lumbridge", Palette.TITLE);
        assertLine(children.get(2), "Status", Palette.TITLE, "Locked", palette.text(Palette.Tone.BAD));
        assertLine(children.get(3), "Quests", Palette.ACCENT, null, null);
        assertLine(children.get(4), "+2 more", palette.text(Palette.Tone.NEUTRAL), null, null);
        assertEquals(165, overlay.getPanelComponent().getPreferredSize().width);
    }

    @Test
    public void detailedIsWiderForWhatThePlaceHolds()
    {
        when(plugin.hudModel()).thenReturn(new HudModel(COMPACT.getLines(), true));
        render();
        assertEquals(210, overlay.getPanelComponent().getPreferredSize().width);
    }

    @Test
    public void noHudDrawsNothing()
    {
        when(plugin.hudModel()).thenReturn(HudModel.NONE);
        Graphics2D graphics = mock(Graphics2D.class);
        assertNull(overlay.render(graphics));
        verifyNoInteractions(graphics);
        assertTrue(overlay.getPanelComponent().getChildren().isEmpty());
    }

    @Test
    public void thePanelIsBuiltAgainOnlyWhenTheModelOrPaletteChanges() throws Exception
    {
        render();
        Object status = overlay.getPanelComponent().getChildren().get(2);
        render();
        assertSame("nothing changed: the same panel", status, overlay.getPanelComponent().getChildren().get(2));

        Palette custom = Palette.of(Palette.Preset.CUSTOM, new Color(0, 128, 255, 110),
            new Color(255, 255, 0, 100), new Color(128, 0, 128, 110));
        when(plugin.palette()).thenReturn(custom);
        render();
        Object recoloured = overlay.getPanelComponent().getChildren().get(2);
        assertNotSame(status, recoloured);
        assertEquals(custom.text(Palette.Tone.BAD), field(recoloured, "rightColor"));

        when(plugin.hudModel()).thenReturn(new HudModel(Arrays.asList(
            new HudModel.Line("Here", "Draynor Village", null)), false));
        render();
        assertEquals("a new model: a new panel", 2, overlay.getPanelComponent().getChildren().size());
        assertEquals("Draynor Village", field(overlay.getPanelComponent().getChildren().get(1), "right"));
    }

    private void render()
    {
        BufferedImage image = new BufferedImage(400, 600, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        overlay.render(graphics);
        graphics.dispose();
    }

    private static void assertLine(Object child, String left, Color leftColour, String right, Color rightColour)
        throws Exception
    {
        LineComponent line = (LineComponent) child;
        assertEquals(left, field(line, "left"));
        assertEquals(left, leftColour, field(line, "leftColor"));
        assertEquals(left, right, field(line, "right"));
        if (right != null)
        {
            assertEquals(left, rightColour, field(line, "rightColor"));
        }
    }

    private static Object field(Object component, String name) throws Exception
    {
        Field field = component.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(component);
    }
}

package com.fatelocked.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

public class GameArtTest
{
    private final SpriteManager sprites = mock(SpriteManager.class);
    private final ItemManager items = mock(ItemManager.class);
    private final GameArt art = new GameArt(sprites, items);

    @Test
    @SuppressWarnings("unchecked")
    public void aSpriteArrivesOnTheSwingThreadOnceAndIsKept() throws Exception
    {
        List<BufferedImage> first = new ArrayList<>();
        List<BufferedImage> second = new ArrayList<>();
        onEdt(() -> {
            art.load(Art.STRICT_MODE, first::add);
            art.load(Art.STRICT_MODE, second::add);
        });
        ArgumentCaptor<Consumer<BufferedImage>> callback = ArgumentCaptor.forClass(Consumer.class);
        verify(sprites, times(1)).getSpriteAsync(eq(SpriteID.Magicon2.TELE_BLOCK), eq(0), callback.capture());

        BufferedImage teleBlock = new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB);
        boolean[] onEdt = new boolean[1];
        callback.getValue().accept(teleBlock);
        onEdt(() -> onEdt[0] = true);
        assertEquals(List.of(teleBlock), first);
        assertEquals("both callers waiting are answered", List.of(teleBlock), second);

        List<BufferedImage> later = new ArrayList<>();
        onEdt(() -> art.load(Art.STRICT_MODE, image -> {
            later.add(image);
            onEdt[0] = SwingUtilities.isEventDispatchThread();
        }));
        assertSame(teleBlock, later.get(0));
        assertEquals(true, onEdt[0]);
        verify(sprites, times(1)).getSpriteAsync(anyInt(), anyInt(), any(Consumer.class));
    }

    @Test
    public void anItemIsDrawnAsItsStackAndArrivesWhenTheGameHasRenderedIt() throws Exception
    {
        AsyncBufferedImage stardust = new AsyncBufferedImage(mock(ClientThread.class), 36, 32,
            BufferedImage.TYPE_INT_ARGB);
        when(items.getImage(ItemID.STAR_DUST, 175, false)).thenReturn(stardust);
        List<BufferedImage> got = new ArrayList<>();
        onEdt(() -> art.load(Art.FATE_POINTS, got::add));
        onEdt(() -> { });
        assertEquals("nothing until the game renders it", List.of(), got);

        stardust.loaded();
        onEdt(() -> { });
        assertEquals(List.of(stardust), got);
    }

    @Test
    @SuppressWarnings("unchecked")
    public void artThatNeverLoadsIsAskedForAgainNextTime() throws Exception
    {
        onEdt(() -> art.load(Art.PLACE, image -> { }));
        ArgumentCaptor<Consumer<BufferedImage>> callback = ArgumentCaptor.forClass(Consumer.class);
        verify(sprites).getSpriteAsync(eq(SpriteID.WorldmapIcon.PLANET), eq(0), callback.capture());
        List<BufferedImage> got = new ArrayList<>();
        onEdt(() -> art.load(Art.PLACE, got::add));
        callback.getValue().accept(null);
        onEdt(() -> { });
        assertEquals(List.of(), got);

        onEdt(() -> art.load(Art.PLACE, got::add));
        verify(sprites, times(2)).getSpriteAsync(eq(SpriteID.WorldmapIcon.PLANET), eq(0), any(Consumer.class));
        verify(items, never()).getImage(anyInt(), anyInt(), any(Boolean.class));
    }

    private static void onEdt(Runnable task) throws Exception
    {
        SwingUtilities.invokeAndWait(task);
    }
}

package com.fatelocked.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.fatelocked.preview.SwingSnapshot;
import java.util.List;
import javax.swing.SwingUtilities;
import org.junit.Test;

public class KitTest
{
    @Test
    public void statTilesTakeTheirHeight() throws Exception
    {
        int[] height = new int[1];
        SwingUtilities.invokeAndWait(() -> {
            StatTiles tiles = new StatTiles();
            tiles.show(new StatTiles.Tile(1, "Can do", Palette.Tone.GOOD),
                new StatTiles.Tile(2, "Locked", Palette.Tone.BAD));
            height[0] = SwingSnapshot.settle(tiles, 200);
            assertEquals(2, tiles.getComponentCount());
        });
        assertEquals(38, height[0]);
    }

    @Test
    public void aLongReasonStopsAtTwoLinesWithAnEllipsisAndATooltip() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            TextBlock block = new TextBlock(Type.small(), Palette.TEXT_MUTED, 2, 120);
            block.setText("Needs Cook's Assistant, Fishing Contest, Goblin Diplomacy, Big Chompy Bird Hunting and more");
            List<String> lines = block.lines();
            assertEquals(2, lines.size());
            assertTrue(lines.get(1), lines.get(1).endsWith("…"));
            assertEquals(block.getText(), block.getToolTipText());

            block.setText("Short reason");
            assertEquals(List.of("Short reason"), block.lines());
            assertNull("nothing is cut, so no tooltip", block.getToolTipText());
        });
    }

    @Test
    public void aRowShowsItsReasonOnlyWhenItHasOne() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ItemRow row = new ItemRow().show("Cook's Assistant", "Can do", Palette.Tone.GOOD, null);
            assertFalse(row.reason().isVisible());
            assertEquals("Can do", row.pill().getWord());
            row.show("Black Knights' Fortress", "Locked", Palette.Tone.BAD, "Unlock it in the tracker");
            assertTrue(row.reason().isVisible());
            assertEquals(Palette.Tone.BAD, row.pill().getTone());
            assertEquals("Black Knights' Fortress", row.title());
        });
    }

    @Test
    public void aPillWithNoWordIsHidden() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            StatusPill pill = new StatusPill("Locked", Palette.Tone.BAD);
            assertTrue(pill.isVisible());
            pill.show(null, Palette.Tone.NEUTRAL);
            assertFalse(pill.isVisible());
        });
    }

    @Test
    public void progressStaysBetweenNoneAndAll()
    {
        ProgressBar bar = new ProgressBar();
        bar.setFraction(1.5);
        assertEquals(1.0, bar.getFraction(), 0);
        bar.setFraction(-0.5);
        assertEquals(0.0, bar.getFraction(), 0);
    }

    @Test
    public void buttonsAreAsTallAsEachOtherAndALinkIsJustItsText() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            FlatButton primary = new FlatButton("Connect tracker", FlatButton.Kind.PRIMARY);
            FlatButton secondary = new FlatButton("Cancel", FlatButton.Kind.SECONDARY);
            FlatButton link = new FlatButton("Open tracker", FlatButton.Kind.LINK);
            assertEquals(primary.getPreferredSize().height, secondary.getPreferredSize().height);
            assertTrue(link.getPreferredSize().height < primary.getPreferredSize().height);
            assertTrue(primary.getPreferredSize().width > link.getPreferredSize().width);
        });
    }

    @Test
    public void aSectionOpensAndClosesAndTellsItsListeners() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Section section = new Section("Here", false);
            boolean[] told = new boolean[1];
            section.onToggle(open -> told[0] = open);
            assertFalse(section.body().isVisible());
            section.setExpanded(true);
            assertTrue(section.body().isVisible());
            assertTrue(told[0]);
        });
    }
}

