import org.junit.Before;
import org.junit.Test;

/** The owner's review, 28 Sept: what the game says, read for the rows the tracker leaves undecided. */
public class FateLockedGameFactsTest
{
    /** Lumbridge Castle, whose caves' monsters the tracker leaves undecided. */
    private static final CanonicalChunk CASTLE = new CanonicalChunk(50, 50);

    private final Client client = mock(Client.class);
    private final ItemManager items = mock(ItemManager.class);
    private final FateLockedPlugin plugin = new FateLockedPlugin();
    private DecisionService rules;

    @Before
    public void setUp() throws Exception
    {
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz"));
        rules = DecisionService.create(RulesSnapshot.of(FateLockedBundle.loadFromJson(new Gson(), json)),
            "iron example", "iron example");
        PluginTestSupport.set(plugin, "client", client);
        PluginTestSupport.set(plugin, "itemManager", items);
        when(client.isClientThread()).thenReturn(true);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getTickCount()).thenReturn(100);
        when(client.getWorldType()).thenReturn(EnumSet.of(WorldType.MEMBERS));
        when(client.getVarpValue(VarPlayerID.QP)).thenReturn(41);
        when(client.getRealSkillLevel(any(Skill.class))).thenReturn(30);
        // The Lost Tribe is under way; every other quest is still to start.
        int[] stack = new int[1];
        doAnswer(ask -> {
            stack[0] = (Integer) ask.getArguments()[1] == Quest.THE_LOST_TRIBE.getId() ? 0 : 1;
            return null;
        }).when(client).runScript(any(), any());
        when(client.getIntStack()).thenReturn(stack);
        ItemContainer inventory = mock(ItemContainer.class);
        when(inventory.getItems()).thenReturn(new Item[] {new Item(ItemID.CANDLE_LANTERN_LIT, 1),
            new Item(ItemID.EDGEVILLEDUNGEONKEY, 1), new Item(-1, 0)});
        when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
        name(ItemID.CANDLE_LANTERN_LIT, "Candle lantern");
        name(ItemID.EDGEVILLEDUNGEONKEY, "Brass key");
    }

    @Test
    public void theGameIsAskedOnlyAboutWhatUndecidedRowsNeed()
    {
        GameFacts facts = plugin.gameFacts(rules, CASTLE);

        assertEquals(Boolean.TRUE, facts.getMembers());
        assertEquals(41, facts.getQuestPoints());
        assertEquals(Integer.valueOf(30), facts.getLevels().get(Skill.MINING));
        assertEquals("only the quests its rows name", EnumSet.of(Quest.THE_LOST_TRIBE, Quest.DEATH_TO_THE_DORGESHUUN),
            facts.getQuests().keySet());
        assertEquals(QuestState.IN_PROGRESS, facts.getQuests().get(Quest.THE_LOST_TRIBE));
        assertEquals(QuestState.NOT_STARTED, facts.getQuests().get(Quest.DEATH_TO_THE_DORGESHUUN));
        assertEquals(new HashSet<>(Arrays.asList("candle lantern", "brass key")), facts.getCarried());
        assertEquals(Boolean.TRUE, facts.getLight());

        assertSame("read once a tick", facts, plugin.gameFacts(rules, CASTLE));
        verify(client, times(2)).runScript(any(), any());
    }

    /** The caves' guard only needs The Lost Tribe started: now it can be done; the frogs need more. */
    @Test
    public void theHereCardDecidesByThem()
    {
        HereModel here = new HerePresenter().present(rules, CASTLE, plugin.gameFacts(rules, CASTLE));
        HereModel.Group combat = here.getGroups().stream().filter(group -> group.getCategory().equals("COMBAT"))
            .findFirst().orElseThrow(AssertionError::new);
        assertEquals("Can do", row(combat, "Cave goblin guard").getWord());
        HereModel.Row frog = row(combat, "Big frog");
        assertEquals("Not ready", frog.getWord());
        assertEquals("Death to the Dorgeshuun", frog.getReason());
    }

    @Test
    public void nothingIsReadWhereNoRowNeedsIt()
    {
        assertSame(GameFacts.NONE, plugin.gameFacts(rules, new CanonicalChunk(46, 52)));
        assertSame("logged out", GameFacts.NONE, plugin.gameFacts(rules, null));
        when(client.isClientThread()).thenReturn(false);
        assertSame("off the client thread", GameFacts.NONE, plugin.gameFacts(rules, CASTLE));
        verify(client, never()).runScript(any(), any());
        verify(items, never()).getItemComposition(anyInt());
    }

    private void name(int id, String name)
    {
        ItemComposition composition = mock(ItemComposition.class);
        when(composition.getName()).thenReturn(name);
        when(items.getItemComposition(id)).thenReturn(composition);
    }

    private static HereModel.Row row(HereModel.Group group, String name)
    {
        return group.getRows().stream().filter(row -> row.getName().equals(name)).findFirst()
            .orElseThrow(() -> new AssertionError("no " + name));
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;

import com.fatelocked.LockedAreaAlerts.Alert;
import com.fatelocked.rules.PermissionStatus;
import org.junit.Test;

/** U10, decision 6: a line per area, and the locked alert once per locked area. */
public class LockedAreaAlertsTest
{
    private static final FateLockedConfig.LockedAreaAlert ALL = FateLockedConfig.LockedAreaAlert.CHAT_SOUND_FADE;
    private static final Alert FULL = new Alert(true, true, true);
    private static final Alert LINE = new Alert(true, false, false);
    private static final Alert NONE = LockedAreaAlerts.NONE;

    private final LockedAreaAlerts alerts = new LockedAreaAlerts();

    @Test
    public void walkingWithinOneLockedAreaAlertsOnce()
    {
        assertEquals(LINE, alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 0, ALL, true));
        assertEquals(FULL, alerts.enter(PermissionStatus.LOCKED, "Falador", 1, ALL, true));
        assertEquals(NONE, alerts.enter(PermissionStatus.LOCKED, "Falador", 2, ALL, true));
        assertEquals(NONE, alerts.enter(PermissionStatus.LOCKED, "Falador", 3, ALL, true));
    }

    /** Decision 6: the sound and fade are for coming in from unlocked land. */
    @Test
    public void aNewLockedAreaNextToTheLastPostsItsLineOnly()
    {
        alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 0, ALL, true);
        alerts.enter(PermissionStatus.LOCKED, "Falador", 1, ALL, true);
        assertEquals(LINE, alerts.enter(PermissionStatus.LOCKED, "Taverley", 2, ALL, true));
    }

    /** Walking along a border doesn't repeat the alert. */
    @Test
    public void theSameAreaWaitsAMinuteBeforeAlertingAgain()
    {
        alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 0, ALL, false);
        assertEquals(FULL, alerts.enter(PermissionStatus.LOCKED, "Falador", 10, ALL, false));
        alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 20, ALL, false);
        assertEquals("back within a minute", NONE, alerts.enter(PermissionStatus.LOCKED, "Falador", 109, ALL, false));
        alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 109, ALL, false);
        assertEquals("a minute on", FULL, alerts.enter(PermissionStatus.LOCKED, "Falador", 110, ALL, false));
    }

    @Test
    public void notReadyAndUndecidedPlacesNeverAlert()
    {
        assertEquals(NONE, alerts.enter(PermissionStatus.UNKNOWN, "chunk:1,1", 0, ALL, true));
        assertEquals("not ready is owned: its line only", LINE,
            alerts.enter(PermissionStatus.NOT_READY, "Catherby", 1, ALL, true));
        assertEquals(NONE, alerts.enter(PermissionStatus.NOT_READY, "Seers' Village", 2, ALL, false));
        assertEquals("the next area has its line", LINE, alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 3, ALL, true));
    }

    @Test
    public void routineLinesAreForAreaChangesWhenTheyAreAnnounced()
    {
        assertEquals(NONE, alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 0, ALL, false));
        assertEquals(LINE, alerts.enter(PermissionStatus.ALLOWED, "Draynor Village", 1, ALL, true));
        assertEquals(NONE, alerts.enter(PermissionStatus.ALLOWED, "Draynor Village", 2, ALL, true));
    }

    @Test
    public void theAlertSettingDecidesWhatTheAlertDoes()
    {
        for (FateLockedConfig.LockedAreaAlert level : FateLockedConfig.LockedAreaAlert.values())
        {
            LockedAreaAlerts fresh = new LockedAreaAlerts();
            fresh.enter(PermissionStatus.ALLOWED, "Lumbridge", 0, level, true);
            assertEquals(level.name(), new Alert(level.chat(), level.sound(), level.fade()),
                fresh.enter(PermissionStatus.LOCKED, "Falador", 1, level, true));
        }
    }

    /** At login the next entry alerts afresh, even standing in the same locked area. */
    @Test
    public void aNewSessionAlertsAfresh()
    {
        alerts.enter(PermissionStatus.ALLOWED, "Lumbridge", 0, ALL, false);
        alerts.enter(PermissionStatus.LOCKED, "Falador", 1, ALL, false);

        alerts.forget();

        assertEquals(FULL, alerts.enter(PermissionStatus.LOCKED, "Falador", 2, ALL, false));
    }
}

package com.fatelocked;

import org.junit.Test;

import java.time.Instant;
import java.time.ZoneId;
import java.util.HashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SyncViewTest
{
    private static final ZoneId LONDON = ZoneId.of("Europe/London");
    /** 18:00 in London. */
    private static final Instant NOW = Instant.parse("2026-09-26T17:00:00Z");

    @Test
    public void connectedShowsWhenTheRulesWereLastConfirmedOnThePlayersClock()
    {
        SyncView view = view(TrackerConnectionSnapshot.connected(
            Instant.parse("2026-09-26T16:59:00Z"), "41"));

        assertEquals("Connected", view.status);
        assertEquals(SyncView.Tone.GREEN, view.tone);
        assertEquals("17:59", view.lastSync);
        assertNull(view.detail);
        assertEquals(SyncView.Action.CHECK_NOW, view.action);
    }

    @Test
    public void aFailedCheckSaysWhyAndWhenTheNextCheckIs()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE,
            Instant.parse("2026-09-26T16:30:00Z"), "41",
            SyncReason.UNREACHABLE, NOW.plusSeconds(120)));

        assertEquals("Could not reach tracker", view.status);
        assertEquals("RuneLite couldn't reach the tracker. Next check at 18:02.", view.detail);
        assertEquals("17:30", view.lastSync);
        assertEquals(SyncView.Action.CHECK_NOW, view.action);
    }

    @Test
    public void syncOffKeepsThePairingAndPointsToTheSetting()
    {
        SyncView view = view(SyncMachine.idle(false, true));

        assertEquals("Online sync is off", view.status);
        assertTrue(view.detail, view.detail.contains("Turn on online sync"));
        assertEquals(SyncView.Action.ENABLE_SYNC, view.action);
        assertEquals(SyncView.Connect.TURN_ON_SYNC, view.connect);
        assertEquals("\u2014", view.lastSync);
    }

    @Test
    public void withNoPairingTheActionIsConnect()
    {
        for (boolean allowed : new boolean[] {false, true})
        {
            SyncView view = view(SyncMachine.idle(allowed, false));
            assertEquals("Not connected", view.status);
            assertEquals(SyncView.Action.CONNECT, view.action);
        }
    }

    @Test
    public void aPairingThatTimedOutPointsToConnect()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.EXPIRED,
            null, null, SyncReason.NO_PROFILE, null));

        assertEquals(SyncView.Tone.RED, view.tone);
        assertEquals(SyncView.Action.CONNECT, view.action);
    }

    @Test
    public void aLapsedProfilePointsToTheWebTracker()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.WAITING,
            NOW.minusSeconds(3600), null, SyncReason.NO_RECENT_UPDATE, null));

        assertEquals(SyncView.Tone.AMBER, view.tone);
        assertEquals(SyncView.Action.OPEN_TRACKER, view.action);
    }

    @Test
    public void aNewerBundleFormatAsksForAPluginUpdate()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.IMPORT_FAILED,
            null, "41", SyncReason.FUTURE_FORMAT, null));

        assertEquals("Plugin update needed", view.status);
        assertEquals(SyncView.Tone.RED, view.tone);
        assertEquals(SyncView.Action.UPDATE_PLUGIN, view.action);
        assertTrue(view.detail, view.detail.contains("Plugin Hub"));
    }

    @Test
    public void rulesThatCannotBeUsedPointToTheWebTracker()
    {
        SyncView view = view(TrackerConnectionSnapshot.of(TrackerConnectionState.IMPORT_FAILED,
            null, "41", SyncReason.INVALID_RULES, null));

        assertEquals(SyncView.Action.OPEN_TRACKER, view.action);
    }

    @Test
    public void checkNowIsOfferedOnlyWithAPairingAndSyncOn()
    {
        assertFalse(view(SyncMachine.idle(true, false)).canCheckNow);
        assertFalse(view(SyncMachine.idle(false, true)).canCheckNow);
        assertTrue(view(SyncMachine.idle(true, true)).canCheckNow);
        assertTrue(view(TrackerConnectionSnapshot.connected(NOW, "41")).canCheckNow);
        assertTrue(view(TrackerConnectionSnapshot.of(TrackerConnectionState.OFFLINE,
            null, null, SyncReason.BUSY, NOW.plusSeconds(120))).canCheckNow);
    }

    @Test
    public void theConnectButtonSaysWhatItWillDo()
    {
        assertEquals(SyncView.Connect.CONNECT, view(SyncMachine.idle(true, false)).connect);
        assertEquals(SyncView.Connect.TURN_ON_SYNC, view(SyncMachine.idle(false, true)).connect);
        // A first pairing that hasn't delivered has nothing to keep.
        assertEquals(SyncView.Connect.CONNECT, view(of(TrackerConnectionState.WAITING,
            SyncReason.CONFIRM_IN_BROWSER)).connect);
        assertEquals(SyncView.Connect.CONNECT, view(of(TrackerConnectionState.EXPIRED,
            SyncReason.NO_PROFILE)).connect);
        // A working pairing is kept: re-pairing asks first.
        assertEquals(SyncView.Connect.REPAIR,
            view(TrackerConnectionSnapshot.connected(NOW, "41")).connect);
        assertEquals(SyncView.Connect.REPAIR, view(of(TrackerConnectionState.OFFLINE,
            SyncReason.UNREACHABLE)).connect);
        assertEquals(SyncView.Connect.CANCEL_REPAIR, view(of(TrackerConnectionState.WAITING,
            SyncReason.CONFIRM_REPAIR)).connect);
        assertEquals("Re-pair tracker\u2026", SyncView.Connect.REPAIR.label);
    }

    private static TrackerConnectionSnapshot of(TrackerConnectionState state, SyncReason reason)
    {
        return TrackerConnectionSnapshot.of(state, null, null, reason, null);
    }

    @Test
    public void aCodeTheOwnerDisconnectedPointsToConnect()
    {
        SyncView view = view(of(TrackerConnectionState.EXPIRED, SyncReason.GONE));

        assertEquals("Disconnected in the web tracker", view.status);
        assertEquals(SyncView.Action.CONNECT, view.action);
        assertEquals(SyncView.Connect.CONNECT, view.connect);
        assertFalse(view.canCheckNow);
    }

    @Test
    public void thePairingShowsOnlyTheLastFourCharactersOfItsCode()
    {
        assertEquals("\u2026cdef", view(TrackerConnectionSnapshot.connected(NOW, "41")
            .forPairing("0123456789abcdef0123456789abcdef")).pairing);
        assertEquals("\u2014", view(SyncMachine.idle(true, false)).pairing);
    }

    @Test
    public void everyReasonHasItsOwnStatusAndExplanation()
    {
        Set<String> statuses = new HashSet<>();
        Set<String> details = new HashSet<>();
        for (SyncReason reason : SyncReason.values())
        {
            if (reason == SyncReason.NONE) continue;
            SyncView view = view(TrackerConnectionSnapshot.of(
                TrackerConnectionState.OFFLINE, null, null, reason, NOW.plusSeconds(30)));
            assertTrue(reason + " shares its status", statuses.add(view.status));
            if (reason == SyncReason.CHECKING)
            {
                // "Checking the tracker" says it all.
                assertNull(view.detail);
                continue;
            }
            assertNotNull(reason + " has no explanation", view.detail);
            assertTrue(reason + " shares its explanation", details.add(view.detail));
        }
    }

    private static SyncView view(TrackerConnectionSnapshot snapshot)
    {
        return SyncView.of(snapshot, NOW, LONDON);
    }
}

