package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPOutputStream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * The web app's bundle cases (contracts/golden-bundles/cases.json): input
 * every import must refuse rather than load empty or partial rules, and
 * changes it must shrug off, keeping the same answers as the run they start
 * from. The Stage 2 cases need a reader of the rules' capabilities (E7): a
 * stray root field, or a missing root copy of what the rules now name.
 */
@RunWith(Parameterized.class)
public class GoldenBundleCasesTest
{
    private static final Gson GSON = new Gson();

    @Parameterized.Parameters(name = "{0} {1}")
    public static List<Object[]> cases() throws IOException
    {
        JsonObject file = GoldenBundleContractTest.json("cases.json");
        List<Object[]> cases = new ArrayList<>();
        for (JsonElement element : file.getAsJsonArray("reject"))
        {
            cases.add(new Object[] {"refuses", name(element), element.getAsJsonObject()});
        }
        for (JsonElement element : file.getAsJsonArray("sameAnswers"))
        {
            cases.add(new Object[] {"keeps its answers for", name(element), element.getAsJsonObject()});
        }
        for (JsonElement element : file.getAsJsonArray("stage2SameAnswers"))
        {
            cases.add(new Object[] {"keeps its answers for", name(element), element.getAsJsonObject()});
        }
        // The plugin's own (F1): a travel table it can't read never costs the bundle.
        for (String travel : List.of("\"a table\"", "[1, 2]", "{\"spell:x\": {\"label\": 7}}", "{\"item:x\": null}"))
        {
            cases.add(new Object[] {"keeps its answers for", "a travel section of " + travel, GSON.fromJson(
                "{\"scenario\": \"vanilla-mid\", \"set\": {\"rules.travel\": " + travel + "}}", JsonObject.class)});
        }
        return cases;
    }

    private final boolean refuse;
    private final String name;
    private final JsonObject bundleCase;

    public GoldenBundleCasesTest(String kind, String name, JsonObject bundleCase)
    {
        this.refuse = kind.equals("refuses");
        this.name = name;
        this.bundleCase = bundleCase;
    }

    @Test
    public void readsTheCaseAsTheTrackerIntends() throws IOException
    {
        String input = input();
        if (refuse)
        {
            try
            {
                FateLockedBundle.loadFromJson(GSON, input);
                fail(name + " was accepted");
            }
            catch (JsonParseException | IllegalArgumentException expected)
            {
                // Refused on purpose, so the active rules stay as they were.
            }
            return;
        }

        FateLockedBundle bundle = FateLockedBundle.loadFromJson(GSON, input);
        String scenario = bundleCase.get("scenario").getAsString();
        JsonObject expected = GoldenBundleContractTest.json(scenario + ".expect.json");
        List<String> mismatches = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("chunks").entrySet())
        {
            CanonicalChunk chunk = GoldenBundleContractTest.chunk(entry.getKey());
            if (bundle.regionAt(chunk) == null && bundle.subAreaAt(chunk) == null) continue;
            FateLockedBundle.LockState want = entry.getValue().getAsBoolean()
                ? FateLockedBundle.LockState.UNLOCKED : FateLockedBundle.LockState.LOCKED;
            if (bundle.lockStateAt(chunk) != want) mismatches.add("chunk " + entry.getKey());
        }
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("areas").entrySet())
        {
            if (bundle.isUnlocked(entry.getKey()) != entry.getValue().getAsBoolean())
            {
                mismatches.add("area " + entry.getKey());
            }
        }
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("banks").entrySet())
        {
            int bankId = Integer.parseInt(entry.getKey());
            CanonicalChunk chunk = new CanonicalChunk(bankId / 256, bankId % 256);
            if (bundle.isBankUnlocked(chunk) != entry.getValue().getAsBoolean())
            {
                mismatches.add("bank " + entry.getKey());
            }
        }
        assertEquals(name, List.of(), mismatches);
    }

    /** The case's input text, or its scenario's bundle, changed as the recipe says. */
    private String input() throws IOException
    {
        String text = bundleCase.has("input")
            ? bundleCase.get("input").getAsString().repeat(
                bundleCase.has("repeat") ? bundleCase.get("repeat").getAsInt() : 1)
            : scenarioText();
        if (bundleCase.has("truncate"))
        {
            text = text.substring(0, (int) (text.length() * bundleCase.get("truncate").getAsDouble()));
        }
        if (bundleCase.has("compress") && bundleCase.get("compress").getAsBoolean())
        {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try (GZIPOutputStream gzip = new GZIPOutputStream(bytes))
            {
                gzip.write(text.getBytes(StandardCharsets.UTF_8));
            }
            text = "FLGZ:" + Base64.getEncoder().encodeToString(bytes.toByteArray());
        }
        return text;
    }

    /** The scenario's bundle with the recipe's fields set and removed. */
    private String scenarioText() throws IOException
    {
        String scenario = bundleCase.get("scenario").getAsString();
        JsonObject root = GSON.fromJson(GoldenBundleContractTest.gunzip(
            GoldenBundleContractTest.bytes(scenario + ".bundle.json.gz")), JsonObject.class);
        if (bundleCase.has("set"))
        {
            for (Map.Entry<String, JsonElement> entry : bundleCase.getAsJsonObject("set").entrySet())
            {
                parentOf(root, entry.getKey()).add(last(entry.getKey()), entry.getValue());
            }
        }
        if (bundleCase.has("remove"))
        {
            for (JsonElement path : bundleCase.getAsJsonArray("remove"))
            {
                String dotted = path.getAsString();
                if (parentOf(root, dotted).remove(last(dotted)) == null)
                {
                    fail(name + ": nothing at " + dotted);
                }
            }
        }
        return GSON.toJson(root);
    }

    private static JsonObject parentOf(JsonObject root, String dotted)
    {
        String[] parts = dotted.split("\\.");
        JsonObject node = root;
        for (int i = 0; i < parts.length - 1; i++)
        {
            node = node.getAsJsonObject(parts[i]);
        }
        return node;
    }

    private static String last(String dotted)
    {
        String[] parts = dotted.split("\\.");
        return parts[parts.length - 1];
    }

    private static String name(JsonElement bundleCase)
    {
        return bundleCase.getAsJsonObject().get("name").getAsString();
    }
}

package com.fatelocked;

import net.runelite.client.config.ConfigManager;
import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TrackerConnectionSettingsTest
{
    private static final String PAIRING_CODE = "0123456789abcdef0123456789abcdef";
    private ConfigManager configManager;

    @Before
    public void setUp()
    {
        configManager = mock(ConfigManager.class);
    }

    @Test
    public void networkAccessDefaultsOffEvenWithAnExistingPairingOrLegacyOptIn()
    {
        when(configManager.getConfiguration(FateLockedConfig.GROUP, "onlineSync"))
            .thenReturn("true");
        when(configManager.getConfiguration(
            FateLockedConfig.GROUP, TrackerConnectionSettings.PAIRING_CODE_KEY))
            .thenReturn(PAIRING_CODE);
        TrackerConnectionSettings settings = new TrackerConnectionSettings(configManager);
        assertTrue(settings.isPaired());
        assertFalse(settings.networkAccessAllowed());
    }

    @Test
    public void pairingIdentityUsesANonVisibleInternalKey()
    {
        TrackerConnectionSettings settings = new TrackerConnectionSettings(configManager);
        settings.replacePairingCode(PAIRING_CODE);
        verify(configManager).setConfiguration(
            FateLockedConfig.GROUP, TrackerConnectionSettings.PAIRING_CODE_KEY, PAIRING_CODE);
    }

    @Test
    public void successfulUnifiedPairingClearsLegacyConnectionKeysAndRelayTokens()
    {
        when(configManager.getConfigurationKeys(FateLockedConfig.GROUP + "."))
            .thenReturn(Arrays.asList(
                FateLockedConfig.GROUP + ".eventToken." + PAIRING_CODE,
                "stateToken." + PAIRING_CODE,
                FateLockedConfig.GROUP + ".suggestToken." + PAIRING_CODE,
                "ackToken." + PAIRING_CODE,
                FateLockedConfig.GROUP + ".trackerPairingCode",
                FateLockedConfig.GROUP + ".strictMode"));

        TrackerConnectionSettings settings = new TrackerConnectionSettings(configManager);
        settings.clearLegacySettings();

        verify(configManager).unsetConfiguration(FateLockedConfig.GROUP, "onlineSync");
        verify(configManager).unsetConfiguration(FateLockedConfig.GROUP, "syncCode");
        verify(configManager).unsetConfiguration(FateLockedConfig.GROUP, "relayUrl");
        verify(configManager).unsetConfiguration(
            FateLockedConfig.GROUP, "eventToken." + PAIRING_CODE);
        verify(configManager).unsetConfiguration(
            FateLockedConfig.GROUP, "stateToken." + PAIRING_CODE);
        verify(configManager).unsetConfiguration(
            FateLockedConfig.GROUP, "suggestToken." + PAIRING_CODE);
        verify(configManager).unsetConfiguration(
            FateLockedConfig.GROUP, "ackToken." + PAIRING_CODE);
        verify(configManager, never()).unsetConfiguration(
            FateLockedConfig.GROUP, TrackerConnectionSettings.PAIRING_CODE_KEY);
        verify(configManager, never()).unsetConfiguration(
            FateLockedConfig.GROUP, "strictMode");
    }

    @Test
    public void legacyCleanupToleratesMissingConfigurationKeyEnumeration()
    {
        when(configManager.getConfigurationKeys(FateLockedConfig.GROUP + "."))
            .thenReturn(null);

        new TrackerConnectionSettings(configManager).clearLegacySettings();

        verify(configManager).unsetConfiguration(FateLockedConfig.GROUP, "onlineSync");
        verify(configManager).unsetConfiguration(FateLockedConfig.GROUP, "syncCode");
        verify(configManager).unsetConfiguration(FateLockedConfig.GROUP, "relayUrl");
    }

    @Test
    public void blankAndInvalidStoredPairingCodesAreUnpaired()
    {
        TrackerConnectionSettings settings = new TrackerConnectionSettings(configManager);
        when(configManager.getConfiguration(
            FateLockedConfig.GROUP, TrackerConnectionSettings.PAIRING_CODE_KEY)).thenReturn("   ");
        assertEquals("", settings.pairingCode());
        assertFalse(settings.isPaired());
        when(configManager.getConfiguration(
            FateLockedConfig.GROUP, TrackerConnectionSettings.PAIRING_CODE_KEY))
            .thenReturn("0123456789abcdef0123456789abcdeg");
        assertEquals("", settings.pairingCode());
        assertFalse(settings.isPaired());
    }

    @Test
    public void validStoredPairingCodeIsPaired()
    {
        when(configManager.getConfiguration(
            FateLockedConfig.GROUP, TrackerConnectionSettings.PAIRING_CODE_KEY))
            .thenReturn(" " + PAIRING_CODE + " ");
        TrackerConnectionSettings settings = new TrackerConnectionSettings(configManager);
        assertEquals(PAIRING_CODE, settings.pairingCode());
        assertTrue(settings.isPaired());
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.fatelocked.ui.Palette;
import com.google.gson.Gson;
import java.awt.Rectangle;
import java.awt.Shape;
import java.lang.management.ManagementFactory;
import java.lang.management.ThreadMXBean;
import java.lang.reflect.Proxy;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import org.junit.Test;

/**
 * A9, F2: what runs in every frame, or for every option of every menu, makes no garbage: the world
 * map's loop over a golden run, and the menu tag passing over options it could never tag. Counted
 * with the JVM's own tally of the bytes a thread allocates.
 */
public class A9PerformanceTest
{
    private static final int WARM_UP = 100_000;
    private static final int ROUNDS = 100_000;

    @Test
    public void theWorldMapLoopMakesNoGarbage() throws Exception
    {
        FateLockedBundle mid = FateLockedBundle.loadFromJson(new Gson(),
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz")));
        WorldMapModel model = WorldMapModel.of(
            DecisionService.create(RulesSnapshot.of(mid), "iron example", "iron example"));
        Rectangle map = new Rectangle(0, 0, 700, 470);
        WorldMapProjection projection = new WorldMapProjection(map, 1.5f, 3200, 3200);
        Shape clip = WorldMapClip.of(map, null, null);
        Shape outline = FateLockedWorldMapOverlay.outlinePath(model, projection);
        Palette palette = Palette.defaults();
        NoopGraphics graphics = new NoopGraphics();

        FateLockedWorldMapOverlay.draw(graphics, model, projection, palette, clip, outline);
        assertTrue("the loop fills the locked land in view", graphics.fills > 0);
        assertEquals("and draws the outline, over its underlay", 2, graphics.draws);

        double bytes = perRound(() -> FateLockedWorldMapOverlay.draw(graphics, model, projection, palette, clip, outline));
        assertTrue(bytes + " bytes a frame", bytes < 1);
    }

    @Test
    public void theMenuTagPassesOverOptionsWithoutGarbage()
    {
        FateLockedPlugin plugin = new FateLockedPlugin();
        for (MenuAction type : new MenuAction[] {MenuAction.WALK, MenuAction.CANCEL, MenuAction.EXAMINE_NPC,
            MenuAction.EXAMINE_OBJECT, MenuAction.EXAMINE_ITEM, MenuAction.PLAYER_FIRST_OPTION})
        {
            MenuEntryAdded event = new MenuEntryAdded(entryOf(type));
            double bytes = perRound(() -> plugin.onMenuEntryAdded(event));
            assertTrue(type + ": " + bytes + " bytes an option", bytes < 1);
        }
    }

    /**
     * The bytes this thread allocates a round of the work, on average, once the JIT has had a warm-up.
     * Anything made every round is 16 bytes or more; under one byte a round is the tally's own cost
     * and the odd one-off.
     */
    private static double perRound(Runnable work)
    {
        ThreadMXBean bean = ManagementFactory.getThreadMXBean();
        assumeTrue(bean instanceof com.sun.management.ThreadMXBean);
        com.sun.management.ThreadMXBean threads = (com.sun.management.ThreadMXBean) bean;
        assumeTrue(threads.isThreadAllocatedMemorySupported() && threads.isThreadAllocatedMemoryEnabled());
        long id = Thread.currentThread().getId();
        for (int i = 0; i < WARM_UP; i++)
        {
            work.run();
        }
        long before = threads.getThreadAllocatedBytes(id);
        for (int i = 0; i < ROUNDS; i++)
        {
            work.run();
        }
        return (threads.getThreadAllocatedBytes(id) - before) / (double) ROUNDS;
    }

    /**
     * A menu entry of this type, as a proxy that answers without making anything: a mock would
     * record every call, which is garbage of its own.
     */
    private static MenuEntry entryOf(MenuAction type)
    {
        return (MenuEntry) Proxy.newProxyInstance(MenuEntry.class.getClassLoader(), new Class<?>[] {MenuEntry.class},
            (proxy, method, args) -> "getType".equals(method.getName()) ? type : null);
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.fatelocked.guardian.GuardedActionFactory;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * F1: the filter lets through exactly the menu types the tag could ever tag. For every
 * {@link MenuAction}, an entry as RuneLite makes it, with an NPC where RuneLite gives one and a
 * tile in the scene, is tagged only if its facts are a kind travel is matched on, or it is placed
 * in a chunk.
 */
public class MenuTagFilterTest
{
    /** The types RuneLite's menu entries give an NPC for. */
    private static final Set<MenuAction> WITH_AN_NPC = EnumSet.of(
        MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION, MenuAction.NPC_THIRD_OPTION,
        MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION, MenuAction.WIDGET_TARGET_ON_NPC,
        MenuAction.EXAMINE_NPC);
    private static final Set<MenuAction> EXAMINE = EnumSet.of(
        MenuAction.EXAMINE_OBJECT, MenuAction.EXAMINE_NPC, MenuAction.EXAMINE_ITEM,
        MenuAction.EXAMINE_ITEM_GROUND);

    private final Client client = mock(Client.class);

    @Test
    public void theFilterLetsThroughExactlyWhatCouldBeTagged()
    {
        MenuFactsReader reader = new MenuFactsReader(client);
        GuardedActionFactory factory = new GuardedActionFactory();
        ChunkLocator locator = new ChunkLocator(client);
        int taggable = 0;
        for (MenuAction type : MenuAction.values())
        {
            MenuEntry entry = asRuneLiteMakesIt(type);
            boolean couldBeTagged = reader.read(entry).getKind() != MenuFacts.Kind.OTHER
                || factory.from(entry, locator).getChunk() != null;
            assertEquals(type.name(), couldBeTagged, MenuTagFilter.mayTag(type));
            if (couldBeTagged) taggable++;
        }
        assertEquals("items and spells, objects, ground items, NPCs, and a use on an NPC", 18, taggable);
    }

    @Test
    public void walkingCancelExamineAndPlayersAreNeverRead()
    {
        for (MenuAction type : EnumSet.of(MenuAction.WALK, MenuAction.CANCEL, MenuAction.EXAMINE_OBJECT,
            MenuAction.EXAMINE_NPC, MenuAction.EXAMINE_ITEM, MenuAction.EXAMINE_ITEM_GROUND,
            MenuAction.PLAYER_FIRST_OPTION, MenuAction.PLAYER_EIGHTH_OPTION, MenuAction.RUNELITE))
        {
            assertFalse(type.name(), MenuTagFilter.mayTag(type));
        }
        assertFalse("an entry with no type", MenuTagFilter.mayTag(null));
    }

    /** An entry of this type as the client makes it: its own words, an NPC where one is given, a tile in view. */
    private MenuEntry asRuneLiteMakesIt(MenuAction type)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getType()).thenReturn(type);
        when(entry.getOption()).thenReturn(EXAMINE.contains(type) ? "Examine"
            : type == MenuAction.WALK ? "Walk here" : type == MenuAction.CANCEL ? "Cancel" : "Use");
        when(entry.getTarget()).thenReturn("Thing");
        when(entry.getWorldViewId()).thenReturn(WorldView.TOPLEVEL);
        when(entry.getParam0()).thenReturn(10);
        when(entry.getParam1()).thenReturn(10);
        when(entry.getItemId()).thenReturn(-1);
        TestWorld.topLevel(client);
        if (WITH_AN_NPC.contains(type))
        {
            NPC npc = mock(NPC.class);
            TestWorld.standAt(client, npc, new WorldPoint(3200, 3200, 0));
            when(entry.getNpc()).thenReturn(npc);
        }
        return entry;
    }
}

