package com.fatelocked.rules;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * The decision service on the small v4 fixture (bound to Nubles). These are
 * the cases FateRuleEngineTest pinned before B4 deleted that engine; the
 * golden bundles cover the rest in DecisionServiceGoldenTest.
 */
public class DecisionServiceTest
{
    private static final CanonicalChunk LUMBRIDGE = new CanonicalChunk(50, 50);

    private static String fixtureText(String name) throws Exception
    {
        try (InputStream in = DecisionServiceTest.class.getClassLoader().getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    private static DecisionService playing(String json, String player)
    {
        return DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(new Gson(), json)), "nubles", player);
    }

    private static DecisionService nubles() throws Exception
    {
        return playing(fixtureText("bundles/v4-rules.json"), "nubles");
    }

    @Test
    public void preservesAuthoredStatusesAndMatchesNamesCaseInsensitively() throws Exception
    {
        DecisionService rules = nubles();

        assertEquals(PermissionStatus.ALLOWED, rules.chunk(LUMBRIDGE).getStatus());
        assertEquals(PermissionStatus.ALLOWED,
            rules.target(LUMBRIDGE, "shop", "LUMBRIDGE GENERAL STORE").getStatus());
        assertEquals(PermissionStatus.NOT_READY,
            rules.target(LUMBRIDGE, null, "Cook's Assistant").getStatus());
        assertEquals(PermissionStatus.LOCKED, rules.target(LUMBRIDGE, "NPC", "Goblin").getStatus());
        assertEquals("the plugin's own tag doesn't change what matches", PermissionStatus.LOCKED,
            rules.target(LUMBRIDGE, "NPC", "<col=ffff00>Goblin</col> <col=f87171>(Locked)</col>").getStatus());
        assertEquals(PermissionStatus.UNKNOWN, rules.target(LUMBRIDGE, "OBJECT", "Unmapped").getStatus());
        assertNull(rules.target(LUMBRIDGE, "OBJECT", "Unmapped").getReason());
        assertEquals(PermissionStatus.LOCKED, rules.item(4151).getStatus());
        assertEquals(PermissionStatus.UNKNOWN, rules.item(999999).getStatus());
    }

    @Test
    public void evaluatesOnlyAppAuthoredMobilityNames() throws Exception
    {
        DecisionService rules = nubles();

        assertEquals(PermissionStatus.ALLOWED, rules.mobility("Fairy Rings").getStatus());
        assertEquals(PermissionStatus.ALLOWED, rules.mobility("  fairy   rings ").getStatus());
        assertEquals(PermissionStatus.LOCKED, rules.mobility("Spirit Trees").getStatus());
        assertEquals(PermissionStatus.UNKNOWN,
            playing(fixtureText("bundles/v4-rules.json"), "zezima").mobility("Fairy Rings").getStatus());
        assertEquals(PermissionStatus.UNKNOWN, rules.mobility("Unmapped Network").getStatus());

        JsonObject withoutKnownNames = new Gson().fromJson(fixtureText("bundles/v4-rules.json"), JsonObject.class);
        withoutKnownNames.getAsJsonObject("rules").remove("knownMobility");
        assertEquals(PermissionStatus.UNKNOWN,
            playing(withoutKnownNames.toString(), "nubles").mobility("Spirit Trees").getStatus());
    }

    @Test
    public void malformedKnownMobilityShapesBecomeEmptyAndUnknown() throws Exception
    {
        JsonArray mixed = new JsonArray();
        mixed.add("Fairy Rings");
        mixed.add(7);

        for (JsonElement malformed : Arrays.asList(
            new JsonObject(), new JsonPrimitive("Fairy Rings"), new JsonPrimitive(7), mixed))
        {
            JsonObject root = new Gson().fromJson(fixtureText("bundles/v4-rules.json"), JsonObject.class);
            root.getAsJsonObject("rules").add("knownMobility", malformed);

            FateLockedBundle bundle = FateLockedBundle.loadFromJson(new Gson(), root.toString());
            assertEquals(Collections.emptyList(), bundle.getRules().getKnownMobility());
            try
            {
                bundle.getRules().getKnownMobility().add("Spirit Trees");
                fail("normalized known mobility must be immutable");
            }
            catch (UnsupportedOperationException expected)
            {
                // Expected: parsed authority cannot be mutated after validation.
            }
            assertEquals(PermissionStatus.UNKNOWN,
                playing(root.toString(), "nubles").mobility("Fairy Rings").getStatus());
        }
    }

    /** The fixture as a Chunked run that owns only the start chunk, with these Stage 2 fields in its rules. */
    private static DecisionService chunked(JsonElement capabilities, JsonElement frontier) throws Exception
    {
        JsonObject root = new Gson().fromJson(fixtureText("bundles/v4-rules.json"), JsonObject.class);
        JsonObject rules = root.getAsJsonObject("rules");
        rules.addProperty("gameModeId", "chunked");
        if (capabilities != null) rules.add("capabilities", capabilities);
        if (frontier != null) rules.add("frontier", frontier);
        return playing(root.toString(), "nubles");
    }

    private static JsonArray strings(String... values)
    {
        JsonArray array = new JsonArray();
        for (String value : values) array.add(value);
        return array;
    }

    @Test
    public void theFrontierIsTheTrackersWhenTheRulesNameIt() throws Exception
    {
        JsonArray frontier = strings("60,60", "not a key", "50,51");
        frontier.add(7);
        DecisionService rules = chunked(strings("someFutureSection", "frontier"), frontier);

        // Across the sea, as only the tracker knows; the bad items are skipped.
        assertTrue(rules.isFrontier(new CanonicalChunk(60, 60)));
        assertTrue(rules.isFrontier(new CanonicalChunk(50, 51)));
        // Next to the start chunk, but not on the tracker's frontier.
        assertFalse(rules.isFrontier(new CanonicalChunk(49, 50)));
    }

    @Test
    public void withoutItsCapabilityOrAListTheFrontierIsTheOwnedChunksNeighbours() throws Exception
    {
        JsonObject notAList = new JsonObject();
        for (DecisionService rules : Arrays.asList(
            chunked(null, strings("60,60")),
            chunked(strings("banks"), strings("60,60")),
            chunked(new JsonPrimitive("frontier"), strings("60,60")),
            chunked(strings("frontier"), notAList)))
        {
            assertTrue(rules.isFrontier(new CanonicalChunk(49, 50)));
            assertFalse(rules.isFrontier(new CanonicalChunk(60, 60)));
        }
    }

    /** The fixture with chunkEntries and places in its rules, and these capabilities (none when null). */
    private static DecisionService withPlaces(JsonElement entries, JsonElement places, JsonArray capabilities)
        throws Exception
    {
        JsonObject root = new Gson().fromJson(fixtureText("bundles/v4-rules.json"), JsonObject.class);
        JsonObject rules = root.getAsJsonObject("rules");
        rules.add("chunkEntries", entries);
        rules.add("places", places);
        if (capabilities != null) rules.add("capabilities", capabilities);
        return playing(root.toString(), "nubles");
    }

    private static DecisionService withPlaces(JsonElement entries, JsonElement places, boolean named) throws Exception
    {
        return withPlaces(entries, places, named ? strings("chunkEntries", "places") : null);
    }

    private static JsonObject place(String kind, String name, String area)
    {
        JsonObject place = new JsonObject();
        place.addProperty("kind", kind);
        if (name != null) place.addProperty("name", name);
        if (area != null) place.addProperty("area", area);
        return place;
    }

    @Test
    public void theOceanAndInteriorsReadTheTrackersEntries() throws Exception
    {
        JsonObject entries = new JsonObject();
        entries.addProperty("45,45", "LOCKED");
        entries.addProperty("48,150", "ALLOWED");
        entries.addProperty("48,151", "NOT_READY");
        entries.addProperty("48,152", "A_NEWER_STATUS");
        entries.addProperty("48,153", 3);
        JsonObject places = new JsonObject();
        places.add("45,45", place("ocean", null, null));
        places.add("48,150", place("interior", "Mor Ul Rek · Outer Area", "Mor Ul Rek (TzHaar City)"));
        places.add("48,151", place("interior", null, "Keldagrim"));
        places.add("48,152", new JsonPrimitive("not a place"));
        DecisionService rules = withPlaces(entries, places, true);

        assertEquals(new Decision(PermissionStatus.LOCKED, "Ocean", null, Decision.Source.CHUNK),
            rules.chunk(new CanonicalChunk(45, 45)));
        assertEquals(new Decision(PermissionStatus.ALLOWED, "Mor Ul Rek · Outer Area", null, Decision.Source.CHUNK),
            rules.chunk(new CanonicalChunk(48, 150)));
        assertEquals(new Decision(PermissionStatus.NOT_READY, "Keldagrim", null, Decision.Source.CHUNK),
            rules.chunk(new CanonicalChunk(48, 151)));
        // A status from a newer tracker reads UNKNOWN; a value that isn't one leaves the chunk unmapped.
        assertEquals(new Decision(PermissionStatus.UNKNOWN, null, null, Decision.Source.CHUNK),
            rules.chunk(new CanonicalChunk(48, 152)));
        assertFalse(rules.chunk(new CanonicalChunk(48, 153)).isAuthored());
        // Land keeps its snapshot's answer.
        assertEquals(PermissionStatus.ALLOWED, rules.chunk(LUMBRIDGE).getStatus());
    }

    @Test
    public void withoutTheirCapabilitiesOrAsAnythingButObjectsThePlacesAreUnmapped() throws Exception
    {
        JsonObject entries = new JsonObject();
        entries.addProperty("45,45", "LOCKED");
        JsonObject places = new JsonObject();
        places.add("45,45", place("ocean", null, null));
        for (DecisionService rules : Arrays.asList(
            withPlaces(entries, places, false),
            withPlaces(strings("45,45"), places, true),
            withPlaces(new JsonPrimitive("LOCKED"), places, true)))
        {
            assertFalse(rules.chunk(new CanonicalChunk(45, 45)).isAuthored());
        }
        // Entries without places, or without the places capability, still decide, unnamed.
        assertEquals(new Decision(PermissionStatus.LOCKED, null, null, Decision.Source.CHUNK),
            withPlaces(entries, new JsonArray(), true).chunk(new CanonicalChunk(45, 45)));
        assertEquals(new Decision(PermissionStatus.LOCKED, null, null, Decision.Source.CHUNK),
            withPlaces(entries, places, strings("chunkEntries")).chunk(new CanonicalChunk(45, 45)));
    }

    /** The fixture with this bank table in its rules, named in its capabilities when asked. */
    private static DecisionService withBanks(JsonElement banks, boolean named) throws Exception
    {
        JsonObject root = new Gson().fromJson(fixtureText("bundles/v4-rules.json"), JsonObject.class);
        JsonObject rules = root.getAsJsonObject("rules");
        rules.add("banks", banks);
        if (named) rules.add("capabilities", strings("banks"));
        return playing(root.toString(), "nubles");
    }

    @Test
    public void theBankTableIsReadLeniently() throws Exception
    {
        JsonObject table = new JsonObject();
        // No facility chunks: the bank is where its chunk is, and the table outranks the chunk's row.
        JsonObject castle = new JsonObject();
        castle.addProperty("name", "Lumbridge Castle");
        castle.addProperty("status", "LOCKED");
        castle.addProperty("reason", "Roll it");
        castle.addProperty("at", "50,50");
        table.add("12850", castle);
        // A newer status reads UNKNOWN.
        JsonObject newer = new JsonObject();
        newer.addProperty("name", "Draynor Village");
        newer.addProperty("status", "A_NEWER_STATUS");
        newer.addProperty("at", "48,50");
        newer.add("physical", strings("48,50"));
        table.add("12338", newer);
        // Without a chunk it can't be placed.
        JsonObject nowhere = new JsonObject();
        nowhere.addProperty("name", "Nowhere");
        nowhere.addProperty("status", "LOCKED");
        table.add("1", nowhere);
        table.add("2", new JsonPrimitive("not a bank"));
        DecisionService rules = withBanks(table, true);

        assertEquals(new Decision(PermissionStatus.LOCKED, "Lumbridge Castle", "Roll it", Decision.Source.ROW),
            rules.bankAt(LUMBRIDGE));
        assertEquals(new Decision(PermissionStatus.UNKNOWN, "Draynor Village", null, Decision.Source.ROW),
            rules.bankAt(new CanonicalChunk(48, 50)));
        assertNull("no bank in the table is allowed", rules.nearestBank(new CanonicalChunk(49, 50)));
        // Without the capability, or as anything but an object, the rows decide as before.
        for (DecisionService older : Arrays.asList(withBanks(table, false), withBanks(strings("12850"), true)))
        {
            assertEquals(PermissionStatus.ALLOWED, older.bankAt(LUMBRIDGE).getStatus());
            assertEquals(new FateLockedBundle.Nearest(LUMBRIDGE, 1), older.nearestBank(new CanonicalChunk(49, 50)));
        }
    }

    @Test
    public void anotherCharacterGetsNoRowsNorLocks() throws Exception
    {
        DecisionService zezima = playing(fixtureText("bundles/v4-rules.json"), "zezima");

        assertEquals(PermissionStatus.UNKNOWN,
            zezima.target(LUMBRIDGE, "SHOP", "Lumbridge General Store").getStatus());
        assertEquals(PermissionStatus.UNKNOWN, zezima.chunk(LUMBRIDGE).getStatus());
        assertFalse(zezima.details(LUMBRIDGE).isPresent());
        assertEquals("Wrong account", zezima.trustReason());
        // Names aren't decisions.
        assertEquals("Lumbridge", zezima.chunkName(LUMBRIDGE));
    }

    @Test
    public void unauthoredChunksAndOlderExportRowsRemainUnknown() throws Exception
    {
        DecisionService legacy = playing(fixtureText("bundles/v3-standard.json"), "nubles");
        CanonicalChunk falador = new CanonicalChunk(46, 52);
        assertEquals(PermissionStatus.UNKNOWN, legacy.target(falador, "BANK", "").getStatus());
        assertEquals(Decision.Source.LEGACY, legacy.chunk(falador).getSource());

        assertEquals(PermissionStatus.UNKNOWN, nubles().chunk(new CanonicalChunk(1, 1)).getStatus());
        assertEquals(Decision.Source.UNMAPPED, nubles().chunk(new CanonicalChunk(1, 1)).getSource());
    }
}

package com.fatelocked;

import org.junit.Test;

import java.time.Instant;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SyncMachineTest
{
    private static final Instant START = Instant.parse("2026-09-25T12:00:00Z");

    private final SyncMachine machine = new SyncMachine();

    @Test
    public void aCheckIsDueAtOnceAndReservesTheNextTickWhileItRuns()
    {
        assertTrue(machine.checkDue(START));
        assertFalse(machine.checkDue(START.plusSeconds(SyncMachine.WAITING_POLL_SECONDS - 1)));
        assertTrue(machine.checkDue(START.plusSeconds(SyncMachine.WAITING_POLL_SECONDS)));
    }

    @Test
    public void failuresWaitTwiceAsLongEachTimeUpToFiveMinutes()
    {
        long[] waits = {30, 60, 120, 240, 300, 300};
        Instant now = START;
        for (long wait : waits)
        {
            machine.failed(now, SyncMachine.FAILURE_BACKOFF_SECONDS);
            assertFalse("before " + wait, machine.checkDue(now.plusSeconds(wait - 1)));
            now = now.plusSeconds(wait);
            assertTrue("after " + wait, machine.checkDue(now));
        }
    }

    @Test
    public void beforeAnyCheckTheStatusSaysWhetherSyncIsOffOrAboutToCheck()
    {
        assertEquals(SyncReason.CHECKING, SyncMachine.idle(true, true).getReason());
        assertEquals(SyncReason.SYNC_OFF, SyncMachine.idle(false, true).getReason());
        assertEquals(SyncReason.NOT_PAIRED, SyncMachine.idle(true, false).getReason());
        assertEquals(SyncReason.NOT_PAIRED, SyncMachine.idle(false, false).getReason());
    }

    @Test
    public void aFailureSaysWhyAndWhenTheNextCheckIs()
    {
        machine.accepted("41", START);

        TrackerConnectionSnapshot failed = machine.failure(TrackerConnectionState.OFFLINE,
            SyncReason.UNREACHABLE, START.plusSeconds(60), SyncMachine.FAILURE_BACKOFF_SECONDS);

        assertEquals(SyncReason.UNREACHABLE, failed.getReason());
        assertEquals(START.plusSeconds(90), failed.getNextCheck());
        assertEquals(START, failed.getLastSync());
        assertFalse(machine.checkDue(START.plusSeconds(89)));
        assertTrue(machine.checkDue(START.plusSeconds(90)));
    }

    @Test
    public void aRetryAfterIsHonouredAsGivenFromThirtySecondsToAnHour()
    {
        Instant now = START;
        // Asked twice for two minutes: two minutes each time, not doubled.
        for (int time = 0; time < 2; time++)
        {
            TrackerConnectionSnapshot busy = machine.busy(now, 120);
            assertEquals(SyncReason.BUSY, busy.getReason());
            assertEquals(now.plusSeconds(120), busy.getNextCheck());
            now = now.plusSeconds(120);
        }
        assertEquals(now.plusSeconds(30), machine.busy(now, 5).getNextCheck());
        assertEquals(now.plusSeconds(3600), machine.busy(now, 7200).getNextCheck());
    }

    @Test
    public void aBusyReplyWithoutRetryAfterBacksOffLikeAFailure()
    {
        assertEquals(START.plusSeconds(30), machine.busy(START, 0).getNextCheck());
        assertEquals(START.plusSeconds(60), machine.busy(START, 0).getNextCheck());
    }

    @Test
    public void checkNowForgetsTheBackOffAtMostEveryTenSeconds()
    {
        for (int failure = 0; failure < 4; failure++)
        {
            machine.failed(START, SyncMachine.FAILURE_BACKOFF_SECONDS);
        }
        assertFalse(machine.checkDue(START));

        assertTrue(machine.checkNow(START));
        assertTrue(machine.checkDue(START));
        assertFalse(machine.checkNow(START.plusSeconds(SyncMachine.CHECK_NOW_SECONDS - 1)));
        assertTrue(machine.checkNow(START.plusSeconds(SyncMachine.CHECK_NOW_SECONDS)));
        // And the next failure waits the shortest time again.
        machine.failed(START.plusSeconds(10), SyncMachine.FAILURE_BACKOFF_SECONDS);
        assertTrue(machine.checkDue(START.plusSeconds(10 + SyncMachine.FAILURE_BACKOFF_SECONDS)));
    }

    @Test
    public void loggedOutAHealthyConnectionIsCheckedEveryFiveMinutes()
    {
        machine.loggedIn(false, START);
        machine.accepted("41", START);

        assertFalse(machine.checkDue(START.plusSeconds(SyncMachine.CONNECTED_POLL_SECONDS)));
        assertFalse(machine.checkDue(START.plusSeconds(SyncMachine.LOGGED_OUT_POLL_SECONDS - 1)));
        assertTrue(machine.checkDue(START.plusSeconds(SyncMachine.LOGGED_OUT_POLL_SECONDS)));
    }

    @Test
    public void aLoginMakesACheckDueAtOnceButALoadingScreenDoesNot()
    {
        machine.loggedIn(false, START);
        machine.accepted("41", START);
        Instant login = START.plusSeconds(30);

        machine.loggedIn(true, login);
        assertTrue(machine.checkDue(login));

        machine.confirmed(login);
        machine.loggedIn(true, login.plusSeconds(10));
        assertFalse(machine.checkDue(login.plusSeconds(10)));
        assertTrue(machine.checkDue(login.plusSeconds(SyncMachine.CONNECTED_POLL_SECONDS)));
    }

    @Test
    public void aLoginStillWaitsForTheRelaysRetryAfter()
    {
        machine.loggedIn(false, START);
        machine.busy(START, 600);

        machine.loggedIn(true, START.plusSeconds(60));

        assertFalse(machine.checkDue(START.plusSeconds(599)));
        assertTrue(machine.checkDue(START.plusSeconds(600)));
    }

    @Test
    public void acceptedRulesAreConnectedAndCheckedEveryMinute()
    {
        machine.failed(START, SyncMachine.FAILURE_BACKOFF_SECONDS);

        TrackerConnectionSnapshot connected = machine.accepted("41", START);

        assertEquals(TrackerConnectionState.CONNECTED, connected.getState());
        assertEquals("41", machine.acceptedVersion());
        assertEquals(START, machine.lastSync());
        assertFalse(machine.checkDue(START.plusSeconds(SyncMachine.CONNECTED_POLL_SECONDS - 1)));
        assertTrue(machine.checkDue(START.plusSeconds(SyncMachine.CONNECTED_POLL_SECONDS)));
    }

    @Test
    public void aConfirmationRefreshesTheSyncTimeAndKeepsTheVersion()
    {
        machine.accepted("41", START);
        Instant later = START.plusSeconds(90);

        TrackerConnectionSnapshot connected = machine.confirmed(later);

        assertEquals(TrackerConnectionState.CONNECTED, connected.getState());
        assertEquals(later, connected.getLastSync());
        assertEquals("41", connected.getAcceptedVersion());
    }

    @Test
    public void aNewPairingWaitsForTheBrowserQuicklyThenSlowlyThenGivesUp()
    {
        machine.pairingStarted(START);

        TrackerConnectionSnapshot early = machine.notFound(false, START.plusSeconds(10));
        assertEquals(SyncReason.CONFIRM_IN_BROWSER.status, early.getMessage());
        assertTrue(machine.checkDue(START.plusSeconds(10 + SyncMachine.WAITING_POLL_SECONDS)));

        Instant slow = START.plusSeconds(SyncMachine.PAIRING_FAST_POLL_WINDOW_SECONDS);
        assertEquals(SyncReason.CONFIRM_IN_BROWSER.status, machine.notFound(false, slow).getMessage());
        assertFalse(machine.checkDue(slow.plusSeconds(SyncMachine.PAIRING_SLOW_POLL_SECONDS - 1)));

        TrackerConnectionSnapshot expired = machine.notFound(false,
            START.plusSeconds(SyncMachine.PAIRING_CONFIRM_SECONDS));
        assertEquals(TrackerConnectionState.EXPIRED, expired.getState());
        assertEquals(SyncReason.NO_PROFILE.status, expired.getMessage());
    }

    @Test
    public void aRePairingKeepsTheSyncTimeAndGivesUpAfterTenMinutes()
    {
        machine.accepted("41", START);
        Instant repair = START.plusSeconds(60);

        TrackerConnectionSnapshot waiting = machine.repairStarted(repair);
        assertEquals(SyncReason.CONFIRM_REPAIR, waiting.getReason());
        assertEquals(START, waiting.getLastSync());
        assertNull(machine.acceptedVersion());
        assertFalse(machine.firstPairingWaiting());

        assertEquals(SyncReason.CONFIRM_REPAIR, machine.notFound(false, repair.plusSeconds(10)).getReason());
        assertTrue(machine.repairing());

        TrackerConnectionSnapshot kept = machine.notFound(false,
            repair.plusSeconds(SyncMachine.PAIRING_CONFIRM_SECONDS));
        assertEquals(SyncReason.REPAIR_ABANDONED, kept.getReason());
        assertEquals(START, kept.getLastSync());
        assertFalse(machine.repairing());
    }

    @Test
    public void aFirstPairingIsNotARePairing()
    {
        machine.pairingStarted(START);

        assertTrue(machine.firstPairingWaiting());
        assertEquals(SyncReason.NO_PROFILE, machine.notFound(false,
            START.plusSeconds(SyncMachine.PAIRING_CONFIRM_SECONDS)).getReason());
        assertTrue(machine.firstPairingWaiting());
    }

    @Test
    public void cancellingARePairingChecksTheWorkingPairingAtOnce()
    {
        machine.accepted("41", START);
        machine.repairStarted(START.plusSeconds(60));

        TrackerConnectionSnapshot back = machine.repairCancelled();

        assertEquals(SyncReason.CHECKING, back.getReason());
        assertFalse(machine.repairing());
        assertTrue(machine.checkDue(START.plusSeconds(61)));
    }

    @Test
    public void aRePairingThatDeliversIsOver()
    {
        machine.repairStarted(START);

        machine.accepted("42", START.plusSeconds(30));

        assertFalse(machine.repairing());
        assertFalse(machine.firstPairingWaiting());
    }

    @Test
    public void aCodeTheOwnerDisconnectedIsGoneUntilItDeliversAgain()
    {
        machine.accepted("41", START);
        Instant gone = START.plusSeconds(60);

        TrackerConnectionSnapshot shown = machine.gone(gone);

        assertEquals(TrackerConnectionState.EXPIRED, shown.getState());
        assertEquals(SyncReason.GONE, shown.getReason());
        assertEquals(START, shown.getLastSync());
        assertNull(machine.acceptedVersion());
        assertTrue(machine.pairingGone());
        assertFalse(machine.checkDue(gone.plusSeconds(SyncMachine.LOGGED_OUT_POLL_SECONDS - 1)));
        assertTrue(machine.checkDue(gone.plusSeconds(SyncMachine.LOGGED_OUT_POLL_SECONDS)));

        machine.accepted("42", gone.plusSeconds(600));
        assertFalse(machine.pairingGone());
    }

    @Test
    public void aProfileThatLapsedSaysNoRecentUpdateAndForgetsItsVersion()
    {
        machine.accepted("41", START);

        TrackerConnectionSnapshot lapsed = machine.notFound(true, START.plusSeconds(60));

        assertEquals(TrackerConnectionState.WAITING, lapsed.getState());
        assertEquals(SyncReason.NO_RECENT_UPDATE.status, lapsed.getMessage());
        // The next check asks for whatever the relay has, with no validator.
        assertNull(machine.acceptedVersion());
        assertNull(machine.validator());
        assertEquals(START, lapsed.getLastSync());
    }

    @Test
    public void aLocalImportForgetsTheVersionSoTheNextCheckFetchesInFull()
    {
        assertFalse(machine.localRulesReplaced());
        machine.accepted("41", START);

        assertTrue(machine.localRulesReplaced());

        assertNull(machine.acceptedVersion());
        assertTrue(machine.checkDue(START));
    }

    @Test
    public void aSeedHoldsSavedRulesUntilThisSessionAcceptsAnything()
    {
        assertTrue(machine.seed("\"41\""));
        assertEquals("41", machine.acceptedVersion());

        machine.accepted("42", START);
        assertFalse(machine.seed("40"));
        assertEquals("42", machine.acceptedVersion());
    }

    @Test
    public void aRejectedVersionBecomesTheValidatorUntilNewerRulesArrive()
    {
        machine.accepted("41", START);
        assertEquals("41", machine.validator());

        TrackerConnectionSnapshot failed = machine.rejected("42", SyncReason.FUTURE_FORMAT, START);

        assertEquals(TrackerConnectionState.IMPORT_FAILED, failed.getState());
        assertEquals(SyncReason.FUTURE_FORMAT, failed.getReason());
        assertEquals("42", machine.validator());
        assertEquals("41", machine.acceptedVersion());
        // Still that version, still for the same reason.
        assertEquals(SyncReason.FUTURE_FORMAT,
            machine.stillRejected(START.plusSeconds(30)).getReason());
        assertEquals("42", machine.validator());

        machine.accepted("43", START.plusSeconds(90));
        assertNull(machine.rejectedVersion());
        assertEquals("43", machine.validator());
    }

    @Test
    public void aRejectedVersionGoesWithTheProfile()
    {
        machine.rejected("42", SyncReason.INVALID_RULES, START);

        machine.notFound(false, START.plusSeconds(30));

        assertNull(machine.rejectedVersion());
        assertNull(machine.validator());
    }

    @Test
    public void changingThePairingOrConsentStartsOver()
    {
        machine.accepted("41", START);
        assertEquals(TrackerConnectionState.WAITING, machine.pairingReplaced(true).getState());
        assertNull(machine.acceptedVersion());
        assertNull(machine.lastSync());

        machine.accepted("41", START);
        assertEquals(TrackerConnectionState.DISCONNECTED,
            machine.networkAccessChanged(false, true).getState());
        assertNull(machine.acceptedVersion());
        assertTrue(machine.checkDue(START));
    }
}

package com.fatelocked;

import com.fatelocked.guardian.travel.IntentClassifier;
import com.fatelocked.guardian.travel.TravelMatch;
import com.fatelocked.rules.Decision;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.fatelocked.rules.TravelTable;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeSet;
import java.util.zip.GZIPInputStream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Runs the web app's golden bundles through the real codec and rule engine
 * and compares the answers with the app's own (see
 * src/test/resources/contracts/PINNED for the web commit they came from).
 */
@RunWith(Parameterized.class)
public class GoldenBundleContractTest
{
    static final String DIR = "contracts/golden-bundles/";
    private static final Gson GSON = new Gson();

    @Parameterized.Parameters(name = "{0}")
    public static List<Object[]> scenarios() throws IOException
    {
        List<Object[]> ids = new ArrayList<>();
        for (JsonElement scenario : json("manifest.json").getAsJsonArray("scenarios"))
        {
            ids.add(new Object[] {scenario.getAsJsonObject().get("id").getAsString()});
        }
        return ids;
    }

    private final String id;
    private final byte[] gzipped;
    private final FateLockedBundle bundle;
    private final JsonObject expected;

    public GoldenBundleContractTest(String id) throws IOException
    {
        this.id = id;
        gzipped = bytes(id + ".bundle.json.gz");
        bundle = FateLockedBundle.loadFromJson(GSON, gunzip(gzipped));
        expected = json(id + ".expect.json");
    }

    @Test
    public void landChunksMatchTheTracker()
    {
        List<String> mismatches = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("chunks").entrySet())
        {
            CanonicalChunk chunk = chunk(entry.getKey());
            if (!isLand(chunk)) continue;
            FateLockedBundle.LockState want = entry.getValue().getAsBoolean()
                ? FateLockedBundle.LockState.UNLOCKED : FateLockedBundle.LockState.LOCKED;
            FateLockedBundle.LockState got = bundle.lockStateAt(chunk);
            if (got != want) mismatches.add(entry.getKey() + " want " + want + " got " + got);
        }
        assertEquals(id + " land chunks", List.of(), mismatches);
    }

    /**
     * Every land, ocean and interior chunk reads the tracker's entry (R1), and
     * a place without a snapshot is named as the tracker names it.
     */
    @Test
    public void everyPlaceMatchesTheTracker() throws IOException
    {
        DecisionService engine = DecisionService.create(RulesSnapshot.of(bundle), null, null);
        List<String> mismatches = new ArrayList<>();
        int places = 0;
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("entries").entrySet())
        {
            CanonicalChunk chunk = chunk(entry.getKey());
            Decision decision = engine.chunk(chunk);
            if (!entry.getValue().getAsString().equals(decision.getStatus().name()))
            {
                mismatches.add(entry.getKey() + " want " + entry.getValue().getAsString() + " got " + decision.getStatus());
            }
            if (!isLand(chunk)) places++;
        }
        assertEquals(id + " entries", List.of(), mismatches);
        assertTrue(id + " has ocean or interior chunks", places > 0);

        List<String> misnamed = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : json("places.json").getAsJsonObject("places").entrySet())
        {
            CanonicalChunk chunk = chunk(entry.getKey());
            if (bundle.permissionsAt(chunk).isPresent()) continue;
            JsonObject place = entry.getValue().getAsJsonObject();
            String want = "ocean".equals(place.get("kind").getAsString()) ? "Ocean"
                : place.has("name") ? place.get("name").getAsString()
                : place.has("area") ? place.get("area").getAsString() : null;
            String got = engine.chunk(chunk).getLabel();
            if (!Objects.equals(want, got)) misnamed.add(entry.getKey() + " want " + want + " got " + got);
        }
        assertEquals(id + " place names", List.of(), misnamed);
    }

    @Test
    public void namedAreasMatchTheTracker()
    {
        List<String> mismatches = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("areas").entrySet())
        {
            boolean want = entry.getValue().getAsBoolean();
            if (bundle.isUnlocked(entry.getKey()) != want)
            {
                mismatches.add(entry.getKey() + " want " + want);
            }
        }
        assertEquals(id + " named areas", List.of(), mismatches);
    }

    @Test
    public void banksMatchTheTracker()
    {
        List<String> mismatches = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : expected.getAsJsonObject("banks").entrySet())
        {
            int bankId = Integer.parseInt(entry.getKey());
            CanonicalChunk chunk = new CanonicalChunk(bankId / 256, bankId % 256);
            boolean want = entry.getValue().getAsBoolean();
            if (bundle.isBankUnlocked(chunk) != want) mismatches.add(entry.getKey() + " want " + want);
        }
        assertEquals(id + " banks", List.of(), mismatches);
    }

    @Test
    public void frontierMatchesTheTracker()
    {
        if (!expected.has("frontier")) return;
        TreeSet<String> want = new TreeSet<>();
        for (JsonElement key : expected.getAsJsonArray("frontier")) want.add(key.getAsString());
        TreeSet<String> got = new TreeSet<>();
        DecisionService engine = DecisionService.create(RulesSnapshot.of(bundle), null, null);
        for (String key : expected.getAsJsonObject("chunks").keySet())
        {
            CanonicalChunk chunk = chunk(key);
            if (isLand(chunk) && engine.isFrontier(chunk)) got.add(key);
        }
        assertEquals(id + " frontier", want, got);
    }

    /**
     * F2 (G7, G13): every option of every travel method, clicked on each of
     * its ids as the game gives them, is classified back to that method and
     * option by id alone; and each answer the golden pins is the tracker's.
     */
    @Test
    public void travelMatchesTheTracker()
    {
        TravelTable table = bundle.getRules().getTravel();
        IntentClassifier classifier = new IntentClassifier();
        List<String> mismatches = new ArrayList<>();
        int clicks = 0;
        for (TravelTable.Method method : table.methods())
        {
            for (String option : texts(method))
            {
                for (MenuFacts click : clicks(method, option))
                {
                    clicks++;
                    TravelMatch match = classifier.classify(click, table);
                    if (match == null || match.getMethod() != method || match.getOption() != method.option(option))
                    {
                        mismatches.add(method.getId() + "|" + option + " on " + click);
                    }
                }
            }
        }
        assertTrue(id + " clicks " + clicks, clicks > 1000);
        assertEquals(id + " travel", List.of(), mismatches);

        for (Map.Entry<String, JsonElement> answer : expected.getAsJsonObject("travel").entrySet())
        {
            String[] key = answer.getKey().split("\\|", 2);
            String option = key[1].startsWith("code:") ? "Last-destination (" + key[1].substring(5) + ")" : key[1];
            TravelMatch match = classifier.classify(clicks(table.method(key[0]), option).get(0), table);
            assertEquals(id + " " + answer.getKey(), answer.getValue().getAsString(), match.getOption().getStatus().name());
        }
    }

    /** The menu texts a method's options are clicked as: each option, and a fairy ring's Last-destination for each code. */
    static List<String> texts(TravelTable.Method method)
    {
        List<String> texts = new ArrayList<>(method.getOptions().keySet());
        for (String code : method.getCodes().keySet()) texts.add("Last-destination (" + code + ")");
        return texts;
    }

    /** Clicks on a method as the game gives them: its spell on the spellbook, or each id in the inventory or the scene. */
    static List<MenuFacts> clicks(TravelTable.Method method, String option)
    {
        List<MenuFacts> clicks = new ArrayList<>();
        if (method.getMatch() == TravelTable.Match.SPELL)
        {
            clicks.add(MenuFacts.builder().kind(MenuFacts.Kind.WIDGET).interfaceGroup(InterfaceID.MAGIC_SPELLBOOK)
                .spellbook(TravelTable.SPELLBOOKS.indexOf(method.getSpellbook())).option(option)
                .target(method.getSpell()).build());
            return clicks;
        }
        for (int itemOrObject : method.getIds())
        {
            MenuFacts.MenuFactsBuilder click = MenuFacts.builder().option(option).target(method.getLabel());
            switch (method.getMatch())
            {
                case ITEMS:
                    click.kind(MenuFacts.Kind.WIDGET).interfaceGroup(InterfaceID.INVENTORY).itemId(itemOrObject);
                    break;
                case OBJECTS:
                    click.kind(MenuFacts.Kind.OBJECT).objectId(itemOrObject);
                    break;
                default:
                    click.kind(MenuFacts.Kind.NPC).npcId(itemOrObject);
                    break;
            }
            clicks.add(click.build());
        }
        return clicks;
    }

    @Test
    public void rulesEntriesSurviveTheCodec()
    {
        JsonObject rulesChunks = GSON.fromJson(gunzip(gzipped), JsonObject.class)
            .getAsJsonObject("rules").getAsJsonObject("chunks");
        DecisionService engine = DecisionService.create(RulesSnapshot.of(bundle), null, null);
        List<String> mismatches = new ArrayList<>();
        for (Map.Entry<String, JsonElement> entry : rulesChunks.entrySet())
        {
            String want = entry.getValue().getAsJsonObject().get("entry").getAsString();
            String got = engine.chunk(chunk(entry.getKey())).getStatus().name();
            if (!want.equals(got)) mismatches.add(entry.getKey() + " want " + want + " got " + got);
        }
        assertTrue(id + " has v4 rules", rulesChunks.size() > 0);
        assertEquals(id + " v4 entries", List.of(), mismatches);
    }

    @Test
    public void compressedBundleDecodesToTheSameRules()
    {
        FateLockedBundle compressed = FateLockedBundle.loadFromJson(GSON,
            "FLGZ:" + Base64.getEncoder().encodeToString(gzipped));
        for (String key : expected.getAsJsonObject("chunks").keySet())
        {
            CanonicalChunk chunk = chunk(key);
            assertEquals(id + " " + key, bundle.lockStateAt(chunk), compressed.lockStateAt(chunk));
        }
        for (String name : expected.getAsJsonObject("areas").keySet())
        {
            assertEquals(id + " " + name, bundle.isUnlocked(name), compressed.isUnlocked(name));
        }
    }

    /** A chunk the plugin's legacy engine maps to a named area or continent. */
    private boolean isLand(CanonicalChunk chunk)
    {
        return bundle.regionAt(chunk) != null || bundle.subAreaAt(chunk) != null;
    }

    static CanonicalChunk chunk(String key)
    {
        String[] parts = key.split(",");
        return new CanonicalChunk(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
    }

    static JsonObject json(String name) throws IOException
    {
        return GSON.fromJson(new String(bytes(name), StandardCharsets.UTF_8), JsonObject.class);
    }

    static byte[] bytes(String name) throws IOException
    {
        try (InputStream in = GoldenBundleContractTest.class.getClassLoader()
            .getResourceAsStream(DIR + name))
        {
            if (in == null) throw new IOException("missing golden file " + name);
            return in.readAllBytes();
        }
    }

    static String gunzip(byte[] gzipped)
    {
        try (GZIPInputStream in = new GZIPInputStream(new java.io.ByteArrayInputStream(gzipped));
             ByteArrayOutputStream out = new ByteArrayOutputStream())
        {
            in.transferTo(out);
            return out.toString(StandardCharsets.UTF_8);
        }
        catch (IOException ex)
        {
            throw new IllegalStateException("corrupt golden bundle", ex);
        }
    }
}

package com.fatelocked;

import org.junit.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Stream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The Plugin Hub notes promise that Strict Mode stops only exactly matched
 * travel, and that no menu entry is ever removed, reordered or created.
 * Pinned at the source level so a new consume site cannot slip in unnoticed.
 */
public class PluginHubClickBoundaryTest
{
    @Test
    public void onlyTheTravelClickHandlerConsumesGameClicks() throws Exception
    {
        int consumes = 0;
        for (Map.Entry<Path, String> source : productionSources().entrySet())
        {
            // Swing key events (the keybind button) are not game clicks.
            if (!source.getValue().contains("MenuOptionClicked")) continue;
            int found = occurrences(source.getValue(), ".consume()");
            if (found > 0)
            {
                assertEquals("a game click is consumed in " + source.getKey(),
                    "StrictModeClickHandler.java",
                    source.getKey().getFileName().toString());
            }
            consumes += found;
        }
        assertEquals(1, consumes);

        String handler = sourceNamed("StrictModeClickHandler.java");
        int travel = handler.indexOf("public GuardResult handleTravel(");
        assertTrue(travel >= 0);
        assertTrue(handler.indexOf(".consume()") > travel);
    }

    @Test
    public void menusAreNeverRemovedReorderedOrCreated() throws Exception
    {
        String all = String.join("\n", productionSources().values());
        for (String forbidden : new String[] {
            "setMenuEntries(", "createMenuEntry(", "setDeprioritized(",
            "removeMenuEntry(", "setForceLeftClick(", "setOption(" })
        {
            assertFalse(forbidden, all.contains(forbidden));
        }
        // The only change to a menu is the " (Locked)" tag on a target.
        assertEquals(1, occurrences(all, "entry.setTarget("));
        assertEquals(0, occurrences(all.replace("entry.setTarget(", "")
            .replace("point.setTarget(", ""), ".setTarget("));
    }

    private static String sourceNamed(String fileName) throws IOException
    {
        for (Map.Entry<Path, String> entry : productionSources().entrySet())
        {
            if (entry.getKey().getFileName().toString().equals(fileName))
            {
                return entry.getValue();
            }
        }
        throw new AssertionError("missing production source " + fileName);
    }

    private static Map<Path, String> productionSources() throws IOException
    {
        Map<Path, String> sources = new LinkedHashMap<>();
        try (Stream<Path> paths = Files.walk(Paths.get("src", "main", "java")))
        {
            paths.filter(path -> path.toString().endsWith(".java"))
                .sorted()
                .forEach(path -> sources.put(path, read(path)));
        }
        return sources;
    }

    private static String read(Path path)
    {
        try
        {
            return new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
        }
        catch (IOException ex)
        {
            throw new AssertionError("could not read " + path, ex);
        }
    }

    private static int occurrences(String text, String needle)
    {
        int count = 0;
        for (int at = text.indexOf(needle); at >= 0; at = text.indexOf(needle, at + 1))
        {
            count++;
        }
        return count;
    }
}

package com.fatelocked;

import com.fatelocked.guardian.StrictModeAuditEntry;
