    private static GeneralPath whole(Run run, Kind kind, int playerX, int playerY,
        ChunkBorderRenderer.Projector projector, Occlusion occlusion)
    {
        return ChunkBorderRenderer.lines(Collections.singletonList(run), kind, playerX, playerY, SIZE, SIZE, projector,
            GROUND, occlusion).whole;
    }

    private static BufferedImage draw(List<Run> runs, FateLockedConfig.ChunkBorders borders, boolean fog,
        Occlusion occlusion)
    {
        BufferedImage image = new BufferedImage(1100, 1100, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        ChunkBorderRenderer.draw(graphics, runs, borders, fog, Palette.defaults(), 60, 60, SIZE, SIZE, FLAT, GROUND,
            occlusion);
        graphics.dispose();
        return image;
    }

    private static boolean any(boolean[][] tiles)
    {
        for (boolean[] column : tiles)
        {
            for (boolean tile : column)
            {
                if (tile)
                {
                    return true;
                }
            }
        }
        return false;
    }

    /** Whether any pixel is this colour, give or take a unit of compositing. */
    private static boolean has(BufferedImage image, Color colour)
    {
        for (int x = 0; x < image.getWidth(); x++)
        {
            for (int y = 0; y < image.getHeight(); y++)
            {
                if (near(image.getRGB(x, y), colour))
                {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean near(int argb, Color colour)
    {
        Color pixel = new Color(argb, true);
        return Math.abs(pixel.getRed() - colour.getRed()) <= 1 && Math.abs(pixel.getGreen() - colour.getGreen()) <= 1
            && Math.abs(pixel.getBlue() - colour.getBlue()) <= 1 && Math.abs(pixel.getAlpha() - colour.getAlpha()) <= 1;
    }

    /** Each segment of a path as {type, x, y}. */
    private static List<double[]> segments(GeneralPath path)
    {
        List<double[]> segments = new ArrayList<>();
        double[] coords = new double[6];
        for (PathIterator it = path.getPathIterator(null); !it.isDone(); it.next())
        {
            int type = it.currentSegment(coords);
            segments.add(new double[] {type, coords[0], coords[1]});
        }
        return segments;
    }

    /** Each drawn piece of an upright line, as {from, to} up the canvas. */
    private static List<double[]> pieces(GeneralPath path)
    {
        List<double[]> pieces = new ArrayList<>();
        List<double[]> segments = segments(path);
        for (int i = 1; i < segments.size(); i++)
        {
            if (segments.get(i)[0] == PathIterator.SEG_LINETO)
            {
                pieces.add(new double[] {segments.get(i - 1)[2], segments.get(i)[2]});
            }
        }
        return pieces;
    }

    /** Each dash of an upright line wholly between two heights on the canvas, as {from, to}. */
    private static List<double[]> dashes(GeneralPath path, double from, double to)
    {
        List<double[]> dashes = new ArrayList<>();
        List<double[]> segments = segments(path);
        int i = 0;
        while (i < segments.size())
        {
            double start = segments.get(i++)[2];
            double end = start;
            while (i < segments.size() && segments.get(i)[0] == PathIterator.SEG_LINETO)
            {
                end = segments.get(i++)[2];
            }
            if (start >= from && end <= to)
            {
                dashes.add(new double[] {start, end});
            }
        }
        return dashes;
    }
}

package com.fatelocked;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.RejectedExecutionException;

import static org.junit.Assert.assertEquals;

public class SerialFileWriterTest
{
    private final List<Runnable> executorTasks = new ArrayList<>();
    private final SerialFileWriter writer = new SerialFileWriter(executorTasks::add);

    @Test
    public void writesRunOffTheCallingThreadInTheOrderTheyWereAskedFor()
    {
        List<String> written = new ArrayList<>();

        writer.submit(() -> written.add("history"));
        writer.submit(() -> written.add("audit"));
        writer.submit(() -> written.add("slayer"));

        // Nothing is written by the caller, and one drain runs them all.
        assertEquals(0, written.size());
        assertEquals(1, executorTasks.size());

        runExecutor();
        assertEquals(List.of("history", "audit", "slayer"), written);
    }

    @Test
    public void aFailedWriteDoesNotStopTheOnesAfterIt()
    {
        List<String> written = new ArrayList<>();

        writer.submit(() -> { throw new IllegalStateException("disk full"); });
        writer.submit(() -> written.add("audit"));
        runExecutor();

        assertEquals(List.of("audit"), written);
    }

    @Test
    public void aWriteAskedForAfterTheQueueEmptiedStartsANewDrain()
    {
        List<String> written = new ArrayList<>();

        writer.submit(() -> written.add("first"));
        runExecutor();
        writer.submit(() -> written.add("second"));

        assertEquals(1, executorTasks.size());
        runExecutor();
        assertEquals(List.of("first", "second"), written);
    }

    @Test
    public void aRefusedDrainLetsTheNextWriteTryAgain()
    {
        List<String> written = new ArrayList<>();
        boolean[] refuse = {true};
        SerialFileWriter refusing = new SerialFileWriter(task -> {
            if (refuse[0])
            {
                throw new RejectedExecutionException("shutting down");
            }
            executorTasks.add(task);
        });

        refusing.submit(() -> written.add("first"));
        refuse[0] = false;
        refusing.submit(() -> written.add("second"));
        runExecutor();

        assertEquals(List.of("first", "second"), written);
    }

    private void runExecutor()
    {
        while (!executorTasks.isEmpty())
        {
            executorTasks.remove(0).run();
        }
    }
}

package com.fatelocked;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RepeatedValueLimiterTest
{
    private static final long THIRTY_SECONDS = 30_000L;

    @Test
    public void reportsTheFirstValue()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
    }

    @Test
    public void suppressesTheSameValueInsideTheWindow()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
        assertFalse(limiter.shouldReport("first", 30_999L));
    }

    @Test
    public void reportsADifferentValueImmediately()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
        assertTrue(limiter.shouldReport("different", 2_000L));
    }

    @Test
    public void reportsTheSameValueAtTheWindowBoundary()
    {
        RepeatedValueLimiter limiter =
            new RepeatedValueLimiter(THIRTY_SECONDS);

        assertTrue(limiter.shouldReport("first", 1_000L));
        assertTrue(limiter.shouldReport("first", 31_000L));
    }

    @Test
    public void reportsAConcurrentIdenticalValueOnlyOnce() throws Exception
    {
        int callers = 16;
        ExecutorService executor = Executors.newFixedThreadPool(callers);
        try
        {
            for (int round = 0; round < 100; round++)
            {
                RepeatedValueLimiter limiter =
                    new RepeatedValueLimiter(THIRTY_SECONDS);
                CountDownLatch ready = new CountDownLatch(callers);
                CountDownLatch start = new CountDownLatch(1);
                List<Future<Boolean>> results = new ArrayList<>();
                for (int caller = 0; caller < callers; caller++)
                {
                    results.add(executor.submit(() -> {
                        ready.countDown();
                        start.await();
                        return limiter.shouldReport("same", 1_000L);
                    }));
                }
                ready.await();
                start.countDown();

                int reports = 0;
                for (Future<Boolean> result : results)
                {
                    if (result.get()) reports++;
                }
                assertEquals(
                    "concurrent reports in round " + round,
                    1,
                    reports);
            }
        }
        finally
        {
            executor.shutdownNow();
        }
    }
}

