    private static List<String> texts(Container root)
    {
        return all(root, com.fatelocked.ui.TextBlock.class::isInstance).stream()
            .map(block -> ((com.fatelocked.ui.TextBlock) block).getText()).collect(Collectors.toList());
    }

    private static List<Fold> folds(Container root)
    {
        return all(root, Fold.class::isInstance).stream().map(Fold.class::cast).collect(Collectors.toList());
    }

    /** The small labels shown, such as a closed category's summary, leaving out the " · " between. */
    private static List<String> labels(Container root)
    {
        List<String> shown = new ArrayList<>();
        for (Fold fold : folds(root))
        {
            for (Component label : all(fold, JLabel.class::isInstance))
            {
                String text = ((JLabel) label).getText();
                if (!text.isEmpty() && !text.trim().equals("·") && !text.matches("\\d+"))
                {
                    shown.add(text);
                }
            }
        }
        return shown;
    }

    private static List<FlatButton> buttons(Container root)
    {
        return all(root, FlatButton.class::isInstance).stream().map(FlatButton.class::cast)
            .collect(Collectors.toList());
    }

    private static List<Component> all(Container root, Predicate<Component> match)
    {
        List<Component> found = new ArrayList<>();
        for (Component child : root.getComponents())
        {
            if (match.test(child) && child.isVisible())
            {
                found.add(child);
            }
            if (child instanceof Container && child.isVisible())
            {
                found.addAll(all((Container) child, match));
            }
        }
        return found;
    }

    private static void onEdt(Runnable task) throws Exception
    {
        SwingUtilities.invokeAndWait(task);
    }
}

package com.fatelocked.sidebar;

import static com.fatelocked.rules.PermissionStatus.ALLOWED;
import static com.fatelocked.rules.PermissionStatus.LOCKED;
import static com.fatelocked.rules.PermissionStatus.NOT_READY;
import static com.fatelocked.rules.PermissionStatus.UNKNOWN;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;

/** The owner's review, 28 Sept: a row the tracker leaves undecided is decided by what the game says. */
public class RowChecksTest
{
    private static final String CAVES = "The Lost Tribe started; Death to the Dorgeshuun; Light source";

    @Test
    public void aRowTheTrackerDecidedStaysAsItIs()
    {
        assertEquals(new RowChecks.Decided(LOCKED, "Unlock Axe Shops"),
            RowChecks.decide(LOCKED, "Unlock Axe Shops", everything()));
        assertEquals(new RowChecks.Decided(NOT_READY, "Woodcutting 15/60 · cap 20"),
            RowChecks.decide(NOT_READY, "Woodcutting 15/60 · cap 20", everything()));
        assertEquals(new RowChecks.Decided(ALLOWED, null), RowChecks.decide(ALLOWED, null, GameFacts.NONE));
    }

    /** The Lumbridge caves' frogs: the quest started, the next one done and a lantern carried. */
    @Test
    public void everyRequirementMetCanBeDone()
    {
        GameFacts facts = facts(true, 0, Collections.emptyMap(),
            quests(Quest.THE_LOST_TRIBE, QuestState.IN_PROGRESS, Quest.DEATH_TO_THE_DORGESHUUN, QuestState.FINISHED),
            Collections.emptySet(), true);
        assertEquals(new RowChecks.Decided(ALLOWED, null), RowChecks.decide(UNKNOWN, CAVES, facts));
    }

    @Test
    public void onlyWhatIsLeftIsNamed()
    {
        GameFacts started = facts(true, 0, Collections.emptyMap(),
            quests(Quest.THE_LOST_TRIBE, QuestState.IN_PROGRESS, Quest.DEATH_TO_THE_DORGESHUUN, QuestState.NOT_STARTED),
            Collections.emptySet(), false);
        assertEquals(new RowChecks.Decided(NOT_READY, "Death to the Dorgeshuun; Light source"),
            RowChecks.decide(UNKNOWN, CAVES, started));
    }

    /** Logged out, or where the game can't say, nothing counts as met: the row isn't ready, and says why. */
    @Test
    public void whatTheGameCantSayIsNotMet()
    {
        assertEquals(new RowChecks.Decided(NOT_READY, CAVES), RowChecks.decide(UNKNOWN, CAVES, GameFacts.NONE));
        assertEquals(new RowChecks.Decided(NOT_READY, "A trustworthy partner in the opposite gang"),
            RowChecks.decide(UNKNOWN, "A trustworthy partner in the opposite gang", everything()));
    }

    /** A skilling row keeps the level and cap the tracker gives, and needs them met too. */
    @Test
    public void skillingKeepsItsLevelAndCap()
    {
        GameFacts started = facts(true, 0, Collections.emptyMap(), quests(Quest.THE_LOST_TRIBE, QuestState.FINISHED),
            Collections.emptySet(), null);
        assertEquals(new RowChecks.Decided(ALLOWED, "Fishing 1/1 · cap 10"),
            RowChecks.decide(UNKNOWN, "Fishing 1/1 · cap 10; The Lost Tribe started", started));
        assertEquals(new RowChecks.Decided(NOT_READY, "Mining 1/20 · cap 0"),
            RowChecks.decide(UNKNOWN, "Mining 1/20 · cap 0; The Lost Tribe started", started));
        assertEquals(new RowChecks.Decided(NOT_READY, "Mining 20/20 · cap 10"),
            RowChecks.decide(UNKNOWN, "Mining 20/20 · cap 10", started));
    }

    @Test
    public void eachKindOfRequirement()
    {
        assertTrue(RowChecks.met("F2P Only", facts(false, 0, Collections.emptyMap(), Collections.emptyMap(),
            Collections.emptySet(), null)));
        assertFalse("not on a members world", RowChecks.met("F2P Only", everything()));
        assertFalse("nor when the world isn't known", RowChecks.met("F2P Only", GameFacts.NONE));

        assertTrue(RowChecks.met("Lost City", quest(Quest.LOST_CITY, QuestState.FINISHED)));
        assertFalse(RowChecks.met("Lost City", quest(Quest.LOST_CITY, QuestState.IN_PROGRESS)));
        assertTrue(RowChecks.met("The Lost Tribe started", quest(Quest.THE_LOST_TRIBE, QuestState.IN_PROGRESS)));
        assertTrue(RowChecks.met("The Lost Tribe started", quest(Quest.THE_LOST_TRIBE, QuestState.FINISHED)));
        assertFalse(RowChecks.met("The Lost Tribe started", quest(Quest.THE_LOST_TRIBE, QuestState.NOT_STARTED)));
        assertTrue(RowChecks.met("Started The Restless Ghost",
            quest(Quest.THE_RESTLESS_GHOST, QuestState.IN_PROGRESS)));
        assertFalse(RowChecks.met("Started The Restless Ghost",
            quest(Quest.THE_RESTLESS_GHOST, QuestState.NOT_STARTED)));

        String temple = "While Guthix Sleeps: reached the Ancient Guthixian Temple";
        assertTrue("done passes every stage", RowChecks.met(temple,
            quest(Quest.WHILE_GUTHIX_SLEEPS, QuestState.FINISHED)));
        assertFalse("a stage part way through can't be seen", RowChecks.met(temple,
            quest(Quest.WHILE_GUTHIX_SLEEPS, QuestState.IN_PROGRESS)));
        assertTrue("the tracker's name for a Recipe for Disaster part", RowChecks.met("RFD: Dwarf",
            quest(Quest.RECIPE_FOR_DISASTER__MOUNTAIN_DWARF, QuestState.FINISHED)));

        assertTrue(RowChecks.met("Quest Points 32", facts(true, 32, Collections.emptyMap(), Collections.emptyMap(),
            Collections.emptySet(), null)));
        assertFalse(RowChecks.met("Quest Points 32", facts(true, 31, Collections.emptyMap(), Collections.emptyMap(),
            Collections.emptySet(), null)));
        assertTrue(RowChecks.met("Attack 15", level(Skill.ATTACK, 15)));
        assertFalse(RowChecks.met("Attack 15", level(Skill.ATTACK, 14)));
        assertFalse("a level the game didn't give", RowChecks.met("Attack 15", GameFacts.NONE));

        assertTrue(RowChecks.met("Brass key", carrying("brass key")));
        assertFalse(RowChecks.met("Brass key", carrying("steel key ring")));
        assertTrue("either of several", RowChecks.met("Dramen staff or lunar staff", carrying("lunar staff")));
        assertTrue(RowChecks.met("Light source", facts(true, 0, Collections.emptyMap(), Collections.emptyMap(),
            Collections.emptySet(), true)));
        assertFalse(RowChecks.met("Light source", facts(true, 0, Collections.emptyMap(), Collections.emptyMap(),
            Collections.emptySet(), false)));
    }

    @Test
    public void theQuestsNamedAreTheOnesToAskTheGameAbout()
    {
        assertEquals(new LinkedHashSet<>(Arrays.asList(Quest.THE_LOST_TRIBE, Quest.DEATH_TO_THE_DORGESHUUN,
                Quest.WHILE_GUTHIX_SLEEPS, Quest.RECIPE_FOR_DISASTER__MOUNTAIN_DWARF, Quest.THE_RESTLESS_GHOST)),
            RowChecks.questsNamed(Arrays.asList(CAVES, "While Guthix Sleeps: reached the Ancient Guthixian Temple",
                "RFD: Dwarf; Brass key", null, "Started The Restless Ghost; Attack 15")));
    }

    @Test
    public void aSkillLineIsReadAsTheTrackerWritesIt()
    {
        assertEquals(new SkillLine("Woodcutting", 15, 60, 20), SkillLine.parse("Woodcutting 15/60 · cap 20"));
        assertEquals(new SkillLine("Woodcutting", 15, 60, 20), SkillLine.parse(" Woodcutting 15/60 · cap 20 "));
        assertEquals(null, SkillLine.parse("Unlock Axe Shops"));
        assertFalse(new SkillLine("Woodcutting", 15, 60, 20).met());
        assertFalse("the cap too", new SkillLine("Woodcutting", 70, 60, 50).met());
        assertTrue(new SkillLine("Woodcutting", 60, 60, 60).met());
    }

    /** Every requirement of the kinds the game can check, met: a members world, all quests done, 300 points. */
    private static GameFacts everything()
    {
        Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
        for (Quest quest : Quest.values())
        {
            quests.put(quest, QuestState.FINISHED);
        }
        return facts(true, 300, Collections.emptyMap(), quests, Collections.emptySet(), true);
    }

    private static GameFacts quest(Quest quest, QuestState state)
    {
        return facts(true, 0, Collections.emptyMap(), quests(quest, state), Collections.emptySet(), null);
    }

    private static GameFacts level(Skill skill, int level)
    {
        Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
        levels.put(skill, level);
        return facts(true, 0, levels, Collections.emptyMap(), Collections.emptySet(), null);
    }

    private static GameFacts carrying(String... names)
    {
        return facts(true, 0, Collections.emptyMap(), Collections.emptyMap(), new HashSet<>(Arrays.asList(names)),
            null);
    }

    private static Map<Quest, QuestState> quests(Object... pairs)
    {
        Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
        for (int i = 0; i < pairs.length; i += 2)
        {
            quests.put((Quest) pairs[i], (QuestState) pairs[i + 1]);
        }
        return quests;
    }

    private static GameFacts facts(Boolean members, int questPoints, Map<Skill, Integer> levels,
        Map<Quest, QuestState> quests, Set<String> carried, Boolean light)
    {
        return new GameFacts(members, questPoints, levels, quests, carried, light);
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * A9: what Strict Mode's travel matching will know about a click. The ids
 * are the ones RuneLite 1.12.39 gives: the spellbook is interface 218, the
 * inventory 149 and the worn items 387, whose slots draw their item in the
 * second child (RuneLite's MenuEntrySwapperPlugin reads worn items that way).
 */
public class MenuFactsTest
{
    private static final int VARROCK_TELEPORT_TABLET = 8007;
    private static final int AMULET_OF_GLORY_4 = 1712;
    private static final int FAIRY_RING = 29495;
    private static final int ARCEUUS = 3;

    private final Client client = mock(Client.class);
    private final MenuFactsReader reader = new MenuFactsReader(client);

    @Test
    public void textLosesColourTagsAndTheLockTagButKeepsItsCase()
    {
        assertEquals("Cast", MenuFactsReader.text("<col=ff9040>Cast</col>"));
        assertEquals("Varrock Teleport", MenuFactsReader.text(
            "<col=00ff00>Varrock Teleport</col> <col=f87171>(Locked)</col>"));
        assertEquals("Amulet of glory(4)", MenuFactsReader.text("<col=ff9040>Amulet of glory(4)</col>"));
        assertEquals("Last-destination (CKS)", MenuFactsReader.text("Last-destination (CKS)"));
        assertEquals("Necklace of passage(5)", MenuFactsReader.text(" Necklace of  passage(5) "));
        assertEquals("", MenuFactsReader.text(null));
    }

    @Test
    public void aSpellCarriesTheActiveSpellbook()
    {
        when(client.getVarbitValue(VarbitID.SPELLBOOK)).thenReturn(ARCEUUS);
        MenuEntry cast = widgetOption("Cast", "<col=00ff00>Ape Atoll Teleport</col>",
            InterfaceID.MAGIC_SPELLBOOK, -1);

        MenuFacts facts = reader.read(cast);

        assertEquals(MenuFacts.Kind.WIDGET, facts.getKind());
        assertEquals("Cast", facts.getOption());
        assertEquals("Ape Atoll Teleport", facts.getTarget());
        assertEquals(InterfaceID.MAGIC_SPELLBOOK, facts.getInterfaceGroup());
        assertEquals(ARCEUUS, facts.getSpellbook());
        assertEquals(MenuFacts.NONE, facts.getItemId());
        assertEquals(MenuFacts.NONE, facts.getNpcId());
        assertEquals(MenuFacts.NONE, facts.getObjectId());
    }

    @Test
    public void anInventoryItemCarriesItsIdAndNoSpellbook()
    {
        MenuEntry tablet = widgetOption("Break", "Varrock teleport", InterfaceID.INVENTORY,
            VARROCK_TELEPORT_TABLET);

        MenuFacts facts = reader.read(tablet);

        assertEquals(VARROCK_TELEPORT_TABLET, facts.getItemId());
        assertEquals(InterfaceID.INVENTORY, facts.getInterfaceGroup());
        assertEquals(MenuFacts.NONE, facts.getSpellbook());
        verify(client, never()).getVarbitValue(anyInt());
        verify(tablet, never()).getWidget();
    }

    @Test
    public void aWornItemFallsBackToTheItemInItsSlot()
    {
        MenuEntry rub = widgetOption("Edgeville", "Amulet of glory(4)", InterfaceID.WORNITEMS, -1);
        wornSlot(rub, AMULET_OF_GLORY_4);
        assertEquals(AMULET_OF_GLORY_4, reader.read(rub).getItemId());

        MenuEntry named = widgetOption("Edgeville", "Amulet of glory(4)", InterfaceID.WORNITEMS,
            AMULET_OF_GLORY_4);
        assertEquals(AMULET_OF_GLORY_4, reader.read(named).getItemId());
        verify(named, never()).getWidget();

        MenuEntry empty = widgetOption("Remove", "", InterfaceID.WORNITEMS, -1);
        wornSlot(empty, -1);
        assertEquals(MenuFacts.NONE, reader.read(empty).getItemId());
        MenuEntry noSlot = widgetOption("Remove", "", InterfaceID.WORNITEMS, -1);
        assertEquals(MenuFacts.NONE, reader.read(noSlot).getItemId());
        MenuEntry noChild = widgetOption("Remove", "", InterfaceID.WORNITEMS, -1);
        when(noChild.getWidget()).thenReturn(mock(Widget.class));
        assertEquals(MenuFacts.NONE, reader.read(noChild).getItemId());
    }

    @Test
    public void anItemElsewhereHasNoFallback()
    {
        MenuEntry elsewhere = widgetOption("Withdraw-1", "Varrock teleport", InterfaceID.BANKSIDE, -1);

        assertEquals(MenuFacts.NONE, reader.read(elsewhere).getItemId());
        verify(elsewhere, never()).getWidget();
    }

    @Test
    public void npcAndObjectOptionsCarryTheirIdsAndWorldView()
    {
        NPC captain = mock(NPC.class);
        when(captain.getId()).thenReturn(3648);
        MenuEntry travel = entry(MenuAction.NPC_THIRD_OPTION, "Travel", "Captain Tobias");
        when(travel.getNpc()).thenReturn(captain);
        MenuFacts boat = reader.read(travel);
        assertEquals(MenuFacts.Kind.NPC, boat.getKind());
        assertEquals(3648, boat.getNpcId());
        assertEquals(MenuFacts.NONE, boat.getObjectId());

        MenuEntry gone = entry(MenuAction.NPC_FIRST_OPTION, "Talk-to", "Captain Tobias");
        assertEquals(MenuFacts.NONE, reader.read(gone).getNpcId());

        MenuEntry ring = entry(MenuAction.GAME_OBJECT_SECOND_OPTION, "Zanaris", "Fairy ring");
        when(ring.getIdentifier()).thenReturn(FAIRY_RING);
        when(ring.getWorldViewId()).thenReturn(5);
        MenuFacts fairyRing = reader.read(ring);
        assertEquals(MenuFacts.Kind.OBJECT, fairyRing.getKind());
        assertEquals(FAIRY_RING, fairyRing.getObjectId());
        assertEquals(5, fairyRing.getWorldViewId());
        assertEquals(MenuFacts.NONE, fairyRing.getInterfaceGroup());
    }

    @Test
    public void everythingElseIsOtherWithNoIds()
    {
        for (MenuAction type : new MenuAction[] {
            MenuAction.WALK, MenuAction.EXAMINE_OBJECT, MenuAction.GROUND_ITEM_THIRD_OPTION,
            MenuAction.PLAYER_FIRST_OPTION, MenuAction.WORLD_ENTITY_FIRST_OPTION,
            MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, MenuAction.WIDGET_CONTINUE, MenuAction.RUNELITE, null })
        {
            MenuEntry entry = entry(type, "Walk here", "");
            when(entry.getIdentifier()).thenReturn(FAIRY_RING);
            when(entry.getItemId()).thenReturn(VARROCK_TELEPORT_TABLET);
            when(entry.getParam1()).thenReturn(WidgetUtil.packComponentId(InterfaceID.MAGIC_SPELLBOOK, 1));

            MenuFacts facts = reader.read(entry);

            assertEquals(String.valueOf(type), MenuFacts.Kind.OTHER, facts.getKind());
            assertEquals(String.valueOf(type), MenuFacts.builder()
                .option("Walk here").worldViewId(facts.getWorldViewId()).build(), facts);
        }
        assertSame(MenuFacts.EMPTY, reader.read(null));
        assertEquals(MenuFacts.Kind.OTHER, MenuFacts.EMPTY.getKind());
        verify(client, never()).getVarbitValue(anyInt());
    }

    private static MenuEntry widgetOption(String option, String target, int group, int itemId)
    {
        MenuEntry entry = entry(MenuAction.CC_OP, option, target);
        when(entry.getParam1()).thenReturn(WidgetUtil.packComponentId(group, 3));
        when(entry.getItemId()).thenReturn(itemId);
        return entry;
    }

    private static void wornSlot(MenuEntry entry, int itemId)
    {
        Widget slot = mock(Widget.class);
        Widget item = mock(Widget.class);
        when(item.getItemId()).thenReturn(itemId);
        when(slot.getChild(1)).thenReturn(item);
        when(entry.getWidget()).thenReturn(slot);
    }

    private static MenuEntry entry(MenuAction type, String option, String target)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getType()).thenReturn(type);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        return entry;
    }
}

package com.fatelocked;

import com.fatelocked.detectors.SkillLevelDetector;
import com.fatelocked.rules.Trust;
import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.io.InputStream;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * RuneLite reports LOGGED_IN after every loading screen as well as after a
 * login. Only a login, a hop, a reconnect or a different account may reset
 * the once-per-login warnings and the level and diary baselines; a teleport
 * must not repeat the account warning or swallow the next level-up.
 */
public class FateLockedLoginSessionTest
{
    private static final long MAIN_ACCOUNT = 7L;
    private static final long OTHER_ACCOUNT = 8L;
    private static final CanonicalChunk LUMBRIDGE = new CanonicalChunk(50, 50);
    private static final int WHIP = 4151;

    private final Client client = mock(Client.class);
    private FateLockedPlugin plugin;

    @Before
    public void logIn() throws Exception
    {
        plugin = new FateLockedPlugin();
        set("client", client);
        when(client.getAccountHash()).thenReturn(MAIN_ACCOUNT);
        fire(GameState.LOGIN_SCREEN, GameState.LOGGING_IN, GameState.LOGGED_IN);
    }

    @Test
    public void loadingScreensKeepTheSession() throws Exception
    {
        play();
        for (int teleport = 0; teleport < 3; teleport++)
        {
            fire(GameState.LOADING, GameState.LOGGED_IN);
        }

        assertWarningsKept();
        assertFalse("diary reading kept", (Boolean) get("diaryReadingDue"));
        assertTrue("a level-up after a teleport still counts",
            detector().detect("Attack", 51).isPresent());
    }

    @Test
    public void aHopOrReconnectResetsBaselinesButNotWarnings() throws Exception
    {
        for (GameState interruption : new GameState[] {
            GameState.HOPPING, GameState.CONNECTION_LOST })
        {
            play();
            fire(interruption, GameState.LOADING, GameState.LOGGED_IN);

            assertWarningsKept();
            assertTrue(interruption + " re-reads diaries",
                (Boolean) get("diaryReadingDue"));
            // The client re-sends every skill, which must not read as a level-up.
            assertFalse(interruption + " re-baselines skills",
                detector().detect("Attack", 51).isPresent());
        }
    }

    @Test
    public void loggingOutStartsTheNextLoginAfresh() throws Exception
    {
        play();

        fire(GameState.LOGIN_SCREEN);
        assertWarningsForgotten();

        fire(GameState.LOGGING_IN, GameState.LOGGED_IN);
        assertTrue((Boolean) get("diaryReadingDue"));
        assertFalse(detector().detect("Attack", 51).isPresent());
    }

    @Test
    public void aDifferentAccountStartsAfresh() throws Exception
    {
        play();
        when(client.getAccountHash()).thenReturn(OTHER_ACCOUNT);

        fire(GameState.LOADING, GameState.LOGGED_IN);

        assertWarningsForgotten();
        assertTrue((Boolean) get("diaryReadingDue"));
        assertFalse(detector().detect("Attack", 51).isPresent());
    }

    @Test
    public void turningThePluginOnStartsCleanAndAdoptsTheLogin() throws Exception
    {
        play();
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);

        startSessionTracking();
        assertWarningsForgotten();
        assertTrue((Boolean) get("diaryReadingDue"));
        assertFalse(detector().detect("Attack", 50).isPresent());

        // Already logged in, so its next loading screen is not a new login.
        play();
        fire(GameState.LOADING, GameState.LOGGED_IN);
        assertWarningsKept();
        assertTrue(detector().detect("Attack", 51).isPresent());
    }

    /** Rules bound to one character are answered only for that character. */
    @Test
    public void theDecisionServiceFollowsTheCharacterLoggedIn() throws Exception
    {
        FateLockedBundle rules;
        try (InputStream in = getClass().getClassLoader().getResourceAsStream("bundles/v4-rules.json"))
        {
            rules = FateLockedBundle.loadFromJson(new Gson(), new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
        set("active", new ActiveRules(rules, FateLockedPlugin.RulesSource.RELAY));
        Player player = mock(Player.class);
        when(client.getLocalPlayer()).thenReturn(player);

        when(player.getName()).thenReturn("Nubles");
        fire(GameState.LOADING, GameState.LOGGED_IN);
        assertEquals(Trust.TRUSTED, plugin.decisions().trust());

        when(player.getName()).thenReturn("Someone Else");
        when(client.getAccountHash()).thenReturn(OTHER_ACCOUNT);
        fire(GameState.LOADING, GameState.LOGGED_IN);
        assertEquals(Trust.WRONG_CHARACTER, plugin.decisions().trust());

        when(client.getLocalPlayer()).thenReturn(null);
        fire(GameState.LOGIN_SCREEN);
        assertEquals(Trust.LOGGED_OUT, plugin.decisions().trust());
    }

    /** What a few minutes of play leaves behind. */
    private void play() throws Exception
    {
        detector().clear();
        detector().detect("Attack", 50);
        set("diaryReadingDue", false);
        set("lastAccountWarned", "zezima");
        set("lastChunk", LUMBRIDGE);
        warnedOverTier().clear();
        warnedOverTier().add(WHIP);
    }

    private void assertWarningsKept() throws Exception
    {
        assertEquals("account warning not repeated", "zezima", get("lastAccountWarned"));
        assertEquals("chunk not re-announced", LUMBRIDGE, get("lastChunk"));
        assertTrue("gear warning not repeated", warnedOverTier().contains(WHIP));
    }

    private void assertWarningsForgotten() throws Exception
    {
        assertNull(get("lastAccountWarned"));
        assertNull(get("lastChunk"));
        assertTrue(warnedOverTier().isEmpty());
    }

    private void fire(GameState... states)
    {
        for (GameState state : states)
        {
            GameStateChanged event = new GameStateChanged();
            event.setGameState(state);
            plugin.onGameStateChanged(event);
        }
    }

    private void startSessionTracking() throws Exception
    {
        Method method = FateLockedPlugin.class.getDeclaredMethod("startSessionTracking");
        method.setAccessible(true);
        method.invoke(plugin);
    }

    private SkillLevelDetector detector() throws Exception
    {
        return (SkillLevelDetector) get("skillLevelDetector");
    }

    @SuppressWarnings("unchecked")
    private Set<Integer> warnedOverTier() throws Exception
    {
        return (Set<Integer>) get("warnedOverTier");
    }

    private Object get(String name) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(plugin);
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.clearInvocations;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * B9: the world map's pins are the areas the tracker says are locked, on
 * every golden bundle. They follow the decision service, so they appear when
 * the rules' character logs in and are gone on another character.
 */
public class LockedAreaPinsTest
{
    private static final Gson GSON = new Gson();

    private final FateLockedPlugin plugin = new FateLockedPlugin();
    private final FateLockedConfig config = mock(FateLockedConfig.class);
    private final Client client = mock(Client.class);
    private final WorldMapPointManager map = mock(WorldMapPointManager.class);

    @Before
    public void setUp() throws Exception
    {
        when(config.worldMapMarkers()).thenReturn(true);
        set("config", config);
        set("client", client);
        set("worldMapPointManager", map);
    }

    @Test
    public void thePinsAreTheAreasTheTrackerSaysAreLocked() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
            FateLockedBundle rules = FateLockedBundle.loadFromJson(GSON, json);
            JsonElement account = GSON.fromJson(json, JsonObject.class).getAsJsonObject("rules").get("account");
            Set<String> want = new TreeSet<>();
            for (Map.Entry<String, JsonElement> area
                : GoldenBundleContractTest.json(id + ".expect.json").getAsJsonObject("areas").entrySet())
            {
                if (!area.getValue().getAsBoolean() && rules.getSubAreaChunks().containsKey(area.getKey()))
                {
                    want.add(area.getKey());
                }
            }

            String player = account == null || account.isJsonNull() ? "Anyone" : account.getAsString();
            assertEquals(id, want, pinsFor(rules, player));
            assertTrue(id + " pins something", !want.isEmpty());
        }
    }

    @Test
    public void anotherCharacterOrNobodyGetsNoPinsAndALoginBringsThem() throws Exception
    {
        FateLockedBundle mid = FateLockedBundle.loadFromJson(GSON,
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz")));

        assertEquals(Set.of(), pinsFor(mid, "Someone Else"));
        assertEquals(Set.of(), pinsFor(mid, null));
        assertEquals("logging in places them", 164, pinsFor(mid, "Iron Example").size());

        when(config.worldMapMarkers()).thenReturn(false);
        assertEquals("the setting off", Set.of(), pinsFor(mid, "Iron Example"));
    }

    /** E1: the pins are drawn in the palette's locked colour, and a colour change redraws them. */
    @Test
    public void thePinsTakeThePalettesLockedColour() throws Exception
    {
        FateLockedBundle mid = FateLockedBundle.loadFromJson(GSON,
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz")));
        pinsFor(mid, "Iron Example");
        assertEquals(com.fatelocked.ui.Palette.defaults().lockedEdge(), pinColour());

        when(config.colourPreset()).thenReturn(FateLockedConfig.ColourPreset.CUSTOM);
        when(config.unlockedColor()).thenReturn(new java.awt.Color(0, 128, 255, 110));
        when(config.frontierColor()).thenReturn(new java.awt.Color(255, 255, 0, 100));
        when(config.lockedColor()).thenReturn(new java.awt.Color(128, 0, 128, 110));
        clearInvocations(map);
        GearDecisionTest.configChanged(plugin, "lockedColor");

        assertEquals(new java.awt.Color(128, 0, 128), pinColour());
    }

    /** The colour inside the last pin placed, above its padlock. */
    private java.awt.Color pinColour()
    {
        ArgumentCaptor<WorldMapPoint> added = ArgumentCaptor.forClass(WorldMapPoint.class);
        verify(map, atLeast(1)).add(added.capture());
        java.awt.image.BufferedImage image = added.getValue().getImage();
        return new java.awt.Color(image.getRGB(7, 2), true);
    }

    /** The pins placed when these rules are in force for this character (null: nobody logged in). */
    private Set<String> pinsFor(FateLockedBundle rules, String name) throws Exception
    {
        set("active", new ActiveRules(rules, FateLockedPlugin.RulesSource.RELAY));
        Player player = name == null ? null : mock(Player.class);
        if (player != null) when(player.getName()).thenReturn(name);
        when(client.getLocalPlayer()).thenReturn(player);
        clearInvocations(map);

        Method refresh = FateLockedPlugin.class.getDeclaredMethod("refreshDecisions");
        refresh.setAccessible(true);
        refresh.invoke(plugin);

        ArgumentCaptor<WorldMapPoint> added = ArgumentCaptor.forClass(WorldMapPoint.class);
        verify(map, atLeast(0)).add(added.capture());
        Set<String> names = new TreeSet<>();
        for (WorldMapPoint point : added.getAllValues()) names.add(point.getName());
        return names;
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

