    /**
     * B14: inside an instance the rules judge the chunk it is a copy of. From
     * Lumbridge Castle the player enters an instance copied from Seers'
     * Village (LOCKED in vanilla-mid): one alert, none while inside, and an
     * instance zone with no template changes nothing.
     */
    @Test
    public void anInstanceCopiedFromALockedChunkAlertsOnce() throws Exception
    {
        FateLockedBundle mid = playing("Iron Example");
        CanonicalChunk seers = new CanonicalChunk(42, 54);
        assertEquals(PermissionStatus.LOCKED, mid.permissionsAt(seers).get().getEntry());

        walk(new CanonicalChunk(50, 50));
        verify(client, never()).playSoundEffect(LOCKED_SOUND);

        enterInstanceOf(seers, 5, 5);
        enterInstanceOf(seers, 6, 7);
        enterInstanceOf(null, 6, 7);

        verify(client, times(1)).playSoundEffect(LOCKED_SOUND);
        verify(notifier).notify("You've entered a locked area: " + mid.labelAt(seers));
        List<String> lines = chatLines();
        assertEquals(2, lines.size());
        assertTrue(lines.get(1), lines.get(1).contains(mid.labelAt(seers)) && lines.get(1).contains(": Locked"));
    }

    /**
     * Stand in an instance whose every zone is a copy of the source chunk's
     * south-west zone (null: no template anywhere), at scene zone x, y.
     */
    private void enterInstanceOf(CanonicalChunk source, int zoneX, int zoneY)
    {
        int[][][] templates = new int[4][13][13];
        for (int[][] plane : templates) for (int[] row : plane) Arrays.fill(row, -1);
        if (source != null)
        {
            // RuneLite's encoding: the source zone in 8-tile units, plane 0, no rotation.
            int template = ((source.getCx() << 3) << 14) | ((source.getCy() << 3) << 3);
            for (int[] row : templates[0]) Arrays.fill(row, template);
        }
        Scene scene = mock(Scene.class);
        when(scene.isInstance()).thenReturn(true);
        when(scene.getInstanceTemplateChunks()).thenReturn(templates);
        WorldView instance = mock(WorldView.class);
        when(instance.isTopLevel()).thenReturn(true);
        when(instance.getScene()).thenReturn(scene);
        when(player.getWorldView()).thenReturn(instance);
        when(player.getLocalLocation()).thenReturn(
            new LocalPoint((zoneX * 8 + 3) * 128 + 64, (zoneY * 8 + 3) * 128 + 64, WorldView.TOPLEVEL));
        plugin.onGameTick(null);
    }

    /** vanilla-mid, with a character logged in. */
    private FateLockedBundle playing(String name) throws Exception
    {
        FateLockedBundle mid = FateLockedBundle.loadFromJson(new Gson(),
            GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz")));
        set("active", new ActiveRules(mid, FateLockedPlugin.RulesSource.RELAY));
        when(player.getName()).thenReturn(name);
        return mid;
    }

    private List<String> chatLines()
    {
        ArgumentCaptor<QueuedMessage> queued = ArgumentCaptor.forClass(QueuedMessage.class);
        verify(chat, atLeast(0)).queue(queued.capture());
        List<String> lines = new ArrayList<>();
        for (QueuedMessage message : queued.getAllValues()) lines.add(message.getRuneLiteFormattedMessage());
        return lines;
    }

    private void loadRules() throws Exception
    {
        FateLockedBundle rules = FateLockedBundle.loadFromJson(new Gson(), RULES);
        assertFalse(rules.isEmpty());
        assertEquals(FateLockedBundle.LockState.UNLOCKED, rules.lockStateAt(LUMBRIDGE));
        assertEquals(FateLockedBundle.LockState.LOCKED, rules.lockStateAt(FALADOR));
        assertEquals(FateLockedBundle.LockState.LOCKED, rules.lockStateAt(FALADOR_EAST));
        assertEquals(FateLockedBundle.LockState.UNAUTHORED, rules.lockStateAt(UNMAPPED));
        set("active", new ActiveRules(rules, FateLockedPlugin.RulesSource.NONE));
    }

    /** Stand in each chunk for one game tick. */
    /** E6: the HUD is worked out each tick for where the player stands, and kept while nothing changes. */
    @Test
    public void theHudFollowsThePlayer() throws Exception
    {
        loadRules();
        when(config.hudMode()).thenReturn(FateLockedConfig.HudMode.COMPACT);

        walk(LUMBRIDGE);
        HudModel atLumbridge = plugin.hudModel();
        assertEquals("Misthalin", HudPresenterTest.lines(atLumbridge).get("Here"));
        assertEquals("Unlocked", HudPresenterTest.lines(atLumbridge).get("Status"));
        walk(LUMBRIDGE);
        assertSame("a model like the last is kept, so the panel isn't built again", atLumbridge, plugin.hudModel());

        walk(FALADOR);
        assertEquals("Locked", HudPresenterTest.lines(plugin.hudModel()).get("Status"));

        when(config.hudMode()).thenReturn(FateLockedConfig.HudMode.OFF);
        walk(FALADOR);
        assertSame(HudModel.NONE, plugin.hudModel());

        // Where the player's chunk can't be found, the HUD says nothing of the last one.
        when(config.hudMode()).thenReturn(FateLockedConfig.HudMode.COMPACT);
        walk(FALADOR);
        assertEquals("Locked", HudPresenterTest.lines(plugin.hudModel()).get("Status"));
        when(player.getLocalLocation()).thenReturn(null);
        plugin.onGameTick(null);
        assertSame(HudModel.NONE, plugin.hudModel());
    }

    /** E6: Detailed lists what the place holds, as the sidebar's Here card does, and the run's progress. */
    @Test
    public void theDetailedHudListsWhatThePlaceHolds() throws Exception
    {
        playing("Iron Example");
        when(config.hudMode()).thenReturn(FateLockedConfig.HudMode.DETAILED);
        walk(LUMBRIDGE);

        HudModel model = plugin.hudModel();
        assertTrue(model.isDetailed());
        java.util.Map<String, String> lines = HudPresenterTest.lines(model);
        assertEquals(ProgressText.hudLine(plugin.decisions().progress()), lines.get("Unlocked"));
        com.fatelocked.sidebar.HereModel here =
            new com.fatelocked.sidebar.HerePresenter().present(plugin.decisions(), LUMBRIDGE);
        assertFalse("Lumbridge holds something", here.getGroups().isEmpty());
        for (com.fatelocked.sidebar.HereModel.Group group : here.getGroups())
        {
            assertTrue(group.getTitle(), lines.containsKey(group.getTitle()));
        }
    }

    /**
     * The owner's review, 28 Sept: Here is worked out again when the game says more. The caves'
     * guard needs only The Lost Tribe started, which the tracker can't see but the game can.
     */
    @Test
    public void hereFollowsWhatTheGameSays() throws Exception
    {
        playing("Iron Example");
        when(config.hudMode()).thenReturn(FateLockedConfig.HudMode.DETAILED);
        when(client.isClientThread()).thenReturn(true);
        when(client.getGameState()).thenReturn(net.runelite.api.GameState.LOGGED_IN);
        when(client.getWorldType()).thenReturn(java.util.EnumSet.of(net.runelite.api.WorldType.MEMBERS));
        // The quest-state script's answer: 1 is still to start, 0 under way.
        int[] answer = {1};
        when(client.getIntStack()).thenReturn(answer);
        when(client.getTickCount()).thenReturn(1000);
        walk(LUMBRIDGE);
        assertEquals("Not ready", HudPresenterTest.lines(plugin.hudModel()).get("Cave goblin guard"));

        answer[0] = 0;
        when(client.getTickCount()).thenReturn(1001);
        walk(LUMBRIDGE);
        assertEquals("Can do", HudPresenterTest.lines(plugin.hudModel()).get("Cave goblin guard"));
    }

    /** E6: the way to the nearest bank is found again when the player moves, and when the rules change. */
    @Test
    public void theHudsNearestBankFollowsThePlayerAndTheRules() throws Exception
    {
        // custom-lumbridge-banks-off allows the banks at Lumbridge Castle and South Draynor.
        String json = GoldenBundleContractTest.gunzip(
            GoldenBundleContractTest.bytes("custom-lumbridge-banks-off.bundle.json.gz"));
        set("active", new ActiveRules(FateLockedBundle.loadFromJson(new Gson(), json), FateLockedPlugin.RulesSource.RELAY));
        when(player.getName()).thenReturn("Iron Example");
        when(config.hudMode()).thenReturn(FateLockedConfig.HudMode.COMPACT);
        CanonicalChunk draynor = new CanonicalChunk(48, 50);

        walk(draynor);
        assertEquals("Here", HudPresenterTest.lines(plugin.hudModel()).get("Bank"));
        walk(new CanonicalChunk(46, 50));
        assertEquals("Draynor Vill… · 2 E", HudPresenterTest.lines(plugin.hudModel()).get("Bank"));
        walk(draynor);

        // The tracker locks South Draynor's chunk and bank: in the same chunk, Lumbridge is nearest.
        JsonObject locked = new Gson().fromJson(json, JsonObject.class);
        locked.getAsJsonObject("rules").getAsJsonObject("chunks").getAsJsonObject("48,50").addProperty("entry", "LOCKED");
        locked.getAsJsonObject("rules").getAsJsonObject("banks").getAsJsonObject("12338").addProperty("status", "LOCKED");
        set("active", new ActiveRules(FateLockedBundle.loadFromJson(new Gson(), locked.toString()),
            FateLockedPlugin.RulesSource.RELAY));
        walk(draynor);
        assertEquals("Lumbridge · 2 E", HudPresenterTest.lines(plugin.hudModel()).get("Bank"));
    }

    private void walk(CanonicalChunk... chunks)
    {
        for (CanonicalChunk chunk : chunks)
        {
            TestWorld.standAt(client, player, new WorldPoint((chunk.getCx() << 6) + 8, (chunk.getCy() << 6) + 8, 0));
            // The tick event carries nothing the plugin reads.
            plugin.onGameTick(null);
        }
    }

    private void set(String name, Object value) throws Exception
    {
        Field field = FateLockedPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.fatelocked.ui.Palette;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * B8: the world map, from the decision service. It draws the tracker's land
 * (every chunk the rules decide, the sea left out) in its colours, the
 * frontier of a Chunked run exactly as the tracker's golden frontier, and a
 * tooltip; nothing at all on another character.
 */
public class WorldMapTooltipTest
{
    private static final Gson GSON = new Gson();

    @Test
    public void theMapDrawsTheTrackersLandAndFrontierOnEveryGolden() throws Exception
    {
        for (Object[] scenario : GoldenBundleContractTest.scenarios())
        {
            String id = (String) scenario[0];
            String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
            JsonObject wire = GSON.fromJson(json, JsonObject.class);
            JsonObject chunks = wire.getAsJsonObject("rules").getAsJsonObject("chunks");
            JsonObject expected = GoldenBundleContractTest.json(id + ".expect.json");
            RulesSnapshot rules = RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json));
            String account = account(wire);
            DecisionService playing = DecisionService.create(rules, account, account);

            Set<String> drawn = new TreeSet<>();
            Set<String> frontier = new TreeSet<>();
            List<String> mismatches = new ArrayList<>();
            for (CanonicalChunk chunk : playing.mappedChunks())
            {
                String key = chunk.getCx() + "," + chunk.getCy();
                drawn.add(key);
                WorldMapChunks.Fill fill = WorldMapChunks.fill(playing, chunk);
                if (fill == WorldMapChunks.Fill.FRONTIER) frontier.add(key);
                String entry = chunks.getAsJsonObject(key).get("entry").getAsString();
                boolean owned = "ALLOWED".equals(entry) || "NOT_READY".equals(entry);
                if (owned != (fill == WorldMapChunks.Fill.UNLOCKED)) mismatches.add(key + " " + entry + " drawn " + fill);
            }
            Set<String> wantFrontier = new TreeSet<>();
            if (expected.has("frontier"))
            {
                for (JsonElement key : expected.getAsJsonArray("frontier")) wantFrontier.add(key.getAsString());
            }

            assertEquals(id + " draws the tracker's land", new TreeSet<>(chunks.keySet()), drawn);
            assertEquals(id + " colours", List.of(), mismatches);
            assertEquals(id + " frontier", wantFrontier, frontier);
            for (String key : expected.getAsJsonObject("chunks").keySet())
            {
                if (!chunks.has(key)) assertFalse(id + " sea " + key, drawn.contains(key));
            }
            if (account != null)
            {
                DecisionService other = DecisionService.create(rules, account, "someone else");
                for (CanonicalChunk chunk : other.mappedChunks())
                {
                    assertNull(id + " another character", WorldMapChunks.fill(other, chunk));
                }
            }
        }
        assertFalse("a Chunked golden has a frontier", frontierOf("chunked-walk").isEmpty());
    }

    @Test
    public void tooltipsSayWhereAndWhat() throws Exception
    {
        DecisionService mid = playing("vanilla-mid");

        assertEquals("Lumbridge · Misthalin</br><col=34d399>Unlocked</col>",
            WorldMapChunks.tooltip(mid, new CanonicalChunk(50, 50), List.of(), Palette.defaults()));
        assertTrue(WorldMapChunks.tooltip(mid, new CanonicalChunk(42, 54), List.of(), Palette.defaults())
            .endsWith("</br><col=f87171>Locked</col>"));
        assertTrue(WorldMapChunks.tooltip(mid, new CanonicalChunk(39, 53), List.of(), Palette.defaults())
            .endsWith("</br><col=f59e0b>Not ready</col>"));
        assertEquals("a chunk only the tracker names",
            "Chunk (16, 44)</br><col=f87171>Locked</col>",
            WorldMapChunks.tooltip(mid, new CanonicalChunk(16, 44), List.of(), Palette.defaults()));
        assertNull("the sea", WorldMapChunks.tooltip(mid, new CanonicalChunk(40, 41), List.of(), Palette.defaults()));
        assertEquals("the colours follow the palette", "Lumbridge · Misthalin</br><col=56b4e9>Unlocked</col>",
            WorldMapChunks.tooltip(mid, new CanonicalChunk(50, 50), List.of(),
                Palette.of(Palette.Preset.COLOUR_BLIND_SAFE, null, null, null)));
        assertEquals("Lumbridge · Misthalin</br><col=34d399>Unlocked</col>"
                + "</br><col=a5a5a5>Monsters: Cow</col>",
            WorldMapChunks.tooltip(mid, new CanonicalChunk(50, 50), List.of("Monsters: Cow"), Palette.defaults()));

        CanonicalChunk next = frontierOf("chunked-walk").iterator().next();
        assertTrue(WorldMapChunks.tooltip(playing("chunked-walk"), next, List.of(), Palette.defaults())
            .endsWith("</br><col=facc15>Locked — rollable next</col>"));
    }

    @Test
    public void anotherCharacterGetsNoTooltip() throws Exception
    {
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("vanilla-mid.bundle.json.gz"));
        DecisionService other = DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), "iron example", "someone else");

        assertNull(WorldMapChunks.tooltip(other, new CanonicalChunk(50, 50), List.of(), Palette.defaults()));

        String walk = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes("chunked-walk.bundle.json.gz"));
        RulesSnapshot walkRules = RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, walk));
        CanonicalChunk next = frontierOf("chunked-walk").iterator().next();
        assertTrue(DecisionService.create(walkRules, "iron example", "iron example").isFrontier(next));
        assertFalse(DecisionService.create(walkRules, "iron example", "someone else").isFrontier(next));
    }

    @Test
    public void anOlderExportDrawsItsAreasAsBefore() throws Exception
    {
        FateLockedBundle v3;
        try (InputStream in = getClass().getClassLoader().getResourceAsStream("bundles/v3-standard.json"))
        {
            v3 = FateLockedBundle.loadFromJson(GSON, new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
        DecisionService nubles = DecisionService.create(RulesSnapshot.of(v3), "nubles", "nubles");

        assertEquals(Set.of(new CanonicalChunk(50, 50), new CanonicalChunk(46, 52)), nubles.mappedChunks());
        assertEquals(WorldMapChunks.Fill.UNLOCKED, WorldMapChunks.fill(nubles, new CanonicalChunk(46, 52)));
        assertEquals("Falador · Asgarnia</br><col=34d399>Unlocked</col>",
            WorldMapChunks.tooltip(nubles, new CanonicalChunk(46, 52), List.of(), Palette.defaults()));
    }

    /**
     * Until B17's boundary test covers every surface: the overlay draws through WorldMapChunks,
     * by way of the model worked out once per decision service (U18). It uses no deprecated
     * RuneLite API, and never walks every chunk in a frame.
     */
    @Test
    public void theOverlayDrawsThroughWorldMapChunks() throws Exception
    {
        String source = source("FateLockedWorldMapOverlay.java");
        for (String old : new String[] { "lockStateAt(", "isFrontierChunk(", "labelAt(", "getRegionChunks(",
            "getRenderOverview(", "RenderOverview", "ComponentID", "OverlayPriority", "widgets.InterfaceID",
            "mappedChunks()" })
        {
            assertFalse(old, source.contains(old));
        }
        assertTrue(source.contains("WorldMapModel.of("));
        assertTrue(source("WorldMapModel.java").contains("WorldMapChunks.fill("));
        assertTrue(source.contains("WorldMapChunks.tooltip("));
        assertTrue("the tooltip takes the plugin's palette", source.contains("plugin.palette()"));
    }

    private static String source(String name) throws Exception
    {
        return new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(
            "src", "main", "java", "com", "fatelocked", name)), StandardCharsets.UTF_8);
    }

    private static Set<CanonicalChunk> frontierOf(String id) throws Exception
    {
        Set<CanonicalChunk> frontier = new java.util.LinkedHashSet<>();
        for (JsonElement key : GoldenBundleContractTest.json(id + ".expect.json").getAsJsonArray("frontier"))
        {
            frontier.add(GoldenBundleContractTest.chunk(key.getAsString()));
        }
        return frontier;
    }

    private static DecisionService playing(String id) throws Exception
    {
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
        String account = account(GSON.fromJson(json, JsonObject.class));
        return DecisionService.create(RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), account, account);
    }

    private static String account(JsonObject wire)
    {
        JsonElement bound = wire.getAsJsonObject("rules").get("account");
        return bound == null || bound.isJsonNull() ? null : AccountBinding.normalize(bound.getAsString());
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.fatelocked.SpotMemory.Spot;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.google.gson.Gson;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
