/**
 * Renders the sidebar states the web guide shows (Stage 3 G3), in RuneLite's own theme, with no
 * client and no display: {@code gradle guideScreenshots} writes the PNGs and
 * {@code guide-screenshots.json} to {@code build/guide-screenshots}. The json says where each of
 * a shot's callouts points, as fractions of the image, from where the components were laid out,
 * so a marker can't drift from what it names.
 *
 * <p>Each shot opens only the card its chapter is about. The run is the golden bundles' fictional
 * "Iron Example", so the images show no real player.
 */
public final class GuideScreenshots
{
    private GuideScreenshots()
    {
    }

    public static void main(String[] args) throws Exception
    {
        Path out = Paths.get(args.length > 0 ? args[0] : "build/guide-screenshots");
        Files.createDirectories(out);
        onEdt(() -> {
            if (!RuneLiteLAF.setup())
            {
                throw new IllegalStateException("RuneLite's theme did not install");
            }
            return null;
        });
        String artFolder = System.getProperty("fatelocked.previewArt", "");
        IconSource icons = artFolder.isEmpty() ? IconSource.NONE : new FolderArt(Paths.get(artFolder));

        JsonArray entries = new JsonArray();
        for (Shot shot : shots(icons))
        {
            JComponent root = onEdt(shot.build);
            BufferedImage image = onEdt(() -> SwingSnapshot.paint(root, PluginPanel.PANEL_WIDTH, 0));
            byte[] png = png(image);
            Files.write(out.resolve(shot.id + ".png"), png);

            JsonObject entry = new JsonObject();
            entry.addProperty("id", shot.id);
            entry.addProperty("file", shot.id + ".png");
            entry.addProperty("width", image.getWidth());
            entry.addProperty("height", image.getHeight());
            entry.addProperty("sha256", sha256(png));
            JsonObject anchors = new JsonObject();
            for (Anchor anchor : shot.anchors)
            {
                double[] at = onEdt(() -> anchor.locate(root, image));
                JsonArray point = new JsonArray();
                point.add(at[0]);
                point.add(at[1]);
                anchors.add(anchor.name, point);
            }
            entry.add("anchors", anchors);
            entries.add(entry);
            System.out.println("wrote " + out.resolve(shot.id + ".png") + " (" + image.getWidth() + "x"
                + image.getHeight() + ")");
        }
        JsonObject manifest = new JsonObject();
        manifest.addProperty("runeliteVersion", RuneLiteProperties.getVersion());
        manifest.add("shots", entries);
        Files.write(out.resolve("guide-screenshots.json"),
            (new GsonBuilder().setPrettyPrinting().create().toJson(manifest) + "\n").getBytes(StandardCharsets.UTF_8));
    }

    private static List<Shot> shots(IconSource icons) throws IOException
    {
        String firstRun = "Log in to see the place you're standing in.";
        List<Shot> shots = new ArrayList<>();
        shots.add(new Shot("sidebar-not-connected", () -> SidebarShots.sidebar(icons,
            StatusCardModel.of(Tone.NEUTRAL, "Not connected", "Connect the tracker to load your run's rules.")
                .withActions(CardAction.CONNECT, CardAction.USE_BACKUP),
            HereModel.message(firstRun), StrictModeModel.off(), null, SidebarShots.disconnected()),
            new Anchor("status", text("Not connected")),
            new Anchor("connect", text("Connect tracker")),
            new Anchor("backup", text("Use a backup instead"))));
        shots.add(new Shot("sidebar-waiting", () -> SidebarShots.sidebar(icons,
            StatusCardModel.of(Tone.PENDING, "Waiting for confirmation",
                "Confirm this profile in the browser tab RuneLite opened. RuneLite checks every few seconds.")
                .withActions(CardAction.OPEN_PAGE_AGAIN, CardAction.CANCEL_PAIRING),
            HereModel.message(firstRun), StrictModeModel.off(), null, SidebarShots.disconnected()),
            new Anchor("status", text("Waiting for confirmation")),
            new Anchor("open-again", text("Open page again")),
            new Anchor("cancel", text("Cancel"))));
        shots.add(new Shot("sidebar-overview", () -> open(upToDate(icons), null),
            new Anchor("status", text("Rules up to date")),
            new Anchor("cards", section("Here")),
            new Anchor("more-settings", startsWith("More settings"))));
        HereModel tower = SidebarShots.here("vanilla-mid", 42, 53, true);
        HereModel.Subgroup firstSkill = tower.getGroups().stream()
            .filter(group -> group.getCategory().equals("SKILLING")).findFirst()
            .map(group -> group.getSubgroups().get(0)).orElseThrow(IllegalStateException::new);
        shots.add(new Shot("sidebar-here", () -> {
            Sidebar sidebar = (Sidebar) SidebarShots.sidebar(icons, SidebarShots.upToDate(), tower,
                SidebarShots.active(), SidebarShots.run(), SidebarShots.connected());
            // Skilling open at its first skill; the rest closed, as they start. Its first row clicked.
            sidebar.here().setOpen(new java.util.TreeSet<>(Arrays.asList("SKILLING", firstSkill.getKey())));
            sidebar.here().showPointer(PointerText.pointing(firstSkill.getRows().get(0).getName(), true), true);
            return open(sidebar, sidebar.here());
        },
            new Anchor("status", pill("Locked")),
            new Anchor("reason", text("Unlock Seers' Village")),
            new Anchor("counts", inside("Here", type(StatTiles.class))),
            new Anchor("arrow", startsWith("The arrow points")),
            new Anchor("categories", text("Skilling")),
            new Anchor("skills", text(firstSkill.getTitle()))));
        shots.add(new Shot("sidebar-strict-mode", () -> {
            Sidebar sidebar = (Sidebar) SidebarShots.sidebar(icons, SidebarShots.upToDate(),
                SidebarShots.here("vanilla-mid", 50, 50, true),
                new StrictModeModel(true, "Paused · 42s", Tone.PENDING, null, CardAction.RESUME_STRICT_MODE,
                    Arrays.asList("Varrock Teleport, 12:02", "Ring of dueling: Emir's Arena, 11:40")),
                SidebarShots.run(), SidebarShots.connected());
            return open(sidebar, sidebar.strictMode());
        },
            new Anchor("switch", inside("Strict Mode", type(ToggleSwitch.class))),
            new Anchor("paused", pill("Paused · 42s")),
            new Anchor("resume", text("Resume")),
            new Anchor("stopped", text("Recently stopped"))));
        shots.add(new Shot("sidebar-run", () -> {
            Sidebar sidebar = upToDate(icons);
            return open(sidebar, sidebar.run());
        },
            new Anchor("character", text("Iron Example (you)")),
            new Anchor("progress", text("15 of 187 areas unlocked")),
            new Anchor("keys", type(StatTiles.class)),
            new Anchor("ritual", text("Ritual of Clarity"))));
        shots.add(new Shot("sidebar-roll-inbox", () -> {
            Sidebar sidebar = upToDate(icons);
            sidebar.rollInbox().apply(new RollInboxModel(12, 2, 1, false));
            return open(sidebar, sidebar.rollInbox());
        },
            new Anchor("events", text("Local events")),
            new Anchor("needs-checking", text("Needs checking")),
            new Anchor("open", text("Open web Roll Inbox"))));
        shots.add(new Shot("sidebar-connection", () -> {
            Sidebar sidebar = upToDate(icons);
            return open(sidebar, sidebar.connection());
        },
            new Anchor("sync", inside("Connection & backup", type(ToggleSwitch.class))),
            new Anchor("repair", text("Re-pair tracker…")),
            new Anchor("check", text("Check now")),
            new Anchor("clipboard", text("Import from clipboard"))));
        shots.add(new Shot("sidebar-out-of-date", () -> {
            Sidebar sidebar = (Sidebar) SidebarShots.sidebar(icons,
                StatusCardModel.of(Tone.PENDING, "Rules may be out of date",
                    "Last synced 32 min ago. RuneLite couldn't reach the tracker; next check at 12:35."
                        + " Strict Mode is inactive until the rules refresh.")
                    .withActions(CardAction.CHECK_NOW, null),
                SidebarShots.here("vanilla-mid", 50, 50, true),
                new StrictModeModel(true, "Inactive", Tone.PENDING,
                    "Not blocking anything: the rules are more than 15 minutes old.", null,
                    Collections.emptyList()), SidebarShots.run(), SidebarShots.connected());
            return open(sidebar, sidebar.strictMode());
        },
            new Anchor("status", text("Rules may be out of date")),
            new Anchor("check", text("Check now")),
            new Anchor("inactive", pill("Inactive"))));
        shots.add(new Shot("sidebar-different-character", () -> {
            Sidebar sidebar = (Sidebar) SidebarShots.sidebar(icons,
                StatusCardModel.of(Tone.BAD, "Different character",
                    "This run belongs to " + SidebarShots.CHARACTER + ", and you're logged in as Zezima."
                        + " Warnings and Strict Mode are off."),
                SidebarShots.here("vanilla-mid", 50, 50, false),
                new StrictModeModel(true, "Inactive", Tone.PENDING,
                    "Not blocking anything: the rules are for " + SidebarShots.CHARACTER + ".", null,
                    Collections.emptyList()), SidebarShots.run(), SidebarShots.connected());
            return open(sidebar, sidebar.here());
        },
            new Anchor("status", text("Different character")),
            new Anchor("here", section("Here"))));
        return shots;
    }

    private static Sidebar upToDate(IconSource icons) throws Exception
    {
        return (Sidebar) SidebarShots.sidebar(icons, SidebarShots.upToDate(),
            SidebarShots.here("vanilla-mid", 50, 50, true), SidebarShots.active(), SidebarShots.run(),
            SidebarShots.connected());
    }

    /** The sidebar with only this card open, or none. */
    private static Sidebar open(Sidebar sidebar, Section card)
    {
        for (Section section : Arrays.asList(sidebar.here(), sidebar.strictMode(), sidebar.run(),
            sidebar.rollInbox(), sidebar.connection()))
        {
            section.setExpanded(section == card);
        }
        return sidebar;
    }

    private static final class Shot
    {
        final String id;
        final Callable<JComponent> build;
        final List<Anchor> anchors;

        Shot(String id, Callable<JComponent> build, Anchor... anchors)
        {
            this.id = id;
            this.build = build;
            this.anchors = Arrays.asList(anchors);
        }
    }

    /** A named point on a shot: the middle of the first shown component that matches. */
    private static final class Anchor
    {
        final String name;
        final Predicate<Component> match;

        Anchor(String name, Predicate<Component> match)
        {
            this.name = name;
            this.match = match;
        }

        double[] locate(JComponent root, BufferedImage image)
        {
            Component found = find(root, match);
            if (found == null)
            {
                throw new IllegalStateException("No component for the callout " + name);
            }
            Rectangle bounds = SwingUtilities.convertRectangle(found.getParent(), found.getBounds(), root);
            return new double[] {
                round((bounds.x + bounds.width / 2.0) / image.getWidth()),
                round((bounds.y + bounds.height / 2.0) / image.getHeight())};
        }
    }

    private static Component find(Container container, Predicate<Component> match)
    {
        for (Component child : container.getComponents())
        {
            if (!child.isVisible())
            {
                continue;
            }
            if (match.test(child))
            {
                return child;
            }
            if (child instanceof Container)
            {
                Component found = find((Container) child, match);
                if (found != null)
                {
                    return found;
                }
            }
        }
        return null;
    }

    /** The first match inside the card with this title. */
    private static Predicate<Component> inside(String title, Predicate<Component> match)
    {
        return component -> {
            Component card = component.getParent();
            while (card != null && !(card instanceof Section && title.equals(((Section) card).getTitle())))
            {
                card = card.getParent();
            }
            return card != null && match.test(component);
        };
    }

    private static Predicate<Component> text(String text)
    {
        return component -> text.equals(textOf(component));
    }

    private static Predicate<Component> startsWith(String text)
    {
        return component -> textOf(component) != null && textOf(component).startsWith(text);
    }

    private static Predicate<Component> pill(String word)
    {
        return component -> component instanceof StatusPill && word.equals(((StatusPill) component).getWord());
    }

    private static Predicate<Component> type(Class<? extends Component> type)
    {
        return type::isInstance;
    }

    /** A card's header: the top of the card with this title. */
    private static Predicate<Component> section(String title)
    {
        return component -> component instanceof Section && title.equals(((Section) component).getTitle());
    }

    private static String textOf(Component component)
    {
        if (component instanceof JLabel)
        {
            return ((JLabel) component).getText();
        }
        if (component instanceof AbstractButton)
        {
            return ((AbstractButton) component).getText();
        }
        if (component instanceof TextBlock)
        {
            return ((TextBlock) component).getText();
        }
        return null;
    }

    private static double round(double fraction)
    {
        return Math.round(fraction * 100) / 100.0;
    }

    private static byte[] png(BufferedImage image) throws Exception
    {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        ImageIO.write(image, "png", bytes);
        return bytes.toByteArray();
    }

    private static String sha256(byte[] bytes) throws Exception
    {
        StringBuilder hex = new StringBuilder();
        for (byte b : MessageDigest.getInstance("SHA-256").digest(bytes))
        {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }

    private static <T> T onEdt(Callable<T> task) throws Exception
    {
        AtomicReference<T> result = new AtomicReference<>();
        AtomicReference<Exception> failure = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            try
            {
                result.set(task.call());
            }
            catch (Exception e)
            {
                failure.set(e);
            }
        });
        if (failure.get() != null)
        {
            throw failure.get();
        }
        return result.get();
    }
}

package com.fatelocked.guardian;

import org.junit.Test;

import java.time.Duration;
import java.util.concurrent.atomic.AtomicLong;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StrictModePauseTest
{
    private final AtomicLong nanos = new AtomicLong(Long.MAX_VALUE - Duration.ofSeconds(30).toNanos());
    private final StrictModePause pause = new StrictModePause(nanos::get);

    @Test
    public void pausesForExactlySixtySeconds()
    {
        pause.pauseFor(Duration.ofSeconds(60));
        assertEquals(60, pause.remainingSeconds());
        advance(Duration.ofSeconds(17));
        assertEquals(43, pause.remainingSeconds());
        advance(Duration.ofMillis(42_500));
        assertEquals("a part-second still counts", 1, pause.remainingSeconds());
        advance(Duration.ofMillis(500));
        assertFalse(pause.isPaused());
    }

    /** The clock starts near its limit, so the countdown also survives nanoTime wrapping. */
    @Test
    public void countsElapsedTimeAcrossTheClocksWrap()
    {
        pause.pauseFor(Duration.ofSeconds(60));
        advance(Duration.ofSeconds(45));
        assertTrue(pause.isPaused());
        assertEquals(15, pause.remainingSeconds());
    }

    @Test
    public void resumeEndsThePauseAtOnce()
    {
        pause.pauseFor(Duration.ofSeconds(60));
        pause.resume();
        assertFalse(pause.isPaused());
        assertEquals(0, pause.remainingSeconds());
    }

    private void advance(Duration duration)
    {
        nanos.addAndGet(duration.toNanos());
    }
}

package com.fatelocked.guardian;

import com.google.gson.Gson;
import org.junit.Test;

import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StrictModeAuditLogTest
{
    @Test
    public void twoClientsKeepEachOthersEntries() throws Exception
    {
        Path file = Files.createTempDirectory("fate-strict-log").resolve("events.json");
        StrictModeAuditLog main = new StrictModeAuditLog(new Gson(), file);
        StrictModeAuditLog second = new StrictModeAuditLog(new Gson(), file);

        main.append(new StrictModeAuditEntry(1, "TRAVEL", "from-main", "50,50", "locked"));
        second.append(new StrictModeAuditEntry(2, "TRAVEL", "from-second", "50,50", "locked"));

        StrictModeAuditLog reloaded = new StrictModeAuditLog(new Gson(), file);
        assertEquals("from-second", reloaded.recent(2).get(0).getTarget());
        assertEquals("from-main", reloaded.recent(2).get(1).getTarget());
    }

    @Test
    public void aDamagedLogIsKeptAsideNotWrittenOver() throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-log");
        Path file = directory.resolve("events.json");
        Files.writeString(file, "{damaged");

        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);
        log.append(new StrictModeAuditEntry(1, "TRAVEL", "goblin", "50,50", "locked"));

        assertEquals(1, new StrictModeAuditLog(new Gson(), file).recent(10).size());
        try (java.util.stream.Stream<Path> files = Files.list(directory))
        {
            Path kept = files.filter(path -> path.getFileName().toString()
                .startsWith("events.json.corrupt-")).findFirst().orElse(null);
            assertTrue("the damaged log was kept", kept != null);
            assertEquals("{damaged", Files.readString(kept));
        }
    }

    @Test
    public void persistsOnlyNewestHundredWithoutSensitiveFields() throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-log");
        Path file = directory.resolve("events.json");
        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);
        for (int i = 0; i < 101; i++)
        {
            log.append(new StrictModeAuditEntry(
                i, "TRAVEL", "goblin-" + i, "50,50", "locked",
                "BLOCKED", false, i == 100));
        }

        StrictModeAuditLog reloaded = new StrictModeAuditLog(new Gson(), file);
        assertEquals(100, reloaded.recent(200).size());
        StrictModeAuditEntry latest = reloaded.recent(1).get(0);
        assertEquals("goblin-100", latest.getTarget());
        assertEquals("BLOCKED", latest.getOutcome());
        assertFalse(latest.isPaused());
        assertTrue(latest.isAlternativeAvailable());
        String json = Files.readString(file);
        assertFalse(json.contains("account"));
        assertFalse(json.contains("inventory"));
        assertFalse(json.contains("chat"));
        assertFalse(json.contains("token"));
        assertFalse(json.contains("route"));
    }

    @Test
    public void loadsSafeLegacyEntriesAsBlockedWithoutLosingFields()
        throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-legacy");
        Path file = directory.resolve("events.json");
        try (InputStream input = getClass().getClassLoader()
            .getResourceAsStream("audit/strict-mode-events-v1.json"))
        {
            Files.copy(input, file);
        }

        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);
        StrictModeAuditEntry entry = log.recent(1).get(0);

        assertEquals(1721815200000L, entry.getTimestamp());
        assertEquals("OBJECT", entry.getActionKind());
        assertEquals("Ancient gate", entry.getTarget());
        assertEquals("50,50", entry.getChunk());
        assertEquals("is locked", entry.getReason());
        assertEquals("BLOCKED", entry.getOutcome());
        assertFalse(entry.isPaused());
        assertFalse(entry.isAlternativeAvailable());
    }

    @Test
    public void normalizedLegacyBlockRemainsVisibleInRecentPreventedLines()
        throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-visible");
        Path file = directory.resolve("events.json");
        try (InputStream input = getClass().getClassLoader()
            .getResourceAsStream("audit/strict-mode-events-v1.json"))
        {
            Files.copy(input, file);
        }
        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);

        assertEquals(
            Collections.singletonList("Ancient gate \u2014 is locked"),
            StrictModeAuditPresenter.recentPrevented(log.recent(5)));
    }

    @Test
    public void doesNotPromoteSensitiveOrPartialRecordsToLegacyBlocks()
        throws Exception
    {
        Path directory = Files.createTempDirectory("fate-strict-malformed");
        Path file = directory.resolve("events.json");
        Files.writeString(file,
            "{\"entries\":["
                + "{\"timestamp\":1,\"actionKind\":\"OBJECT\","
                + "\"target\":\"Gate\",\"chunk\":\"50,50\","
                + "\"reason\":\"locked\",\"account\":\"secret\"},"
                + "{\"timestamp\":2,\"actionKind\":\"TRAVEL\","
                + "\"target\":\"Walk here\",\"chunk\":\"51,51\","
                + "\"reason\":\"locked\",\"paused\":true},"
                + "{\"timestamp\":\"3\",\"actionKind\":42,"
                + "\"target\":99,\"chunk\":\"51,51\","
                + "\"reason\":\"locked\"}]}"
        );

        StrictModeAuditLog log = new StrictModeAuditLog(new Gson(), file);

        assertTrue(log.recent(10).isEmpty());
    }
}

package com.fatelocked.guardian;

import com.fatelocked.ChunkLocator;
import com.fatelocked.MenuFacts;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GuardedActionFactoryTest
{
    private final GuardedActionFactory factory = new GuardedActionFactory();
    private final Client client = mock(Client.class);
    private final ChunkLocator locator = new ChunkLocator(client);

    @Test
    public void normalizesNpcAndBankActors()
    {
        NPC npc = mock(NPC.class);
        when(npc.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
        MenuEntry attack = entry("Attack", "<col=ffff00>Goblin</col>");
        when(attack.getNpc()).thenReturn(npc);
        assertEquals(GuardedAction.Kind.NPC,
            factory.from(attack, locator).getKind());
        assertEquals("goblin", factory.from(attack, locator).getTarget());
        MenuEntry tagged = entry("Attack", "<col=ffff00>Goblin</col> <col=f87171>(Locked)</col>");
        when(tagged.getNpc()).thenReturn(npc);
        assertEquals("the plugin's own tag is removed", "goblin", factory.from(tagged, locator).getTarget());

        MenuEntry bank = entry("Bank", "Banker");
        when(bank.getNpc()).thenReturn(npc);
        assertEquals(GuardedAction.Kind.BANK,
            factory.from(bank, locator).getKind());
    }

    /** Travel is the tracker's table's to match, by id (F4): menu text alone is never a teleport here. */
    @Test
    public void walkingAndTeleportTextHaveNoChunkWhileEquipmentIsRecognized()
    {
        // "Walk here" carries viewport pixel coordinates, not a scene tile,
        // so it is never given a chunk (and never tagged).
        MenuEntry walk = entry("Walk here", "");
        when(walk.getType()).thenReturn(MenuAction.WALK);
        when(walk.getParam0()).thenReturn(10);
        when(walk.getParam1()).thenReturn(20);
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(walk, locator).getKind());
        assertNull(factory.from(walk, locator).getChunk());

        MenuEntry teleport = entry("Teleport", "Falador");
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(teleport, locator).getKind());
        assertNull(factory.from(teleport, locator).getChunk());

        MenuEntry wield = entry("Wield", "Abyssal whip");
        when(wield.getItemId()).thenReturn(4151);
        assertEquals(GuardedAction.Kind.EQUIPMENT,
            factory.from(wield, locator).getKind());
        assertEquals(Integer.valueOf(4151),
            factory.from(wield, locator).getItemId());
    }

    @Test
    public void examineAndUnrelatedWidgetsStayUnknown()
    {
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(entry("Examine", "Goblin"), locator).getKind());
        assertEquals(GuardedAction.Kind.UNKNOWN,
            factory.from(entry("Continue", ""), locator).getKind());
    }

    @Test
    public void transportTextIsNeverAChunk()
    {
        String[] transports = {
            "mine cart", "magic carpet", "balloon", "eagle", "minigame teleport"
        };
        for (String transport : transports)
        {
            assertEquals(GuardedAction.Kind.UNKNOWN,
                factory.from(entry("Travel via " + transport, "Falador"), locator).getKind());
        }
    }

    /** F1: from the option's facts, read once, the factory says what it says from the entry. */
    @Test
    public void theFactsSayWhatTheEntrySays()
    {
        NPC npc = mock(NPC.class);
        when(npc.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));
        MenuEntry attack = entry("Attack", "<col=ffff00>Goblin</col>");
        when(attack.getNpc()).thenReturn(npc);
        MenuEntry wield = entry("Wield", "Abyssal whip");
        when(wield.getItemId()).thenReturn(4151);
        MenuEntry examine = entry("Examine", "Goblin");
        for (MenuEntry entry : new MenuEntry[] {attack, wield, examine})
        {
            MenuFacts facts = MenuFacts.builder()
                .option(entry.getOption().replaceAll("<[^>]*>", ""))
                .target(entry.getTarget().replaceAll("<[^>]*>", ""))
                .build();
            assertEquals(entry.getOption(), factory.from(entry, locator), factory.from(facts, entry, locator));
        }
        GuardedAction bank = factory.from(MenuFacts.builder().option("Bank").target("Banker").build(),
            entry("Bank", "Banker"), locator);
        assertEquals("the facts keep their case; the factory's words don't", "bank", bank.getOption());
        assertEquals("banker", bank.getTarget());
    }

    /** A non-breaking space in a name is a space, as in the facts. */
    @Test
    public void anyWhitespaceIsOneSpace()
    {
        assertEquals("goblin (level-2)", factory.from(entry("Attack", "Goblin\u00a0 (level-2)"), locator).getTarget());
    }

    private static MenuEntry entry(String option, String target)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getOption()).thenReturn(option);
        when(entry.getTarget()).thenReturn(target);
        when(entry.getType()).thenReturn(MenuAction.UNKNOWN);
        when(entry.getItemId()).thenReturn(-1);
        return entry;
    }
}

package com.fatelocked.guardian;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class StrictModeReadinessTest
{
    @Test
    public void activeOnlyWhenEveryTrustFactHolds()
    {
        StrictModeReadiness ready = evaluate(true, false, true, "Nubles", "Nubles", true, true);
        assertEquals(StrictModeReadiness.State.ACTIVE, ready.getState());
        assertNull(ready.getReason());
    }

    @Test
    public void offAndPausedNeedNoReason()
    {
        assertEquals(StrictModeReadiness.State.OFF,
            evaluate(false, false, false, null, null, false, false).getState());
        assertEquals(StrictModeReadiness.State.OFF,
            evaluate(false, true, true, "Nubles", "Nubles", true, true).getState());
        StrictModeReadiness paused = evaluate(true, true, true, "Nubles", "Nubles", true, true);
        assertEquals(StrictModeReadiness.State.PAUSED, paused.getState());
        assertNull(paused.getReason());
    }

    /** Paused means it would block otherwise, so a pause never hides why it couldn't. */
    @Test
    public void aPauseDoesNotHideWhyStrictModeCannotAct()
    {
        assertInactive("no tracker rules are loaded",
            evaluate(true, true, false, null, null, false, false));
        assertInactive("the rules are more than 15 minutes old",
            evaluate(true, true, true, "Nubles", "Nubles", true, false));
        assertInactive("the rules have no travel table; sync them from the tracker again",
            StrictModeReadiness.evaluate(true, true, true, false, "Nubles", "Nubles", true, true));
    }

    @Test
    public void inactiveNamesTheFirstMissingFact()
    {
        assertInactive("no tracker rules are loaded",
            evaluate(true, false, false, "Nubles", "Nubles", true, true));
        assertInactive("the rules have no travel table; sync them from the tracker again",
            StrictModeReadiness.evaluate(true, false, true, false, "Nubles", "Nubles", true, true));
        assertInactive("the tracker profile has no linked account",
            evaluate(true, false, true, "  ", "Nubles", false, true));
        assertInactive("you are not logged in",
            evaluate(true, false, true, "Nubles", null, false, true));
        assertInactive("the profile is for Nubles; you're logged in as Zezima",
            evaluate(true, false, true, " Nubles ", "Zezima", false, true));
        assertInactive("the rules are more than 15 minutes old",
            evaluate(true, false, true, "Nubles", "Nubles", true, false));
    }

    private static void assertInactive(String reason, StrictModeReadiness readiness)
    {
        assertEquals(StrictModeReadiness.State.INACTIVE, readiness.getState());
        assertEquals(reason, readiness.getReason());
    }

    private static StrictModeReadiness evaluate(
        boolean enabled, boolean paused, boolean rules, String bound, String player,
        boolean matches, boolean fresh)
    {
        return StrictModeReadiness.evaluate(enabled, paused, rules, true, bound, player, matches, fresh);
    }
}

package com.fatelocked.guardian;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import net.runelite.api.events.MenuOptionClicked;
import org.junit.Test;

import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

public class StrictModeClickHandlerTest
{
    private final StrictModeClickHandler handler =
        new StrictModeClickHandler(new StrictModeGuard());

    @Test
    public void travelConsumesExactlyOnceOnlyForExactLockedTripsWhileActive()
    {
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        MenuOptionClicked lockedEvent = mock(MenuOptionClicked.class);
        handler.handleTravel(lockedEvent, exact, locked, active());
        verify(lockedEvent, times(1)).consume();

        assertNotConsumed(exact, travelDecision(PermissionStatus.ALLOWED), active());
        assertNotConsumed(exact, travelDecision(PermissionStatus.NOT_READY), active());
        assertNotConsumed(exact, travelDecision(PermissionStatus.UNKNOWN), active());
        assertNotConsumed(exact, locked, readiness(false, false, true, true));
        assertNotConsumed(exact, locked, paused());
        assertNotConsumed(exact, locked, readiness(true, false, true, false));
        assertNotConsumed(exact, locked, readiness(true, false, false, true));
        assertNotConsumed(unknownTravel(), locked, active());
        assertNotConsumed(null, locked, active());
        assertNotConsumed(exact, null, active());
        assertNotConsumed(exact, locked, null);
    }

    @Test
    public void decidingNeverTouchesTheClick()
    {
        MenuOptionClicked event = mock(MenuOptionClicked.class);

        assertEquals(GuardResult.Outcome.BLOCK, handler.decide(
            exactTravel(), travelDecision(PermissionStatus.LOCKED), active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW_PAUSED, handler.handleTravel(
            event, exactTravel(), travelDecision(PermissionStatus.LOCKED), paused()).getOutcome());
        verify(event, never()).consume();
    }

    private void assertNotConsumed(
        TravelAction action,
        TravelDecision decision,
        StrictModeReadiness readiness)
    {
        MenuOptionClicked event = mock(MenuOptionClicked.class);
        GuardResult result = handler.handleTravel(
            event, action, decision, readiness);
        assertNotEquals(GuardResult.Outcome.BLOCK, result.getOutcome());
        verify(event, never()).consume();
    }

    private static TravelAction exactTravel()
    {
        return new TravelAction("spell:standard:falador-teleport", "Cast", "Falador Teleport",
            Collections.singletonList(new CanonicalChunk(46, 52)), false, TravelAction.Confidence.EXACT);
    }

    private static TravelAction unknownTravel()
    {
        return new TravelAction(null, null, "Unknown",
            Collections.emptyList(), false, TravelAction.Confidence.UNKNOWN);
    }

    private static TravelDecision travelDecision(PermissionStatus status)
    {
        return new TravelDecision(status, "Destination", "not unlocked");
    }

    private static StrictModeReadiness active()
    {
        return readiness(true, false, true, true);
    }

    private static StrictModeReadiness paused()
    {
        return readiness(true, true, true, true);
    }

    private static StrictModeReadiness readiness(
        boolean enabled, boolean paused, boolean accountMatches, boolean fresh)
    {
        return StrictModeGuardTest.readiness(enabled, paused, accountMatches, fresh);
    }
}

package com.fatelocked.guardian;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelDecision;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;

public class StrictModeGuardTest
{
    private final StrictModeGuard guard = new StrictModeGuard();

    @Test
    public void travelBlocksOnlyExactLockedTripsWhileActive()
    {
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        assertEquals(GuardResult.Outcome.BLOCK,
            guard.decideTravel(exact, locked, active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.UNKNOWN),
                active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, off()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, stale()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, wrongAccount()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(unknownTravel(), locked, active()).getOutcome());
        assertEquals("an exact match needs somewhere to go", GuardResult.Outcome.ALLOW,
            guard.decideTravel(noDestination(), locked, active()).getOutcome());
        assertEquals("one place, not one of several", GuardResult.Outcome.ALLOW,
            guard.decideTravel(severalPlaces(), locked, active()).getOutcome());
        assertEquals("networks and boats are tagged, never blocked", GuardResult.Outcome.ALLOW,
            guard.decideTravel(advisory(), locked, active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(advisory(), locked, paused()).getOutcome());
    }

    @Test
    public void aPauseLetsOnlyAProvenLockThroughAsPaused()
    {
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        assertEquals(GuardResult.Outcome.ALLOW_PAUSED,
            guard.decideTravel(exact, locked, paused()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.ALLOWED),
                paused()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(unknownTravel(), locked, paused()).getOutcome());
        // Paused on stale rules: it couldn't have blocked, so it isn't a pause.
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, readiness(true, true, true, false)).getOutcome());
    }

    @Test
    public void travelAllowsOtherStatusesAndNullInputs()
    {
        TravelAction exact = exactTravel();
        TravelDecision locked = travelDecision(PermissionStatus.LOCKED);

        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.ALLOWED),
                active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, travelDecision(PermissionStatus.NOT_READY),
                active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(null, locked, active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, null, active()).getOutcome());
        assertEquals(GuardResult.Outcome.ALLOW,
            guard.decideTravel(exact, locked, null).getOutcome());
    }

    @Test
    public void travelBlockAlwaysImpliesExactLockedDecision()
    {
        for (PermissionStatus status : PermissionStatus.values())
        {
            TravelAction action = exactTravel();
            GuardResult result = guard.decideTravel(
                action, travelDecision(status), active());

            if (result.getOutcome() == GuardResult.Outcome.BLOCK)
            {
                assertEquals(PermissionStatus.LOCKED,
                    result.getDecision().getStatus());
                assertEquals(TravelAction.Confidence.EXACT,
                    action.getConfidence());
            }
            else
            {
                assertEquals(GuardResult.Outcome.ALLOW, result.getOutcome());
            }
        }
    }

    private static TravelAction exactTravel()
    {
        return new TravelAction("spell:standard:falador-teleport", "Cast", "Falador Teleport",
            Collections.singletonList(new CanonicalChunk(46, 52)), false, TravelAction.Confidence.EXACT);
    }

    private static TravelAction noDestination()
    {
        return new TravelAction("item:somewhere", "Teleport", "Teleport",
            Collections.emptyList(), false, TravelAction.Confidence.EXACT);
    }

    private static TravelAction severalPlaces()
    {
        return new TravelAction("item:digsite-pendant", "Rub", "Digsite pendant",
            Arrays.asList(new CanonicalChunk(52, 53), new CanonicalChunk(58, 59)), false, TravelAction.Confidence.EXACT);
    }

    private static TravelAction advisory()
    {
        return new TravelAction("network:fairy-ring", "Zanaris", "Fairy ring to Zanaris",
            Collections.singletonList(new CanonicalChunk(37, 69)), true, TravelAction.Confidence.EXACT);
    }

    private static TravelAction unknownTravel()
    {
        return new TravelAction(null, null, "Unknown",
            Collections.emptyList(), false, TravelAction.Confidence.UNKNOWN);
    }

    private static TravelDecision travelDecision(PermissionStatus status)
    {
        return new TravelDecision(status, "Destination", "not unlocked");
    }

    private static StrictModeReadiness active()
    {
        return readiness(true, false, true, true);
    }

    private static StrictModeReadiness off()
    {
        return readiness(false, false, true, true);
    }

    private static StrictModeReadiness paused()
    {
        return readiness(true, true, true, true);
    }

    private static StrictModeReadiness stale()
    {
        return readiness(true, false, true, false);
    }

    private static StrictModeReadiness wrongAccount()
    {
        return readiness(true, false, false, true);
    }

    /** Rules bound to Nubles, played by Nubles or by someone else. */
    static StrictModeReadiness readiness(
        boolean enabled, boolean paused, boolean accountMatches, boolean fresh)
    {
        return StrictModeReadiness.evaluate(enabled, paused, true, true, "Nubles",
            accountMatches ? "Nubles" : "Zezima", accountMatches, fresh);
    }
}

package com.fatelocked.guardian;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** B16 (G10): Strict Mode's status, one view for the sidebar row and the HUD line. */
public class StrictModeStatusViewTest
{
    @Test
    public void eachStateReadsAsItShould()
    {
        StrictModeStatusView active = StrictModeStatusView.of(true, false, 0, null);
        assertEquals(StrictModeStatusView.Tone.ACTIVE, active.getTone());
        assertEquals("Active", active.getText());
        assertNull(active.getExplanation());

        StrictModeStatusView paused = StrictModeStatusView.of(true, true, 42, null);
        assertEquals(StrictModeStatusView.Tone.PAUSED, paused.getTone());
        assertEquals("Paused · 42s", paused.getText());
        assertEquals(42, paused.getSecondsLeft());

        StrictModeStatusView inactive = StrictModeStatusView.of(true, false, 0, "you are not logged in");
        assertEquals(StrictModeStatusView.Tone.INACTIVE, inactive.getTone());
        assertEquals("Inactive", inactive.getText());
        assertEquals("Not blocking anything: you are not logged in.", inactive.getExplanation());

        StrictModeStatusView off = StrictModeStatusView.of(false, true, 42, "no tracker rules are loaded");
        assertEquals(StrictModeStatusView.Tone.OFF, off.getTone());
        assertEquals("Off", off.getText());
    }

    @Test
    public void aPauseShowsFirstAndTheHudHidesOff()
    {
        assertEquals(StrictModeStatusView.Tone.PAUSED,
            StrictModeStatusView.of(true, true, 5, "the rules are more than 15 minutes old").getTone());
        assertEquals("Paused · 0s", StrictModeStatusView.of(true, true, -3, null).getText());
        assertEquals(StrictModeStatusView.Tone.ACTIVE, StrictModeStatusView.of(true, false, 0, "  ").getTone());

        assertFalse(StrictModeStatusView.of(false, false, 0, null).isShownOnHud());
        assertTrue(StrictModeStatusView.of(true, false, 0, null).isShownOnHud());
        assertTrue(StrictModeStatusView.of(true, true, 9, null).isShownOnHud());
        assertTrue(StrictModeStatusView.of(true, false, 0, "you are not logged in").isShownOnHud());
    }
}

