        return FateLockedBundle.loadFromJson(new Gson(), json());
    }

    /** The table's rules, bound to Nubles, with this character playing. */
    public static DecisionService playing(String player)
    {
        return DecisionService.create(RulesSnapshot.of(bundle()), "nubles", player);
    }

    public static DecisionService nubles()
    {
        return playing("nubles");
    }

    /** Cast on a standard spell. */
    public static MenuFacts cast(String spell)
    {
        return spell(STANDARD, "Cast", spell);
    }

    public static MenuFacts spell(int spellbook, String option, String name)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.WIDGET).interfaceGroup(InterfaceID.MAGIC_SPELLBOOK)
            .spellbook(spellbook).option(option).target(name).build();
    }

    /** An option on an item in the inventory. */
    public static MenuFacts item(int itemId, String option, String name)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.WIDGET).interfaceGroup(InterfaceID.INVENTORY)
            .itemId(itemId).option(option).target(name).build();
    }

    public static MenuFacts object(int objectId, String option, String name)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.OBJECT).objectId(objectId).option(option).target(name).build();
    }

    public static MenuFacts npc(int npcId, String option, String name)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.NPC).npcId(npcId).option(option).target(name).build();
    }

    /** Anything that is never travel: walking, dialogue, a player. */
    public static MenuFacts other(String option, String target)
    {
        return MenuFacts.builder().option(option).target(target).build();
    }
}

package com.fatelocked.guardian.travel;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.MenuFacts;
import com.fatelocked.rules.TravelTable;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * F2 (G7, G13): a click is travel only when the tracker's table matches its
 * own ids and its exact option text. The ids are the ones RuneLite gives
 * (see MenuFactsTest); the rows are vanilla-interiors' table.
 */
public class IntentClassifierTest
{
    private static final Gson GSON = new Gson();
    private static final int STANDARD = 0;
    private static final int ANCIENT = 1;
    private static final int LUNAR = 2;
    private static final int ARCEUUS = 3;
    private static final int AMULET_OF_GLORY_4 = 1712;
    private static final int DIGSITE_PENDANT_5 = 11194;
    private static final int VARROCK_TELEPORT_TABLET = 8007;
    private static final int FAIRY_RING = 29495;
    private static final int PORT_SARIM_CREW = 14978;

    private final IntentClassifier classifier = new IntentClassifier();
    private final TravelTable table = golden("vanilla-interiors");

    /** Two spells share a name; the active spellbook tells them apart (G7). */
    @Test
    public void aSpellIsItsSpellbookAndName()
    {
        assertEquals("spell:arceuus:ape-atoll-teleport", id(spell(ARCEUUS, "Cast", "Ape Atoll Teleport")));
        assertEquals(new CanonicalChunk(43, 142), destination(spell(ARCEUUS, "Cast", "Ape Atoll Teleport")));
        assertEquals("spell:standard:ape-atoll-teleport", id(spell(STANDARD, "Cast", "Ape Atoll Teleport")));
        assertNull("the Lunar book has no such spell", classifier.classify(spell(LUNAR, "Cast", "Ape Atoll Teleport"), table));
        assertNull("a spellbook it doesn't know", classifier.classify(spell(4, "Cast", "Ape Atoll Teleport"), table));
        assertNull(classifier.classify(spell(MenuFacts.NONE, "Cast", "Ape Atoll Teleport"), table));

        // Senntisten lands in 51,52 (web 3580d64); Carrallanger is spelled as the game spells it.
        assertEquals(new CanonicalChunk(51, 52), destination(spell(ANCIENT, "Cast", "Senntisten Teleport")));
        assertEquals("spell:ancient:carrallanger-teleport", id(spell(ANCIENT, "Cast", "Carrallanger Teleport")));
        assertNull("an option the spell doesn't have", classifier.classify(spell(STANDARD, "Examine", "Varrock Teleport"), table));

        MenuFacts notTheSpellbook = MenuFacts.builder().kind(MenuFacts.Kind.WIDGET).interfaceGroup(InterfaceID.INVENTORY)
            .spellbook(STANDARD).option("Cast").target("Varrock Teleport").build();
        assertNull(classifier.classify(notTheSpellbook, table));
    }

    /** An item is its id in the inventory or the worn items, and nowhere else. */
    @Test
    public void anItemIsItsIdInTheInventoryOrWornItems()
    {
        TravelMatch rub = classifier.classify(item(InterfaceID.INVENTORY, AMULET_OF_GLORY_4, "Rub"), table);
        assertEquals("item:amulet-of-glory", rub.getMethod().getId());
        assertNull("Rub picks the place after the click", rub.getOption().destination());
        assertEquals(new CanonicalChunk(48, 54), destination(item(InterfaceID.WORNITEMS, AMULET_OF_GLORY_4, "Edgeville")));
        assertEquals("tablet:varrock-teleport", id(item(InterfaceID.INVENTORY, VARROCK_TELEPORT_TABLET, "Break")));

        // The Digsite pendant's Rub goes to one of three places (G7).
        TravelMatch digsite = classifier.classify(item(InterfaceID.INVENTORY, DIGSITE_PENDANT_5, "Rub"), table);
        assertEquals("item:digsite-pendant", digsite.getMethod().getId());
        assertNull(digsite.getOption().destination());

        assertNull("never travel", classifier.classify(item(InterfaceID.INVENTORY, AMULET_OF_GLORY_4, "Wear"), table));
        assertNull("in the bank", classifier.classify(item(InterfaceID.BANKSIDE, AMULET_OF_GLORY_4, "Edgeville"), table));
        assertNull("no item", classifier.classify(item(InterfaceID.INVENTORY, MenuFacts.NONE, "Edgeville"), table));
    }

    /** An object or NPC is its own id; a fairy ring's Last-destination is its code. */
    @Test
    public void anObjectOrNpcIsItsId()
    {
        assertEquals("network:fairy-ring", id(object(FAIRY_RING, "Zanaris")));
        TravelMatch last = classifier.classify(object(FAIRY_RING, "Last-destination (CKS)"), table);
        assertEquals("code:CKS", last.getOption().getText());
        assertEquals(new CanonicalChunk(53, 54), last.getOption().destination());
        assertNull("the dial opens; the code isn't known yet", classifier.classify(object(FAIRY_RING, "Configure"), table));
        assertEquals("boat:port-sarim-ship", id(npc(PORT_SARIM_CREW, "Travel")));

        assertNull("an item's id isn't an object's", classifier.classify(object(AMULET_OF_GLORY_4, "Edgeville"), table));
        assertNull("an object's id isn't an NPC's", classifier.classify(npc(FAIRY_RING, "Zanaris"), table));
        assertNull(classifier.classify(object(MenuFacts.NONE, "Zanaris"), table));
        assertNull(classifier.classify(npc(MenuFacts.NONE, "Travel"), table));
    }

    /** Walking, examining and the rest are never travel; nor is anything without a table. */
    @Test
    public void everythingElseIsNotTravel()
    {
        MenuFacts walk = MenuFacts.builder().option("Walk here").itemId(AMULET_OF_GLORY_4).objectId(FAIRY_RING).build();
        assertNull(classifier.classify(walk, table));
        assertNull(classifier.classify(MenuFacts.EMPTY, table));
        assertNull(classifier.classify(null, table));
        assertNull(classifier.classify(item(InterfaceID.INVENTORY, AMULET_OF_GLORY_4, "Edgeville"), null));
    }

    /** A click two methods match is neither's; one matched by its option alone is that one's. */
    @Test
    public void aClickTwoMethodsMatchIsNeither()
    {
        TravelTable shared = TravelTable.parse(GSON.fromJson("{"
            + "\"item:a\": {\"label\": \"A\", \"match\": {\"items\": [1]}, \"options\": {"
            + "  \"Teleport\": {\"to\": [\"50,50\"], \"status\": \"LOCKED\"}, \"Home\": {\"to\": [\"50,51\"], \"status\": \"LOCKED\"}}},"
            + "\"item:b\": {\"label\": \"B\", \"match\": {\"items\": [1, 2]}, \"options\": {"
            + "  \"Teleport\": {\"to\": [\"46,52\"], \"status\": \"LOCKED\"}, \"Away\": {\"to\": [\"46,53\"], \"status\": \"LOCKED\"}}}"
            + "}", JsonObject.class));

        assertNull(classifier.classify(item(InterfaceID.INVENTORY, 1, "Teleport"), shared));
        assertEquals("item:a", id(item(InterfaceID.INVENTORY, 1, "Home"), shared));
        assertEquals("item:b", id(item(InterfaceID.INVENTORY, 1, "Away"), shared));
        assertEquals("item:b", id(item(InterfaceID.INVENTORY, 2, "Teleport"), shared));
    }

    private String id(MenuFacts facts)
    {
        return id(facts, table);
    }

    private String id(MenuFacts facts, TravelTable in)
    {
        TravelMatch match = classifier.classify(facts, in);
        return match == null ? null : match.getMethod().getId();
    }

    private CanonicalChunk destination(MenuFacts facts)
    {
        return classifier.classify(facts, table).getOption().destination();
    }

    static MenuFacts spell(int spellbook, String option, String name)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.WIDGET).interfaceGroup(InterfaceID.MAGIC_SPELLBOOK)
            .spellbook(spellbook).option(option).target(name).build();
    }

    static MenuFacts item(int group, int itemId, String option)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.WIDGET).interfaceGroup(group).itemId(itemId)
            .option(option).target("An item").build();
    }

    static MenuFacts object(int objectId, String option)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.OBJECT).objectId(objectId).option(option).target("An object").build();
    }

    static MenuFacts npc(int npcId, String option)
    {
        return MenuFacts.builder().kind(MenuFacts.Kind.NPC).npcId(npcId).option(option).target("Someone").build();
    }

    static TravelTable golden(String id)
    {
        try (InputStream in = IntentClassifierTest.class.getClassLoader()
            .getResourceAsStream("contracts/golden-bundles/" + id + ".bundle.json.gz");
             GZIPInputStream gzip = new GZIPInputStream(in);
             ByteArrayOutputStream out = new ByteArrayOutputStream())
        {
            gzip.transferTo(out);
            return FateLockedBundle.loadFromJson(GSON, out.toString(StandardCharsets.UTF_8)).getRules().getTravel();
        }
        catch (java.io.IOException ex)
        {
            throw new IllegalStateException(ex);
        }
    }
}

package com.fatelocked.guardian.travel;

import com.fatelocked.FateLockedBundle;
import com.fatelocked.MenuFacts;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.RulesSnapshot;
import com.google.gson.Gson;
import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;

import static com.fatelocked.guardian.travel.TravelFixtures.AMULET_OF_GLORY_4;
import static com.fatelocked.guardian.travel.TravelFixtures.ANCIENT;
import static com.fatelocked.guardian.travel.TravelFixtures.DIGSITE_PENDANT_5;
import static com.fatelocked.guardian.travel.TravelFixtures.FAIRY_RING;
import static com.fatelocked.guardian.travel.TravelFixtures.FALADOR_TABLET;
import static com.fatelocked.guardian.travel.TravelFixtures.LUMBRIDGE_TABLET;
import static com.fatelocked.guardian.travel.TravelFixtures.cast;
import static com.fatelocked.guardian.travel.TravelFixtures.item;
import static com.fatelocked.guardian.travel.TravelFixtures.nubles;
import static com.fatelocked.guardian.travel.TravelFixtures.object;
import static com.fatelocked.guardian.travel.TravelFixtures.other;
import static com.fatelocked.guardian.travel.TravelFixtures.spell;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * F3 (G6): a trip's decision is the tracker's own for the option clicked,
 * which already counts the unlocks the method needs and where it lands. An
 * option that can go to several places is Unknown, even when the tracker
 * locks it: the place is picked after the click.
 */
public class TravelRuleEvaluatorTest
{
    private final TravelRuleEvaluator evaluator = new TravelRuleEvaluator();
    private final IntentClassifier classifier = new IntentClassifier();
    private final DecisionService rules = nubles();

    @Test
    public void aTripIsTheTrackersDecisionForItsOption()
    {
        assertEquals(new TravelDecision(PermissionStatus.LOCKED, "Falador Teleport", "Unlock Falador"),
            evaluate(cast("Falador Teleport"), rules));
        assertEquals(new TravelDecision(PermissionStatus.ALLOWED, "Lumbridge Teleport", null),
            evaluate(cast("Lumbridge Teleport"), rules));
        assertEquals(new TravelDecision(PermissionStatus.NOT_READY, "Camelot Teleport", "No route from Lumbridge"),
            evaluate(cast("Camelot Teleport"), rules));
        assertEquals(new TravelDecision(PermissionStatus.LOCKED, "Falador teleport", "Unlock Falador"),
            evaluate(item(FALADOR_TABLET, "Break", "Falador teleport"), rules));
        assertEquals(PermissionStatus.ALLOWED, evaluate(item(LUMBRIDGE_TABLET, "Break", "Lumbridge teleport"), rules).getStatus());
        assertEquals(new TravelDecision(PermissionStatus.LOCKED, "Amulet of glory(4) to Al Kharid", "Unlock Al Kharid"),
            evaluate(item(AMULET_OF_GLORY_4, "Al Kharid", "Amulet of glory(4)"), rules));
    }

    /** G6: the method's own unlock, as the web names it: a spellbook, the Digsite pendant. */
    @Test
    public void eachMethodNeedsItsOwnUnlock()
    {
        assertEquals(new TravelDecision(PermissionStatus.LOCKED, "Senntisten Teleport", "Needs Ancient Magicks"),
            evaluate(spell(ANCIENT, "Cast", "Senntisten Teleport"), rules));
        assertEquals(new TravelDecision(PermissionStatus.LOCKED, "Digsite pendant (5) to Digsite", "Needs Digsite Pendant"),
            evaluate(item(DIGSITE_PENDANT_5, "Digsite", "Digsite pendant (5)"), rules));
    }

    /** G7: several places, or none, are Unknown whatever the tracker says. */
    @Test
    public void severalPlacesAreUnknown()
    {
        assertEquals(PermissionStatus.UNKNOWN, evaluate(item(DIGSITE_PENDANT_5, "Rub", "Digsite pendant (5)"), rules).getStatus());
        assertEquals(PermissionStatus.UNKNOWN, evaluate(cast("Varrock Teleport"), rules).getStatus());
        assertEquals(PermissionStatus.UNKNOWN, evaluate(item(AMULET_OF_GLORY_4, "Rub", "Amulet of glory(4)"), rules).getStatus());
    }

    /** Advisory travel still has the tracker's decision, for tags; the guard never blocks it. */
    @Test
    public void advisoryTravelKeepsItsDecision()
    {
        assertEquals(new TravelDecision(PermissionStatus.LOCKED, "Fairy ring to Zanaris", "Needs Fairy Rings"),
            evaluate(object(FAIRY_RING, "Zanaris", "Fairy ring"), rules));
    }

    @Test
    public void anotherCharacterOrOlderRulesDecideNothing() throws Exception
    {
        TravelDecision other = evaluate(cast("Falador Teleport"), TravelFixtures.playing("zezima"));
        assertEquals(PermissionStatus.UNKNOWN, other.getStatus());

        DecisionService legacy = DecisionService.create(RulesSnapshot.of(fixture("bundles/v3-standard.json")), "nubles", "nubles");
        assertEquals(PermissionStatus.UNKNOWN, evaluate(cast("Falador Teleport"), legacy).getStatus());
    }

    @Test
    public void anythingElseIsUnknown()
    {
        assertEquals(new TravelDecision(PermissionStatus.UNKNOWN, "Continue", null), evaluate(other("Continue", ""), rules));
        assertEquals(new TravelDecision(PermissionStatus.UNKNOWN, "Unknown travel", null), evaluator.evaluate(null, null, rules));
        TravelMatch match = classifier.classify(cast("Falador Teleport"), rules.travelTable());
        TravelAction action = TravelAction.of(match, cast("Falador Teleport"));
        assertEquals(PermissionStatus.UNKNOWN, evaluator.evaluate(match, action, null).getStatus());
        assertEquals(PermissionStatus.UNKNOWN, evaluator.evaluate(null, action, rules).getStatus());
        assertNull(evaluator.evaluate(null, action, rules).getReason());
    }

    private TravelDecision evaluate(MenuFacts facts, DecisionService decisions)
    {
        TravelMatch match = classifier.classify(facts, decisions.travelTable());
        TravelAction action = match == null ? TravelAction.notTravel(facts) : TravelAction.of(match, facts);
        return evaluator.evaluate(match, action, decisions);
    }

    private FateLockedBundle fixture(String name) throws Exception
    {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(name))
        {
            return FateLockedBundle.loadFromJson(new Gson(), new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
    }
}

package com.fatelocked.guardian.travel;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.RulesSnapshot;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import org.junit.Test;

import java.io.InputStream;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;

import static com.fatelocked.guardian.travel.TravelFixtures.AMULET_OF_GLORY_4;
import static com.fatelocked.guardian.travel.TravelFixtures.DIGSITE_PENDANT_5;
import static com.fatelocked.guardian.travel.TravelFixtures.EDGEVILLE;
import static com.fatelocked.guardian.travel.TravelFixtures.EMIRS_ARENA;
import static com.fatelocked.guardian.travel.TravelFixtures.FALADOR;
import static com.fatelocked.guardian.travel.TravelFixtures.FALADOR_TABLET;
import static com.fatelocked.guardian.travel.TravelFixtures.LUMBRIDGE;
import static com.fatelocked.guardian.travel.TravelFixtures.LUMBRIDGE_TABLET;
import static com.fatelocked.guardian.travel.TravelFixtures.RING_OF_DUELING_8;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

/**
 * F7: another way there, from the tracker's travel table: a trip on an item
 * the player carries or wears, to one place, that the tracker allows for
 * the run. In the fixture the Lumbridge tablet and the glory's Edgeville
 * are allowed; the Falador tablet, the glory's Karamja and Al Kharid, and
 * the Digsite pendant are locked; a Rub goes to one of several places.
 */
public class TravelAlternativeFinderTest
{
    private static final Gson GSON = new Gson();
    private static final String LUMBRIDGE_AREA = "Lumbridge · Misthalin";

    private final TravelAlternativeFinder finder = new TravelAlternativeFinder();
    private final TravelAvailability availability = mock(TravelAvailability.class);
    private final DecisionService rules = spy(TravelFixtures.nubles());
    private final Set<Integer> carried = new HashSet<>();

    public TravelAlternativeFinderTest()
    {
        when(availability.hasAnyItem(any())).thenAnswer(call -> {
            Set<Integer> ids = call.getArgument(0);
            return ids != null && !Collections.disjoint(ids, carried);
        });
    }

    @Test
    public void onlyACarriedTripToOnePlaceTheTrackerAllows()
    {
        assertFalse("carrying nothing", find(FALADOR).isPresent());

        carrying(FALADOR_TABLET, DIGSITE_PENDANT_5);
        assertFalse("every trip they have is locked, or goes to several places", find(FALADOR).isPresent());

        carrying(LUMBRIDGE_TABLET);
        assertEquals(new TravelAlternative("tablet:lumbridge-teleport|Break", "Lumbridge teleport", LUMBRIDGE),
            find(FALADOR).get());
    }

    @Test
    public void anOptionThatNamesAPlaceIsNamed()
    {
        carrying(AMULET_OF_GLORY_4);

        assertEquals(new TravelAlternative("item:amulet-of-glory|Edgeville", "Amulet of glory to Edgeville", EDGEVILLE),
            find(FALADOR).get());
    }

    /** The blocked trip's area first, then the nearest; then the lower id. */
    @Test
    public void theBlockedTripsAreaRanksFirst()
    {
        carrying(LUMBRIDGE_TABLET, AMULET_OF_GLORY_4);
        assertEquals(LUMBRIDGE_AREA, rules.areaName(LUMBRIDGE));

        assertEquals("neither in Falador's area: the nearer", "item:amulet-of-glory|Edgeville", id(FALADOR));

        doReturn(LUMBRIDGE_AREA).when(rules).areaName(FALADOR);
        assertEquals("in the blocked trip's area, though farther", "tablet:lumbridge-teleport|Break", id(FALADOR));

        CanonicalChunk northOfEdgeville = new CanonicalChunk(48, 55);
        assertEquals("the nearest", "item:amulet-of-glory|Edgeville", id(northOfEdgeville));

        CanonicalChunk between = new CanonicalChunk(49, 52);
        assertEquals("as near as each other: the lower id", "item:amulet-of-glory|Edgeville", id(between));
        doReturn(LUMBRIDGE_AREA).when(rules).areaName(between);
        assertEquals("tablet:lumbridge-teleport|Break", id(between));

        carrying(LUMBRIDGE_TABLET, RING_OF_DUELING_8);
        CanonicalChunk unnamed = new CanonicalChunk(50, 51);
        assertNull(rules.areaName(unnamed));
        assertNull(rules.areaName(EMIRS_ARENA));
        assertEquals("an area the lists don't name matches nothing", "tablet:lumbridge-teleport|Break", id(unnamed));
    }

    /** Where the area lists name nothing, the nearest wins: the same place first. */
    @Test
    public void withoutAreasTheNearestWins()
    {
        carrying(LUMBRIDGE_TABLET, RING_OF_DUELING_8);
        doReturn(null).when(rules).areaName(any());

        assertEquals("the same place, over the one next to it", "tablet:lumbridge-teleport|Break", id(LUMBRIDGE));
        assertEquals("item:ring-of-dueling|Emir's Arena", id(EMIRS_ARENA));
    }

    /** Spells aren't carried: only item trips are suggested, even with every id read as carried. */
    @Test
    public void onlyItemsAreSuggested()
    {
        when(availability.hasAnyItem(any())).thenReturn(true);

        assertEquals("tablet:lumbridge-teleport|Break", id(LUMBRIDGE));
    }

    /** One place, allowed: not an allowed trip to several places, nor one not ready. */
    @Test
    public void onlyOnePlaceTheTrackerAllows()
    {
        JsonObject root = GSON.fromJson(TravelFixtures.json(), JsonObject.class);
        root.getAsJsonObject("rules").getAsJsonObject("travel").add("item:odd", GSON.fromJson("{"
            + "\"label\": \"Odd item\", \"match\": {\"items\": [1]}, \"options\": {"
            + "\"Everywhere\": {\"to\": [\"50,50\", \"50,51\"], \"status\": \"ALLOWED\"},"
            + "\"Home\": {\"to\": [\"50,50\"], \"status\": \"NOT_READY\", \"reason\": \"No route\"}}}", JsonObject.class));
        DecisionService odd = DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, root.toString())), "nubles", "nubles");
        carrying(1);

        assertFalse(finder.find(blocked(LUMBRIDGE), odd, availability).isPresent());
    }

    @Test
    public void anotherCharacterOrOlderRulesSuggestNothing() throws Exception
    {
        carrying(LUMBRIDGE_TABLET, AMULET_OF_GLORY_4);

        assertFalse(finder.find(blocked(FALADOR), TravelFixtures.playing("zezima"), availability).isPresent());
        DecisionService legacy = DecisionService.create(
            RulesSnapshot.of(fixture("bundles/v3-standard.json")), "nubles", "nubles");
        assertFalse(finder.find(blocked(FALADOR), legacy, availability).isPresent());
    }

    @Test
    public void unresolvedInputsNeverProduceAGuess()
    {
        carrying(LUMBRIDGE_TABLET);
        TravelAction notTravel = new TravelAction(null, null, "Unknown",
            Collections.emptyList(), false, TravelAction.Confidence.UNKNOWN);
        TravelAction severalPlaces = new TravelAction("item:amulet-of-glory", "Rub", "Amulet of glory(4)",
            Arrays.asList(EDGEVILLE, FALADOR), false, TravelAction.Confidence.EXACT);

        assertFalse(finder.find(null, rules, availability).isPresent());
        assertFalse(finder.find(notTravel, rules, availability).isPresent());
        assertFalse(finder.find(severalPlaces, rules, availability).isPresent());
        assertFalse(finder.find(blocked(FALADOR), null, availability).isPresent());
        assertFalse(finder.find(blocked(FALADOR), rules, null).isPresent());
    }

    @Test
    public void finderExposesDataSelectionOnly()
    {
        for (Method method : TravelAlternativeFinder.class.getDeclaredMethods())
        {
            assertFalse(method.getName().matches(
                "(?i).*(click|move|invoke|interact|menu|activate).*"));
            assertFalse(Client.class.isAssignableFrom(method.getReturnType()));
            for (Class<?> parameterType : method.getParameterTypes())
            {
                assertFalse(Client.class.isAssignableFrom(parameterType));
            }
        }
        assertNull(TravelAlternative.class.getSuperclass().getSuperclass());
    }

    private Optional<TravelAlternative> find(CanonicalChunk destination)
    {
        return finder.find(blocked(destination), rules, availability);
    }

    private String id(CanonicalChunk destination)
    {
        return find(destination).get().getId();
    }

    private void carrying(Integer... items)
    {
        carried.clear();
        carried.addAll(Arrays.asList(items));
    }

    /** A blocked trip to one place. */
    private static TravelAction blocked(CanonicalChunk destination)
    {
        return new TravelAction("spell:standard:falador-teleport", "Cast", "Falador Teleport",
            Collections.singletonList(destination), false, TravelAction.Confidence.EXACT);
    }

    private FateLockedBundle fixture(String name) throws Exception
    {
        try (InputStream in = getClass().getClassLoader().getResourceAsStream(name))
        {
            return FateLockedBundle.loadFromJson(new Gson(), new String(in.readAllBytes(), StandardCharsets.UTF_8));
        }
    }
}

