/**
 * B16: an optional hotkey pauses Strict Mode for 60 seconds, through the
 * client thread as the banner's button does. It is not set by default, and
 * does nothing while Strict Mode is off.
 */
public class StrictModeHotkeyTest
{
    private final FateLockedPlugin plugin = new FateLockedPlugin();
    private final FateLockedConfig config = mock(FateLockedConfig.class);
    private final FateLockedPanel panel = mock(FateLockedPanel.class);

    @Before
    public void setUp() throws Exception
    {
        PluginTestSupport.runQueuedWorkInline(plugin);
        PluginTestSupport.set(plugin, "config", config);
        PluginTestSupport.set(plugin, "panel", panel);
        PluginTestSupport.set(plugin, "client", mock(Client.class));
    }

    @Test
    public void itIsNotSetByDefault()
    {
        assertEquals(Keybind.NOT_SET, new FateLockedConfig() { }.pauseStrictModeHotkey());
    }

    @Test
    public void pressingItPausesStrictModeForSixtySeconds() throws Exception
    {
        when(config.strictMode()).thenReturn(true);

        hotkey().hotkeyPressed();

        StrictModePause pause = (StrictModePause) PluginTestSupport.get(plugin, "strictPause");
        assertTrue(pause.isPaused());
        assertTrue(pause.remainingSeconds() > 55);
        ArgumentCaptor<com.fatelocked.sidebar.StrictModeModel> shown =
            ArgumentCaptor.forClass(com.fatelocked.sidebar.StrictModeModel.class);
        verify(panel).showStrictMode(shown.capture());
        assertTrue(shown.getValue().getWord(), shown.getValue().getWord().startsWith("Paused"));
        assertEquals(com.fatelocked.sidebar.CardAction.RESUME_STRICT_MODE, shown.getValue().getAction());
        assertEquals(StrictModeStatusView.Tone.PAUSED, plugin.getStrictModeStatus().getTone());
    }

    @Test
    public void itDoesNothingWhileStrictModeIsOff() throws Exception
    {
        when(config.strictMode()).thenReturn(false);

        hotkey().hotkeyPressed();

        assertFalse(((StrictModePause) PluginTestSupport.get(plugin, "strictPause")).isPaused());
    }

    @Test
    public void itReadsTheSetting() throws Exception
    {
        Keybind keybind = new Keybind(java.awt.event.KeyEvent.VK_F9, 0);
        when(config.pauseStrictModeHotkey()).thenReturn(keybind);
        java.lang.reflect.Field supplier = HotkeyListener.class.getDeclaredField("keybind");
        supplier.setAccessible(true);
        @SuppressWarnings("unchecked")
        java.util.function.Supplier<Keybind> read = (java.util.function.Supplier<Keybind>) supplier.get(hotkey());
        assertEquals(keybind, read.get());
    }

    private HotkeyListener hotkey() throws Exception
    {
        return (HotkeyListener) PluginTestSupport.get(plugin, "pauseStrictHotkey");
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** U20: the locked-area fade is one fade out, never a pulse. */
public class FlashFadeTest
{
    @Test
    public void itStartsStrongestAndOnlyWeakensToNothing()
    {
        assertEquals(FlashFade.MAX_ALPHA, FlashFade.alpha(0));
        int previous = FlashFade.MAX_ALPHA;
        for (long ms = 0; ms <= 3_000; ms++)
        {
            int alpha = FlashFade.alpha(ms);
            assertTrue(ms + " ms: never stronger again", alpha <= previous);
            previous = alpha;
        }
        assertTrue("still there near the end", FlashFade.alpha(FlashFade.DURATION_MS - 100) > 0);
        assertEquals(0, FlashFade.alpha(FlashFade.DURATION_MS));
        assertEquals(0, FlashFade.alpha(FlashFade.DURATION_MS + 1));
        assertEquals("not begun", 0, FlashFade.alpha(-1));
    }

    /** It eases out: most of its strength goes early, so it's quiet well before it ends. */
    @Test
    public void itEasesOut()
    {
        assertTrue(FlashFade.alpha(FlashFade.DURATION_MS / 2) < FlashFade.MAX_ALPHA / 2);
    }
}

package com.fatelocked;

import org.junit.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * B17: every surface reads the rules through DecisionService. The bundle's
 * old lock-state answers are read only by LegacyRules (for v1-3 exports)
 * and RulesSnapshot (which hands them to the decision service), so no
 * surface can answer "is this locked?" a second way (U4, R2). The Slayer
 * reach the old engine had is gone altogether.
 */
public class DecisionBoundaryTest
{
    private static final String[] OLD_ANSWERS = {
        ".lockStateAt(", ".isUnlocked(", ".isFrontierChunk(", ".nearestUsableBank(", ".nearestUsableShop(",
        ".isBankUnlocked(", ".getItemTiers(", ".labelAt(",
        ".getUnlockedAreas(", ".getTotalAreas(", ".getUnlockedChunks(", ".getTotalChunks(",
    };
    /** The bundle itself, and the two readers allowed to ask it. */
    private static final List<String> READERS = List.of("FateLockedBundle.java", "LegacyRules.java", "RulesSnapshot.java");

    @Test
    public void onlyTheRulesSnapshotAndLegacyRulesReadTheOldAnswers() throws IOException
    {
        List<String> offenders = new ArrayList<>();
        List<Path> sources = sources();
        for (Path source : sources)
        {
            String name = source.getFileName().toString();
            if (READERS.contains(name)) continue;
            String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);
            for (String call : OLD_ANSWERS)
            {
                if (text.contains(call)) offenders.add(name + ": " + call);
            }
        }
        assertTrue("the production sources are found", sources.size() > 50);
        assertEquals(new ArrayList<String>(), offenders);
    }

    @Test
    public void theOldSlayerReachIsGone() throws IOException
    {
        for (Path source : sources())
        {
            String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);
            assertTrue(source.toString(), !text.contains("monsterReach("));
        }
    }

    private static List<Path> sources() throws IOException
    {
        try (Stream<Path> paths = Files.walk(Paths.get("src", "main", "java")))
        {
            return paths.filter(path -> path.toString().endsWith(".java")).sorted().collect(Collectors.toList());
        }
    }
}

