            overlay.render(graphics);
            drawn.verify(() -> FateLockedMinimapOverlay.draw(eq(graphics), any(), eq(scene),
                eq(FateLockedConfig.ChunkBorders.OFF), eq(true), any(), eq(60), eq(60), anyInt(), anyInt(), any()));
        }
    }

    /**
     * A tile is a few pixels on the minimap, so its dashes run a third of a chunk's side, not
     * a third of a tile; and nothing stands in front of anything there.
     */
    @Test
    public void theMinimapsDashesAreAChunksThird()
    {
        try (MockedStatic<ChunkBorderRenderer> renderer = mockStatic(ChunkBorderRenderer.class))
        {
            FateLockedMinimapOverlay.draw(graphics, new Rectangle(0, 0, 10, 10), eastHalfLocked(),
                FateLockedConfig.ChunkBorders.LOCKED_EDGES, false, Palette.defaults(), 60, 60, 104, 104,
                (x, y) -> null);
            renderer.verify(() -> ChunkBorderRenderer.draw(eq(graphics), any(), any(), eq(false), any(), eq(60),
                eq(60), eq(104), eq(104), any(), eq(ChunkBorderRenderer.MINIMAP_PERIOD),
                eq(ChunkBorderRenderer.Occlusion.NONE)));
        }
    }

    /** A scene whose east half is locked, with a chunk line at 64 tiles both ways. */
    static SceneEdges eastHalfLocked()
    {
        SceneEdges.Zone[][] zones = new SceneEdges.Zone[13][13];
        for (int zx = 0; zx < 13; zx++)
        {
            for (int zy = 0; zy < 13; zy++)
            {
                zones[zx][zy] = new SceneEdges.Zone(zx < 8 ? TintPolicy.Tint.UNLOCKED : TintPolicy.Tint.LOCKED,
                    new CanonicalChunk(50 + zx / 8, 50 + zy / 8));
            }
        }
        return SceneEdges.of(zones);
    }

    /** The minimap's scene over a flat projection. */
    private static BufferedImage draw(FateLockedConfig.ChunkBorders borders, boolean fog)
    {
        BufferedImage image = new BufferedImage(1100, 1100, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        FateLockedMinimapOverlay.draw(graphics, new Rectangle(500, 0, 400, 1100), eastHalfLocked(), borders, fog,
            Palette.defaults(), 60, 60, 104, 104, (x, y) -> new Point2D.Double(x * 10, y * 10));
        assertNull("the clip is put back", graphics.getClip());
        graphics.dispose();
        return image;
    }

    private static boolean has(BufferedImage image, Color colour)
    {
        for (int x = 0; x < image.getWidth(); x++)
        {
            for (int y = 0; y < image.getHeight(); y++)
            {
                if (near(image.getRGB(x, y), colour))
                {
                    return true;
                }
            }
        }
        return false;
    }

    /** Whether a pixel is this colour, give or take a unit of compositing. */
    private static boolean near(int argb, Color colour)
    {
        Color pixel = new Color(argb, true);
        return Math.abs(pixel.getRed() - colour.getRed()) <= 1 && Math.abs(pixel.getGreen() - colour.getGreen()) <= 1
            && Math.abs(pixel.getBlue() - colour.getBlue()) <= 1 && Math.abs(pixel.getAlpha() - colour.getAlpha()) <= 1;
    }

    /** With no minimap on screen, nothing is drawn and the scene isn't worked out. */
    @Test
    public void noMinimapShownDrawsNothing()
    {
        Widget hidden = mock(Widget.class);
        when(hidden.isHidden()).thenReturn(true);
        when(client.getWidget(anyInt())).thenReturn(hidden);

        assertNull(overlay.render(graphics));

        verifyNoInteractions(graphics);
        verify(plugin, never()).sceneEdges(any(), any(), anyInt());
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.client.config.ConfigManager;
import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.SocketPolicy;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.time.Clock;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The relay fixture's transport cases, through the real connection
 * controller and a real socket: a reset connection, no answer in time, and
 * a reply larger than any real bundle.
 */
public class RelayTransportFixtureTest
{
    private static final String CODE = "0123456789abcdef0123456789abcdef";

    private final List<String> prepared = new CopyOnWriteArrayList<>();
    private final List<TrackerConnectionSnapshot> published = new CopyOnWriteArrayList<>();
    private MockWebServer server;
    private TrackerConnectionController controller;

    @Before
    public void setUp() throws Exception
    {
        Map<String, String> configuration = new ConcurrentHashMap<>();
        configuration.put(TrackerConnectionSettings.PAIRING_CODE_KEY, CODE);
        configuration.put(FateLockedConfig.NETWORK_ACCESS_KEY, "true");
        ConfigManager configManager = mock(ConfigManager.class);
        when(configManager.getConfiguration(anyString(), anyString()))
            .thenAnswer(invocation -> configuration.get(invocation.getArgument(1)));

        server = new MockWebServer();
        server.start();
        Interceptor redirectToServer = chain -> {
            Request original = chain.request();
            return chain.proceed(original.newBuilder()
                .url(server.url(original.url().encodedPath()))
                .build());
        };
        OkHttpClient http = new OkHttpClient.Builder()
            .addInterceptor(redirectToServer)
            .readTimeout(500, TimeUnit.MILLISECONDS)
            .build();
        controller = new TrackerConnectionController(
            http, new Gson(), new TrackerConnectionSettings(configManager),
            Clock.systemUTC(), Runnable::run,
            new TrackerConnectionController.RelayBundleImporter<String>()
            {
                @Override
                public TrackerConnectionController.Prepared<String> prepare(String payload)
                {
                    prepared.add(payload);
                    return TrackerConnectionController.Prepared.ok(payload);
                }

                @Override
                public boolean commit(String payload, String version)
                {
                    return true;
                }
            },
            published::add);
    }

    @After
    public void tearDown() throws Exception
    {
        controller.stop();
        server.shutdown();
    }

    @Test
    public void everyTransportCaseIsCovered() throws Exception
    {
        for (JsonElement element : RelayContractFixtureTest.fixture().getAsJsonArray("cases"))
        {
            JsonObject relayCase = element.getAsJsonObject();
            if (!relayCase.get("from").getAsString().equals("transport")) continue;
            String transport = relayCase.get("transport").getAsString();
            assertTrue(relayCase.get("name").getAsString(),
                List.of("reset", "timeout", "oversized").contains(transport));
        }
    }

    @Test
    public void aResetConnectionIsUnreachable() throws Exception
    {
        JsonObject relayCase = transportCase("reset");
        server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.DISCONNECT_AT_START));

        poll(relayCase);

        assertEquals("unreachable", relayCase.get("outcome").getAsString());
        waitFor(this::unreachable);
    }

    @Test
    public void noAnswerInTimeIsUnreachable() throws Exception
    {
        JsonObject relayCase = transportCase("timeout");
        server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));

        poll(relayCase);

        assertEquals("unreachable", relayCase.get("outcome").getAsString());
        waitFor(this::unreachable);
    }

    @Test
    public void aReplyLargerThanAnyRealBundleIsUnreadable() throws Exception
    {
        JsonObject relayCase = transportCase("oversized");
        int bodyBytes = relayCase.get("bodyBytes").getAsInt();
        StringBuilder payload = new StringBuilder(bodyBytes);
        while (payload.length() < bodyBytes) payload.append('x');
        server.enqueue(new MockResponse()
            .setResponseCode(200)
            .addHeader("ETag", "42")
            .setBody("{\"version\":42,\"payload\":\"" + payload + "\"}"));

        poll(relayCase);

        assertEquals("unreadable", relayCase.get("outcome").getAsString());
        waitFor(() -> shown(SyncReason.UNREADABLE.status));
        assertTrue(prepared.isEmpty());
    }

    private void poll(JsonObject relayCase)
    {
        controller.seedAcceptedVersion(relayCase.get("held").getAsString());
        controller.poll();
    }

    private boolean unreachable()
    {
        return shown(SyncReason.UNREACHABLE.status);
    }

    private boolean shown(String offlineMessage)
    {
        return published.stream().anyMatch(snapshot ->
            snapshot.getState() == TrackerConnectionState.OFFLINE
                && offlineMessage.equals(snapshot.getMessage()));
    }

    private static JsonObject transportCase(String transport) throws Exception
    {
        for (JsonElement element : RelayContractFixtureTest.fixture().getAsJsonArray("cases"))
        {
            JsonObject relayCase = element.getAsJsonObject();
            if (relayCase.has("transport")
                && relayCase.get("transport").getAsString().equals(transport))
            {
                return relayCase;
            }
        }
        throw new AssertionError("the relay fixture has no " + transport + " case");
    }

    private static void waitFor(BooleanSupplier condition) throws Exception
    {
        for (int attempt = 0; attempt < 300; attempt++)
        {
            if (condition.getAsBoolean()) return;
            Thread.sleep(10);
        }
        throw new AssertionError("condition was not reached");
    }
}

package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Where the rules think something is (G11): the tile's own chunk on the
 * surface, the template chunk inside an instance, the sea chunk under a
 * boat, and nothing at all when that can't be known.
 */
public class ChunkLocatorTest
{
    /** The main scene's south-west corner: tile 3136,3136 is chunk 49,49. */
    private static final int BASE = 3136;
    private static final int DECK_ID = 3;

    private final Client client = mock(Client.class);
    private final WorldView main = mock(WorldView.class);
    private final Scene scene = mock(Scene.class);
    private final ChunkLocator locator = new ChunkLocator(client);

    @Before
    public void surface()
    {
        when(client.getTopLevelWorldView()).thenReturn(main);
        when(client.getWorldView(WorldView.TOPLEVEL)).thenReturn(main);
        when(main.isTopLevel()).thenReturn(true);
        when(main.getId()).thenReturn(WorldView.TOPLEVEL);
        when(main.getScene()).thenReturn(scene);
        when(main.getPlane()).thenReturn(0);
        when(main.getSizeX()).thenReturn(104);
        when(main.getSizeY()).thenReturn(104);
        when(scene.getBaseX()).thenReturn(BASE);
        when(scene.getBaseY()).thenReturn(BASE);
    }

    @Test
    public void onTheSurfaceItIsTheTilesOwnChunk()
    {
        standAt(main, 40, 104 - 1);

        assertEquals(new CanonicalChunk((BASE + 40) >> 6, (BASE + 103) >> 6), locator.player());
    }

    @Test
    public void insideAnInstanceItIsTheChunkTheInstanceCameFrom()
    {
        // Zone 5,5 of this instance is a copy of the zone at tile 3200,3200 (Lumbridge, chunk 50,50).
        instance(5, 5, template(400, 400));
        standAt(main, 5 * 8 + 3, 5 * 8 + 6);

        assertEquals(new CanonicalChunk(50, 50), locator.player());
    }

    @Test
    public void anInstanceZoneWithNoTemplateIsUnknown()
    {
        instance(5, 5, template(400, 400));
        standAt(main, 6 * 8, 6 * 8);

        assertNull(locator.player());
    }

    @Test
    public void aZoneOutsideTheInstanceGridIsUnknown()
    {
        instance(5, 5, template(400, 400));
        standAt(main, 13 * 8 + 1, 40);

        assertNull(locator.player());
    }

    @Test
    public void onABoatItIsTheSeaChunkUnderTheShip()
    {
        WorldView deck = deck();
        WorldEntity ship = mock(WorldEntity.class);
        when(ship.getWorldView()).thenReturn(deck);
        when(ship.transformToMainWorld(any(LocalPoint.class)))
            .thenReturn(new LocalPoint(100 * 128 + 64, 10 * 128 + 64, WorldView.TOPLEVEL));
        ships(ship);
        standAt(deck, 2, 2);

        assertEquals(new CanonicalChunk((BASE + 100) >> 6, (BASE + 10) >> 6), locator.player());
    }

    @Test
    public void aDeckWithNoShipIsUnknown()
    {
        WorldView deck = deck();
        ships();
        standAt(deck, 2, 2);

        assertNull(locator.player());
    }

    @Test
    public void menuTargetsUseTheirNpcOrTheirTile()
    {
        NPC guard = mock(NPC.class);
        when(guard.getWorldView()).thenReturn(main);
        when(guard.getLocalLocation()).thenReturn(new LocalPoint(10 * 128 + 64, 20 * 128 + 64, WorldView.TOPLEVEL));
        MenuEntry talk = entry(MenuAction.NPC_FIRST_OPTION, 0, 0);
        when(talk.getNpc()).thenReturn(guard);
        assertEquals(new CanonicalChunk((BASE + 10) >> 6, (BASE + 20) >> 6), locator.menuTarget(talk));

        MenuEntry door = entry(MenuAction.GAME_OBJECT_FIRST_OPTION, 70, 30);
        assertEquals(new CanonicalChunk((BASE + 70) >> 6, (BASE + 30) >> 6), locator.menuTarget(door));
        MenuEntry item = entry(MenuAction.GROUND_ITEM_THIRD_OPTION, 1, 2);
        assertEquals(new CanonicalChunk(BASE >> 6, BASE >> 6), locator.menuTarget(item));
    }

    @Test
    public void optionsWithNoTileAreUnknown()
    {
        for (MenuAction action : new MenuAction[] {
            MenuAction.WALK, MenuAction.WORLD_ENTITY_FIRST_OPTION, MenuAction.CC_OP })
        {
            assertNull(action.name(), locator.menuTarget(entry(action, 10, 10)));
        }
        assertNull("off the scene", locator.menuTarget(entry(MenuAction.GAME_OBJECT_FIRST_OPTION, 104, 5)));
        assertNull("an unknown world view", locator.sceneTile(99, 5, 5));
        assertNull("nobody logged in", locator.player());
        assertNull(locator.menuTarget(null));
    }

    /** B14: overlays draw where the player stands and tint it as the rules judge it. */
    @Test
    public void inTheSceneThePlayerStandsInTheCopyButIsJudgedByTheOriginal()
    {
        instance(5, 5, template(400, 400));
        when(main.getBaseX()).thenReturn(6400);
        when(main.getBaseY()).thenReturn(6400);
        standAt(main, 5 * 8 + 3, 5 * 8 + 6);

        Located here = locator.playerInScene();

        assertEquals(new CanonicalChunk(50, 50), here.getRules());
        assertEquals(new CanonicalChunk((6400 + 43) >> 6, (6400 + 46) >> 6), here.getScene());
        assertEquals(0, here.getPlane());
        assertEquals("the player's tile in the scene", 43, here.getSceneX());
        assertEquals(46, here.getSceneY());
    }

    @Test
    public void onABoatTheSceneIsTheSeaUnderTheShip()
    {
        when(main.getBaseX()).thenReturn(BASE);
        when(main.getBaseY()).thenReturn(BASE);
        WorldView deck = deck();
        WorldEntity ship = mock(WorldEntity.class);
        when(ship.getWorldView()).thenReturn(deck);
        when(ship.transformToMainWorld(any(LocalPoint.class)))
            .thenReturn(new LocalPoint(100 * 128 + 64, 10 * 128 + 64, WorldView.TOPLEVEL));
        ships(ship);
        standAt(deck, 2, 2);

        Located here = locator.playerInScene();

        CanonicalChunk sea = new CanonicalChunk((BASE + 100) >> 6, (BASE + 10) >> 6);
        assertEquals(sea, here.getRules());
        assertEquals(sea, here.getScene());
        assertEquals("the sea tile under the ship", 100, here.getSceneX());
        assertEquals(10, here.getSceneY());
        ships();
        assertNull("a deck with no ship", locator.playerInScene());
        when(client.getLocalPlayer()).thenReturn(null);
        assertNull("nobody logged in", locator.playerInScene());
    }

    /** U3: the scene's borders are worked out zone by zone, each judged by what it is a copy of. */
    @Test
    public void eachSceneZoneIsJudgedByTheChunkItIsACopyOf()
    {
        when(main.getBaseX()).thenReturn(BASE);
        when(main.getBaseY()).thenReturn(BASE);
        assertEquals("on the surface, its own chunk",
            new CanonicalChunk((BASE + 8 * 8) >> 6, BASE >> 6), locator.sceneZone(8, 0));
        assertNull("past the scene", locator.sceneZone(13, 0));
        assertNull(locator.sceneZone(0, 13));
        assertNull(locator.sceneZone(-1, 0));

        instance(5, 5, template(400, 400));
        when(main.getBaseX()).thenReturn(6400);
        when(main.getBaseY()).thenReturn(6400);
        assertEquals("a copy of Lumbridge", new CanonicalChunk(50, 50), locator.sceneZone(5, 5));
        assertNull("a zone with no template", locator.sceneZone(5, 6));
    }

    /**
     * Where things stand in the real world, for the way back to one: the game's own world
     * location on the surface; nothing inside an instance, whose tiles are copies, or on a
     * boat's deck, and nothing for nobody.
     */
    @Test
    public void onlyTheRealWorldHasPlacesToFindAgain()
    {
        net.runelite.api.coords.WorldPoint oak = new net.runelite.api.coords.WorldPoint(3210, 3200, 0);
        net.runelite.api.GameObject tree = mock(net.runelite.api.GameObject.class);
        when(tree.getWorldView()).thenReturn(main);
        when(tree.getWorldLocation()).thenReturn(oak);
        NPC guard = mock(NPC.class);
        when(guard.getWorldView()).thenReturn(main);
        when(guard.getWorldLocation()).thenReturn(oak);
        standAt(main, 40, 40);
        net.runelite.api.coords.WorldPoint standing = new net.runelite.api.coords.WorldPoint(BASE + 40, BASE + 40, 0);
        when(client.getLocalPlayer().getWorldLocation()).thenReturn(standing);

        assertEquals(oak, locator.world(tree));
        assertEquals(oak, locator.world(guard));
        assertEquals(standing, locator.playerWorld());

        instance(5, 5, template(400, 400));
        assertNull(locator.world(tree));
        assertNull(locator.world(guard));
        assertNull(locator.playerWorld());

        when(scene.isInstance()).thenReturn(false);
        WorldView deck = deck();
        when(deck.getScene()).thenReturn(scene);
        when(tree.getWorldView()).thenReturn(deck);
        assertNull("on a boat", locator.world(tree));
        assertNull(locator.world((net.runelite.api.TileObject) null));
        when(client.getLocalPlayer()).thenReturn(null);
        assertNull(locator.playerWorld());
    }

    private void standAt(WorldView view, int sceneX, int sceneY)
    {
        // Read the view's id first: Mockito can't stub while another stub is half-made.
        int viewId = view.getId();
        Player player = mock(Player.class);
        when(player.getWorldView()).thenReturn(view);
        when(player.getLocalLocation()).thenReturn(new LocalPoint(sceneX * 128 + 64, sceneY * 128 + 64, viewId));
        when(client.getLocalPlayer()).thenReturn(player);
    }

    /** An instance whose only copied zone is (zoneX, zoneY), on plane 0. */
    private void instance(int zoneX, int zoneY, int template)
    {
        int[][][] templates = new int[4][13][13];
        for (int[][] plane : templates) for (int[] row : plane) Arrays.fill(row, -1);
        templates[0][zoneX][zoneY] = template;
        when(scene.isInstance()).thenReturn(true);
        when(scene.getInstanceTemplateChunks()).thenReturn(templates);
    }

    /** RuneLite's template encoding: the source zone in 8-tile units, plane 0, no rotation. */
    private static int template(int zoneX, int zoneY)
    {
        return (zoneX << 14) | (zoneY << 3);
    }

    private WorldView deck()
    {
        WorldView deck = mock(WorldView.class);
        when(deck.isTopLevel()).thenReturn(false);
        when(deck.getId()).thenReturn(DECK_ID);
        return deck;
    }

    @SuppressWarnings("unchecked")
    private void ships(WorldEntity... ships)
    {
        IndexedObjectSet<WorldEntity> entities = mock(IndexedObjectSet.class);
        when(entities.byIndex(DECK_ID)).thenReturn(ships.length > 0 ? ships[0] : null);
        when(entities.iterator()).thenAnswer(call -> ships.length > 0
            ? Arrays.asList(ships).iterator() : Collections.<WorldEntity>emptyIterator());
        org.mockito.Mockito.doReturn(entities).when(main).worldEntities();
    }

    private MenuEntry entry(MenuAction action, int sceneX, int sceneY)
    {
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getType()).thenReturn(action);
        when(entry.getParam0()).thenReturn(sceneX);
        when(entry.getParam1()).thenReturn(sceneY);
        when(entry.getWorldViewId()).thenReturn(WorldView.TOPLEVEL);
        return entry;
    }
}

package com.fatelocked;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
