    /** A Compact HUD's facts for a player standing in this chunk. */
    static HudPresenter.Facts.FactsBuilder facts(DecisionService decisions, CanonicalChunk chunk)
    {
        return HudPresenter.Facts.builder().mode(FateLockedConfig.HudMode.COMPACT).decisions(decisions).chunk(chunk);
    }

    /** Each line's value by its label; a line with no value maps to null. */
    static Map<String, String> lines(HudModel model)
    {
        Map<String, String> lines = new LinkedHashMap<>();
        for (HudModel.Line line : model.getLines())
        {
            lines.put(line.getLabel(), line.getValue());
        }
        return lines;
    }

    private static List<String> labels(HudModel model)
    {
        List<String> labels = new ArrayList<>();
        for (HudModel.Line line : model.getLines())
        {
            labels.add(line.getLabel());
        }
        return labels;
    }

    private static HudModel.Line line(HudModel model, String label)
    {
        for (HudModel.Line line : model.getLines())
        {
            if (line.getLabel().equals(label)) return line;
        }
        throw new AssertionError("no " + label + " line");
    }

    /** The Status line's words and tone, and the Why line's, for a chunk. */
    private static List<String> status(DecisionService decisions, CanonicalChunk chunk)
    {
        HudModel model = HudPresenter.present(facts(decisions, chunk).build());
        HudModel.Line status = line(model, "Status");
        Map<String, String> lines = lines(model);
        return Arrays.asList(status.getValue(), String.valueOf(status.getTone()), lines.get("Why"));
    }

    private static String word(String entry)
    {
        switch (entry)
        {
            case "ALLOWED": return "Unlocked";
            case "LOCKED": return "Locked";
            case "NOT_READY": return "Not ready";
            default: return "Uncharted";
        }
    }

    private static String tone(String entry)
    {
        switch (entry)
        {
            case "ALLOWED": return "GOOD";
            case "LOCKED": return "BAD";
            case "NOT_READY": return "PENDING";
            default: return "NEUTRAL";
        }
    }

    private static DecisionService playing(String id, String player) throws Exception
    {
        String json = GoldenBundleContractTest.gunzip(GoldenBundleContractTest.bytes(id + ".bundle.json.gz"));
        return DecisionService.create(
            RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, json)), "iron example", player);
    }

    private static String fixtureText(String name) throws Exception
    {
        try (InputStream in = HudPresenterTest.class.getClassLoader().getResourceAsStream(name))
        {
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    /** The rules as any character sees them: names aren't decisions. */
    private static DecisionService anyone(JsonObject root)
    {
        return DecisionService.create(RulesSnapshot.of(FateLockedBundle.loadFromJson(GSON, root.toString())), null, null);
    }

    /** A snapshot's string field; null when absent, null or not a string. */
    private static String string(JsonObject snapshot, String field)
    {
        JsonElement value = snapshot.get(field);
        return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString() ? value.getAsString() : null;
    }
}

package com.fatelocked;

import com.fatelocked.panel.LocalTimeText;

import java.time.Instant;
import java.time.ZoneId;

/**
 * What the sidebar shows for the tracker connection: a short status in a
 * tone, one line saying why and what to do about it, and times on the
 * player's own clock. Pure: made from a snapshot, the time now and the
 * player's time zone.
 */
final class SyncView
{
    enum Tone
    {
        GREEN,
        AMBER,
        RED,
        GRAY
    }

    /** The one thing the player can do about the state. */
    enum Action
    {
        /** Nothing: it sorts itself out. */
        NONE,
        /** Press Check now. */
        CHECK_NOW,
        /** Press Connect tracker. */
        CONNECT,
        /** Tick "Enable online sync"; the pairing is kept. */
        ENABLE_SYNC,
        /** Open the web tracker, which sends the rules again. */
        OPEN_TRACKER,
        /** Update Fate Locked in the Plugin Hub. */
        UPDATE_PLUGIN
    }

    final String status;
    final Tone tone;
    /** Why, and what to do; null when the status says it all. */
    final String detail;
    final Action action;
    /** When the relay last delivered or confirmed the rules, or a dash. */
    final String lastSync;
    /** Whether Check now has anything to check: a pairing, with online sync on. */
    final boolean canCheckNow;
    /** What the connect button says and does. */
    final Connect connect;
    /** The code in use, as its last four characters, or a dash. */
    final String pairing;

    /** The connect button's job in each state. */
    enum Connect
    {
        /** No working pairing: pair, asking for consent first if need be. */
        CONNECT("Connect tracker"),
        /** Paired with online sync off: turn it on and use that pairing. */
        TURN_ON_SYNC("Turn on online sync"),
        /** A working pairing: ask, then pair again, keeping it until the new one delivers. */
        REPAIR("Re-pair tracker\u2026"),
        /** A re-pairing is waiting: go back to the working pairing. */
        CANCEL_REPAIR("Cancel re-pairing");

        final String label;

        Connect(String label)
        {
            this.label = label;
        }
    }

    private SyncView(String status, Tone tone, String detail, Action action,
        String lastSync, boolean canCheckNow, Connect connect, String pairing)
    {
        this.pairing = pairing;
        this.status = status;
        this.tone = tone;
        this.detail = detail;
        this.action = action;
        this.lastSync = lastSync;
        this.canCheckNow = canCheckNow;
        this.connect = connect;
    }

    static SyncView of(TrackerConnectionSnapshot snapshot, Instant now, ZoneId zone)
    {
        String lastSync = snapshot.getLastSync() == null
            ? "\u2014" : LocalTimeText.of(snapshot.getLastSync(), now, zone);
        String nextCheck = snapshot.getNextCheck() == null
            ? "" : " Next check at " + LocalTimeText.of(snapshot.getNextCheck(), now, zone) + ".";
        Tone tone = tone(snapshot.getState());
        TrackerConnectionState state = snapshot.getState();
        Action action = state == TrackerConnectionState.CONNECTED
            || state == TrackerConnectionState.OFFLINE
            ? Action.CHECK_NOW : Action.NONE;
        String detail;
        switch (snapshot.getReason())
        {
            case NOT_PAIRED:
                detail = "Press Connect tracker to get your rules from the web tracker.";
                action = Action.CONNECT;
                break;
            case SYNC_OFF:
                detail = "Your pairing is kept. Press Turn on online sync to pick it"
                    + " up again.";
                action = Action.ENABLE_SYNC;
                break;
            case CONFIRM_REPAIR:
                detail = "Confirm the profile in the browser tab RuneLite opened."
                    + " Until it arrives, RuneLite keeps your current pairing.";
                break;
            case GONE:
                detail = "The tracker's owner pressed Disconnect in the web tracker,"
                    + " so it sends no more rules to this pairing. Press Connect"
                    + " tracker to pair again.";
                action = Action.CONNECT;
                break;
            case REPAIR_ABANDONED:
                detail = "No new profile arrived within 10 minutes, so RuneLite kept"
                    + " your current pairing.";
                break;
            case CONFIRM_IN_BROWSER:
                detail = "Confirm the profile in the browser tab RuneLite opened."
                    + " RuneLite checks every few seconds.";
                break;
            case NO_PROFILE:
                detail = "No profile arrived within 10 minutes."
                    + " Press Connect tracker to try again.";
                action = Action.CONNECT;
                break;
            case NO_RECENT_UPDATE:
                detail = "The tracker hasn't sent your rules in the last 24 hours."
                    + " Open the web tracker to send them again.";
                action = Action.OPEN_TRACKER;
                break;
            case OLDER_RULES:
                detail = "The relay sent older rules than yours, so yours stay in use."
                    + " Open the web tracker to send yours again." + nextCheck;
                action = Action.OPEN_TRACKER;
                break;
            case UNREACHABLE:
                detail = "RuneLite couldn't reach the tracker." + nextCheck;
                break;
            case UNREADABLE:
                detail = "Something other than the tracker answered, such as a Wi-Fi"
                    + " sign-in page." + nextCheck;
                break;
            case BUSY:
                detail = "The tracker asked RuneLite to check less often." + nextCheck;
                break;
            case UNAVAILABLE:
                detail = "The tracker had a problem." + nextCheck;
                break;
            case FUTURE_FORMAT:
                detail = "Your tracker sent rules in a newer format than this version"
                    + " of Fate Locked reads. Update it in the Plugin Hub.";
                action = Action.UPDATE_PLUGIN;
                break;
            case INVALID_RULES:
                detail = "The tracker sent rules RuneLite couldn't use."
                    + " Open the web tracker to send them again.";
                action = Action.OPEN_TRACKER;
                break;
            default:
                if (state == TrackerConnectionState.IMPORT_FAILED)
                {
                    detail = "RuneLite couldn't apply the tracker's rules." + nextCheck;
                    action = Action.CHECK_NOW;
                }
                else
                {
                    detail = null;
                }
                break;
        }
        boolean canCheckNow = snapshot.getReason() != SyncReason.NOT_PAIRED
            && snapshot.getReason() != SyncReason.SYNC_OFF
            && snapshot.getReason() != SyncReason.GONE;
        String pairing = snapshot.getPairingEnding() == null
            ? "\u2014" : "\u2026" + snapshot.getPairingEnding();
        return new SyncView(snapshot.getMessage(), tone, detail, action, lastSync, canCheckNow,
            connect(snapshot.getReason()), pairing);
    }

    private static Connect connect(SyncReason reason)
    {
        switch (reason)
        {
            case NOT_PAIRED:
            case CONFIRM_IN_BROWSER:
            case NO_PROFILE:
            case GONE:
                // Nothing that works to keep: pair from scratch.
                return Connect.CONNECT;
            case SYNC_OFF:
                return Connect.TURN_ON_SYNC;
            case CONFIRM_REPAIR:
                return Connect.CANCEL_REPAIR;
            default:
                return Connect.REPAIR;
        }
    }

    private static Tone tone(TrackerConnectionState state)
    {
        switch (state)
        {
            case CONNECTED:
                return Tone.GREEN;
            case WAITING:
            case IMPORTING:
                return Tone.AMBER;
            case EXPIRED:
            case IMPORT_FAILED:
                return Tone.RED;
            default:
                return Tone.GRAY;
        }
    }
}

package com.fatelocked;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import lombok.Value;

/**
 * The loaded scene as the rules draw it (U3): where its chunk lines run, which of them are
 * locked, and where its locked land lies. It is worked out once per scene from the scene's
 * 8-tile zones, so an instance, which is copied zone by zone from anywhere, breaks where its
 * zones do. On the surface the zone lines that matter are the chunk lines.
 *
 * <p>A line between a locked place and an unlocked one is a locked edge. A line between two
 * different chunks that are alike is a plain edge. A place the rules don't decide draws no
 * edge, and neither does the scene's own border.
 */
final class SceneEdges
{
    /** Instances are copied in 8-tile zones. */
    static final int ZONE = 8;
    /** A scene with nothing to draw. */
    static final SceneEdges NONE = new SceneEdges(Collections.emptyList(), Collections.emptyList());

    enum Kind { LOCKED, PLAIN }

    /** A zone: how the rules tint it, and the rules chunk it is a copy of (null when unknown). */
    @Value
    static class Zone
    {
        TintPolicy.Tint tint;
        CanonicalChunk rules;
    }

    /**
     * A straight run of edge along one line of scene tiles. A vertical run lies on
     * {@code x = line} from {@code y = from} to {@code y = to}; a horizontal one on
     * {@code y = line}. The locked side is +1 when it has the larger coordinate, -1 when the
     * smaller, and 0 for a plain edge.
     */
    @Value
    static class Run
    {
        boolean vertical;
        int line;
        int from;
        int to;
        Kind kind;
        int lockedSide;
    }

    /** Locked land in one row of zones, in scene tiles: from x0, y0 up to x1, y1. */
    @Value
    static class Block
    {
        int x0;
        int y0;
        int x1;
        int y1;
    }

    private final List<Run> edges;
    private final List<Block> locked;

    private SceneEdges(List<Run> edges, List<Block> locked)
    {
        this.edges = edges;
        this.locked = locked;
    }

    /** The scene's edges, joined where they carry on. */
    List<Run> edges()
    {
        return edges;
    }

    /** The scene's locked land, one block per run of locked zones in a row. */
    List<Block> locked()
    {
        return locked;
    }

    /** The scene these zones make, indexed [zone x][zone y]. */
    static SceneEdges of(Zone[][] zones)
    {
        int width = zones.length;
        int height = width == 0 ? 0 : zones[0].length;
        List<Run> runs = new ArrayList<>();
        for (int zx = 1; zx < width; zx++)
        {
            line(runs, true, zx * ZONE, zones[zx - 1], zones[zx]);
        }
        List<Block> locked = new ArrayList<>();
        Zone[] below = null;
        for (int zy = 0; zy < height; zy++)
        {
            Zone[] row = new Zone[width];
            for (int zx = 0; zx < width; zx++)
            {
                row[zx] = zones[zx][zy];
            }
            if (below != null)
            {
                line(runs, false, zy * ZONE, below, row);
            }
            lockedRow(locked, zy, row);
            below = row;
        }
        return new SceneEdges(Collections.unmodifiableList(runs), Collections.unmodifiableList(locked));
    }

    /** The runs along one line, between the zones before it and the zones after it. */
    private static void line(List<Run> runs, boolean vertical, int line, Zone[] before, Zone[] after)
    {
        Kind open = null;
        int openSide = 0;
        int start = 0;
        for (int i = 0; i <= before.length; i++)
        {
            Kind kind = i < before.length ? kind(before[i], after[i]) : null;
            int side = kind == Kind.LOCKED && after[i].getTint() == TintPolicy.Tint.LOCKED ? 1
                : kind == Kind.LOCKED ? -1 : 0;
            if (open != null && (kind != open || side != openSide))
            {
                runs.add(new Run(vertical, line, start, i * ZONE, open, openSide));
                open = null;
            }
            if (kind != null && open == null)
            {
                open = kind;
                openSide = side;
                start = i * ZONE;
            }
        }
    }

    /** The locked zones of one row, joined where they touch. */
    private static void lockedRow(List<Block> locked, int zy, Zone[] row)
    {
        int start = -1;
        for (int zx = 0; zx <= row.length; zx++)
        {
            boolean isLocked = zx < row.length && row[zx] != null && row[zx].getTint() == TintPolicy.Tint.LOCKED;
            if (isLocked && start < 0)
            {
                start = zx;
            }
            else if (!isLocked && start >= 0)
            {
                locked.add(new Block(start * ZONE, zy * ZONE, zx * ZONE, (zy + 1) * ZONE));
                start = -1;
            }
        }
    }

    /** The edge between two neighbouring zones, or null for none. */
    private static Kind kind(Zone a, Zone b)
    {
        if (a == null || b == null
            || a.getTint() == TintPolicy.Tint.UNKNOWN || b.getTint() == TintPolicy.Tint.UNKNOWN)
        {
            return null;
        }
        if (a.getTint() != b.getTint())
        {
            return Kind.LOCKED;
        }
        return Objects.equals(a.getRules(), b.getRules()) ? null : Kind.PLAIN;
    }
}

package com.fatelocked;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.UUID;

final class PairingSupport
{
    private static final String TRACKER_URL =
        "https://nubles.github.io/OSRS-Fate-Locked/";

    private PairingSupport()
    {
    }

    static String newCode()
    {
        return UUID.randomUUID().toString().replace("-", "");
    }

    static String trackerPairingUrl(String code)
    {
        return TRACKER_URL + "#runelite-pair=" + code;
    }

    /**
     * Names a pairing in local files without writing the code: the first 16
     * hex digits of its SHA-256. Null when there is no pairing.
     */
    static String tag(String code)
    {
        if (code == null || code.trim().isEmpty())
        {
            return null;
        }
        try
        {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(code.trim().getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (int i = 0; i < 8; i++)
            {
                hex.append(String.format("%02x", digest[i]));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException ex)
        {
            // Every Java runtime provides SHA-256.
            throw new IllegalStateException(ex);
        }
    }
}

package com.fatelocked;

/**
 * The fade when a locked area is entered (U20): one fade out, never a pulse. It starts at its
 * strongest and only weakens, easing out, so it can't flicker. The old frame pulsed at about
 * 2.5 Hz for 1.6 seconds; RuneLite's own flash toggles at 1.25 Hz.
 */
final class FlashFade
{
    /** How long the fade lasts. */
    static final long DURATION_MS = 1_100;
    /** Its alpha at the start, the strongest it gets. */
    static final int MAX_ALPHA = 200;

    private FlashFade()
    {
    }

    /** The fade's alpha this long after it started: the strongest at the start, and none from the end on. */
    static int alpha(long elapsedMs)
    {
        if (elapsedMs < 0 || elapsedMs >= DURATION_MS)
        {
            return 0;
        }
        double left = 1 - (double) elapsedMs / DURATION_MS;
        return (int) Math.round(MAX_ALPHA * left * left);
    }
}

package com.fatelocked;

import lombok.extern.slf4j.Slf4j;

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.concurrent.Executor;

/**
 * Runs local file writes one at a time and in the order they were asked
 * for, off the game and Swing threads, on RuneLite's shared executor. A
 * write queued before the plugin stops still finishes, so nothing already
 * recorded is lost; anything a write reports back to plugin state goes
 * through the client-thread gate.
 */
@Slf4j
final class SerialFileWriter
{
    private final Executor executor;
    private final Queue<Runnable> queue = new ArrayDeque<>();
    private boolean draining;

    SerialFileWriter(Executor executor)
    {
        this.executor = executor;
    }

    void submit(Runnable write)
    {
        synchronized (queue)
        {
            queue.add(write);
            if (draining)
            {
                return;
            }
            draining = true;
        }
        try
        {
            executor.execute(this::drain);
        }
        catch (RuntimeException ex)
        {
            // The executor refused (the client is closing): let the next
            // write try again rather than wait for a drain that never runs.
            synchronized (queue)
            {
                draining = false;
            }
            log.warn("Could not queue a local file write: {}", ex.getMessage());
        }
    }

    private void drain()
    {
        while (true)
        {
            Runnable write;
            synchronized (queue)
            {
                write = queue.poll();
                if (write == null)
                {
                    draining = false;
                    return;
                }
            }
            try
            {
                write.run();
            }
            catch (RuntimeException ex)
            {
                log.warn("A local file write failed", ex);
            }
        }
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.Trust;
import com.fatelocked.ui.Palette;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.GeneralPath;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * The run on the world map (U18, decision 4): locked land shaded dark like fog of war, the
 * frontier of a Chunked run lightly filled, unlocked land left clear, and the unlocked land
 * outlined with the locked edge's dash. Land only, as the web map shows it; nothing on another
 * character. It draws inside the map only, never over the overview or the surface selector.
 *
 * <p>What to draw is worked out once per decision service ({@link WorldMapModel}), and placed with
 * RuneLite's own maths ({@link WorldMapProjection}), so it lines up with the pins. The placing, the
 * clip and the outline are worked out again only when the map moves, the overview or the surface
 * selector opens or closes, or the rules change (A9): a frame of a map at rest makes no garbage.
 */
public class FateLockedWorldMapOverlay extends Overlay
{
    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;
    private final TooltipManager tooltipManager;

    // What the map draws for the rules in force.
    private DecisionService modelDecisions;
    private WorldMapModel model = WorldMapModel.NONE;
    // Where the map was, and how tiles fell on it.
    private Rectangle viewBounds;
    private float viewZoom;
    private int viewX;
    private int viewY;
    private WorldMapProjection projection;
    // The clip, for the map and whichever of the overview and the selector were shown.
    private Rectangle clipBounds;
    private Rectangle clipOverview;
    private Rectangle clipSelector;
    private Shape clip;
    // The outline in canvas pixels, for these rules in this view.
    private WorldMapModel outlineModel;
    private WorldMapProjection outlineProjection;
    private Shape outline;
    // The last tooltip, kept while the mouse stays on one chunk.
    private DecisionService tipDecisions;
    private CanonicalChunk tipChunk;
    private boolean tipContents;
    private Palette tipPalette;
    private String tip;

    @Inject
    FateLockedWorldMapOverlay(Client client, FateLockedPlugin plugin, FateLockedConfig config,
        TooltipManager tooltipManager)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.tooltipManager = tooltipManager;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(Overlay.PRIORITY_LOW);
        setLayer(OverlayLayer.MANUAL);
        drawAfterInterface(InterfaceID.WORLDMAP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        FateLockedConfig.WorldMapMode mode = config.worldMapMode();
        if (!mode.shading()) return null;
        DecisionService decisions = plugin.decisions();
        // No rules, or another character's: the map draws nothing.
        if (decisions.trust() != Trust.TRUSTED) return null;
        Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
        WorldMap worldMap = client.getWorldMap();
        if (map == null || worldMap == null) return null;
        Rectangle bounds = map.getBounds();
        Point centre = worldMap.getWorldMapPosition();
        float zoom = worldMap.getWorldMapZoom();
        if (bounds == null || centre == null || zoom <= 0) return null;

        WorldMapModel current = model(decisions);
        WorldMapProjection view = projection(bounds, zoom, centre.getX(), centre.getY());
        Shape mapClip = clip(bounds, shown(InterfaceID.Worldmap.OVERVIEW_CONTAINER),
            shown(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0));
        draw(graphics, current, view, plugin.palette(), mapClip, outline(current, view));
        if (mode.tooltip())
        {
            tooltip(decisions, view, mapClip, mode.contents());
        }
        return null;
    }

    /**
     * Draw the model where the projection places it, inside the clip: one fill per run of
     * chunks in view, then the outline. Called every frame, so it makes no garbage.
     */
    static void draw(Graphics2D graphics, WorldMapModel model, WorldMapProjection projection, Palette palette,
        Shape clip, Shape outline)
    {
        int west = projection.westChunk();
        int east = projection.eastChunk();
        int south = projection.southChunk();
        int north = projection.northChunk();
        Shape before = graphics.getClip();
        graphics.clip(clip);
        List<WorldMapModel.Run> runs = model.runs();
        for (int i = 0; i < runs.size(); i++)
        {
            WorldMapModel.Run run = runs.get(i);
            if (run.getCy() < south || run.getCy() > north || run.getCx1() < west || run.getCx0() > east)
            {
                continue;
            }
            graphics.setColor(run.getFill() == WorldMapChunks.Fill.FRONTIER
                ? palette.frontierFill() : palette.lockedShade());
            int x0 = projection.lineX(Math.max(run.getCx0(), west) << 6);
            int x1 = projection.lineX((Math.min(run.getCx1(), east) + 1) << 6);
            int y0 = projection.lineY((run.getCy() + 1) << 6);
            int y1 = projection.lineY(run.getCy() << 6);
            graphics.fillRect(x0, y0, x1 - x0, y1 - y0);
        }
        graphics.setStroke(Palette.UNDERLAY_STROKE);
        graphics.setColor(Palette.UNDERLAY);
        graphics.draw(outline);
        graphics.setStroke(Palette.LOCKED_EDGE_STROKE);
        graphics.setColor(palette.lockedEdge());
        graphics.draw(outline);
        graphics.setClip(before);
    }

    /** The unlocked land's outline in canvas pixels, kept to the chunks in view, as one path. */
    static Shape outlinePath(WorldMapModel model, WorldMapProjection projection)
    {
        int west = projection.westChunk();
        int east = projection.eastChunk();
        int south = projection.southChunk();
        int north = projection.northChunk();
        GeneralPath outline = new GeneralPath();
        for (WorldMapModel.Edge edge : model.outline())
        {
            // Kept to the chunks in view, so a long dashed line isn't worked out off the map.
            int low = edge.isVertical() ? south : west;
            int high = (edge.isVertical() ? north : east) + 1;
            int across = edge.isVertical() ? east + 1 : north + 1;
            int acrossLow = edge.isVertical() ? west : south;
            int from = Math.max(edge.getFrom(), low);
            int to = Math.min(edge.getTo(), high);
            if (edge.getLine() < acrossLow || edge.getLine() > across || from >= to)
            {
                continue;
            }
            if (edge.isVertical())
            {
                int x = projection.lineX(edge.getLine() << 6);
                outline.moveTo(x, projection.lineY(from << 6));
                outline.lineTo(x, projection.lineY(to << 6));
            }
            else
            {
                int y = projection.lineY(edge.getLine() << 6);
                outline.moveTo(projection.lineX(from << 6), y);
                outline.lineTo(projection.lineX(to << 6), y);
            }
        }
        return outline;
    }

    /** How tiles fall on the map as shown; worked out again only when it moves or zooms. */
    private WorldMapProjection projection(Rectangle bounds, float zoom, int x, int y)
    {
        if (!bounds.equals(viewBounds) || zoom != viewZoom || x != viewX || y != viewY)
        {
            projection = new WorldMapProjection(bounds, zoom, x, y);
            viewBounds = bounds;
            viewZoom = zoom;
            viewX = x;
            viewY = y;
        }
        return projection;
    }

    /**
     * Where to draw: worked out again only when the map's bounds change, or the overview or the
     * selector opens or closes.
     */
    private Shape clip(Rectangle bounds, Rectangle overview, Rectangle selector)
    {
        if (!bounds.equals(clipBounds) || !Objects.equals(overview, clipOverview)
            || !Objects.equals(selector, clipSelector))
        {
            clip = WorldMapClip.of(bounds, overview, selector);
            clipBounds = bounds;
            clipOverview = overview;
            clipSelector = selector;
        }
        return clip;
    }

    /** The outline for these rules in this view; worked out again only when either changes. */
    private Shape outline(WorldMapModel current, WorldMapProjection view)
    {
        if (current != outlineModel || view != outlineProjection)
        {
            outline = outlinePath(current, view);
            outlineModel = current;
            outlineProjection = view;
        }
        return outline;
    }

    /** What the map draws for these rules, worked out again only when they change. */
    private WorldMapModel model(DecisionService decisions)
    {
        if (decisions != modelDecisions)
        {
            modelDecisions = decisions;
            model = WorldMapModel.of(decisions);
        }
        return model;
    }

    /** A widget's bounds while it is shown, else null. */
    private Rectangle shown(int id)
    {
        Widget widget = client.getWidget(id);
        return widget == null || widget.isHidden() ? null : widget.getBounds();
    }

    /** The area, status and contents of the chunk under the mouse, built again only when it changes. */
    private void tooltip(DecisionService decisions, WorldMapProjection projection, Shape clip, boolean contents)
    {
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null || !clip.contains(mouse.getX(), mouse.getY())) return;
        CanonicalChunk hovered = new CanonicalChunk(projection.tileX(mouse.getX()) >> 6,
            projection.tileY(mouse.getY()) >> 6);
        Palette palette = plugin.palette();
        if (decisions != tipDecisions || !hovered.equals(tipChunk) || contents != tipContents
            || palette != tipPalette)
        {
            tipDecisions = decisions;
            tipChunk = hovered;
            tipContents = contents;
            tipPalette = palette;
            // Capped per category, so a dense chunk stays a tooltip, not a page.
            List<String> content = contents ? plugin.getBundle().contentAt(hovered, 4) : Collections.emptyList();
            tip = WorldMapChunks.tooltip(decisions, hovered, content, palette);
        }
        if (tip != null)
        {
            tooltipManager.add(new Tooltip(tip));
        }
    }
}

package com.fatelocked;

import java.awt.Color;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Carries each player's settings from before Stage 3 over to the merged ones (D2, U11).
 *
 * <p>RuneLite writes every declared setting's default before the plugin starts, and did
 * for the old ones, so a stored value can't tell a choice from a default. The rule: a new
 * setting whose old keys are all still at their old defaults keeps its own default;
 * otherwise the old choice maps across. The old keys are left stored for one release, so
 * an older build on the same profile still reads them. {@code settingsVersion}, written
 * last, marks a profile done; a profile switch runs it again for that profile.
 */
final class SettingsMigration
{
    static final String VERSION_KEY = "settingsVersion";
    static final int VERSION = 2;

    /** Raw access to the plugin's stored settings. */
    interface ConfigStore
    {
        /** The stored value, or null when unset. */
        String get(String key);

        void set(String key, String value);
    }

    /** The settings Stage 3 retired, with the defaults they had. */
    static final Map<String, String> OLD_DEFAULTS;

    static
    {
        Map<String, String> old = new LinkedHashMap<>();
        old.put("chatOnEnter", "true");
        old.put("warnOnLocked", "true");
        old.put("flashOnLocked", "true");
        old.put("warnLockedBank", "true");
        old.put("warnLockedSlayer", "true");
        old.put("warnOverTierGear", "true");
        old.put("warnAccountMismatch", "true");
        old.put("tagLockedMenus", "true");
        old.put("tagLockedTeleports", "true");
        old.put("showHud", "true");
        old.put("showNearest", "true");
        old.put("showChunkContentBox", "false");
        old.put("drawWorldMap", "true");
        old.put("worldMapTooltip", "true");
        old.put("worldMapTooltipContent", "true");
        old.put("drawScene", "true");
        old.put("highlightLockedBorders", "true");
        // Grey (107, 114, 128) at alpha 60, as RuneLite stored it: ARGB in one number.
        old.put("unauthoredColor", String.valueOf(0x3C6B7280));
        OLD_DEFAULTS = Collections.unmodifiableMap(old);
    }

    /** The colours Stage 3 kept, with the defaults they have; a changed one means Custom. */
    private static final Map<String, Color> COLOUR_DEFAULTS;

    static
    {
        FateLockedConfig defaults = new FateLockedConfig() { };
        Map<String, Color> colours = new LinkedHashMap<>();
        colours.put("unlockedColor", defaults.unlockedColor());
        colours.put("frontierColor", defaults.frontierColor());
        colours.put("lockedColor", defaults.lockedColor());
        COLOUR_DEFAULTS = Collections.unmodifiableMap(colours);
    }

    private SettingsMigration()
    {
    }

    static void migrate(ConfigStore store)
    {
        if (version(store.get(VERSION_KEY)) >= VERSION)
        {
            return;
        }

        // A new player has no old settings stored, so nothing below maps across.
        boolean chat = old(store, "chatOnEnter");
        if (changed(store, "chatOnEnter", "warnOnLocked", "flashOnLocked"))
        {
            store.set("lockedAreaAlert",
                alert(chat, old(store, "warnOnLocked"), old(store, "flashOnLocked")).name());
        }
        if (changed(store, "chatOnEnter"))
        {
            store.set("announceAreaChanges", String.valueOf(chat));
        }
        if (changed(store, "warnLockedBank", "warnLockedSlayer", "warnOverTierGear"))
        {
            store.set("ruleWarnings", String.valueOf(old(store, "warnLockedBank")
                || old(store, "warnLockedSlayer") || old(store, "warnOverTierGear")));
        }
        if (changed(store, "tagLockedMenus", "tagLockedTeleports"))
        {
            store.set("tagLockedOptions",
                String.valueOf(old(store, "tagLockedMenus") || old(store, "tagLockedTeleports")));
        }
        if (changed(store, "showHud", "showNearest", "showChunkContentBox"))
        {
            store.set("hudMode", (old(store, "showChunkContentBox") ? FateLockedConfig.HudMode.DETAILED
                : old(store, "showHud") ? FateLockedConfig.HudMode.COMPACT : FateLockedConfig.HudMode.OFF).name());
        }
        if (changed(store, "drawWorldMap", "worldMapTooltip", "worldMapTooltipContent"))
        {
            store.set("worldMapMode", worldMap(old(store, "drawWorldMap"), old(store, "worldMapTooltip"),
                old(store, "worldMapTooltipContent")).name());
        }
        if (changed(store, "drawScene", "highlightLockedBorders"))
        {
            store.set("chunkBorders", (old(store, "highlightLockedBorders") ? FateLockedConfig.ChunkBorders.LOCKED_EDGES
                : old(store, "drawScene") ? FateLockedConfig.ChunkBorders.ALL_EDGES
                : FateLockedConfig.ChunkBorders.OFF).name());
        }
        boolean custom = false;
        for (Map.Entry<String, Color> colour : COLOUR_DEFAULTS.entrySet())
        {
            String stored = store.get(colour.getKey());
            if (stored == null || stored.equals(rgb(colour.getValue())))
            {
                continue;
            }
            custom = true;
            // The old pickers saved a picked colour fully solid: the sidebar's swatches did,
            // and RuneLite's picker hides transparency without @Alpha. A solid tint hides the
            // map under it, so the colour gets its default's transparency back.
            Integer picked = argb(stored);
            if (picked != null && picked >>> 24 == 0xFF)
            {
                store.set(colour.getKey(), String.valueOf(colour.getValue().getAlpha() << 24 | picked & 0xFFFFFF));
            }
        }
        if (custom)
        {
            store.set("colourPreset", FateLockedConfig.ColourPreset.CUSTOM.name());
        }
        store.set(VERSION_KEY, String.valueOf(VERSION));
    }

    static FateLockedConfig.LockedAreaAlert alert(boolean chat, boolean sound, boolean fade)
    {
        if (sound && fade)
        {
            return FateLockedConfig.LockedAreaAlert.CHAT_SOUND_FADE;
        }
        if (sound)
        {
            return FateLockedConfig.LockedAreaAlert.CHAT_SOUND;
        }
        if (fade)
        {
            return FateLockedConfig.LockedAreaAlert.CHAT_FADE;
        }
        return chat ? FateLockedConfig.LockedAreaAlert.CHAT : FateLockedConfig.LockedAreaAlert.OFF;
    }

    private static FateLockedConfig.WorldMapMode worldMap(boolean shading, boolean tooltip, boolean contents)
    {
        if (!shading)
        {
            return FateLockedConfig.WorldMapMode.OFF;
        }
        if (!tooltip)
        {
            return FateLockedConfig.WorldMapMode.SHADING;
        }
        return contents ? FateLockedConfig.WorldMapMode.SHADING_TOOLTIP_CONTENTS
            : FateLockedConfig.WorldMapMode.SHADING_TOOLTIP;
    }

    /** Whether the player changed any of these old settings from its default. */
    private static boolean changed(ConfigStore store, String... keys)
    {
        List<String> names = Arrays.asList(keys);
        return names.stream().anyMatch(key -> store.get(key) != null && !OLD_DEFAULTS.get(key).equals(store.get(key)));
    }

    /** An old switch's value, or its default when it was never stored. */
    private static boolean old(ConfigStore store, String key)
    {
        String stored = store.get(key);
        return Boolean.parseBoolean(stored == null ? OLD_DEFAULTS.get(key) : stored);
    }

    private static int version(String stored)
    {
        try
        {
            return stored == null ? 0 : Integer.parseInt(stored);
        }
        catch (NumberFormatException e)
        {
            return 0;
        }
    }

    /** How RuneLite stores a colour. */
    static String rgb(Color colour)
    {
        return String.valueOf(colour.getRGB());
    }

    /** A stored colour as RuneLite reads it, alpha in the top byte; null when it can't be read. */
    private static Integer argb(String stored)
    {
        try
        {
            return Integer.decode(stored);
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import net.runelite.api.WorldView;

/**
 * The loaded scene as the rules draw it, worked out again only when a scene loads, or the
 * plane, the base or the rules change (A9). The game view and the minimap draw from one.
 * Client thread.
 */
final class SceneEdgesCache
{
    private DecisionService decisions;
    private int generation = -1;
    private int plane = -1;
    private int baseX;
    private int baseY;
    private SceneEdges scene = SceneEdges.NONE;

    /** The scene for these rules, on this plane of this load of the scene. */
    SceneEdges get(DecisionService rules, WorldView view, int onPlane, int load, ChunkLocator locator)
    {
        if (rules != decisions || load != generation || onPlane != plane
            || view.getBaseX() != baseX || view.getBaseY() != baseY)
        {
            decisions = rules;
            generation = load;
            plane = onPlane;
            baseX = view.getBaseX();
            baseY = view.getBaseY();
            scene = SceneEdges.of(zones(rules, locator, view.getSizeX() / SceneEdges.ZONE,
                view.getSizeY() / SceneEdges.ZONE));
        }
        return scene;
    }

    /** Each zone of the scene, as the rules tint the chunk it is a copy of. */
    private static SceneEdges.Zone[][] zones(DecisionService rules, ChunkLocator locator, int width, int height)
    {
        SceneEdges.Zone[][] zones = new SceneEdges.Zone[width][height];
        for (int zx = 0; zx < width; zx++)
        {
            for (int zy = 0; zy < height; zy++)
            {
                CanonicalChunk chunk = locator.sceneZone(zx, zy);
                zones[zx][zy] = new SceneEdges.Zone(
                    chunk == null ? TintPolicy.Tint.UNKNOWN : TintPolicy.at(rules, chunk), chunk);
            }
        }
        return zones;
    }
}

