package com.fatelocked;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.util.Text;

import java.util.regex.Pattern;

/**
 * Reads a menu entry into {@link MenuFacts} (A9), on the client thread: it
 * reads the spellbook varbit and, for a worn item, the clicked widget.
 */
final class MenuFactsReader
{
    private static final Pattern WHITESPACE =
        Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
    /** A worn slot draws its item in its second child. */
    private static final int WORN_ITEM_CHILD = 1;

    private final Client client;

    MenuFactsReader(Client client)
    {
        this.client = client;
    }

    MenuFacts read(MenuEntry entry)
    {
        if (entry == null) return MenuFacts.EMPTY;
        MenuFacts.MenuFactsBuilder facts = MenuFacts.builder()
            .option(text(entry.getOption()))
            .target(text(entry.getTarget()))
            .worldViewId(entry.getWorldViewId());
        MenuAction type = entry.getType();
        if (type == null) return facts.build();
        switch (type)
        {
            case CC_OP:
            case CC_OP_LOW_PRIORITY:
            {
                int group = WidgetUtil.componentToInterface(entry.getParam1());
                facts.kind(MenuFacts.Kind.WIDGET).interfaceGroup(group).itemId(itemId(entry, group));
                if (group == InterfaceID.MAGIC_SPELLBOOK)
                {
                    facts.spellbook(client.getVarbitValue(VarbitID.SPELLBOOK));
                }
                break;
            }
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
                facts.kind(MenuFacts.Kind.OBJECT).objectId(entry.getIdentifier());
                break;
            case NPC_FIRST_OPTION:
            case NPC_SECOND_OPTION:
            case NPC_THIRD_OPTION:
            case NPC_FOURTH_OPTION:
            case NPC_FIFTH_OPTION:
            {
                NPC npc = entry.getNpc();
                facts.kind(MenuFacts.Kind.NPC).npcId(npc == null ? MenuFacts.NONE : npc.getId());
                break;
            }
            default:
                break;
        }
        return facts.build();
    }

    /**
     * The item behind an item option. A worn slot may not say, so its item
     * is read from the slot's widget, as RuneLite's own menu swapper does.
     */
    private static int itemId(MenuEntry entry, int group)
    {
        int id = entry.getItemId();
        if (id > MenuFacts.NONE || group != InterfaceID.WORNITEMS) return Math.max(id, MenuFacts.NONE);
        Widget slot = entry.getWidget();
        Widget item = slot == null ? null : slot.getChild(WORN_ITEM_CHILD);
        return item == null ? MenuFacts.NONE : Math.max(item.getItemId(), MenuFacts.NONE);
    }

    /** Menu text without colour tags or our lock tag, in its own case. */
    static String text(String value)
    {
        if (value == null) return "";
        return WHITESPACE.matcher(Text.removeTags(value).replace(MenuFacts.LOCKED_MARK, ""))
            .replaceAll(" ").trim();
    }
}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import lombok.extern.slf4j.Slf4j;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.Base64;
import java.util.zip.GZIPOutputStream;

/**
 * Keeps the last accepted rules in saved-rules.json at the root of the data
 * folder, so they survive a restart and an offline start. They belong to
 * the pairing, not the OSRS account, because they must load before login,
 * and the file names the pairing only by its tag, never the code. The
 * bundle is kept compressed ("FLGZ:"), the form the bundle loader reads.
 */
@Slf4j
final class SavedRulesStore
{
    static final String FILE_NAME = "saved-rules.json";
    private static final int FORMAT = 1;
    private static final String GZ_PREFIX = "FLGZ:";

    private final Gson gson;
    private final Path path;

    SavedRulesStore(Gson gson, Path path)
    {
        this.gson = gson;
        this.path = path;
    }

    /**
     * The saved rules, or null when there are none. A damaged file is moved
     * aside as {@code .corrupt-<millis>}; a file from a newer plugin is left
     * alone. Never throws.
     */
    SavedRules load()
    {
        try
        {
            if (!Files.exists(path))
            {
                return null;
            }
            State state = gson.fromJson(
                new String(Files.readAllBytes(path), StandardCharsets.UTF_8),
                State.class);
            if (state != null && state.format > FORMAT)
            {
                return null;
            }
            SavedRules rules = state == null ? null : state.toRules();
            if (rules == null)
            {
                throw new JsonParseException("incomplete saved rules");
            }
            return rules;
        }
        catch (IOException | RuntimeException ex)
        {
            log.warn("Saved rules could not be read: {}", ex.getMessage());
            moveAside();
            return null;
        }
    }

    void save(SavedRules rules) throws IOException
    {
        State state = new State();
        state.format = FORMAT;
        state.source = rules.getSource().name();
        state.savedAt = rules.getSavedAt().toString();
        state.relayVersion = rules.getRelayVersion();
        state.pairingTag = rules.getPairingTag();
        state.payload = compress(rules.getPayload());
        byte[] bytes = gson.toJson(state).getBytes(StandardCharsets.UTF_8);

        Path parent = path.toAbsolutePath().getParent();
        if (parent != null)
        {
            Files.createDirectories(parent);
        }
        Path temporary = path.resolveSibling(path.getFileName() + ".tmp");
        Files.write(temporary, bytes);
        try
        {
            Files.move(temporary, path, StandardCopyOption.ATOMIC_MOVE,
                StandardCopyOption.REPLACE_EXISTING);
        }
        catch (AtomicMoveNotSupportedException ex)
        {
            Files.move(temporary, path, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    /** The bundle compressed as the web app compresses it, unless it already is. */
    static String compress(String bundle)
    {
        String trimmed = bundle.trim();
        if (trimmed.startsWith(GZ_PREFIX))
        {
            return trimmed;
        }
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (GZIPOutputStream gzip = new GZIPOutputStream(bytes))
        {
            gzip.write(trimmed.getBytes(StandardCharsets.UTF_8));
        }
        catch (IOException ex)
        {
            // Writing to memory does not fail.
            throw new IllegalStateException(ex);
        }
        return GZ_PREFIX + Base64.getEncoder().encodeToString(bytes.toByteArray());
    }

    private void moveAside()
    {
        try
        {
            if (Files.exists(path))
            {
                Files.move(path, path.resolveSibling(path.getFileName()
                    + ".corrupt-" + System.currentTimeMillis()),
                    StandardCopyOption.REPLACE_EXISTING);
            }
        }
        catch (IOException ex)
        {
            log.warn("Could not move damaged saved rules aside: {}", ex.getMessage());
        }
    }

    private static final class State
    {
        int format;
        String source;
        String savedAt;
        String relayVersion;
        String pairingTag;
        String payload;

        SavedRules toRules()
        {
            if (format != FORMAT || payload == null || source == null || savedAt == null)
            {
                return null;
            }
            try
            {
                return new SavedRules(payload,
                    FateLockedPlugin.RulesSource.valueOf(source),
                    Instant.parse(savedAt), relayVersion, pairingTag);
            }
            catch (IllegalArgumentException | DateTimeParseException ex)
            {
                return null;
            }
        }
    }
}

package com.fatelocked;

import java.util.Objects;

final class RepeatedValueLimiter
{
    private final long windowMillis;
    private String lastValue;
    private long lastReportedAt;
    private boolean hasReported;

    RepeatedValueLimiter(long windowMillis)
    {
        this.windowMillis = windowMillis;
    }

    synchronized boolean shouldReport(String value, long nowMillis)
    {
        if (!hasReported
            || !Objects.equals(lastValue, value)
            || nowMillis - lastReportedAt >= windowMillis)
        {
            hasReported = true;
            lastValue = value;
            lastReportedAt = nowMillis;
            return true;
        }
        return false;
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import lombok.Value;

/**
 * What the world map draws for a run (U18, decision 4), worked out once per decision service:
 * its locked land and frontier as runs along each chunk row, and the outline of its unlocked
 * land. Unlocked land is left clear, so the map reads as fog over what is still locked. The
 * outline carries "locked" without relying on colour (U15), and goes all the way round: it
 * also follows unlocked land where the tracker's map stops, such as at Tutorial Island, which
 * is free but left off the map because no one can go back.
 */
final class WorldMapModel
{
    /** Nothing to draw: no rules, or another character's. */
    static final WorldMapModel NONE = new WorldMapModel(Collections.emptyList(), Collections.emptyList());

    /** Chunks in one row with the same fill, from column cx0 to cx1, both included. */
    @Value
    static class Run
    {
        int cy;
        int cx0;
        int cx1;
        WorldMapChunks.Fill fill;
    }

    /**
     * A stretch of the unlocked land's outline along a chunk line, in chunks: a vertical one on
     * the west side of column {@code line}, from row {@code from} up to row {@code to}; a
     * horizontal one on the south side of row {@code line}, from column {@code from} to {@code to}.
     */
    @Value
    static class Edge
    {
        boolean vertical;
        int line;
        int from;
        int to;
    }

    private final List<Run> runs;
    private final List<Edge> outline;

    private WorldMapModel(List<Run> runs, List<Edge> outline)
    {
        this.runs = runs;
        this.outline = outline;
    }

    /** The locked land and the frontier, row by row from the south. */
    List<Run> runs()
    {
        return runs;
    }

    /** The outline of the unlocked land: every side where it meets land that isn't unlocked. */
    List<Edge> outline()
    {
        return outline;
    }

    static WorldMapModel of(DecisionService decisions)
    {
        Map<CanonicalChunk, WorldMapChunks.Fill> fills = new HashMap<>();
        for (CanonicalChunk chunk : decisions.mappedChunks())
        {
            WorldMapChunks.Fill fill = WorldMapChunks.fill(decisions, chunk);
            if (fill != null)
            {
                fills.put(chunk, fill);
            }
        }
        return new WorldMapModel(runs(fills), outline(fills));
    }

    private static List<Run> runs(Map<CanonicalChunk, WorldMapChunks.Fill> fills)
    {
        // Row by row, west to east.
        TreeMap<Integer, TreeMap<Integer, WorldMapChunks.Fill>> rows = new TreeMap<>();
        for (Map.Entry<CanonicalChunk, WorldMapChunks.Fill> chunk : fills.entrySet())
        {
            if (chunk.getValue() != WorldMapChunks.Fill.UNLOCKED)
            {
                rows.computeIfAbsent(chunk.getKey().getCy(), row -> new TreeMap<>())
                    .put(chunk.getKey().getCx(), chunk.getValue());
            }
        }
        List<Run> runs = new ArrayList<>();
        for (Map.Entry<Integer, TreeMap<Integer, WorldMapChunks.Fill>> row : rows.entrySet())
        {
            Run open = null;
            for (Map.Entry<Integer, WorldMapChunks.Fill> chunk : row.getValue().entrySet())
            {
                int cx = chunk.getKey();
                if (open != null && open.getCx1() == cx - 1 && open.getFill() == chunk.getValue())
                {
                    open = new Run(open.getCy(), open.getCx0(), cx, open.getFill());
                    continue;
                }
                if (open != null)
                {
                    runs.add(open);
                }
                open = new Run(row.getKey(), cx, cx, chunk.getValue());
            }
            runs.add(open);
        }
        return Collections.unmodifiableList(runs);
    }

    private static List<Edge> outline(Map<CanonicalChunk, WorldMapChunks.Fill> fills)
    {
        // Each unit of outline, keyed by its line: the rows (vertical) or columns (horizontal) it spans.
        TreeMap<Integer, TreeSet<Integer>> vertical = new TreeMap<>();
        TreeMap<Integer, TreeSet<Integer>> horizontal = new TreeMap<>();
        for (Map.Entry<CanonicalChunk, WorldMapChunks.Fill> chunk : fills.entrySet())
        {
            if (chunk.getValue() != WorldMapChunks.Fill.UNLOCKED)
            {
                continue;
            }
            int cx = chunk.getKey().getCx();
            int cy = chunk.getKey().getCy();
            if (!unlocked(fills, cx - 1, cy)) unit(vertical, cx, cy);
            if (!unlocked(fills, cx + 1, cy)) unit(vertical, cx + 1, cy);
            if (!unlocked(fills, cx, cy - 1)) unit(horizontal, cy, cx);
            if (!unlocked(fills, cx, cy + 1)) unit(horizontal, cy + 1, cx);
        }
        List<Edge> outline = new ArrayList<>();
        join(outline, true, vertical);
        join(outline, false, horizontal);
        return Collections.unmodifiableList(outline);
    }

    /** Unlocked land; the rest is locked, the frontier, or off the tracker's map. */
    private static boolean unlocked(Map<CanonicalChunk, WorldMapChunks.Fill> fills, int cx, int cy)
    {
        return fills.get(new CanonicalChunk(cx, cy)) == WorldMapChunks.Fill.UNLOCKED;
    }

    private static void unit(TreeMap<Integer, TreeSet<Integer>> lines, int line, int at)
    {
        lines.computeIfAbsent(line, l -> new TreeSet<>()).add(at);
    }

    /** Join each line's units into stretches. */
    private static void join(List<Edge> outline, boolean vertical, TreeMap<Integer, TreeSet<Integer>> lines)
    {
        for (Map.Entry<Integer, TreeSet<Integer>> line : lines.entrySet())
        {
            int from = Integer.MIN_VALUE;
            int to = Integer.MIN_VALUE;
            for (int at : line.getValue())
            {
                if (at != to)
                {
                    if (from != Integer.MIN_VALUE)
                    {
                        outline.add(new Edge(vertical, line.getKey(), from, to));
                    }
                    from = at;
                }
                to = at + 1;
            }
            outline.add(new Edge(vertical, line.getKey(), from, to));
        }
    }
}

package com.fatelocked.panel;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.util.Locale;

/**
 * A moment as the player's own clock shows it: "18:03" today, "Mon 18:03"
 * within a week either side, "27 Jul 18:03" further off. An absolute time,
 * unlike "5m ago", stays true however long the sidebar goes unrefreshed.
 */
public final class LocalTimeText
{
    private static final DateTimeFormatter TIME =
        DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter DAY_AND_TIME =
        DateTimeFormatter.ofPattern("EEE HH:mm", Locale.ENGLISH);
    private static final DateTimeFormatter DATE_AND_TIME =
        DateTimeFormatter.ofPattern("d MMM HH:mm", Locale.ENGLISH);

    private LocalTimeText()
    {
    }

    public static String of(Instant at, Instant now, ZoneId zone)
    {
        ZonedDateTime local = at.atZone(zone);
        long days = Math.abs(ChronoUnit.DAYS.between(
            now.atZone(zone).toLocalDate(), local.toLocalDate()));
        if (days == 0)
        {
            return TIME.format(local);
        }
        return (days < 7 ? DAY_AND_TIME : DATE_AND_TIME).format(local);
    }

    /** For the player's own clock. */
    public static String of(Instant at)
    {
        return of(at, Instant.now(), ZoneId.systemDefault());
    }
}

package com.fatelocked.events;

import com.fatelocked.storage.LocalFileMerge;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * The newest 250 detected events, kept in a local file that another
 * RuneLite on this computer may share: each write merges into what is on
 * disk rather than replacing it (LocalFileMerge).
 */
public final class FateEventHistory
{
    static final int MAX_EVENTS = 250;

    interface Persistence
    {
        void write(Path target, byte[] bytes) throws IOException;
    }

    private final Gson gson;
    private final Path historyPath;
    private final Persistence persistence;
    private final List<FateEvent> events = new ArrayList<>();

    public FateEventHistory(
        Gson gson, Path historyPath, Path legacyOutboxPath)
        throws IOException
    {
        this(gson, historyPath, legacyOutboxPath, LocalFileMerge::replace);
    }

    FateEventHistory(
        Gson gson,
        Path historyPath,
        Path legacyOutboxPath,
        Persistence persistence)
        throws IOException
    {
        if (gson == null || historyPath == null || persistence == null)
        {
            throw new IllegalArgumentException(
                "History dependencies are required");
        }
        this.gson = gson;
        this.historyPath = historyPath;
        this.persistence = persistence;
        load(legacyOutboxPath);
    }

    public synchronized boolean record(FateEvent event) throws IOException
    {
        if (event == null || event.getEventId() == null
            || event.getEventId().trim().isEmpty()
            || contains(event.getEventId()))
        {
            return false;
        }

        List<FateEvent> candidate = new ArrayList<>(events);
        candidate.add(event);
        List<FateEvent> merged = persist(candidate);
        // Only once written: a failed write leaves memory as it was.
        events.clear();
        events.addAll(merged);
        return true;
    }

    public synchronized List<FateEvent> events()
    {
        return Collections.unmodifiableList(new ArrayList<>(events));
    }

    /** Add events from elsewhere, such as an older shared history, merged as any write is. */
    public synchronized void adopt(List<FateEvent> adopted) throws IOException
    {
        List<FateEvent> candidate = new ArrayList<>(events);
        candidate.addAll(adopted);
        List<FateEvent> merged = persist(candidate);
        events.clear();
        events.addAll(merged);
    }

    /**
     * The events in a history file, or in the older outbox file when there
     * is no history, without writing, moving or repairing either. None when
     * neither can be read.
     */
    public static List<FateEvent> readOnly(Gson gson, Path historyPath, Path legacyOutboxPath)
    {
        try
        {
            if (Files.exists(historyPath))
            {
                State state = gson.fromJson(new String(
                    Files.readAllBytes(historyPath), StandardCharsets.UTF_8), State.class);
                return state == null || state.events == null
                    ? Collections.emptyList() : withoutNulls(state.events);
            }
            if (legacyOutboxPath != null && Files.exists(legacyOutboxPath))
            {
                LegacyState legacy = gson.fromJson(new String(
                    Files.readAllBytes(legacyOutboxPath), StandardCharsets.UTF_8), LegacyState.class);
                return legacy == null || legacy.pending == null
                    ? Collections.emptyList() : withoutNulls(legacy.pending);
            }
        }
        catch (IOException | RuntimeException error)
        {
            // Unreadable: nothing comes from it, and it is left as it is.
        }
        return Collections.emptyList();
    }

    private static List<FateEvent> withoutNulls(List<FateEvent> source)
    {
        List<FateEvent> valid = new ArrayList<>();
        for (FateEvent event : source)
        {
            if (event != null) valid.add(event);
        }
        return valid;
    }

    private boolean contains(String eventId)
    {
        for (FateEvent event : events)
        {
            if (eventId.equals(event.getEventId()))
            {
                return true;
            }
        }
        return false;
    }

    private void load(Path legacyOutboxPath) throws IOException
    {
        if (Files.exists(historyPath))
        {
            loadHistory();
            return;
        }
        if (legacyOutboxPath != null && Files.exists(legacyOutboxPath))
        {
            migrateLegacy(legacyOutboxPath);
        }
    }

    private void loadHistory() throws IOException
    {
        try
        {
            State state = gson.fromJson(
                new String(
                    Files.readAllBytes(historyPath),
                    StandardCharsets.UTF_8),
                State.class);
            if (state == null || state.events == null)
            {
                throw new JsonParseException("invalid event history");
            }
            events.addAll(boundedUnique(state.events));
        }
        catch (RuntimeException error)
        {
            Path corrupt = historyPath.resolveSibling(
                historyPath.getFileName() + ".corrupt-"
                    + System.currentTimeMillis());
            Files.move(historyPath, corrupt,
                StandardCopyOption.REPLACE_EXISTING);
            events.clear();
        }
    }

    private void migrateLegacy(Path legacyOutboxPath) throws IOException
    {
        LegacyState legacy;
        try
        {
            legacy = gson.fromJson(
                new String(
                    Files.readAllBytes(legacyOutboxPath),
                    StandardCharsets.UTF_8),
                LegacyState.class);
        }
        catch (RuntimeException error)
        {
            return;
        }
        if (legacy == null || legacy.pending == null)
        {
            return;
        }
        events.addAll(persist(boundedUnique(legacy.pending)));
    }

    private List<FateEvent> boundedUnique(List<FateEvent> source)
    {
        List<FateEvent> bounded = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int index = source.size() - 1; index >= 0; index--)
        {
            FateEvent event = source.get(index);
            String eventId = event == null ? null : event.getEventId();
            if (eventId == null || eventId.trim().isEmpty()
                || !seen.add(eventId))
            {
                continue;
            }
            bounded.add(event);
            if (bounded.size() == MAX_EVENTS)
            {
                break;
            }
        }
        Collections.reverse(bounded);
        return bounded;
    }

    /**
     * Write these events merged with those on disk now, which another
     * RuneLite may have added since this one loaded: the newest 250, oldest
     * first. A damaged file is moved aside first. Returns what was written.
     */
    private List<FateEvent> persist(List<FateEvent> ours) throws IOException
    {
        List<FateEvent> merged = new ArrayList<>();
        LocalFileMerge.update(historyPath, current -> {
            List<FateEvent> all = new ArrayList<>(onDisk(current));
            all.addAll(ours);
            all.sort(Comparator.comparingLong(FateEvent::getOccurredAt));
            merged.clear();
            merged.addAll(boundedUnique(all));
            State state = new State();
            state.events = new ArrayList<>(merged);
            return gson.toJson(state).getBytes(StandardCharsets.UTF_8);
        }, persistence::write);
        return merged;
    }

    /** The events in the file's current contents; none if there is no file, or it is damaged. */
    private List<FateEvent> onDisk(byte[] current) throws IOException
    {
        if (current == null)
        {
            return Collections.emptyList();
        }
        try
        {
            State state = gson.fromJson(new String(current, StandardCharsets.UTF_8), State.class);
            if (state != null && state.events != null)
            {
                List<FateEvent> valid = new ArrayList<>();
                for (FateEvent event : state.events)
                {
                    if (event != null) valid.add(event);
                }
                return valid;
            }
        }
        catch (RuntimeException error)
        {
            // Damaged: kept aside below, and not written over.
        }
        LocalFileMerge.moveAside(historyPath);
        return Collections.emptyList();
    }

    private static final class State
    {
        private List<FateEvent> events;
    }

    private static final class LegacyState
    {
        private List<FateEvent> pending;
    }
}

