package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.ui.Palette;
import com.fatelocked.ui.Palette.Tone;
import com.fatelocked.ui.Terms;

import java.util.List;

/**
 * What the world map draws for a chunk (B8), from the decision service: the
 * tracker's land in its colours, the frontier of a Chunked run, and a
 * tooltip. The sea the rules don't cover and another character's rules
 * draw nothing, as the web map shows land only.
 */
final class WorldMapChunks
{
    enum Fill { UNLOCKED, FRONTIER, LOCKED }

    private WorldMapChunks()
    {
    }

    /**
     * The chunk's fill, or null when the map draws nothing there: off the
     * tracker's land, such as the sea, whose entries the HUD and tints use.
     * NOT_READY is owned.
     */
    static Fill fill(DecisionService decisions, CanonicalChunk chunk)
    {
        if (!decisions.mappedChunks().contains(chunk)) return null;
        switch (decisions.chunk(chunk).getStatus())
        {
            case ALLOWED:
            case NOT_READY:
                return Fill.UNLOCKED;
            case LOCKED:
                return decisions.isFrontier(chunk) ? Fill.FRONTIER : Fill.LOCKED;
            default:
                return null;
        }
    }

    /**
     * The hover tooltip: the area, the status in the palette's colour and what's there, or
     * null where the map draws nothing. A chunk only the tracker names shows its coordinates.
     */
    static String tooltip(DecisionService decisions, CanonicalChunk chunk, List<String> content, Palette palette)
    {
        Fill fill = fill(decisions, chunk);
        if (fill == null) return null;
        String label = decisions.areaName(chunk);
        StringBuilder tip = new StringBuilder(label != null ? label
            : "Chunk (" + chunk.getCx() + ", " + chunk.getCy() + ")").append("</br>");
        if (fill == Fill.FRONTIER) coloured(tip, palette, Tone.FRONTIER, Terms.LOCKED + " — rollable next");
        else if (fill == Fill.LOCKED) coloured(tip, palette, Tone.BAD, Terms.LOCKED);
        else if (decisions.chunk(chunk).getStatus() == PermissionStatus.NOT_READY)
        {
            coloured(tip, palette, Tone.PENDING, Terms.NOT_READY);
        }
        else coloured(tip, palette, Tone.GOOD, Terms.UNLOCKED);
        for (String line : content)
        {
            coloured(tip.append("</br>"), palette, Tone.NEUTRAL, line);
        }
        return tip.toString();
    }

    private static StringBuilder coloured(StringBuilder tip, Palette palette, Tone tone, String text)
    {
        return tip.append("<col=").append(palette.hex(tone)).append('>').append(text).append("</col>");
    }
}

package com.fatelocked;

import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where world tiles fall on the world map (U18), in RuneLite's own integer maths, so what this
 * plugin draws lines up with every pin on the map, its own included. The old float maths could
 * sit up to a tile off them.
 *
 * <p>RuneLite's {@code WorldMapOverlay.mapWorldPointToGraphicsPoint} counts whole tiles across
 * the map, rounds each offset down to a pixel, then moves a pin to the middle of its tile.
 * Tile lines here are the same offsets before that move, so every pin sits inside its tile.
 */
final class WorldMapProjection
{
    private final int mapX;
    private final int mapY;
    private final int mapHeight;
    private final float zoom;
    private final int widthInTiles;
    private final int heightInTiles;
    /** The tile column at the map's west edge. */
    private final int west;
    /** The tile row at the map's south edge. */
    private final int south;

    /** The map's view: its widget's bounds, pixels a tile, and the tile at its centre. */
    WorldMapProjection(Rectangle map, float zoom, int centreX, int centreY)
    {
        mapX = map.x;
        mapY = map.y;
        mapHeight = map.height;
        this.zoom = zoom;
        widthInTiles = (int) Math.ceil(map.getWidth() / zoom);
        heightInTiles = (int) Math.ceil(map.getHeight() / zoom);
        west = centreX - widthInTiles / 2;
        south = centreY - heightInTiles / 2;
    }

    /** The canvas x of the line on the west side of this tile column. */
    int lineX(int tileX)
    {
        return mapX + (int) ((float) (tileX - west) * zoom);
    }

    /** The canvas y of the line on the south side of this tile row; the canvas's y grows down. */
    int lineY(int tileY)
    {
        return mapY + mapHeight - (int) ((float) (tileY - south) * zoom);
    }

    /** Where RuneLite places a pin on this tile: in its middle. */
    Point pin(int tileX, int tileY)
    {
        int x = (int) ((float) (tileX - west) * zoom);
        int y = (int) ((float) (tileY - south + 1) * zoom);
        double middle = zoom - Math.ceil(zoom / 2);
        y = (int) (y - middle);
        x = (int) (x + middle);
        return new Point(mapX + x, mapY + mapHeight - y);
    }

    /** The tile column under this canvas x. */
    int tileX(int canvasX)
    {
        int tile = west + (int) Math.floor((canvasX - mapX) / zoom);
        while (canvasX < lineX(tile))
        {
            tile--;
        }
        while (canvasX >= lineX(tile + 1))
        {
            tile++;
        }
        return tile;
    }

    /** The tile row under this canvas y. */
    int tileY(int canvasY)
    {
        int tile = south + (int) Math.floor((mapY + mapHeight - canvasY) / zoom);
        while (canvasY >= lineY(tile))
        {
            tile--;
        }
        while (canvasY < lineY(tile + 1))
        {
            tile++;
        }
        return tile;
    }

    /** The westmost chunk column on the map. */
    int westChunk()
    {
        return Math.floorDiv(west, 64);
    }

    /** The eastmost chunk column on the map. */
    int eastChunk()
    {
        return Math.floorDiv(west + widthInTiles, 64);
    }

    /** The southmost chunk row on the map. */
    int southChunk()
    {
        return Math.floorDiv(south, 64);
    }

    /** The northmost chunk row on the map. */
    int northChunk()
    {
        return Math.floorDiv(south + heightInTiles, 64);
    }
}

package com.fatelocked;

import com.google.inject.Inject;
import net.runelite.client.config.ConfigManager;

import java.util.List;

final class TrackerConnectionSettings
{
    static final String RELAY_BASE_URL =
        "https://fate-relay.fatelocked.workers.dev";
    static final String PAIRING_CODE_KEY = "trackerPairingCode";
    private static final String CODE_PATTERN = "[0-9a-f]{32}";
    private static final String[] LEGACY_TOKEN_PREFIXES = {
        "eventToken.", "stateToken.", "suggestToken.", "ackToken."
    };

    private final ConfigManager configManager;

    @Inject
    TrackerConnectionSettings(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    String pairingCode()
    {
        String value = configManager.getConfiguration(
            FateLockedConfig.GROUP, PAIRING_CODE_KEY);
        return value != null && value.trim().matches(CODE_PATTERN)
            ? value.trim() : "";
    }

    boolean isPaired()
    {
        return !pairingCode().isEmpty();
    }

    boolean networkAccessAllowed()
    {
        // A pairing code or the retired onlineSync flag does not imply consent.
        return Boolean.parseBoolean(configManager.getConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY));
    }

    void allowNetworkAccess()
    {
        configManager.setConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY, "true");
    }

    /** The player turned online sync off; the pairing is kept for when it comes back on. */
    void refuseNetworkAccess()
    {
        configManager.setConfiguration(
            FateLockedConfig.GROUP, FateLockedConfig.NETWORK_ACCESS_KEY, "false");
    }

    void replacePairingCode(String code)
    {
        if (code == null || !code.matches(CODE_PATTERN))
        {
            throw new IllegalArgumentException("Invalid pairing code");
        }
        configManager.setConfiguration(
            FateLockedConfig.GROUP, PAIRING_CODE_KEY, code);
    }

    void clearPairing()
    {
        configManager.unsetConfiguration(
            FateLockedConfig.GROUP, PAIRING_CODE_KEY);
    }

    void clearLegacySettings()
    {
        configManager.unsetConfiguration(FateLockedConfig.GROUP, "onlineSync");
        configManager.unsetConfiguration(FateLockedConfig.GROUP, "syncCode");
        configManager.unsetConfiguration(FateLockedConfig.GROUP, "relayUrl");

        List<String> storedKeys = configManager.getConfigurationKeys(
            FateLockedConfig.GROUP + ".");
        if (storedKeys == null)
        {
            return;
        }

        String groupPrefix = FateLockedConfig.GROUP + ".";
        for (String storedKey : storedKeys)
        {
            String key = storedKey != null
                && storedKey.startsWith(groupPrefix)
                ? storedKey.substring(groupPrefix.length())
                : storedKey;
            if (hasLegacyTokenPrefix(key))
            {
                configManager.unsetConfiguration(
                    FateLockedConfig.GROUP, key);
            }
        }
    }

    private static boolean hasLegacyTokenPrefix(String key)
    {
        if (key == null)
        {
            return false;
        }
        for (String prefix : LEGACY_TOKEN_PREFIXES)
        {
            if (key.startsWith(prefix))
            {
                return true;
            }
        }
        return false;
    }

}

package com.fatelocked;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;

/**
 * What a reply to the plugin's one request, GET /r/<code>, means. Decided
 * here in one place and without side effects; the connection controller
 * acts on the answer. The web app's contracts/relay/relay-get.json lists
 * the replies, from the relay and from what can stand in front of it, and
 * the outcome each must have.
 */
final class RelayContract
{
    enum Outcome
    {
        /** Newer rules, to parse and import. */
        RULES,
        /** The rules the plugin holds are still current: a 304, or their version sent in full. */
        UNCHANGED,
        /** A 304 for a version the plugin does not hold; nothing changes. */
        UNCONFIRMED,
        /** Older rules than the plugin holds, or rules it cannot compare with them; not imported. */
        STALE,
        /** Still the version the plugin could not import; not downloaded or tried again. */
        STILL_REJECTED,
        /** No profile for this code. */
        MISSING,
        /** The owner disconnected this code in the web tracker. */
        GONE,
        /** A reply the plugin cannot use. */
        UNREADABLE,
        /** The relay asks the plugin to slow down. */
        BUSY,
        /** The relay or something in front of it failed. */
        UNAVAILABLE
    }

    /** One classified reply. */
    static final class Reply
    {
        final Outcome outcome;
        /** RULES only. */
        final int version;
        /** RULES only. */
        final String payload;
        /** BUSY only: seconds the relay asked for, or 0 when it did not say. */
        final long retryAfterSeconds;
        /** UNREADABLE only: what was wrong with it, for the log. */
        final String detail;

        private Reply(
            Outcome outcome, int version, String payload, long retryAfterSeconds, String detail)
        {
            this.outcome = outcome;
            this.version = version;
            this.payload = payload;
            this.retryAfterSeconds = retryAfterSeconds;
            this.detail = detail;
        }

        private static Reply of(Outcome outcome)
        {
            return new Reply(outcome, 0, null, 0, null);
        }

        private static Reply unreadable(String detail)
        {
            return new Reply(Outcome.UNREADABLE, 0, null, 0, detail);
        }
    }

    private RelayContract()
    {
    }

    /**
     * @param held the version the plugin holds, or null
     * @param rejected the version the plugin could not import, or null; when
     *     set, it was the request's validator
     * @param etag the reply's ETag header, or null
     * @param retryAfter the reply's Retry-After header, or null
     * @param body the reply's body; read only for a 2xx or 404 reply
     */
    static Reply classify(Gson gson, String held, String rejected,
        int status, String etag, String retryAfter, String body)
    {
        if (status == 304)
        {
            String validator = rejected != null ? rejected : held;
            String version = etag == null ? validator : canonicalVersion(etag);
            if (held != null && held.equals(version))
            {
                return Reply.of(Outcome.UNCHANGED);
            }
            return Reply.of(rejected != null && rejected.equals(version)
                ? Outcome.STILL_REJECTED : Outcome.UNCONFIRMED);
        }
        if (status == 404)
        {
            return Reply.of(isGone(gson, body) ? Outcome.GONE : Outcome.MISSING);
        }
        if (status == 429)
        {
            return new Reply(Outcome.BUSY, 0, null, retryAfterSeconds(retryAfter), null);
        }
        if (status < 200 || status >= 300)
        {
            return Reply.of(Outcome.UNAVAILABLE);
        }

        Envelope envelope;
        try
        {
            envelope = gson.fromJson(body, Envelope.class);
        }
        catch (JsonParseException | IllegalStateException ex)
        {
            return Reply.unreadable("not a relay reply");
        }
        if (envelope == null || envelope.payload == null)
        {
            return Reply.unreadable("no rules in the reply");
        }
        if (envelope.version <= 0)
        {
            return Reply.unreadable("no valid version");
        }
        Integer version = etag == null ? Integer.valueOf(envelope.version) : parseVersion(etag);
        if (version == null || version != envelope.version)
        {
            return Reply.unreadable("an ETag that disagrees with the reply");
        }
        if (rejected != null && version.equals(parseVersion(rejected)))
        {
            // A reply that ignored the validator: still nothing new to try.
            return Reply.of(Outcome.STILL_REJECTED);
        }
        Integer previous = held == null ? null : parseVersion(held);
        if (version.equals(previous))
        {
            // Something in front of the relay dropped If-None-Match: the
            // rules the plugin holds, confirmed all the same.
            return Reply.of(Outcome.UNCHANGED);
        }
        if (held != null && (previous == null || version < previous))
        {
            return Reply.of(Outcome.STALE);
        }
        return new Reply(Outcome.RULES, version, envelope.payload, 0, null);
    }

    /**
     * A 2xx reply longer than any real bundle. The connection stops reading
     * it at its cap, so it never reaches classify.
     */
    static Reply oversized()
    {
        return Reply.unreadable("a reply larger than any real bundle");
    }

    /** Whether a 404's body is the relay's {"gone":true} marker; anything else is a plain 404. */
    private static boolean isGone(Gson gson, String body)
    {
        if (body == null) return false;
        try
        {
            Gone marker = gson.fromJson(body, Gone.class);
            return marker != null && marker.gone;
        }
        catch (JsonParseException | IllegalStateException ex)
        {
            return false;
        }
    }

    /** A positive version from a bare, quoted or weak ETag, or null. */
    static Integer parseVersion(String raw)
    {
        if (raw == null) return null;
        String value = raw.trim();
        if (value.startsWith("W/"))
        {
            value = value.substring(2);
        }
        if (value.startsWith("\""))
        {
            if (value.length() < 2 || !value.endsWith("\""))
            {
                return null;
            }
            value = value.substring(1, value.length() - 1);
        }
        else if (value.contains("\""))
        {
            return null;
        }
        if (!value.matches("[1-9][0-9]*")) return null;
        try
        {
            return Integer.valueOf(value);
        }
        catch (NumberFormatException error)
        {
            return null;
        }
    }

    /** The version as the plugin sends it back in If-None-Match. */
    static String canonicalVersion(String raw)
    {
        Integer parsed = parseVersion(raw);
        return parsed == null ? raw : String.valueOf(parsed);
    }

    static long retryAfterSeconds(String raw)
    {
        if (raw == null || !raw.trim().matches("[0-9]+"))
        {
            return 0;
        }
        try
        {
            return Long.parseLong(raw.trim());
        }
        catch (NumberFormatException error)
        {
            return 0;
        }
    }

    private static final class Gone
    {
        private boolean gone;
    }

    private static final class Envelope
    {
        private int version;
        private String payload;
    }
}

package com.fatelocked;

import net.runelite.client.util.Text;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Which OSRS account a tracker profile is for. This is the one place that
 * reads it, and it compares names the way the tracker's normalizeAccountName
 * does (trim, collapse whitespace, lower-case), so the rules, Strict Mode,
 * the HUD and the account warning can never disagree.
 */
final class AccountBinding
{
    private static final Pattern WHITESPACE =
        Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);

    private AccountBinding()
    {
    }

    /**
     * The account the profile is for: the rules' account. Older bundles
     * without rules fall back to the run state's linked account. Null when
     * the profile is not bound to one.
     */
    static String boundAccount(FateLockedBundle bundle)
    {
        if (bundle == null)
        {
            return null;
        }
        String bound = bundle.getRules() != null
            ? bundle.getRules().getAccount()
            : bundle.getState() == null ? null : bundle.getState().getLinkedAccount();
        return normalize(bound).isEmpty() ? null : bound.trim();
    }

    /**
     * The tracker's normalizeAccountName, after RuneLite's own clean-up of
     * a name (icon tags, non-breaking spaces).
     */
    static String normalize(String name)
    {
        if (name == null)
        {
            return "";
        }
        return WHITESPACE.matcher(Text.sanitize(name)).replaceAll(" ")
            .trim().toLowerCase(Locale.ROOT);
    }

    /** Whether a logged-in name is the bound account. */
    static boolean sameAccount(String bound, String player)
    {
        String account = normalize(bound);
        return !account.isEmpty() && account.equals(normalize(player));
    }
}

package com.fatelocked;

import com.fatelocked.panel.LocalTimeText;
import com.fatelocked.sidebar.CardAction;
import com.fatelocked.sidebar.ConnectionModel;
import java.time.Instant;
import java.time.ZoneId;

/**
 * The Connection and backup section: the online-sync switch, the pairing by its last
 * four characters, where the rules in force came from, and which pairing button to
 * offer, as SyncView decides it. Pure.
 */
final class ConnectionPresenter
{
    private ConnectionPresenter()
    {
    }

    /**
     * @param onlineSync whether online sync is on
     * @param paired     whether a pairing is saved
     * @param source     where the rules in force came from
     * @param exportedAt when the tracker exported them, or null
     */
    static ConnectionModel present(TrackerConnectionSnapshot snapshot, boolean onlineSync, boolean paired,
        FateLockedPlugin.RulesSource source, Instant exportedAt, Instant now, ZoneId zone)
    {
        SyncView view = SyncView.of(snapshot, now, zone);
        String pairing = snapshot.getPairingEnding() == null ? null : "…" + snapshot.getPairingEnding();
        return new ConnectionModel(onlineSync, pairing, source(source, snapshot, exportedAt, now, zone),
            action(view.connect), view.canCheckNow, paired,
            !onlineSync ? "Off" : snapshot.getState() == TrackerConnectionState.CONNECTED ? "Online"
                : snapshot.getMessage());
    }

    private static String source(FateLockedPlugin.RulesSource source, TrackerConnectionSnapshot snapshot,
        Instant exportedAt, Instant now, ZoneId zone)
    {
        switch (source)
        {
            case RELAY:
                return snapshot.getLastSync() == null ? "Rules from the tracker, saved by the last start."
                    : "Rules from the tracker, last synced at " + LocalTimeText.of(snapshot.getLastSync(), now, zone)
                        + ".";
            case IMPORT:
                return "Rules from the clipboard" + exported(exportedAt, now, zone);
            case FILE:
                return "Rules from a backup file" + exported(exportedAt, now, zone);
            default:
                return null;
        }
    }

    private static String exported(Instant exportedAt, Instant now, ZoneId zone)
    {
        return exportedAt == null ? "." : ", exported at " + LocalTimeText.of(exportedAt, now, zone) + ".";
    }

    private static CardAction action(SyncView.Connect connect)
    {
        switch (connect)
        {
            case TURN_ON_SYNC:
                return CardAction.TURN_ON_SYNC;
            case REPAIR:
                return CardAction.REPAIR;
            case CANCEL_REPAIR:
                return CardAction.CANCEL_REPAIR;
            default:
                return CardAction.CONNECT;
        }
    }
}

package com.fatelocked;

import java.time.Instant;
import java.util.Objects;

final class TrackerConnectionSnapshot
{
    private final TrackerConnectionState state;
    private final Instant lastSync;
    private final String acceptedVersion;
    private final SyncReason reason;
    /** When the next check is due, for states that say so; null otherwise. */
    private final Instant nextCheck;
    /** The last four characters of the code in use, or null: all the sidebar shows of it. */
    private final String pairingEnding;

    private TrackerConnectionSnapshot(
        TrackerConnectionState state,
        Instant lastSync,
        String acceptedVersion,
        SyncReason reason,
        Instant nextCheck,
        String pairingEnding)
    {
        this.state = state;
        this.lastSync = lastSync;
        this.acceptedVersion = acceptedVersion;
        this.reason = reason == null ? SyncReason.NONE : reason;
        this.nextCheck = nextCheck;
        this.pairingEnding = pairingEnding;
    }

    TrackerConnectionState getState()
    {
        return state;
    }

    Instant getLastSync()
    {
        return lastSync;
    }

    String getAcceptedVersion()
    {
        return acceptedVersion;
    }

    SyncReason getReason()
    {
        return reason;
    }

    Instant getNextCheck()
    {
        return nextCheck;
    }

    String getPairingEnding()
    {
        return pairingEnding;
    }

    /** This snapshot for the pairing whose code this is. */
    TrackerConnectionSnapshot forPairing(String code)
    {
        String ending = code == null || code.length() < 4 ? null : code.substring(code.length() - 4);
        return new TrackerConnectionSnapshot(
            state, lastSync, acceptedVersion, reason, nextCheck, ending);
    }

    /** The short status: the reason's, or the state's own. */
    String getMessage()
    {
        return reason.status != null ? reason.status : stateStatus(state);
    }

    static TrackerConnectionSnapshot disconnected()
    {
        return of(TrackerConnectionState.DISCONNECTED, null, null, SyncReason.NOT_PAIRED, null);
    }

    static TrackerConnectionSnapshot waiting()
    {
        return of(TrackerConnectionState.WAITING, null, null, SyncReason.NONE, null);
    }

    static TrackerConnectionSnapshot connected(
        Instant at, String version)
    {
        return of(TrackerConnectionState.CONNECTED, at, version, SyncReason.NONE, null);
    }

    static TrackerConnectionSnapshot of(
        TrackerConnectionState state,
        Instant lastSync,
        String acceptedVersion,
        SyncReason reason,
        Instant nextCheck)
    {
        return new TrackerConnectionSnapshot(
            state, lastSync, acceptedVersion, reason, nextCheck, null);
    }

    private static String stateStatus(TrackerConnectionState state)
    {
        switch (state)
        {
            case DISCONNECTED:
                return "Not connected";
            case WAITING:
                return "Waiting for tracker";
            case IMPORTING:
                return "Importing tracker data";
            case CONNECTED:
                return "Connected";
            case EXPIRED:
                return "Pairing request expired";
            case OFFLINE:
                return "Tracker is offline";
            case IMPORT_FAILED:
                return "Could not import tracker data";
            default:
                return "";
        }
    }

    /** Two snapshots that would show the same thing are equal, so nothing republishes it. */
    @Override
    public boolean equals(Object other)
    {
        if (this == other) return true;
        if (!(other instanceof TrackerConnectionSnapshot)) return false;
        TrackerConnectionSnapshot that = (TrackerConnectionSnapshot) other;
        return state == that.state
            && Objects.equals(lastSync, that.lastSync)
            && Objects.equals(acceptedVersion, that.acceptedVersion)
            && reason == that.reason
            && Objects.equals(nextCheck, that.nextCheck)
            && Objects.equals(pairingEnding, that.pairingEnding);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(state, lastSync, acceptedVersion, reason, nextCheck, pairingEnding);
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.Progress;
import com.fatelocked.rules.Trust;
import com.fatelocked.ui.Art;
import com.fatelocked.ui.Palette;
import com.fatelocked.ui.Terms;
import java.awt.Color;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * One of the plugin's three infoboxes (A15, E7), shown when the setting is on. Each has its
 * own name, so RuneLite moves it and saves its place on its own; its art is the sidebar's; its
 * words are the web app's. A box with nothing to count, before rules load or on another
 * character, isn't drawn.
 */
final class FateLockedInfoBox extends InfoBox
{
    /** What a box counts. Its name is pinned: RuneLite saves each box's place under it. */
    enum Kind
    {
        KEYS("FateLocked_Keys", Art.KEYS, Palette.Tone.FRONTIER),
        FATE_POINTS("FateLocked_FatePoints", Art.FATE_POINTS, null),
        UNLOCKED("FateLocked_Unlocked", Art.PLACE, Palette.Tone.GOOD);

        private final String boxName;
        private final Art art;
        /** The count's tone; null for plain white. */
        private final Palette.Tone tone;

        Kind(String boxName, Art art, Palette.Tone tone)
        {
            this.boxName = boxName;
            this.art = art;
            this.tone = tone;
        }

        String boxName()
        {
            return boxName;
        }

        Art art()
        {
            return art;
        }
    }

    private final Kind kind;
    private final FateLockedPlugin plugin;

    /** A box whose art is set once it loads. */
    FateLockedInfoBox(Kind kind, FateLockedPlugin plugin)
    {
        super(null, plugin);
        this.kind = kind;
        this.plugin = plugin;
    }

    Kind kind()
    {
        return kind;
    }

    @Override
    public String getName()
    {
        return kind.boxName;
    }

    @Override
    public boolean render()
    {
        return getImage() != null && getText() != null;
    }

    @Override
    public String getText()
    {
        DecisionService decisions = plugin.decisions();
        return text(kind, run(decisions), decisions.progress());
    }

    @Override
    public Color getTextColor()
    {
        return kind.tone == null ? Palette.TITLE : plugin.palette().text(kind.tone);
    }

    @Override
    public String getTooltip()
    {
        DecisionService decisions = plugin.decisions();
        return tooltip(kind, run(decisions), decisions.progress());
    }

    /** The run's Keys and Fate Points, for the rules' own character only. */
    private FateLockedBundle.RunState run(DecisionService decisions)
    {
        return decisions.trust() == Trust.TRUSTED ? plugin.getBundle().getState() : null;
    }

    /** The box's count, or null when there is none to show. */
    static String text(Kind kind, FateLockedBundle.RunState run, Progress progress)
    {
        switch (kind)
        {
            case KEYS:
                return run == null ? null : String.valueOf(run.getKeys());
            case FATE_POINTS:
                return run == null ? null : String.valueOf(run.getFatePoints());
            default:
                return ProgressText.infoBoxText(progress);
        }
    }

    /** The box's tooltip, in the web app's words; Omni-Keys and Chaos Keys only when there are some. */
    static String tooltip(Kind kind, FateLockedBundle.RunState run, Progress progress)
    {
        switch (kind)
        {
            case KEYS:
                if (run == null) return null;
                StringBuilder tip = new StringBuilder(Terms.KEYS).append(": ").append(run.getKeys());
                if (run.getSpecialKeys() > 0)
                {
                    tip.append("</br>").append(Terms.OMNI_KEYS).append(": ").append(run.getSpecialKeys());
                }
                if (run.getChaosKeys() > 0)
                {
                    tip.append("</br>").append(Terms.CHAOS_KEYS).append(": ").append(run.getChaosKeys());
                }
                return tip.toString();
            case FATE_POINTS:
                return run == null ? null : Terms.FATE_POINTS + ": " + run.getFatePoints();
            default:
                return ProgressText.infoBoxTooltip(progress);
        }
    }
}

package com.fatelocked;

import com.fatelocked.guardian.StrictModeAuditEntry;
import com.fatelocked.guardian.StrictModeReadiness;
import com.fatelocked.guardian.travel.TravelAction;
import com.fatelocked.guardian.travel.TravelAvailability;
import com.fatelocked.guardian.travel.TravelGuardianCoordinator;
import com.fatelocked.guardian.travel.TravelGuardianResult;
import com.fatelocked.rules.DecisionService;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;

import java.time.Clock;

/**
 * Thin plugin boundary for coordinator routing and post-enforcement side
 * effects. It reads the click into {@link MenuFacts} on the client thread
 * and never repeats travel recognition, evaluation, or presentation.
 * Clicks that are not exactly matched travel are left alone.
 */
final class TravelGuardianPluginShell
{
    enum Route
    {
        EXACT_TRAVEL,
        NOT_TRAVEL,
        FAIL_OPEN
    }

    @FunctionalInterface
    interface ChatSink
    {
        void write(String message);
    }

    @FunctionalInterface
    interface AuditSink
    {
        void write(StrictModeAuditEntry entry) throws Exception;
    }

    @FunctionalInterface
    interface DiagnosticSink
    {
        void record(String stage, Exception error);
    }

    private final TravelGuardianCoordinator coordinator;
    private final TravelAvailability availability;
    private final ChatSink chatSink;
    private final AuditSink auditSink;
    private final DiagnosticSink diagnosticSink;
    private final Clock clock;

    TravelGuardianPluginShell(
        TravelGuardianCoordinator coordinator,
        TravelAvailability availability,
        ChatSink chatSink,
        AuditSink auditSink,
        DiagnosticSink diagnosticSink,
        Clock clock)
    {
        this.coordinator = coordinator;
        this.availability = availability;
        this.chatSink = chatSink;
        this.auditSink = auditSink;
        this.diagnosticSink = diagnosticSink;
        this.clock = clock;
    }

    Route handle(
        MenuOptionClicked event,
        Client client,
        StrictModeReadiness readiness,
        DecisionService travelRules)
    {
        TravelGuardianResult result;
        try
        {
            MenuFacts facts = new MenuFactsReader(client).read(event.getMenuEntry());
            result = coordinator.handle(event, facts, readiness, travelRules, availability);
        }
        catch (RuntimeException ex)
        {
            diagnose("coordinator", ex);
            return Route.FAIL_OPEN;
        }

        if (result == null)
        {
            diagnose("coordinator",
                new IllegalStateException("coordinator returned no result"));
            return Route.FAIL_OPEN;
        }

        TravelAction action = result.getAction();
        if (action == null
            || action.getConfidence() != TravelAction.Confidence.EXACT)
        {
            return Route.NOT_TRAVEL;
        }

        if (result.isWriteChat() && result.getNotice() != null)
        {
            try
            {
                chatSink.write(result.getNotice().getChatLine());
            }
            catch (RuntimeException ex)
            {
                diagnose("chat", ex);
            }
        }
        if (result.isWriteBlockedAudit() || result.isWritePausedAudit())
        {
            try
            {
                auditSink.write(auditEntry(result));
            }
            catch (Exception ex)
            {
                diagnose("audit", ex);
            }
        }
        return Route.EXACT_TRAVEL;
    }

    private StrictModeAuditEntry auditEntry(TravelGuardianResult result)
    {
        TravelAction action = result.getAction();
        CanonicalChunk destination = action.getDestination();
        String chunk = destination == null ? null
            : destination.getCx() + "," + destination.getCy();
        boolean paused = result.isWritePausedAudit();
        return new StrictModeAuditEntry(
            clock.millis(),
            "TRAVEL",
            result.getDecision().getLabel(),
            chunk,
            result.getDecision().getReason(),
            paused ? "ALLOWED_PAUSED" : "BLOCKED",
            paused,
            !paused && result.getAlternative() != null);
    }

    private void diagnose(String stage, Exception error)
    {
        try
        {
            diagnosticSink.record(stage, error);
        }
        catch (RuntimeException ignored)
        {
            // Diagnostics must never change fail-open or enforced outcomes.
        }
    }
}

package com.fatelocked;

import lombok.Builder;
import lombok.Value;

/**
 * What a clicked menu option is, as plain values (A9). Strict Mode's travel
 * matching reads these instead of the menu entry, so its fixtures can be
 * written down and cited. {@link MenuFactsReader} makes them on the client
 * thread; nothing here depends on RuneLite.
 *
 * <p>Text keeps its case, with colour tags and the plugin's own
 * {@link #LOCKED_MARK} removed. An id that doesn't apply is {@link #NONE}.
 */
@Value
@Builder
public class MenuFacts
{
    /**
     * What the plugin adds to an option the rules lock ({@code Terms.LOCKED_TAG}). Every
     * reader of menu text removes it first, so a tag never changes what an option matches.
     */
    public static final String LOCKED_MARK = "(Locked)";

    /** What the option was on, which decides the ids a travel row may match. */
    public enum Kind
    {
        /** An interface component: a spell, or an inventory or worn item. */
        WIDGET,
        /** A scene object, such as a fairy ring or a portal. */
        OBJECT,
        NPC,
        /** Anything else, which is never travel: walking, players, ground items, examine, ships. */
        OTHER
    }

    public static final int NONE = -1;

    /** A click with nothing to read: no entry at all. */
    public static final MenuFacts EMPTY = MenuFacts.builder().build();

    @Builder.Default
    Kind kind = Kind.OTHER;
    @Builder.Default
    String option = "";
    @Builder.Default
    String target = "";
    /** The interface the option is on, for {@link Kind#WIDGET}. */
    @Builder.Default
    int interfaceGroup = NONE;
    /** The item behind an inventory or worn item option. */
    @Builder.Default
    int itemId = NONE;
    /** The active spellbook (the SPELLBOOK varbit) for an option on the spellbook. */
    @Builder.Default
    int spellbook = NONE;
    @Builder.Default
    int npcId = NONE;
    /** The object's base id, as the menu gives it. */
    @Builder.Default
    int objectId = NONE;
    /** The world view the option belongs to, as the menu gives it. */
    @Builder.Default
    int worldViewId = NONE;
}

package com.fatelocked.storage;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;

/**
 * Updates a local file that another RuneLite on this computer may also be
 * writing. Under an exclusive lock on a "&lt;file&gt;.lock" sidecar, it reads
 * the file as it is now, merges this client's change into it, writes the
 * result to a temp file of its own and moves that into place. Two clients
 * sharing a data folder then keep each other's changes, where rewriting
 * the whole file from memory let the last writer's copy win.
 */
public final class LocalFileMerge
{
    /** The file's new contents, from its current ones: null when there is no file. */
    public interface Merge
    {
        /** Null writes nothing. */
        byte[] apply(byte[] current) throws IOException;
    }

    /** Puts the merged contents in place. */
    public interface Writer
    {
        void write(Path target, byte[] bytes) throws IOException;
    }

    private LocalFileMerge()
    {
    }

    public static void update(Path target, Merge merge) throws IOException
    {
        update(target, merge, LocalFileMerge::replace);
    }

    /**
     * One update at a time within this RuneLite, since a JVM cannot hold two
     * locks on one file, and one across RuneLites, through the file lock.
     */
    public static synchronized void update(Path target, Merge merge, Writer writer)
        throws IOException
    {
        Path parent = target.toAbsolutePath().getParent();
        if (parent != null)
        {
            Files.createDirectories(parent);
        }
        Path lockPath = target.resolveSibling(target.getFileName() + ".lock");
        try (FileChannel lockChannel = FileChannel.open(lockPath,
                StandardOpenOption.CREATE, StandardOpenOption.WRITE);
             FileLock ignored = lockChannel.lock())
        {
            byte[] current = Files.exists(target) ? Files.readAllBytes(target) : null;
            byte[] next = merge.apply(current);
            if (next != null)
            {
                writer.write(target, next);
            }
        }
    }

    /**
     * Write the bytes to a temp file of this write's own, flush them to the
     * disk, and move the file into place, so a reader sees the old contents
     * or the new, never part of them.
     */
    public static void replace(Path target, byte[] bytes) throws IOException
    {
        Path parent = target.toAbsolutePath().getParent();
        Path temporary = Files.createTempFile(parent, target.getFileName() + ".", ".tmp");
        try
        {
            try (FileChannel out = FileChannel.open(temporary,
                StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING))
            {
                ByteBuffer buffer = ByteBuffer.wrap(bytes);
                while (buffer.hasRemaining())
                {
                    out.write(buffer);
                }
                out.force(true);
            }
            try
            {
                Files.move(temporary, target,
                    StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
            }
            catch (AtomicMoveNotSupportedException error)
            {
                Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
            }
        }
        finally
        {
            Files.deleteIfExists(temporary);
        }
    }

    /** Keep a damaged file as "&lt;file&gt;.corrupt-&lt;millis&gt;" rather than writing over it. */
    public static void moveAside(Path target) throws IOException
    {
        Files.move(target, target.resolveSibling(
                target.getFileName() + ".corrupt-" + System.currentTimeMillis()),
            StandardCopyOption.REPLACE_EXISTING);
    }
}

package com.fatelocked;

import com.fatelocked.sidebar.CardAction;
import com.fatelocked.sidebar.ConnectionModel;
import com.fatelocked.sidebar.HereModel;
import com.fatelocked.sidebar.RollInboxModel;
import com.fatelocked.sidebar.RunModel;
import com.fatelocked.sidebar.Sidebar;
import com.fatelocked.sidebar.StatusCardModel;
import com.fatelocked.sidebar.StrictModeModel;
import com.fatelocked.ui.GameArt;
import com.fatelocked.ui.IconSource;
import com.fatelocked.ui.Palette;
import java.awt.BorderLayout;
import java.util.Set;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * The sidebar (Stage 3): a thin Swing view of the models the plugin works out on the
 * client thread (C7). Every update is queued on the Swing thread, so updates apply in
 * the order they were made, whichever thread made them. Settings live in RuneLite's
 * configuration (Decision 4); the sidebar keeps Strict Mode's switch, and online sync's,
 * which carries the player's consent.
 */
class FateLockedPanel extends PluginPanel
{
    static final String TRACKER_URL = "https://nubles.github.io/OSRS-Fate-Locked/";

    private final Sidebar sidebar;
    private Consumer<CardAction> onAction = action -> { };
    private Consumer<Boolean> onStrictModeToggle = on -> { };
    private Consumer<Boolean> onSyncToggle = on -> { };
    private String rollInboxUrl = rollInboxUrl(TRACKER_URL);

    @Inject
    FateLockedPanel(SpriteManager sprites, ItemManager items)
    {
        this(new GameArt(sprites, items));
    }

    FateLockedPanel(IconSource icons)
    {
        setLayout(new BorderLayout());
        setBorder(null);
        setBackground(Palette.PANEL);
        sidebar = new Sidebar(icons);
        add(sidebar, BorderLayout.NORTH);
        sidebar.openTracker().addActionListener(e -> LinkBrowser.browse(TRACKER_URL));
        sidebar.status().onAction(this::act);
        sidebar.strictMode().onAction(this::act);
        sidebar.connection().onAction(this::act);
        sidebar.strictMode().onToggle(on -> onStrictModeToggle.accept(on));
        sidebar.connection().onSyncToggle(on -> onSyncToggle.accept(on));
        sidebar.rollInbox().onOpen(() -> LinkBrowser.browse(rollInboxUrl));
    }

    /** What the player asked for, on the Swing thread; the sidebar handles its own. */
    void act(CardAction action)
    {
        if (action == CardAction.USE_BACKUP)
        {
            sidebar.connection().setExpanded(true);
            return;
        }
        if (action == CardAction.OPEN_TRACKER)
        {
            LinkBrowser.browse(TRACKER_URL);
            return;
        }
        onAction.accept(action);
    }

    void onAction(Consumer<CardAction> handler)
    {
        onAction = handler;
    }

    /** Called with Strict Mode's switch, as the player flipped it. */
    void onStrictModeToggle(Consumer<Boolean> handler)
    {
        onStrictModeToggle = handler;
    }

    /** Called with the online-sync switch, as the player flipped it; consent comes next. */
    void onSyncToggle(Consumer<Boolean> handler)
    {
        onSyncToggle = handler;
    }

    void onIntroDismiss(Runnable handler)
    {
        sidebar.strictMode().onIntroDismiss(handler);
    }

    void showStatus(StatusCardModel model)
    {
        queueOnEdt(() -> sidebar.status().apply(model));
    }

    void showHere(HereModel model)
    {
        queueOnEdt(() -> sidebar.here().apply(model));
    }

    /** Called, on the Swing thread, with what's open each time the player opens or closes part of Here. */
    void onHereFold(Consumer<Set<String>> handler)
    {
        sidebar.here().onFold(handler);
    }

    /** Opens the parts of Here the player left open, such as last time's. */
    void openHere(Set<String> keys)
    {
        queueOnEdt(() -> sidebar.here().setOpen(keys));
    }

    /** Called, on the Swing thread, with a Here row's category and name when the player clicks it. */
    void onHerePoint(BiConsumer<String, String> handler)
    {
        sidebar.here().onPoint(handler);
    }

    /** Called, on the Swing thread, when the player clears Here's arrow. */
    void onHereClearPoint(Runnable handler)
    {
        sidebar.here().onClearPoint(handler);
    }

    /** What Here says about its arrow, or null for nothing; with Clear while one is up. */
    void showHerePointer(String text, boolean active)
    {
        queueOnEdt(() -> sidebar.here().showPointer(text, active));
    }

    void showStrictMode(StrictModeModel model)
    {
        queueOnEdt(() -> sidebar.strictMode().apply(model));
    }

    void showRun(RunModel model)
    {
        queueOnEdt(() -> sidebar.run().apply(model));
    }

    void showConnection(ConnectionModel model)
    {
        queueOnEdt(() -> sidebar.connection().apply(model));
    }

    void showRollInbox(RollInboxModel model)
    {
        queueOnEdt(() -> sidebar.rollInbox().apply(model));
    }

    void setPalette(Palette palette)
    {
        queueOnEdt(() -> sidebar.setPalette(palette));
    }

    /** A short message under the status card, which clears itself (U16). */
    void flashStatus(String message, boolean ok)
    {
        queueOnEdt(() -> sidebar.notice(message, ok ? Palette.Tone.GOOD : Palette.Tone.BAD));
    }

    void showStrictModeIntro()
    {
        queueOnEdt(() -> sidebar.strictMode().showIntro());
    }

    /** Put Strict Mode's switch back where the rules have it, after a change that didn't happen. */
    void restoreStrictMode()
    {
        queueOnEdt(() -> {
            StrictModeModel shown = sidebar.strictMode().model();
            if (shown != null)
            {
                sidebar.strictMode().apply(shown);
            }
        });
    }

    /** Put the online-sync switch back, after the player declined consent or it couldn't be saved. */
    void restoreConnection()
    {
        queueOnEdt(() -> {
            ConnectionModel shown = sidebar.connection().model();
            if (shown != null)
            {
                sidebar.connection().apply(shown);
            }
        });
    }

    void setRollInboxLink(String trackerUrl)
    {
        rollInboxUrl = rollInboxUrl(trackerUrl);
    }

    static String rollInboxUrl(String trackerUrl)
    {
        String base = trackerUrl == null || trackerUrl.trim().isEmpty() ? TRACKER_URL : trackerUrl.trim();
        return base + "?open=roll-inbox";
    }

    /** Ask before replacing a pairing that works. */
    boolean confirmRepair()
    {
        Object[] options = {"Re-pair", "Cancel"};
        return JOptionPane.showOptionDialog(
            this,
            "<html><body style='width: 320px'>Pair RuneLite with a tracker profile again?"
                + "<br><br>RuneLite keeps using your current pairing until the new one"
                + " sends your rules. If none arrives within 10 minutes, nothing"
                + " changes.</body></html>",
            "Fate Locked re-pairing", JOptionPane.YES_NO_OPTION,
            JOptionPane.QUESTION_MESSAGE, null, options, options[1]) == 0;
    }

    /** Ask before forgetting the pairing; the rules in force stay (decision 9). */
    boolean confirmDisconnect()
    {
        Object[] options = {"Disconnect", "Cancel"};
        return JOptionPane.showOptionDialog(
            this,
            "<html><body style='width: 320px'>Disconnect RuneLite from the tracker?"
                + "<br><br>RuneLite stops checking for rules. The rules you have now stay in"
                + " use until you connect again or import others.</body></html>",
            "Fate Locked disconnect", JOptionPane.YES_NO_OPTION,
            JOptionPane.QUESTION_MESSAGE, null, options, options[1]) == 0;
    }

    boolean confirmNetworkConnection()
    {
        Object[] options = {"Enable online sync", "Cancel"};
        return JOptionPane.showOptionDialog(
            this,
            "<html><body style='width: 320px'>" + FateLockedConfig.NETWORK_WARNING
                + "<br><br>RuneLite retrieves rules from the Fate Locked relay. "
                + "It does not upload gameplay data.<br><br>Allow online sync?</body></html>",
            "Fate Locked online sync", JOptionPane.YES_NO_OPTION,
            JOptionPane.WARNING_MESSAGE, null, options, options[1]) == 0;
    }

    Sidebar sidebar()
    {
        return sidebar;
    }

    /**
     * Queue a sidebar update on the Swing thread, even from the Swing thread
     * itself, so updates from every thread apply in the order they were
     * made. Running it at once there let it overtake older updates still
     * queued from other threads: a "Not connected" could be followed by a
     * stale "Connected".
     */
    private static void queueOnEdt(Runnable update)
    {
        SwingUtilities.invokeLater(update);
    }
}

package com.fatelocked;

import net.runelite.api.WorldType;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

/**
 * Whether a detection counts, and may be recorded or earn a roll reminder:
 * rules for a run are loaded, they are bound to the logged-in character,
 * and the world's progress is that account's own. An unbound tracker
 * profile gets no reminders (owner decision, 25 September).
 */
final class DetectionGate
{
    /**
     * Worlds whose progress isn't the account's own: Leagues, Deadman,
     * tournament, beta and no-save worlds, Fresh Start worlds, quest
     * speedrunning, Last Man Standing and the PvP Arena.
     */
    private static final Set<WorldType> OTHER_GAMES = EnumSet.of(
        WorldType.SEASONAL, WorldType.DEADMAN, WorldType.TOURNAMENT_WORLD,
        WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.FRESH_START_WORLD,
        WorldType.QUEST_SPEEDRUNNING, WorldType.LAST_MAN_STANDING, WorldType.PVP_ARENA);

    private DetectionGate()
    {
    }

    static boolean allows(FateLockedBundle rules, String loggedInName, Set<WorldType> worldTypes)
    {
        if (rules == null || rules.getRunId() == null || rules.getRunId().trim().isEmpty())
        {
            return false;
        }
        String bound = AccountBinding.boundAccount(rules);
        return bound != null
            && AccountBinding.sameAccount(bound, loggedInName)
            && (worldTypes == null || Collections.disjoint(worldTypes, OTHER_GAMES));
    }
}

package com.fatelocked.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import javax.swing.plaf.basic.BasicGraphicsUtils;

/** A status in a word, in its colour on a faint fill of the same colour. */
public class StatusPill extends JComponent
{
    private static final int PAD_X = 6;

    private String word = "";
    private Palette.Tone tone = Palette.Tone.NEUTRAL;
    private Palette palette = Palette.defaults();

    public StatusPill()
    {
        setFont(Type.small());
        setOpaque(false);
    }

    public StatusPill(String word, Palette.Tone tone)
    {
        this();
        show(word, tone);
    }

    public void show(String word, Palette.Tone tone)
    {
        this.word = word == null ? "" : word;
        this.tone = tone;
        setVisible(!this.word.isEmpty());
        revalidate();
        repaint();
    }

    public void setPalette(Palette palette)
    {
        this.palette = palette;
        repaint();
    }

    public String getWord()
    {
        return word;
    }

    public Palette.Tone getTone()
    {
        return tone;
    }

    @Override
    public Dimension getPreferredSize()
    {
        FontMetrics metrics = getFontMetrics(getFont());
        return new Dimension(Draw.width(this, metrics, word) + 2 * PAD_X,
            metrics.getHeight() + 2);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int height = getHeight();
            g2.setColor(palette.pill(tone));
            g2.fillRoundRect(0, 0, getWidth(), height, height, height);
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g2.setFont(getFont());
            g2.setColor(palette.text(tone));
            FontMetrics metrics = getFontMetrics(getFont());
            int y = (height - metrics.getHeight()) / 2 + metrics.getAscent();
            BasicGraphicsUtils.drawString(this, g2, word, PAD_X, y);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.fatelocked.ui;

import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.PluginPanel;

/**
 * One thing in a list: its name and its status in a word, with the reason beneath
 * when there is one, wrapped to two lines at most.
 */
public class ItemRow extends JPanel
{
    /** The width a row's text wraps to before the first layout. */
    static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 2 * Space.EDGE - 2 * Space.PAD;

    private final ArtSlot art = new ArtSlot(Space.ICON);
    private final TextBlock name = new TextBlock(Type.body(), Palette.TEXT, 2, TEXT_WIDTH);
    private final StatusPill pill = new StatusPill();
    private final TextBlock reason = new TextBlock(Type.small(), Palette.TEXT_MUTED, 2, TEXT_WIDTH);

    public ItemRow()
    {
        super(new BorderLayout(0, 1));
        setOpaque(false);
        JPanel line = new JPanel(new BorderLayout(Space.ICON_GAP, 0));
        line.setOpaque(false);
        line.add(art, BorderLayout.WEST);
        line.add(name, BorderLayout.CENTER);
        // The pill keeps its own height when a long name wraps, beside the first line.
        JPanel pillSlot = new JPanel(new BorderLayout());
        pillSlot.setOpaque(false);
        pillSlot.add(pill, BorderLayout.NORTH);
        line.add(pillSlot, BorderLayout.EAST);
        add(line, BorderLayout.NORTH);
        add(reason, BorderLayout.CENTER);
        art.setVisible(false);
    }

    /**
     * @param word   the status in a word, or null for none
     * @param reason why, or null
     */
    public ItemRow show(String text, String word, Palette.Tone tone, String reason)
    {
        name.setText(text);
        pill.show(word, tone);
        this.reason.setText(reason);
        this.reason.setVisible(reason != null && !reason.isEmpty());
        return this;
    }

    /** Art beside the name; the reason then lines up under the name. */
    public ItemRow art(BufferedImage image)
    {
        art.setImage(image);
        art.setVisible(true);
        reason.setBorder(new EmptyBorder(0, Space.ICON + Space.ICON_GAP, 0, 0));
        return this;
    }

    public void setPalette(Palette palette)
    {
        pill.setPalette(palette);
    }

    /**
     * Makes the row answer a click, as a link does: the hand, a shade under the pointer, and
     * the action, wherever on the row the click lands.
     */
    public ItemRow onClick(Runnable action)
    {
        setBackground(Palette.HOVER);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        MouseAdapter click = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                action.run();
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                setOpaque(true);
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                setOpaque(false);
                repaint();
            }
        };
        addMouseListener(click);
        for (JComponent part : new JComponent[] {art, name, pill, reason})
        {
            part.addMouseListener(click);
        }
        return this;
    }

    /** Whether a click on the row does something. */
    public boolean clickable()
    {
        return getMouseListeners().length > 0;
    }

    /** What a click on the row does, as the player's click would. */
    public void click()
    {
        for (java.awt.event.MouseListener listener : getMouseListeners())
        {
            listener.mouseClicked(new MouseEvent(this, MouseEvent.MOUSE_CLICKED, 0, 0, 0, 0, 1, false));
        }
    }

    /** The row's name as shown. */
    public String title()
    {
        return name.getText();
    }

    public StatusPill pill()
    {
        return pill;
    }

    public TextBlock reason()
    {
        return reason;
    }
}

