package com.fatelocked.ui;

import com.fatelocked.rules.PermissionStatus;

/**
 * The words players read, as the web app says them. Every surface takes its status
 * words, names and tags from here, so the sidebar, the HUD, chat and the web guide
 * agree (U12).
 */
public final class Terms
{
    /** A place the run can use. */
    public static final String UNLOCKED = "Unlocked";
    /** A row the player can do now. */
    public static final String CAN_DO = "Can do";
    /** Owned, but not usable yet. */
    public static final String NOT_READY = "Not ready";
    public static final String LOCKED = "Locked";
    /** A row the tracker can't decide. */
    public static final String NEEDS_CHECKING = "Needs checking";
    /** A place the tracker doesn't map. */
    public static final String UNCHARTED = "Uncharted";
    /** Next to the unlocked area, in Chunked mode. */
    public static final String FRONTIER = "Frontier";

    public static final String STRICT_MODE = "Strict Mode";
    public static final String KEYS = "Keys";
    public static final String OMNI_KEYS = "Omni-Keys";
    public static final String CHAOS_KEYS = "Chaos Keys";
    public static final String FATE_POINTS = "Fate Points";
    public static final String DIFFERENT_CHARACTER = "Different character";

    /** Appended to a right-click option the rules lock. */
    public static final String LOCKED_TAG = " (Locked)";

    private Terms()
    {
    }

    /** What a place is, in a word. */
    public static String place(PermissionStatus status)
    {
        switch (status)
        {
            case ALLOWED:
                return UNLOCKED;
            case NOT_READY:
                return NOT_READY;
            case LOCKED:
                return LOCKED;
            default:
                return UNCHARTED;
        }
    }

    /** What a row of a place's content is, in a word. */
    public static String row(PermissionStatus status)
    {
        switch (status)
        {
            case ALLOWED:
                return CAN_DO;
            case NOT_READY:
                return NOT_READY;
            case LOCKED:
                return LOCKED;
            default:
                return NEEDS_CHECKING;
        }
    }

    /**
     * The ritual waiting on the next roll, by the name the web app gives it, or null
     * for none or one this build doesn't know, so a raw id is never shown.
     */
    public static String ritual(String id)
    {
        if ("LUCK".equals(id))
        {
            return "Ritual of Clarity";
        }
        if ("GREED".equals(id))
        {
            return "Ritual of Greed";
        }
        return null;
    }
}

package com.fatelocked.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/**
 * Stacks a container's visible children top to bottom, each at the container's full
 * width and its own preferred height, with a gap between them. A hidden child takes
 * no space and no gap, unlike RuneLite's grid layouts.
 */
public final class Stack implements LayoutManager
{
    private final int gap;

    public Stack(int gap)
    {
        this.gap = gap;
    }

    @Override
    public Dimension preferredLayoutSize(Container parent)
    {
        Insets insets = parent.getInsets();
        int width = 0;
        int height = 0;
        int shown = 0;
        for (Component child : parent.getComponents())
        {
            if (!child.isVisible())
            {
                continue;
            }
            Dimension size = child.getPreferredSize();
            width = Math.max(width, size.width);
            height += size.height;
            shown++;
        }
        height += Math.max(0, shown - 1) * gap;
        return new Dimension(width + insets.left + insets.right, height + insets.top + insets.bottom);
    }

    @Override
    public Dimension minimumLayoutSize(Container parent)
    {
        return preferredLayoutSize(parent);
    }

    @Override
    public void layoutContainer(Container parent)
    {
        Insets insets = parent.getInsets();
        int width = parent.getWidth() - insets.left - insets.right;
        int y = insets.top;
        for (Component child : parent.getComponents())
        {
            if (!child.isVisible())
            {
                continue;
            }
            int height = child.getPreferredSize().height;
            child.setBounds(insets.left, y, width, height);
            y += height + gap;
        }
    }

    @Override
    public void addLayoutComponent(String name, Component component)
    {
    }

    @Override
    public void removeLayoutComponent(Component component)
    {
    }
}

package com.fatelocked.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/**
 * Lays visible children left to right at their preferred sizes, wrapping to a new line
 * when the next one doesn't fit, and asks for the height the wrapped lines need. Before
 * the first layout it wraps to the width it was given.
 */
public final class Flow implements LayoutManager
{
    private final int hgap;
    private final int vgap;
    private final int widthHint;

    public Flow(int hgap, int vgap, int widthHint)
    {
        this.hgap = hgap;
        this.vgap = vgap;
        this.widthHint = widthHint;
    }

    @Override
    public Dimension preferredLayoutSize(Container parent)
    {
        Insets insets = parent.getInsets();
        int available = (parent.getWidth() > 0 ? parent.getWidth() : widthHint) - insets.left - insets.right;
        int x = 0;
        int lineHeight = 0;
        int height = 0;
        int widest = 0;
        boolean first = true;
        for (Component child : parent.getComponents())
        {
            if (!child.isVisible())
            {
                continue;
            }
            Dimension size = child.getPreferredSize();
            if (!first && x + hgap + size.width > available)
            {
                height += lineHeight + vgap;
                x = 0;
                lineHeight = 0;
                first = true;
            }
            x += (first ? 0 : hgap) + size.width;
            widest = Math.max(widest, x);
            lineHeight = Math.max(lineHeight, size.height);
            first = false;
        }
        height += lineHeight;
        return new Dimension(widest + insets.left + insets.right, height + insets.top + insets.bottom);
    }

    @Override
    public Dimension minimumLayoutSize(Container parent)
    {
        return preferredLayoutSize(parent);
    }

    @Override
    public void layoutContainer(Container parent)
    {
        Insets insets = parent.getInsets();
        int available = parent.getWidth() - insets.left - insets.right;
        int x = 0;
        int y = insets.top;
        int lineHeight = 0;
        boolean first = true;
        for (Component child : parent.getComponents())
        {
            if (!child.isVisible())
            {
                continue;
            }
            Dimension size = child.getPreferredSize();
            if (!first && x + hgap + size.width > available)
            {
                y += lineHeight + vgap;
                x = 0;
                lineHeight = 0;
                first = true;
            }
            int left = x + (first ? 0 : hgap);
            child.setBounds(insets.left + left, y, Math.min(size.width, available), size.height);
            x = left + size.width;
            lineHeight = Math.max(lineHeight, size.height);
            first = false;
        }
    }

    @Override
    public void addLayoutComponent(String name, Component component)
    {
    }

    @Override
    public void removeLayoutComponent(Component component)
    {
    }
}

package com.fatelocked.ui;

import java.time.Duration;

/** Phrases built from values: ages, short ids and counts, in sentence case. */
public final class Copy
{
    private static final String ELLIPSIS = "…";

    private Copy()
    {
    }

    /** How long ago something happened: "just now", "4 min ago", "3 h ago", "2 days ago". */
    public static String ago(Duration elapsed)
    {
        long seconds = elapsed.getSeconds();
        if (seconds < 60)
        {
            return "just now";
        }
        long minutes = seconds / 60;
        if (minutes < 60)
        {
            return minutes + " min ago";
        }
        long hours = minutes / 60;
        if (hours < 24)
        {
            return hours + " h ago";
        }
        long days = hours / 24;
        return days == 1 ? "1 day ago" : days + " days ago";
    }

    /** An id shown by its last four characters, so a screenshot never carries it whole. */
    public static String shortId(String id)
    {
        if (id == null || id.isEmpty())
        {
            return null;
        }
        return id.length() <= 4 ? id : ELLIPSIS + id.substring(id.length() - 4);
    }

    /** Progress in the unit the run counts. */
    public static String unlocked(int unlocked, int total, String unit)
    {
        return unlocked + " of " + total + " " + unit + " unlocked";
    }
}

package com.fatelocked.ui;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * OSRS art from the game cache, through RuneLite's sprite and item managers. Each
 * piece is loaded once and kept; callers waiting for the same piece are all answered
 * when it arrives. Swing thread only.
 */
public final class GameArt implements IconSource
{
    private final SpriteManager sprites;
    private final ItemManager items;
    private final Map<Art, BufferedImage> loaded = new EnumMap<>(Art.class);
    private final Map<Art, List<Consumer<BufferedImage>>> waiting = new EnumMap<>(Art.class);

    public GameArt(SpriteManager sprites, ItemManager items)
    {
        this.sprites = sprites;
        this.items = items;
    }

    @Override
    public void load(Art art, Consumer<BufferedImage> into)
    {
        BufferedImage image = loaded.get(art);
        if (image != null)
        {
            into.accept(image);
            return;
        }
        List<Consumer<BufferedImage>> queue = waiting.get(art);
        if (queue != null)
        {
            queue.add(into);
            return;
        }
        queue = new ArrayList<>();
        queue.add(into);
        waiting.put(art, queue);
        if (art.kind() == Art.Kind.SPRITE)
        {
            // Called back on the client thread, once the cache is ready.
            sprites.getSpriteAsync(art.id(), art.detail(), sprite -> deliver(art, sprite));
        }
        else
        {
            AsyncBufferedImage item = items.getImage(art.id(), art.detail(), false);
            item.onLoaded(() -> deliver(art, item));
        }
    }

    private void deliver(Art art, BufferedImage image)
    {
        SwingUtilities.invokeLater(() -> {
            List<Consumer<BufferedImage>> queue = waiting.remove(art);
            if (image == null)
            {
                return;
            }
            loaded.put(art, image);
            if (queue != null)
            {
                for (Consumer<BufferedImage> into : queue)
                {
                    into.accept(image);
                }
            }
        });
    }
}

package com.fatelocked.ui;

import java.awt.image.BufferedImage;
import java.util.function.Consumer;

/**
 * Where the sidebar gets its OSRS art. In the client it comes from the game cache,
 * which is ready only from the login screen, so art arrives late and views show
 * nothing in its place until it does.
 */
public interface IconSource
{
    /** No art at all: views draw without it. */
    IconSource NONE = (art, into) -> { };

    /** Hands the art to {@code into} on the Swing thread, now or once it has loaded. */
    void load(Art art, Consumer<BufferedImage> into);
}

package com.fatelocked.ui;

import java.awt.image.BufferedImage;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.util.ImageUtil;

/**
 * The game's small skill icons, as RuneLite ships them with the client, by the skill's
 * name. They need no game cache, so they are there from the start, and at 16 px or less
 * they are drawn 1:1 beside a line.
 */
public final class SkillArt
{
    private static final Map<String, Optional<BufferedImage>> LOADED = new ConcurrentHashMap<>();

    private SkillArt()
    {
    }

    /** The skill's icon, or null for a name that isn't a skill. */
    public static BufferedImage icon(String skill)
    {
        if (skill == null)
        {
            return null;
        }
        return LOADED.computeIfAbsent(skill.trim().toLowerCase(Locale.ROOT), SkillArt::load).orElse(null);
    }

    private static Optional<BufferedImage> load(String name)
    {
        String path = "/skill_icons_small/" + name + ".png";
        if (!name.matches("[a-z]+") || SkillIconManager.class.getResource(path) == null)
        {
            return Optional.empty();
        }
        return Optional.of(ImageUtil.loadImageResource(SkillIconManager.class, path));
    }
}

package com.fatelocked.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.ButtonModel;
import javax.swing.JButton;
import javax.swing.plaf.basic.BasicGraphicsUtils;

/**
 * A button drawn in the sidebar's own style. A card has at most one primary button,
 * in the accent; other actions are secondary, or a quiet link.
 */
public class FlatButton extends JButton
{
    public enum Kind
    {
        PRIMARY,
        SECONDARY,
        LINK
    }

    private static final int BUTTON_HEIGHT = 24;
    private static final int PAD_X = 10;

    private final Kind kind;

    public FlatButton(String text, Kind kind)
    {
        super(text);
        this.kind = kind;
        setFont(kind == Kind.PRIMARY ? Type.title() : Type.body());
        setContentAreaFilled(false);
        setBorderPainted(false);
        setFocusPainted(false);
        setOpaque(false);
        setRolloverEnabled(true);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
    }

    public Kind getKind()
    {
        return kind;
    }

    @Override
    public Dimension getPreferredSize()
    {
        FontMetrics metrics = getFontMetrics(getFont());
        int width = Draw.width(this, metrics, getText());
        return kind == Kind.LINK
            ? new Dimension(width, metrics.getHeight())
            : new Dimension(width + 2 * PAD_X, BUTTON_HEIGHT);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            ButtonModel model = getModel();
            boolean hover = model.isRollover() && isEnabled();
            boolean pressed = model.isArmed() && model.isPressed();
            FontMetrics metrics = getFontMetrics(getFont());
            int textWidth = Draw.width(this, metrics, getText());
            int x = (getWidth() - textWidth) / 2;
            int y = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
            g2.setFont(getFont());

            if (kind == Kind.LINK)
            {
                g2.setColor(isEnabled() ? Palette.ACCENT : Palette.TEXT_MUTED);
                BasicGraphicsUtils.drawString(this, g2, getText(), 0, y);
                if (hover)
                {
                    g2.fillRect(0, y + 1, textWidth, 1);
                }
                return;
            }

            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            Color fill;
            Color text;
            if (kind == Kind.PRIMARY)
            {
                fill = !isEnabled() ? Palette.CONTROL : pressed ? Palette.ACCENT.darker() : hover ? Palette.ACCENT.brighter() : Palette.ACCENT;
                text = isEnabled() ? Palette.ON_ACCENT : Palette.TEXT_MUTED;
            }
            else
            {
                fill = pressed ? Palette.CARD : hover ? Palette.CONTROL_HOVER : Palette.CONTROL;
                text = isEnabled() ? Palette.TEXT : Palette.TEXT_MUTED;
            }
            g2.setColor(fill);
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), Card.ARC, Card.ARC);
            g2.setColor(text);
            BasicGraphicsUtils.drawString(this, g2, getText(), x, y);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.fatelocked.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.plaf.basic.BasicGraphicsUtils;

/**
 * Text that wraps to its width, in at most a set number of lines. A line that is cut
 * ends in an ellipsis, and the tooltip then holds the whole text.
 *
 * <p>Its preferred height depends on its width: before the first layout it wraps to
 * the width it was given, and a new width re-lays the sidebar out.
 */
public class TextBlock extends JComponent
{
    private static final String ELLIPSIS = "…";

    private final int maxLines;
    private final int widthHint;
    private String text = "";
    private List<String> lines = Collections.emptyList();
    private int linesWidth = -1;
    private boolean cut;

    /**
     * @param maxLines  the most lines to show, or 0 for no limit
     * @param widthHint the width to wrap to before the first layout
     */
    public TextBlock(Font font, Color colour, int maxLines, int widthHint)
    {
        this.maxLines = maxLines;
        this.widthHint = widthHint;
        setFont(font);
        setForeground(colour);
        setOpaque(false);
    }

    public void setText(String text)
    {
        String next = text == null ? "" : text;
        if (next.equals(this.text))
        {
            return;
        }
        this.text = next;
        linesWidth = -1;
        revalidate();
        repaint();
    }

    public String getText()
    {
        return text;
    }

    /** The lines as drawn at the current width, for tests. */
    public List<String> lines()
    {
        return wrap(currentWidth());
    }

    @Override
    public String getToolTipText()
    {
        wrap(currentWidth());
        return cut ? text : super.getToolTipText();
    }

    @Override
    public Dimension getPreferredSize()
    {
        if (isPreferredSizeSet())
        {
            return super.getPreferredSize();
        }
        return new Dimension(widthHint, wrap(currentWidth()).size() * lineHeight());
    }

    @Override
    public void setBounds(int x, int y, int width, int height)
    {
        boolean resized = width != getWidth();
        super.setBounds(x, y, width, height);
        if (resized && !text.isEmpty())
        {
            revalidate();
        }
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setFont(getFont());
            g2.setColor(getForeground());
            FontMetrics metrics = getFontMetrics(getFont());
            int y = metrics.getAscent();
            for (String line : wrap(getWidth()))
            {
                BasicGraphicsUtils.drawString(this, g2, line, 0, y);
                y += lineHeight();
            }
        }
        finally
        {
            g2.dispose();
        }
    }

    private int currentWidth()
    {
        return getWidth() > 0 ? getWidth() : widthHint;
    }

    private int lineHeight()
    {
        return getFontMetrics(getFont()).getHeight();
    }

    private List<String> wrap(int width)
    {
        if (width == linesWidth)
        {
            return lines;
        }
        FontMetrics metrics = getFontMetrics(getFont());
        List<String> all = new ArrayList<>();
        for (String paragraph : text.split("\n", -1))
        {
            wrapParagraph(paragraph, width, metrics, all);
        }
        if (text.isEmpty())
        {
            all.clear();
        }
        cut = maxLines > 0 && all.size() > maxLines;
        if (cut)
        {
            List<String> kept = new ArrayList<>(all.subList(0, maxLines));
            kept.set(maxLines - 1, withEllipsis(kept.get(maxLines - 1), width, metrics));
            all = kept;
        }
        lines = Collections.unmodifiableList(all);
        linesWidth = width;
        return lines;
    }

    private void wrapParagraph(String paragraph, int width, FontMetrics metrics, List<String> out)
    {
        StringBuilder line = new StringBuilder();
        for (String word : paragraph.split(" "))
        {
            String candidate = line.length() == 0 ? word : line + " " + word;
            if (fits(candidate, width, metrics))
            {
                line.setLength(0);
                line.append(candidate);
                continue;
            }
            if (line.length() > 0)
            {
                out.add(line.toString());
                line.setLength(0);
            }
            // A word wider than the line breaks where it must.
            String rest = word;
            while (!fits(rest, width, metrics) && rest.length() > 1)
            {
                int end = rest.length() - 1;
                while (end > 1 && !fits(rest.substring(0, end), width, metrics))
                {
                    end--;
                }
                out.add(rest.substring(0, end));
                rest = rest.substring(end);
            }
            line.append(rest);
        }
        out.add(line.toString());
    }

    private String withEllipsis(String line, int width, FontMetrics metrics)
    {
        String base = line;
        while (!base.isEmpty() && !fits(base + ELLIPSIS, width, metrics))
        {
            base = base.substring(0, base.length() - 1);
        }
        return base.replaceAll("[\\s,;:.]+$", "") + ELLIPSIS;
    }

    private boolean fits(String candidate, int width, FontMetrics metrics)
    {
        return Draw.width(this, metrics, candidate) <= width;
    }
}

package com.fatelocked.ui;

import com.fatelocked.rules.PermissionStatus;
import java.awt.BasicStroke;
import java.awt.Color;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.client.ui.ColorScheme;

/**
 * Every colour the plugin draws with, in the sidebar and in game.
 *
 * <p>Surfaces and neutral text are RuneLite's own. Statuses come from a preset: the
 * default, one safe for colour-blind players (Okabe-Ito based), or the player's
 * custom colours. Colour never carries a status alone: text says it in a word, and
 * a locked edge is dashed over a dark underlay in every preset.
 */
public final class Palette
{
    public enum Preset
    {
        DEFAULT,
        COLOUR_BLIND_SAFE,
        CUSTOM
    }

    /** What a colour means, whatever the preset draws it with. */
    public enum Tone
    {
        /** Unlocked, can do, up to date. */
        GOOD,
        /** Not ready, waiting, may be out of date. */
        PENDING,
        /** Locked, failed, a different character. */
        BAD,
        /** Uncharted, needs checking, not connected. */
        NEUTRAL,
        /** Next to the unlocked area, in Chunked mode. */
        FRONTIER
    }

    /** The sidebar's background: RuneLite's own. */
    public static final Color PANEL = ColorScheme.DARK_GRAY_COLOR;
    /** A card on the sidebar. */
    public static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
    /** A header or row under the mouse, on a card: RuneLite's own card hover. */
    public static final Color HOVER = ColorScheme.DARKER_GRAY_HOVER_COLOR;
    /** A tile raised a little from its card. */
    public static final Color RAISED = new Color(38, 38, 38);
    /** A line between groups inside a card. */
    public static final Color HAIRLINE = new Color(50, 50, 50);
    /** A track behind a progress bar. */
    public static final Color TRACK = new Color(52, 52, 52);
    /** A secondary button. */
    public static final Color CONTROL = new Color(52, 52, 52);
    /** A secondary button under the mouse. */
    public static final Color CONTROL_HOVER = new Color(64, 64, 64);
    /** A switch that is off. */
    public static final Color SWITCH_OFF = new Color(76, 76, 76);
    /** Titles, in white as RuneLite's own panels have them. */
    public static final Color TITLE = Color.WHITE;
    /** Body text and values: RuneLite's own label colour. */
    public static final Color TEXT = ColorScheme.TEXT_COLOR;
    /** Labels and secondary lines. */
    public static final Color TEXT_MUTED = ColorScheme.LIGHT_GRAY_COLOR;
    /** The one accent: the web app's gold. */
    public static final Color ACCENT = new Color(251, 191, 36);
    /** Text drawn on the accent. */
    public static final Color ON_ACCENT = new Color(30, 30, 30);

    /** Beneath every locked edge, so it reads on any terrain and in any vision. */
    public static final Color UNDERLAY = new Color(0, 0, 0, 150);
    /** A chunk edge that isn't locked, in "all edges" mode. */
    public static final Color PLAIN_EDGE = new Color(255, 255, 255, 70);
    public static final BasicStroke LOCKED_EDGE_STROKE = new BasicStroke(3f, BasicStroke.CAP_BUTT,
        BasicStroke.JOIN_ROUND, 10f, new float[]{8f, 5f}, 0f);
    public static final BasicStroke UNDERLAY_STROKE = new BasicStroke(5f, BasicStroke.CAP_BUTT,
        BasicStroke.JOIN_ROUND);
    /** Each dash of a locked edge on the game view and the minimap, which are cut on the ground, not by the stroke. */
    public static final BasicStroke LOCKED_DASH_STROKE = new BasicStroke(3f, BasicStroke.CAP_BUTT,
        BasicStroke.JOIN_ROUND);
    public static final BasicStroke PLAIN_EDGE_STROKE = new BasicStroke(1f);

    private static final int PILL_ALPHA = 40;

    private static final Palette DEFAULT_PALETTE = new Palette(
        texts(new Color(52, 211, 153), new Color(245, 158, 11), new Color(248, 113, 113),
            new Color(250, 204, 21)),
        new Color(60, 10, 10, 110), new Color(250, 204, 21, 130), new Color(248, 113, 113));

    private static final Palette COLOUR_BLIND_PALETTE = new Palette(
        texts(new Color(86, 180, 233), new Color(230, 159, 0), new Color(248, 113, 113),
            new Color(240, 228, 66)),
        new Color(20, 20, 40, 110), new Color(240, 228, 66, 120), new Color(248, 113, 113));

    private final Map<Tone, Color> text;
    private final Map<Tone, Color> pill = new EnumMap<>(Tone.class);
    private final Map<Tone, String> hex = new EnumMap<>(Tone.class);
    private final Color lockedShade;
    private final Color frontierFill;
    private final Color lockedEdge;

    private Palette(Map<Tone, Color> text, Color lockedShade, Color frontierFill, Color lockedEdge)
    {
        this.text = text;
        this.lockedShade = lockedShade;
        this.frontierFill = frontierFill;
        this.lockedEdge = lockedEdge;
        for (Map.Entry<Tone, Color> tone : text.entrySet())
        {
            pill.put(tone.getKey(), over(tone.getValue(), PILL_ALPHA, CARD));
            hex.put(tone.getKey(), String.format("%06x", tone.getValue().getRGB() & 0xFFFFFF));
        }
    }

    public static Palette defaults()
    {
        return DEFAULT_PALETTE;
    }

    /**
     * The palette for a preset. The custom colours apply only to {@link Preset#CUSTOM}:
     * unlocked colours unlocked text, frontier fills the frontier, and locked colours
     * locked text, edges and the locked shade, which keeps its alpha.
     */
    public static Palette of(Preset preset, Color unlocked, Color frontier, Color locked)
    {
        switch (preset)
        {
            case COLOUR_BLIND_SAFE:
                return COLOUR_BLIND_PALETTE;
            case CUSTOM:
                Color lockedText = opaque(locked);
                return new Palette(texts(opaque(unlocked), DEFAULT_PALETTE.text(Tone.PENDING), lockedText,
                    opaque(frontier)), locked, frontier, lockedText);
            default:
                return DEFAULT_PALETTE;
        }
    }

    /** The tone a rules decision is drawn in. */
    public static Tone tone(PermissionStatus status)
    {
        switch (status)
        {
            case ALLOWED:
                return Tone.GOOD;
            case NOT_READY:
                return Tone.PENDING;
            case LOCKED:
                return Tone.BAD;
            default:
                return Tone.NEUTRAL;
        }
    }

    /** Text in a tone, on the panel or a card. */
    public Color text(Tone tone)
    {
        return text.get(tone);
    }

    /** The opaque fill behind a status pill's word, on a card. */
    public Color pill(Tone tone)
    {
        return pill.get(tone);
    }

    /** A tone as {@code rrggbb} for game text's {@code <col=>} tags. */
    public String hex(Tone tone)
    {
        return hex.get(tone);
    }

    /** Locked land on the world map and the minimap: darker, like fog. */
    public Color lockedShade()
    {
        return lockedShade;
    }

    /** The frontier on the world map, in Chunked mode. */
    public Color frontierFill()
    {
        return frontierFill;
    }

    /** A locked edge in the scene and on the minimap, drawn dashed over the underlay. */
    public Color lockedEdge()
    {
        return lockedEdge;
    }

    /** The fade when a locked area is entered. */
    public Color flash()
    {
        return lockedEdge;
    }

    private static Map<Tone, Color> texts(Color good, Color pending, Color bad, Color frontier)
    {
        Map<Tone, Color> text = new EnumMap<>(Tone.class);
        text.put(Tone.GOOD, good);
        text.put(Tone.PENDING, pending);
        text.put(Tone.BAD, bad);
        text.put(Tone.NEUTRAL, TEXT_MUTED);
        text.put(Tone.FRONTIER, frontier);
        return text;
    }

    private static Color opaque(Color colour)
    {
        return new Color(colour.getRed(), colour.getGreen(), colour.getBlue());
    }

    /** {@code top} at {@code alpha} over an opaque {@code bottom}, as Java2D composites it. */
    static Color over(Color top, int alpha, Color bottom)
    {
        float a = alpha / 255f;
        return new Color(
            Math.round(a * top.getRed() + (1 - a) * bottom.getRed()),
            Math.round(a * top.getGreen() + (1 - a) * bottom.getGreen()),
            Math.round(a * top.getBlue() + (1 - a) * bottom.getBlue()));
    }
}

package com.fatelocked.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JToggleButton;

/** An on/off switch: the accent when on, grey when off. */
public class ToggleSwitch extends JToggleButton
{
    private static final int TRACK_WIDTH = 28;
    private static final int TRACK_HEIGHT = 16;
    private static final int KNOB = 12;

    public ToggleSwitch()
    {
        setContentAreaFilled(false);
        setBorderPainted(false);
        setFocusPainted(false);
        setOpaque(false);
        setRolloverEnabled(true);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
    }

    @Override
    public Dimension getPreferredSize()
    {
        return new Dimension(TRACK_WIDTH, TRACK_HEIGHT);
    }

    @Override
    public Dimension getMaximumSize()
    {
        return getPreferredSize();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            boolean on = isSelected();
            boolean hover = getModel().isRollover() && isEnabled();
            int y = (getHeight() - TRACK_HEIGHT) / 2;
            Color track = !isEnabled() ? Palette.SWITCH_OFF : on ? (hover ? Palette.ACCENT.brighter() : Palette.ACCENT)
                : hover ? Palette.SWITCH_OFF.brighter() : Palette.SWITCH_OFF;
            g2.setColor(track);
            g2.fillRoundRect(0, y, TRACK_WIDTH, TRACK_HEIGHT, TRACK_HEIGHT, TRACK_HEIGHT);
            int inset = (TRACK_HEIGHT - KNOB) / 2;
            int knobX = on ? TRACK_WIDTH - inset - KNOB : inset;
            g2.setColor(on ? Palette.ON_ACCENT : Palette.TITLE);
            g2.fillOval(knobX, y + inset, KNOB, KNOB);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.fatelocked.ui;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * A square for a piece of OSRS art. It stays empty until the art arrives, since
 * sprites load from the game cache after the sidebar is built. Art larger than the
 * square is scaled down to fit; smaller art is drawn at its own size, centred.
 */
public class ArtSlot extends JComponent
{
    private final int size;
    private BufferedImage image;

    public ArtSlot(int size)
    {
        this.size = size;
        setOpaque(false);
    }

    public void setImage(BufferedImage image)
    {
        this.image = image == null ? null : trim(image);
        repaint();
    }

    /** The image without its fully transparent margins, as item art has. */
    static BufferedImage trim(BufferedImage image)
    {
        int left = image.getWidth();
        int top = image.getHeight();
        int right = -1;
        int bottom = -1;
        for (int y = 0; y < image.getHeight(); y++)
        {
            for (int x = 0; x < image.getWidth(); x++)
            {
                if ((image.getRGB(x, y) >>> 24) != 0)
                {
                    left = Math.min(left, x);
                    top = Math.min(top, y);
                    right = Math.max(right, x);
                    bottom = Math.max(bottom, y);
                }
            }
        }
        if (right < 0 || left == 0 && top == 0 && right == image.getWidth() - 1 && bottom == image.getHeight() - 1)
        {
            return image;
        }
        return image.getSubimage(left, top, right - left + 1, bottom - top + 1);
    }

    public BufferedImage getImage()
    {
        return image;
    }

    @Override
    public Dimension getPreferredSize()
    {
        return new Dimension(size, size);
    }

    @Override
    public Dimension getMinimumSize()
    {
        return getPreferredSize();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        if (image == null)
        {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            int w = image.getWidth();
            int h = image.getHeight();
            if (w > size || h > size)
            {
                double scale = Math.min(size / (double) w, size / (double) h);
                w = (int) Math.round(w * scale);
                h = (int) Math.round(h * scale);
                g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
                g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
            }
            g2.drawImage(image, (getWidth() - w) / 2, (getHeight() - h) / 2, w, h, null);
        }
        finally
        {
            g2.dispose();
        }
    }
}

package com.fatelocked.ui;

import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/** A slim bar: how much of the run is unlocked. */
public class ProgressBar extends JComponent
{
    private static final int BAR_HEIGHT = 4;

    private double fraction;

    public void setFraction(double fraction)
    {
        this.fraction = Math.max(0, Math.min(1, fraction));
        repaint();
    }

    public double getFraction()
    {
        return fraction;
    }

    @Override
    public Dimension getPreferredSize()
    {
        return new Dimension(0, BAR_HEIGHT);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        try
        {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(Palette.TRACK);
            g2.fillRoundRect(0, 0, getWidth(), BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
            int filled = (int) Math.round(getWidth() * fraction);
            if (filled > 0)
            {
                g2.setColor(Palette.ACCENT);
                g2.fillRoundRect(0, 0, Math.max(filled, BAR_HEIGHT), BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
            }
        }
        finally
        {
            g2.dispose();
        }
    }
}

