package com.fatelocked;

import com.fatelocked.sidebar.PointTarget;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Finds what a row of the Here card points at (the owner's review, 28 Sept): the nearest
 * object or NPC by that name in the loaded scene, inside the chunk the player stands in,
 * on their own floor first. The scene is placed zone by zone through {@link ChunkLocator},
 * so an instance is searched as the chunk it copies. Client thread, on a click only.
 */
final class SceneSearch
{
    /** Instances are copied in 8-tile zones, and a zone never straddles a chunk line. */
    private static final int ZONE_TILES = 8;

    private SceneSearch()
    {
    }

    /** What was found: an NPC, or an object at a point; on the player's floor or another. */
    @Value
    static class Found
    {
        /** The NPC, or null for an object. */
        NPC npc;
        LocalPoint point;
        boolean sameFloor;
        /** How far from the player, in local units. */
        int distance;
    }

    /** The nearest thing the target names in the chunk, or null: none loaded, or no player on the land. */
    static Found nearest(Client client, ChunkLocator locator, CanonicalChunk chunk, PointTarget target)
    {
        WorldView view = client.getTopLevelWorldView();
        Player player = client.getLocalPlayer();
        if (view == null || player == null || chunk == null || target == null || player.getWorldView() != view)
        {
            return null;
        }
        LocalPoint from = player.getLocalLocation();
        if (from == null)
        {
            return null;
        }
        Found best = null;
        if (view.npcs() != null)
        {
            for (NPC npc : view.npcs())
            {
                if (npc == null)
                {
                    continue;
                }
                NPCComposition shown = npc.getTransformedComposition();
                String name = shown != null ? shown.getName() : npc.getName();
                if (!target.matches(name, shown != null ? shown.getActions() : null)
                    || !chunk.equals(locator.actor(npc)))
                {
                    continue;
                }
                LocalPoint at = npc.getLocalLocation();
                if (at != null)
                {
                    // NPCs near the player walk the player's floor.
                    best = nearer(best, new Found(npc, at, true, from.distanceTo(at)));
                }
            }
        }
        Scene scene = view.getScene();
        Tile[][][] tiles = scene == null ? null : scene.getTiles();
        if (tiles == null)
        {
            return best;
        }
        int floor = view.getPlane();
        Set<TileObject> seen = Collections.newSetFromMap(new IdentityHashMap<>());
        for (int zoneX = 0; zoneX * ZONE_TILES < view.getSizeX(); zoneX++)
        {
            for (int zoneY = 0; zoneY * ZONE_TILES < view.getSizeY(); zoneY++)
            {
                if (!chunk.equals(locator.sceneZone(zoneX, zoneY)))
                {
                    continue;
                }
                for (int plane = 0; plane < tiles.length; plane++)
                {
                    for (int x = zoneX * ZONE_TILES; x < (zoneX + 1) * ZONE_TILES && x < tiles[plane].length; x++)
                    {
                        for (int y = zoneY * ZONE_TILES; y < (zoneY + 1) * ZONE_TILES && y < tiles[plane][x].length;
                            y++)
                        {
                            Tile tile = tiles[plane][x][y];
                            if (tile == null)
                            {
                                continue;
                            }
                            for (TileObject object : objectsOn(tile))
                            {
                                if (object == null || !seen.add(object) || !named(client, object, target))
                                {
                                    continue;
                                }
                                LocalPoint at = object.getLocalLocation();
                                if (at != null)
                                {
                                    best = nearer(best, new Found(null, at, object.getPlane() == floor,
                                        from.distanceTo(at)));
                                }
                            }
                        }
                    }
                }
            }
        }
        return best;
    }

    /** Whether an object is the target, by the name and options it shows now. */
    private static boolean named(Client client, TileObject object, PointTarget target)
    {
        ObjectComposition shown = shown(client, object);
        return shown != null && target.matches(shown.getName(), shown.getActions());
    }

    /** What an object shows now: the one it stands for, as a patch does as it grows, or itself. Client thread. */
    static ObjectComposition shown(Client client, TileObject object)
    {
        ObjectComposition shown = client.getObjectDefinition(object.getId());
        if (shown != null && shown.getImpostorIds() != null)
        {
            ObjectComposition now = shown.getImpostor();
            shown = now != null ? now : shown;
        }
        return shown;
    }

    private static TileObject[] objectsOn(Tile tile)
    {
        GameObject[] games = tile.getGameObjects();
        int count = games == null ? 0 : games.length;
        TileObject[] all = new TileObject[count + 3];
        for (int i = 0; i < count; i++)
        {
            all[i] = games[i];
        }
        all[count] = tile.getWallObject();
        all[count + 1] = tile.getDecorativeObject();
        all[count + 2] = tile.getGroundObject();
        return all;
    }

    /** On the player's floor first, then the closer. */
    private static Found nearer(Found best, Found next)
    {
        if (best == null)
        {
            return next;
        }
        if (best.isSameFloor() != next.isSameFloor())
        {
            return next.isSameFloor() ? next : best;
        }
        return next.getDistance() < best.getDistance() ? next : best;
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.Trust;
import com.fatelocked.ui.Palette;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Point2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The scene's chunk lines on the minimap, from the same edges as the game view (U3): locked
 * edges dashed over the dark underlay and, under All edges, the other chunk lines thin and
 * faint. With "shade locked land nearby" the locked land is darkened like fog. Nothing fills
 * the chunk the player stands in, and nothing is drawn without rules for the character playing.
 */
public class FateLockedMinimapOverlay extends Overlay
{
    /**
     * How far from the player a point still projects, in local units: past the whole loaded
     * scene, so a block of locked land is placed whole. The minimap's clip drops the rest.
     */
    private static final int PROJECTION_DISTANCE = 30000;

    /** The minimap in each layout: fixed, resizable, and resizable with the bottom bar. */
    static final int[] MINIMAPS = {
        InterfaceID.Toplevel.MINIMAP,
        InterfaceID.ToplevelOsrsStretch.MINIMAP,
        InterfaceID.ToplevelPreEoc.MINIMAP,
    };

    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    @Inject
    FateLockedMinimapOverlay(Client client, FateLockedPlugin plugin, FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.drawMinimap()) return null;
        DecisionService decisions = plugin.decisions();
        // Another character's rules, or none, draw nothing (B6).
        if (decisions.trust() != Trust.TRUSTED) return null;
        Shape minimap = minimapClip();
        if (minimap == null) return null;
        WorldView view = client.getTopLevelWorldView();
        Located here = plugin.chunkLocator().playerInScene();
        if (view == null || here == null) return null;

        draw(graphics, minimap, plugin.sceneEdges(decisions, view, here.getPlane()), config.chunkBorders(),
            config.shadeNearbyLocked(), plugin.palette(), here.getSceneX(), here.getSceneY(),
            view.getSizeX(), view.getSizeY(), (x, y) ->
            {
                Point dot = Perspective.localToMinimap(client, FateLockedSceneOverlay.corner(x, y, view),
                    PROJECTION_DISTANCE);
                return dot == null ? null : new Point2D.Double(dot.getX(), dot.getY());
            });
        return null;
    }

    /**
     * Draw the scene inside the minimap: the locked land first, when it is shaded, then the
     * lines. The locked edges always show, the minimap's own setting being on; the other
     * chunk lines follow the game view's All edges.
     */
    static void draw(Graphics2D graphics, Shape minimap, SceneEdges scene, FateLockedConfig.ChunkBorders borders,
        boolean fog, Palette palette, int playerX, int playerY, int sizeX, int sizeY,
        ChunkBorderRenderer.Projector projector)
    {
        // A projected chunk is far bigger than the minimap, so everything is clipped to it.
        Shape before = graphics.getClip();
        graphics.clip(minimap);
        if (fog)
        {
            graphics.setColor(palette.lockedShade());
            graphics.fill(ChunkBorderRenderer.blocks(scene.locked(), projector));
        }
        FateLockedConfig.ChunkBorders lines = borders == FateLockedConfig.ChunkBorders.ALL_EDGES
            ? FateLockedConfig.ChunkBorders.ALL_EDGES : FateLockedConfig.ChunkBorders.LOCKED_EDGES;
        ChunkBorderRenderer.draw(graphics, scene.edges(), lines, false, palette, playerX, playerY, sizeX, sizeY,
            projector, ChunkBorderRenderer.MINIMAP_PERIOD, ChunkBorderRenderer.Occlusion.NONE);
        graphics.setClip(before);
    }

    /** The minimap shown in the current layout, as its round draw area; null when none is. */
    private Shape minimapClip()
    {
        for (int id : MINIMAPS)
        {
            Widget minimap = client.getWidget(id);
            if (minimap == null || minimap.isHidden()) continue;
            Rectangle bounds = minimap.getBounds();
            if (bounds != null && bounds.width > 0 && bounds.height > 0)
            {
                return new Ellipse2D.Double(bounds.x, bounds.y, bounds.width, bounds.height);
            }
        }
        return null;
    }
}

package com.fatelocked;

/**
 * One per plugin start. Work queued for later, on the client thread, the
 * Swing thread or RuneLite's executor, is wrapped by the session that queued
 * it and does nothing once that session has ended, even if the plugin has
 * been started again since.
 */
final class PluginSession
{
    private volatile boolean active = true;

    /** A session that has already ended, for a plugin that is not running. */
    static PluginSession ended()
    {
        PluginSession session = new PluginSession();
        session.end();
        return session;
    }

    boolean isActive()
    {
        return active;
    }

    void end()
    {
        active = false;
    }

    /** The task, run only if this session is still active when it runs. */
    Runnable guard(Runnable task)
    {
        return () ->
        {
            if (active)
            {
                task.run();
            }
        };
    }
}

