package com.fatelocked.rules;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;
import com.fatelocked.MenuFacts;

import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * The one reader of the tracker's rules. Every surface (sidebar, HUD,
 * overlays, alerts, tags, warnings and Strict Mode) asks it, so they can't
 * disagree. It only looks answers up: missing data stays Unknown and a lock
 * is never inferred from a gap.
 *
 * <p>Immutable, so it can be published to overlays through a volatile
 * field. A new one is made when the rules or the logged-in character change.
 */
public final class DecisionService
{
    private static final String WRONG_ACCOUNT = "Wrong account";

    private final RulesSnapshot rules;
    private final Trust trust;
    private final boolean bound;

    private DecisionService(RulesSnapshot rules, Trust trust, boolean bound)
    {
        this.rules = rules;
        this.trust = trust;
        this.bound = bound;
    }

    /**
     * @param boundAccount    the account the rules are for, normalised the
     *                        tracker's way; null or empty when bound to no one
     * @param loggedInAccount the logged-in character, normalised the same
     *                        way; null or empty when nobody is logged in
     */
    public static DecisionService create(RulesSnapshot rules, String boundAccount, String loggedInAccount)
    {
        RulesSnapshot snapshot = rules == null ? RulesSnapshot.empty() : rules;
        boolean bound = boundAccount != null && !boundAccount.isEmpty();
        Trust trust;
        if (snapshot.isEmpty()) trust = Trust.NO_RULES;
        else if (!bound) trust = Trust.TRUSTED;
        else if (loggedInAccount == null || loggedInAccount.isEmpty()) trust = Trust.LOGGED_OUT;
        else trust = boundAccount.equals(loggedInAccount) ? Trust.TRUSTED : Trust.WRONG_CHARACTER;
        return new DecisionService(snapshot, trust, bound);
    }

    public Trust trust()
    {
        return trust;
    }

    /** Whether the rules name an account. Strict Mode acts only on bound rules. */
    public boolean isBound()
    {
        return bound;
    }

    /** Why the rules don't apply right now; null when they do. */
    public String trustReason()
    {
        switch (trust)
        {
            case NO_RULES: return "No tracker rules are loaded";
            case LOGGED_OUT: return "Not logged in";
            case WRONG_CHARACTER: return WRONG_ACCOUNT;
            default: return null;
        }
    }

    public RulesSnapshot rules()
    {
        return rules;
    }

    /** Whether a chunk may be entered, and why not in the tracker's words (E8). */
    public Decision chunk(CanonicalChunk chunk)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (chunk == null) return unmapped(null);
        if (rules.isLegacy()) return rules.legacy().chunk(chunk);
        Optional<ChunkPermissionSnapshot> snapshot = rules.bundle().permissionsAt(chunk);
        if (!snapshot.isPresent()) return place(chunk);
        ChunkPermissionSnapshot value = snapshot.get();
        return new Decision(value.getEntry(),
            value.getName() == null ? value.getChunkKey() : value.getName(),
            value.getEntryReason(), Decision.Source.CHUNK);
    }

    /**
     * A chunk with no snapshot: the ocean or an interior, as the tracker's
     * entries say (R1), named as its places name it. Unmapped when the rules
     * send no entries, or none for this chunk.
     */
    private Decision place(CanonicalChunk chunk)
    {
        PermissionStatus entry = rules.entryAt(chunk);
        if (entry == null) return unmapped(null);
        RuneliteRulesManifest.Place place = rules.placeAt(chunk);
        String label = place == null ? null : place.isOcean() ? "Ocean" : interiorName(place);
        return new Decision(entry, label, null, Decision.Source.CHUNK);
    }

    /** An interior's name, else the area it belongs to; null when the places give neither. */
    private static String interiorName(RuneliteRulesManifest.Place place)
    {
        return place.getName() != null ? place.getName() : place.getArea();
    }

    /**
     * The tracker's travel table, on any character: what a click is isn't a
     * decision (F2). Null when the rules have none, as older rules don't.
     */
    public TravelTable travelTable()
    {
        return rules.travelTable();
    }

    /**
     * A travel option's decision, as the tracker's table has it for the run
     * (F3): it counts the unlocks the method needs and where it lands.
     */
    public Decision travel(TravelTable.Method method, TravelTable.Option option)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (method == null || option == null) return unmapped(null);
        return new Decision(option.getStatus(), method.getLabel(), option.getReason(), Decision.Source.TRAVEL);
    }

    /** The tracker's rows for a chunk, for the sidebar; empty unless the rules apply. */
    public Optional<ChunkPermissionSnapshot> details(CanonicalChunk chunk)
    {
        if (trust != Trust.TRUSTED || rules.isLegacy() || chunk == null) return Optional.empty();
        return rules.bundle().permissionsAt(chunk);
    }

    /**
     * A row inside a chunk's rules, matched by kind and name (either may be
     * empty to match any). A locked chunk locks everything in it.
     */
    public Decision target(CanonicalChunk chunk, String targetKind, String targetName)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (rules.isLegacy() || chunk == null) return unmapped(targetName);
        Optional<ChunkPermissionSnapshot> optional = rules.bundle().permissionsAt(chunk);
        if (!optional.isPresent()) return unmapped(targetName);
        ChunkPermissionSnapshot snapshot = optional.get();
        String kind = normalizeTarget(targetKind);
        String name = normalizeTarget(targetName);
        for (Map.Entry<String, List<ChunkPermissionRow>> category : snapshot.getCategories().entrySet())
        {
            for (ChunkPermissionRow row : category.getValue())
            {
                boolean kindMatches = kind.isEmpty() || kind.equals(normalizeTarget(row.getTargetKind()));
                boolean nameMatches = name.isEmpty() || name.equals(normalizeTarget(row.getName()));
                if (!kindMatches || !nameMatches) continue;
                PermissionStatus status = snapshot.getEntry() == PermissionStatus.LOCKED
                    ? PermissionStatus.LOCKED : row.getStatus();
                return new Decision(status, row.getName(), row.getDetail(), Decision.Source.ROW);
            }
        }
        return unmapped(targetName);
    }

    /**
     * What a chunk is called, on any character: names aren't decisions. The
     * tracker's name for it, else the area name older exports also carry
     * ("Falador · Asgarnia"); null when the rules name neither.
     */
    public String chunkName(CanonicalChunk chunk)
    {
        if (chunk == null) return null;
        String name = snapshotAt(chunk).map(ChunkPermissionSnapshot::getName).orElse(null);
        return isBlank(name) ? rules.areaLabel(chunk) : name;
    }

    /**
     * The area a chunk belongs to, on any character: the tracker's own, with
     * its region ("Draynor Village · Misthalin") (E8); an interior's name
     * from the rules' places; else as an older export's area lists name it.
     * Null when unnamed, as the sea is. The HUD's "Here" line shows it.
     */
    public String areaName(CanonicalChunk chunk)
    {
        if (chunk == null) return null;
        Optional<ChunkPermissionSnapshot> snapshot = snapshotAt(chunk);
        if (snapshot.isPresent() && snapshot.get().getArea() != null)
        {
            String area = snapshot.get().getArea();
            String region = snapshot.get().getRegion();
            return isBlank(region) || region.trim().equals(area) ? area : area + " · " + region.trim();
        }
        RuneliteRulesManifest.Place place = snapshot.isPresent() ? null : rules.placeAt(chunk);
        if (place != null && !place.isOcean() && interiorName(place) != null) return interiorName(place);
        return rules.areaLabel(chunk);
    }

    /** The region (continent) a chunk is in, on any character; null when the rules don't say. */
    public String regionName(CanonicalChunk chunk)
    {
        if (chunk == null) return null;
        String region = snapshotAt(chunk).map(ChunkPermissionSnapshot::getRegion).orElse(null);
        return isBlank(region) ? rules.regionAt(chunk) : region;
    }

    /**
     * The chunks the rules decide, for the world map: the tracker's land, or
     * an older export's areas. The sea the rules don't cover isn't in it.
     */
    public Set<CanonicalChunk> mappedChunks()
    {
        return rules.mappedChunks();
    }

    /** How much of the run is unlocked; null unless the rules apply to this character. */
    public Progress progress()
    {
        return trust == Trust.TRUSTED ? rules.progress() : null;
    }

    /**
     * Whether a Slayer task can be done (B11): LOCKED when every chunk its
     * monsters live in is locked, ALLOWED when any is owned, and Unknown
     * otherwise, since a lock is never inferred from a gap. A known master's
     * own list decides when the tracker has one (Krystilia's tasks are in the
     * Wilderness), and a place Konar names decides alone; otherwise every
     * master's merged list, then the chunks' monster lists.
     *
     * @param master   the master as the tracker names them, or null when unknown
     * @param location Konar's place, or null
     */
    public Decision slayerTask(String master, String task, String location)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (isBlank(task)) return unmapped(null);
        // The tracker's own decision (R16): the master's first, else the task's whatever the master.
        if (rules.hasSlayerTasks())
        {
            String named = isBlank(location) ? task.trim() : task.trim() + " - " + location.trim();
            RuneliteRulesManifest.SlayerTask decided = isBlank(master) ? null : rules.slayerTaskAt(master.trim() + ":" + named);
            if (decided == null) decided = rules.slayerTaskAt(named);
            if (decided != null) return new Decision(decided.getStatus(), task, decided.getReason(), Decision.Source.SLAYER);
        }
        Set<CanonicalChunk> chunks = slayerChunks(master, task.trim(), location);
        if (chunks.isEmpty()) return unmapped(task);
        boolean allLocked = true;
        for (CanonicalChunk where : chunks)
        {
            PermissionStatus status = chunk(where).getStatus();
            if (status == PermissionStatus.ALLOWED || status == PermissionStatus.NOT_READY)
            {
                return new Decision(PermissionStatus.ALLOWED, task, null, Decision.Source.SLAYER);
            }
            if (status != PermissionStatus.LOCKED) allLocked = false;
        }
        return allLocked
            ? new Decision(PermissionStatus.LOCKED, task, "Only in locked areas", Decision.Source.SLAYER)
            : unmapped(task);
    }

    /** Where a task's monsters live: the most specific list the tracker has for it. */
    private Set<CanonicalChunk> slayerChunks(String master, String task, String location)
    {
        String named = isBlank(location) ? task : task + " - " + location.trim();
        Set<CanonicalChunk> mastersOwn = isBlank(master) ? null : rules.slayerChunks(master.trim() + ":" + named);
        if (mastersOwn != null) return mastersOwn;
        Set<CanonicalChunk> merged = rules.slayerChunks(named);
        // A named place is the whole task: other places don't count.
        if (!isBlank(location)) return merged == null ? Collections.emptySet() : merged;
        return merged == null || merged.isEmpty() ? rules.monsterChunks(task) : merged;
    }

    /** The named areas the rules list, with their chunks, for the world map's pins; on any character. */
    public Map<String, Set<CanonicalChunk>> areas()
    {
        return rules.areas();
    }

    /**
     * Whether a named area the rules list is unlocked, as the tracker says;
     * Unknown for a name they don't list or when the rules don't apply.
     */
    public Decision area(String name)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (name == null || !rules.areas().containsKey(name)) return unmapped(name);
        return rules.isAreaUnlocked(name)
            ? new Decision(PermissionStatus.ALLOWED, name, null, Decision.Source.AREA)
            : new Decision(PermissionStatus.LOCKED, name, name + " is not unlocked", Decision.Source.AREA);
    }

    /**
     * Whether a chunk is on the frontier of a Chunked run: locked, next to an
     * owned chunk, so it can be rolled next. False unless the rules apply.
     */
    public boolean isFrontier(CanonicalChunk chunk)
    {
        return trust == Trust.TRUSTED && chunk != null && rules.isFrontier(chunk);
    }

    /**
     * An older export's content lists for a chunk, for the sidebar; empty
     * unless those rules apply to this character.
     */
    public Map<String, List<String>> legacyContent(CanonicalChunk chunk)
    {
        if (trust != Trust.TRUSTED || !rules.isLegacy() || chunk == null) return Collections.emptyMap();
        return rules.legacyContent(chunk);
    }

    /**
     * The bank at a chunk: the tracker's bank table's decision wherever its
     * facilities are, inside Keldagrim as well as at its entrance (R5); else
     * the chunk's bank row.
     */
    public Decision bankAt(CanonicalChunk chunk)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (rules.isLegacy()) return chunk == null ? unmapped(null) : rules.legacy().bankAt(chunk);
        RuneliteRulesManifest.Bank bank = chunk == null ? null : rules.bankIn(chunk);
        if (bank != null) return new Decision(bank.getStatus(), bank.getName(), bank.getReason(), Decision.Source.ROW);
        return target(chunk, "BANK", "");
    }

    /**
     * Whether the bank at a chunk is rolled under Banks in the tracker:
     * ALLOWED when it is, or when the run doesn't lock banks. Unlike
     * {@link #bankAt}, which also locks a rolled bank whose area or quest is
     * locked, this is only the roll.
     */
    public Decision bankRoll(CanonicalChunk chunk)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (chunk == null) return unmapped(null);
        // A bank is rolled by its own chunk, wherever its facilities are.
        RuneliteRulesManifest.Bank bank = rules.bankIn(chunk);
        CanonicalChunk rolled = bank == null ? chunk : chunkOf(bank.getAt());
        return rolled != null && rules.bankRolled(rolled)
            ? new Decision(PermissionStatus.ALLOWED, null, null, Decision.Source.BANK_ROLL)
            : new Decision(PermissionStatus.LOCKED, null, "Not rolled under Banks", Decision.Source.BANK_ROLL);
    }

    /**
     * The nearest bank this character can use (B13, R5): every chunk the
     * tracker lists a bank in, where its answer is ALLOWED; for an older
     * export, its points of interest as before. Distance is in chunks (the
     * longer axis); ties go to the smaller cx, then cy. Null when none is
     * usable or the rules don't apply.
     */
    public FateLockedBundle.Nearest nearestBank(CanonicalChunk from)
    {
        if (trust != Trust.TRUSTED || from == null) return null;
        if (rules.isLegacy()) return rules.legacy().nearestBank(from);
        if (rules.hasBankTable()) return nearestTrackedBank(from);
        return nearest(from, rules.bankChunks(), "BANKS");
    }

    /**
     * Where a chunk is on the surface: an interior's first entrance, as the
     * rules' places give it, or the chunk itself.
     */
    public CanonicalChunk surfaceOf(CanonicalChunk chunk)
    {
        RuneliteRulesManifest.Place place = chunk == null ? null : rules.placeAt(chunk);
        CanonicalChunk entrance = place == null || place.getEntrances().isEmpty() ? null : chunkOf(place.getEntrances().get(0));
        return entrance == null ? chunk : entrance;
    }

    /**
     * The nearest bank the tracker's table allows (R5): here when its
     * facilities are in this chunk, else by its own chunk. From inside an
     * interior it is measured from the entrance, and leaving counts as a
     * chunk, so a bank at the entrance is never "here".
     */
    private FateLockedBundle.Nearest nearestTrackedBank(CanonicalChunk from)
    {
        RuneliteRulesManifest.Bank here = rules.bankIn(from);
        if (here != null && here.getStatus() == PermissionStatus.ALLOWED) return new FateLockedBundle.Nearest(from, 0);
        CanonicalChunk origin = surfaceOf(from);
        int leaving = origin.equals(from) ? 0 : 1;
        CanonicalChunk best = null;
        int bestDistance = Integer.MAX_VALUE;
        for (Map.Entry<CanonicalChunk, RuneliteRulesManifest.Bank> entry : rules.banksAt().entrySet())
        {
            if (entry.getValue().getStatus() != PermissionStatus.ALLOWED) continue;
            CanonicalChunk chunk = entry.getKey();
            int distance = Math.max(Math.abs(chunk.getCx() - origin.getCx()), Math.abs(chunk.getCy() - origin.getCy()));
            if (best == null || distance < bestDistance || (distance == bestDistance
                && (chunk.getCx() < best.getCx() || (chunk.getCx() == best.getCx() && chunk.getCy() < best.getCy()))))
            {
                best = chunk;
                bestDistance = distance;
            }
        }
        return best == null ? null : new FateLockedBundle.Nearest(best, bestDistance + leaving);
    }

    /** The chunk of a "cx,cy" key; null when it isn't one. */
    private static CanonicalChunk chunkOf(String key)
    {
        String[] xy = key == null ? new String[0] : key.split(",");
        if (xy.length != 2) return null;
        try
        {
            return new CanonicalChunk(Integer.parseInt(xy[0].trim()), Integer.parseInt(xy[1].trim()));
        }
        catch (NumberFormatException notAChunk)
        {
            return null;
        }
    }

    /** The nearest shop this character can use: a SHOPS row the tracker allows. */
    public FateLockedBundle.Nearest nearestShop(CanonicalChunk from)
    {
        if (trust != Trust.TRUSTED || from == null) return null;
        if (rules.isLegacy()) return rules.legacy().nearestShop(from);
        return nearest(from, rules.shopChunks(), "SHOPS");
    }

    /** Whether the rules know where banks or shops are, for the HUD's nearest lines. */
    public boolean hasNearestData()
    {
        if (trust != Trust.TRUSTED) return false;
        if (rules.isLegacy()) return rules.legacy().hasNearestData();
        return !rules.bankChunks().isEmpty() || !rules.shopChunks().isEmpty();
    }

    private FateLockedBundle.Nearest nearest(CanonicalChunk from, Set<CanonicalChunk> candidates, String category)
    {
        // As for the bank table: from inside an interior, from its entrance, and leaving counts as a chunk.
        CanonicalChunk origin = surfaceOf(from);
        int leaving = origin.equals(from) ? 0 : 1;
        CanonicalChunk best = null;
        int bestDistance = Integer.MAX_VALUE;
        for (CanonicalChunk chunk : candidates)
        {
            int distance = Math.max(Math.abs(chunk.getCx() - origin.getCx()), Math.abs(chunk.getCy() - origin.getCy()));
            boolean closer = distance < bestDistance || (distance == bestDistance
                && (chunk.getCx() < best.getCx() || (chunk.getCx() == best.getCx() && chunk.getCy() < best.getCy())));
            if (closer && usable(chunk, category))
            {
                best = chunk;
                bestDistance = distance;
            }
        }
        return best == null ? null : new FateLockedBundle.Nearest(best, bestDistance + leaving);
    }

    /** Whether any row of a category in a chunk is ALLOWED; a locked chunk locks them all. */
    private boolean usable(CanonicalChunk chunk, String category)
    {
        ChunkPermissionSnapshot snapshot = snapshotAt(chunk).orElse(null);
        if (snapshot == null || snapshot.getEntry() == PermissionStatus.LOCKED) return false;
        List<ChunkPermissionRow> rows = snapshot.getCategories().get(category);
        if (rows == null) return false;
        for (ChunkPermissionRow row : rows)
        {
            if (row.getStatus() == PermissionStatus.ALLOWED) return true;
        }
        return false;
    }

    /** A mobility unlock, such as Fairy Rings, by its tracker name. */
    public Decision mobility(String unlockId)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        if (rules.isLegacy() || unlockId == null) return unmapped(unlockId);
        RuneliteRulesManifest manifest = rules.bundle().getRules();
        if (!containsName(manifest.getKnownMobility(), unlockId)) return unmapped(unlockId);
        boolean unlocked = containsName(manifest.getUnlocks().getMobility(), unlockId);
        return unlocked
            ? new Decision(PermissionStatus.ALLOWED, unlockId, null, Decision.Source.MOBILITY)
            : new Decision(PermissionStatus.LOCKED, unlockId, unlockId + " is not unlocked",
                Decision.Source.MOBILITY);
    }

    /**
     * An item's tier and its slot's unlocked tier (B12): the tracker's
     * itemRules and unlocks, or an older export's item tiers against the
     * slot it is worn in. Null when the rules don't rate the item, or don't
     * apply to this character.
     *
     * @param wornSlot where the item is worn ("Weapon"), for older exports
     */
    public ItemTier itemTier(int itemId, String wornSlot)
    {
        if (trust != Trust.TRUSTED) return null;
        if (rules.isLegacy()) return rules.legacy().itemTier(itemId, wornSlot);
        RuneliteRulesManifest manifest = rules.bundle().getRules();
        RuneliteRulesManifest.ItemRule item = manifest.getItemRules().get(String.valueOf(itemId));
        if (item == null || isBlank(item.getSlot())) return null;
        Integer unlocked = manifest.getUnlocks().getEquipment().get(item.getSlot());
        return unlocked == null ? null : new ItemTier(item.getSlot(), item.getTier(), unlocked);
    }

    /** Whether an item's equipment tier is unlocked for its slot. */
    public Decision item(int itemId)
    {
        Decision gate = gate();
        if (gate != null) return gate;
        String label = "Item " + itemId;
        if (rules.isLegacy()) return unmapped(label);
        RuneliteRulesManifest manifest = rules.bundle().getRules();
        RuneliteRulesManifest.ItemRule item = manifest.getItemRules().get(String.valueOf(itemId));
        if (item == null || item.getSlot() == null || item.getSlot().trim().isEmpty()) return unmapped(label);
        Integer unlocked = manifest.getUnlocks().getEquipment().get(item.getSlot());
        if (unlocked == null) return unmapped(label);
        PermissionStatus status = item.getTier() > unlocked ? PermissionStatus.LOCKED : PermissionStatus.ALLOWED;
        String reason = "T" + item.getTier() + "; " + item.getSlot() + " is unlocked to T" + unlocked;
        return new Decision(status, label, reason, Decision.Source.ITEM);
    }

    private Optional<ChunkPermissionSnapshot> snapshotAt(CanonicalChunk chunk)
    {
        return rules.isEmpty() || rules.isLegacy() ? Optional.empty() : rules.bundle().permissionsAt(chunk);
    }

    private static boolean isBlank(String value)
    {
        return value == null || value.trim().isEmpty();
    }

    /** Null when the rules apply; otherwise the Unknown answer every question gets. */
    private Decision gate()
    {
        switch (trust)
        {
            case TRUSTED:
                return null;
            case NO_RULES:
                return new Decision(PermissionStatus.UNKNOWN, null, trustReason(), Decision.Source.TRUST);
            default:
                return new Decision(PermissionStatus.UNKNOWN, WRONG_ACCOUNT, WRONG_ACCOUNT, Decision.Source.TRUST);
        }
    }

    private static Decision unmapped(String label)
    {
        return new Decision(PermissionStatus.UNKNOWN,
            label == null || label.trim().isEmpty() ? null : label, null, Decision.Source.UNMAPPED);
    }

    private static boolean containsName(List<String> values, String name)
    {
        String expected = normalizeName(name);
        if (expected.isEmpty()) return false;
        for (String value : values)
        {
            if (expected.equals(normalizeName(value))) return true;
        }
        return false;
    }

    private static String normalizeName(String value)
    {
        if (value == null) return "";
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** Menu text as rows name it: no colour tags, no lock tag, any case. */
    private static String normalizeTarget(String value)
    {
        if (value == null) return "";
        return value.replaceAll("<[^>]+>", "").replace(MenuFacts.LOCKED_MARK, "").trim().toLowerCase(Locale.ROOT);
    }

    /** The bundle behind these rules, for the few adapters that still render from it. */
    FateLockedBundle bundle()
    {
        return rules.bundle();
    }
}

package com.fatelocked.rules;

import lombok.Value;

/**
 * How much of the run is unlocked, as the run card counts it: named areas,
 * or chunks in a Chunked run, with the land chunks owned for the percentage.
 * The tracker's own counts (R9), or for older rules the rules' area lists.
 */
@Value
public class Progress
{
    public static final String AREAS = "areas";
    public static final String CHUNKS = "chunks";

    /** What unlocked and total count: {@link #AREAS} or {@link #CHUNKS}. */
    String unit;
    int unlocked;
    int total;
    int chunksUnlocked;
    int chunksTotal;

    /** Percent of chunks unlocked, rounded; -1 when there are none. */
    public int percent()
    {
        return chunksTotal <= 0 ? -1 : (int) Math.round(100.0 * chunksUnlocked / chunksTotal);
    }
}

package com.fatelocked.rules;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The loaded rules, fixed at load time. {@link DecisionService} answers from
 * it; nothing else reads the bundle's decisions directly.
 */
public final class RulesSnapshot
{
    private static final RulesSnapshot EMPTY = new RulesSnapshot(FateLockedBundle.empty());

    private final FateLockedBundle bundle;
    private final LegacyRules legacy;
    private final Set<CanonicalChunk> mapped;
    private final Progress progress;
    /** The tracker's chunks with a BANK row, and with SHOPS rows. */
    private final Set<CanonicalChunk> bankChunks;
    private final Set<CanonicalChunk> shopChunks;
    /** The tracker's frontier for a Chunked run, when the rules send it; null otherwise. */
    private final Set<CanonicalChunk> frontier;
    /** Every land, ocean and interior chunk's entry, when the rules send them; empty otherwise. */
    private final Map<CanonicalChunk, PermissionStatus> entries;
    /** What each chunk that isn't land is, when the rules send it; empty otherwise. */
    private final Map<CanonicalChunk, RuneliteRulesManifest.Place> places;
    /** The tracker's bank table, when the rules send it: each bank by its chunk, and by the chunks its facilities are in. */
    private final Map<CanonicalChunk, RuneliteRulesManifest.Bank> banksAt;
    private final Map<CanonicalChunk, RuneliteRulesManifest.Bank> banksIn;

    private RulesSnapshot(FateLockedBundle bundle)
    {
        this.bundle = bundle;
        this.legacy = bundle.isLegacyRules() ? new LegacyRules(bundle) : null;
        this.mapped = Collections.unmodifiableSet(mapped(bundle));
        Progress tracked = bundle.isLegacyRules() ? null : bundle.getRules().getProgress();
        this.progress = tracked != null ? tracked : new Progress(
            bundle.isChunkedBundle() ? Progress.CHUNKS : Progress.AREAS,
            bundle.getUnlockedAreas(), bundle.getTotalAreas(), bundle.getUnlockedChunks(), bundle.getTotalChunks());
        this.bankChunks = Collections.unmodifiableSet(withRows(bundle, mapped, "BANKS", "BANK"));
        this.shopChunks = Collections.unmodifiableSet(withRows(bundle, mapped, "SHOPS", null));
        List<String> frontierKeys = bundle.isLegacyRules() ? null : bundle.getRules().getFrontier();
        this.frontier = frontierKeys == null ? null : Collections.unmodifiableSet(chunks(frontierKeys));
        RuneliteRulesManifest manifest = bundle.isLegacyRules() ? null : bundle.getRules();
        this.entries = Collections.unmodifiableMap(byChunk(manifest == null ? null : manifest.getChunkEntries()));
        this.places = Collections.unmodifiableMap(byChunk(manifest == null ? null : manifest.getPlaces()));
        Map<CanonicalChunk, RuneliteRulesManifest.Bank> at = new HashMap<>();
        Map<CanonicalChunk, RuneliteRulesManifest.Bank> in = new HashMap<>();
        if (manifest != null && manifest.getBanks() != null)
        {
            for (RuneliteRulesManifest.Bank bank : manifest.getBanks().values())
            {
                for (CanonicalChunk chunk : chunks(Collections.singletonList(bank.getAt()))) at.putIfAbsent(chunk, bank);
                for (CanonicalChunk chunk : chunks(bank.getPhysical())) in.putIfAbsent(chunk, bank);
            }
        }
        this.banksAt = Collections.unmodifiableMap(at);
        this.banksIn = Collections.unmodifiableMap(in);
    }

    /** A map by "cx,cy" key, keyed by chunk instead, skipping keys that aren't one. */
    private static <T> Map<CanonicalChunk, T> byChunk(Map<String, T> byKey)
    {
        Map<CanonicalChunk, T> byChunk = new HashMap<>();
        if (byKey == null) return byChunk;
        for (Map.Entry<String, T> entry : byKey.entrySet())
        {
            for (CanonicalChunk chunk : chunks(Collections.singletonList(entry.getKey())))
            {
                byChunk.put(chunk, entry.getValue());
            }
        }
        return byChunk;
    }

    /** The chunks of "cx,cy" keys, skipping any that aren't one. */
    private static Set<CanonicalChunk> chunks(Iterable<String> keys)
    {
        Set<CanonicalChunk> chunks = new LinkedHashSet<>();
        for (String key : keys)
        {
            String[] xy = key.split(",");
            if (xy.length != 2) continue;
            try
            {
                chunks.add(new CanonicalChunk(Integer.parseInt(xy[0].trim()), Integer.parseInt(xy[1].trim())));
            }
            catch (NumberFormatException ignored)
            {
                // Not a chunk key: nothing to draw for it.
            }
        }
        return chunks;
    }

    /** The mapped chunks with a row in a category (of one target kind, when given). */
    private static Set<CanonicalChunk> withRows(
        FateLockedBundle bundle, Set<CanonicalChunk> mapped, String category, String targetKind)
    {
        Set<CanonicalChunk> chunks = new LinkedHashSet<>();
        if (bundle.isLegacyRules()) return chunks;
        for (CanonicalChunk chunk : mapped)
        {
            ChunkPermissionSnapshot snapshot = bundle.permissionsAt(chunk).orElse(null);
            List<ChunkPermissionRow> rows = snapshot == null ? null : snapshot.getCategories().get(category);
            if (rows == null) continue;
            for (ChunkPermissionRow row : rows)
            {
                if (targetKind == null || targetKind.equalsIgnoreCase(row.getTargetKind()))
                {
                    chunks.add(chunk);
                    break;
                }
            }
        }
        return chunks;
    }

    /** The tracker's chunk keys ("cx,cy"), or an older export's area chunks. */
    private static Set<CanonicalChunk> mapped(FateLockedBundle bundle)
    {
        Set<CanonicalChunk> chunks = new LinkedHashSet<>();
        if (bundle.isLegacyRules())
        {
            for (Set<CanonicalChunk> region : bundle.getRegionChunks().values()) chunks.addAll(region);
            return chunks;
        }
        chunks.addAll(chunks(bundle.getRules().getChunks().keySet()));
        return chunks;
    }

    public static RulesSnapshot of(FateLockedBundle bundle)
    {
        return bundle == null || bundle.isEmpty() ? EMPTY : new RulesSnapshot(bundle);
    }

    public static RulesSnapshot empty()
    {
        return EMPTY;
    }

    /** True until rules are loaded: nothing is mapped. */
    public boolean isEmpty()
    {
        return bundle.isEmpty();
    }

    /** True for a v1–3 export, which carries no tracker decisions. */
    public boolean isLegacy()
    {
        return !isEmpty() && bundle.isLegacyRules();
    }

    FateLockedBundle bundle()
    {
        return bundle;
    }

    LegacyRules legacy()
    {
        return legacy;
    }

    /** The tracker's chunks with a bank, fixed when the rules load (all its banks, R5). */
    Set<CanonicalChunk> bankChunks()
    {
        return bankChunks;
    }

    /** The tracker's chunks with a shop, fixed when the rules load. */
    Set<CanonicalChunk> shopChunks()
    {
        return shopChunks;
    }

    /** The run's progress, as the tracker counts it or else from the rules' area lists, fixed when they load. */
    Progress progress()
    {
        return progress;
    }

    /** Every chunk the rules decide, fixed when they load. */
    Set<CanonicalChunk> mappedChunks()
    {
        return mapped;
    }

    /** The named areas the rules list (Falador, Draynor Village…), with their chunks. */
    Map<String, Set<CanonicalChunk>> areas()
    {
        return bundle.getSubAreaChunks();
    }

    /** Whether a named area is unlocked; the golden bundles pin it to the tracker's answers. */
    boolean isAreaUnlocked(String name)
    {
        return bundle.isUnlocked(name);
    }

    /** The tracker's travel table; null without rules, or for older rules, which have none (F1). */
    TravelTable travelTable()
    {
        return isEmpty() || isLegacy() || bundle.getRules() == null ? null : bundle.getRules().getTravel();
    }

    /** Whether the rules send each Slayer task's decision. */
    boolean hasSlayerTasks()
    {
        return !isLegacy() && bundle.getRules().getSlayerTasks() != null;
    }

    /** The tracker's decision for a Slayer task key ("master:task" or "task"); null when it has none. */
    RuneliteRulesManifest.SlayerTask slayerTaskAt(String key)
    {
        return hasSlayerTasks() ? bundle.getRules().getSlayerTasks().get(FateLockedBundle.slayerKey(key)) : null;
    }

    /** The tracker's Slayer index entry for a key; null when it has none. */
    Set<CanonicalChunk> slayerChunks(String key)
    {
        return bundle.slayerChunks(key);
    }

    /** The chunks whose monster lists name a monster, for tasks the Slayer index misses. */
    Set<CanonicalChunk> monsterChunks(String name)
    {
        return bundle.monsterChunks(name);
    }

    /**
     * In a Chunked run, a chunk the run may roll next: the tracker's own
     * frontier, which with Sailing reaches land across the sea (R4), or for
     * older rules a locked chunk next to an owned one.
     */
    boolean isFrontier(CanonicalChunk chunk)
    {
        return frontier != null ? frontier.contains(chunk) : bundle.isFrontierChunk(chunk);
    }

    /** A chunk's entry as the tracker's chunkEntries give it, the ocean and interiors included; null when they don't. */
    PermissionStatus entryAt(CanonicalChunk chunk)
    {
        return entries.get(chunk);
    }

    /** Whether the rules send the tracker's bank table. */
    boolean hasBankTable()
    {
        return !isLegacy() && bundle.getRules().getBanks() != null;
    }

    /** The bank whose facilities are in a chunk, as the tracker's bank table has it; null when none is. */
    RuneliteRulesManifest.Bank bankIn(CanonicalChunk chunk)
    {
        return banksIn.get(chunk);
    }

    /** Each bank in the tracker's table by its chunk: where it is, or the entrance to it. */
    Map<CanonicalChunk, RuneliteRulesManifest.Bank> banksAt()
    {
        return banksAt;
    }

    /** What a chunk that isn't land is, as the rules' places say; null for land or when they don't. */
    RuneliteRulesManifest.Place placeAt(CanonicalChunk chunk)
    {
        return places.get(chunk);
    }

    /** The root-field area name ("Falador · Asgarnia") older exports and unmapped chunks fall back to. */
    String areaLabel(CanonicalChunk chunk)
    {
        return bundle.labelAt(chunk);
    }

    /** The root-field region (continent), as {@link #areaLabel} falls back. */
    String regionAt(CanonicalChunk chunk)
    {
        return bundle.regionAt(chunk);
    }

    /**
     * Whether the bank at a chunk is rolled, or the run doesn't lock banks.
     * Every export carries this in its root fields, and the golden bundles
     * pin it to the tracker's own bank answers.
     */
    boolean bankRolled(CanonicalChunk chunk)
    {
        return bundle.isBankUnlocked(chunk);
    }

    /** An older export's content lists for a chunk ("mon", "shop", "farm", "poi"). */
    Map<String, List<String>> legacyContent(CanonicalChunk chunk)
    {
        return bundle.legacyContentAt(chunk);
    }
}

package com.fatelocked.rules;

import lombok.Getter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Getter
public final class ChunkPermissionSnapshot
{
    private String chunkKey;
    private String name;
    private String region;
    private PermissionStatus entry;
    /** Stage 2: "land" or "ocean"; null in older rules. */
    private String kind;
    /** Stage 2: the rolled area the chunk belongs to, its sub-area else its region; null when none or older rules. */
    private String area;
    /** Stage 2: why the entry isn't ALLOWED, in the tracker's words ("Unlock Falador"); null when it is, or older rules. */
    private String entryReason;
    private Map<String, List<ChunkPermissionRow>> categories;
    private Counts counts;

    ChunkPermissionSnapshot normalized(String fallbackKey)
    {
        ChunkPermissionSnapshot copy = new ChunkPermissionSnapshot();
        copy.chunkKey = chunkKey == null ? fallbackKey : chunkKey;
        copy.name = name;
        copy.region = region;
        copy.entry = entry == null ? PermissionStatus.UNKNOWN : entry;
        copy.kind = blankToNull(kind);
        copy.area = blankToNull(area);
        copy.entryReason = blankToNull(entryReason);

        Map<String, List<ChunkPermissionRow>> normalized = new LinkedHashMap<>();
        if (categories != null)
        {
            for (Map.Entry<String, List<ChunkPermissionRow>> category : categories.entrySet())
            {
                List<ChunkPermissionRow> rows = new ArrayList<>();
                if (category.getValue() != null)
                {
                    for (ChunkPermissionRow row : category.getValue())
                    {
                        if (row != null) rows.add(row.normalized());
                    }
                }
                normalized.put(category.getKey(),
                    Collections.unmodifiableList(rows));
            }
        }
        copy.categories = Collections.unmodifiableMap(normalized);
        copy.counts = counts == null ? new Counts() : counts.normalized();
        return copy;
    }

    private static String blankToNull(String value)
    {
        return value == null || value.trim().isEmpty() ? null : value.trim();
    }

    @Getter
    public static final class Counts
    {
        private int allowed;
        private int notReady;
        private int locked;
        private int unknown;

        private Counts normalized()
        {
            Counts copy = new Counts();
            copy.allowed = Math.max(0, allowed);
            copy.notReady = Math.max(0, notReady);
            copy.locked = Math.max(0, locked);
            copy.unknown = Math.max(0, unknown);
            return copy;
        }
    }
}

package com.fatelocked.rules;

public enum PermissionStatus
{
    ALLOWED,
    NOT_READY,
    LOCKED,
    UNKNOWN
}

package com.fatelocked.rules;

import com.fatelocked.CanonicalChunk;
import com.fatelocked.FateLockedBundle;

/**
 * The v1–3 root-field rules, kept only for file and clipboard imports from
 * older tracker versions. v4 bundles never reach this class: their answers
 * come from the tracker's own decisions in {@code rules}.
 */
final class LegacyRules
{
    private final FateLockedBundle bundle;

    LegacyRules(FateLockedBundle bundle)
    {
        this.bundle = bundle;
    }

    Decision chunk(CanonicalChunk chunk)
    {
        switch (bundle.lockStateAt(chunk))
        {
            case UNLOCKED:
                return new Decision(PermissionStatus.ALLOWED, bundle.labelAt(chunk), null,
                    Decision.Source.LEGACY);
            case LOCKED:
                return new Decision(PermissionStatus.LOCKED, bundle.labelAt(chunk), null,
                    Decision.Source.LEGACY);
            default:
                return new Decision(PermissionStatus.UNKNOWN, null, null, Decision.Source.UNMAPPED);
        }
    }

    /**
     * An item's tier from an older export's item tiers, against the tier the
     * slot it is worn in is unlocked to; null when the export doesn't rate it.
     */
    ItemTier itemTier(int itemId, String wornSlot)
    {
        Integer tier = bundle.getItemTiers().get(String.valueOf(itemId));
        FateLockedBundle.RunState state = bundle.getState();
        if (tier == null || wornSlot == null || state == null || state.getEquipment() == null) return null;
        return new ItemTier(wornSlot, tier, state.getEquipment().getOrDefault(wornSlot, 0));
    }

    /** An older export's nearest usable bank, from its points of interest. */
    FateLockedBundle.Nearest nearestBank(CanonicalChunk from)
    {
        return bundle.nearestUsableBank(from);
    }

    /** An older export's nearest shop in an unlocked area. */
    FateLockedBundle.Nearest nearestShop(CanonicalChunk from)
    {
        return bundle.nearestUsableShop(from);
    }

    boolean hasNearestData()
    {
        return bundle.hasNearestData();
    }

    /** The bank at a chunk: only bank-locked runs lock one, and only until it is rolled. */
    Decision bankAt(CanonicalChunk chunk)
    {
        String label = bundle.labelAt(chunk);
        String name = label == null ? "This bank" : label + " bank";
        return bundle.isBankUnlocked(chunk)
            ? new Decision(PermissionStatus.ALLOWED, name, null, Decision.Source.LEGACY)
            : new Decision(PermissionStatus.LOCKED, name, null, Decision.Source.LEGACY);
    }
}

package com.fatelocked.rules;

import lombok.Value;

/**
 * One answer from the tracker's rules: the status, what the thing is called,
 * and why it is not allowed. {@link DecisionService} is the only source.
 */
@Value
public class Decision
{
    public enum Source
    {
        /** A chunk's entry in the v4 rules. */
        CHUNK,
        /** A row (bank, shop, NPC, …) inside a chunk's v4 rules. */
        ROW,
        /** An item's equipment tier. */
        ITEM,
        /** A mobility unlock such as Fairy Rings. */
        MOBILITY,
        /** Whether a bank is rolled, in a run that locks banks. */
        BANK_ROLL,
        /** Whether a named area (Falador, Draynor Village…) is unlocked. */
        AREA,
        /** Whether a Slayer task's monsters live anywhere owned. */
        SLAYER,
        /** A travel option's decision in the tracker's travel table. */
        TRAVEL,
        /** The v1–3 root-field rules of an older export. */
        LEGACY,
        /** The rules don't apply to this character, or none are loaded. */
        TRUST,
        /** The rules say nothing about this place. */
        UNMAPPED
    }

    PermissionStatus status;
    /** What was asked about, as the rules name it; null when they don't. */
    String label;
    /** Why it isn't allowed, in the tracker's words; null when allowed or not given. */
    String reason;
    Source source;

    public boolean isLocked()
    {
        return status == PermissionStatus.LOCKED;
    }

    /** False when the rules didn't decide: a trust gate or an unmapped place. */
    public boolean isAuthored()
    {
        return source != Source.TRUST && source != Source.UNMAPPED;
    }
}

package com.fatelocked.rules;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.annotations.SerializedName;
import lombok.AccessLevel;
import lombok.Getter;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

@Getter
public final class RuneliteRulesManifest
{
    /** The capability that says a bundle sends the Chunked frontier (R4). */
    public static final String FRONTIER = "frontier";
    /** The capabilities for every chunk's entry and what each non-land chunk is (R1). */
    public static final String CHUNK_ENTRIES = "chunkEntries";
    public static final String PLACES = "places";
    /** The capability for the tracker's bank table: each bank's decision and chunks (R5). */
    public static final String BANKS = "banks";
    /** The capability for the run's progress as the tracker counts it (R9). */
    public static final String PROGRESS = "progress";
    /** The capability for each Slayer task's decision, per master (R16). */
    public static final String SLAYER_TASKS = "slayerTasks";
    /** The capability for the areas the run's mode frees, from the mode itself (R6). */
    public static final String FREE_AREAS = "freeAreas";
    /** The capability for the travel table: each travel method, matched by id, and its options' decisions (F1). */
    public static final String TRAVEL = "travel";

    private String rulesVersion;
    private int contentVersion;
    private int detectorContractVersion;
    private String runId;
    private long runRevision;
    private String account;
    private String gameModeId;
    private String exportedAt;
    private boolean bankLocks;
    @Getter(AccessLevel.NONE)
    @SerializedName("knownMobility")
    private JsonElement knownMobilityDeclaration;
    private transient List<String> knownMobility;
    private Unlocks unlocks;
    private Map<String, ItemRule> itemRules;
    private Map<String, ChunkPermissionSnapshot> chunks;
    /**
     * Stage 2: the sections the bundle has, by capability (R15). A section is
     * read only when this names it, and ids this build doesn't know are
     * ignored. Read leniently: a malformed list names nothing.
     */
    @Getter(AccessLevel.NONE)
    @SerializedName("capabilities")
    private JsonElement capabilitiesDeclaration;
    private transient Set<String> capabilities;
    /** Stage 2, Chunked runs: the chunks the run may roll next ("cx,cy"); null when the bundle doesn't send it. */
    @Getter(AccessLevel.NONE)
    @SerializedName("frontier")
    private JsonElement frontierDeclaration;
    private transient List<String> frontier;
    /** Stage 2: every land, ocean and interior chunk's entry, by "cx,cy"; null when the bundle doesn't send them. */
    @Getter(AccessLevel.NONE)
    @SerializedName("chunkEntries")
    private JsonElement chunkEntriesDeclaration;
    private transient Map<String, PermissionStatus> chunkEntries;
    /** Stage 2: what each chunk that isn't land is, by "cx,cy"; null when the bundle doesn't send it. */
    @Getter(AccessLevel.NONE)
    @SerializedName("places")
    private JsonElement placesDeclaration;
    private transient Map<String, Place> places;
    /** Stage 2: every bank with a chunk, by bank id; null when the bundle doesn't send the table. */
    @Getter(AccessLevel.NONE)
    @SerializedName("banks")
    private JsonElement banksDeclaration;
    private transient Map<String, Bank> banks;
    /** Stage 2: how far the run has come, as its run card counts it; null when not sent or malformed. */
    @Getter(AccessLevel.NONE)
    @SerializedName("progress")
    private JsonElement progressDeclaration;
    private transient Progress progress;
    /** Stage 2: each Slayer task's decision, keyed like slayerChunks; null when the bundle doesn't send them. */
    @Getter(AccessLevel.NONE)
    @SerializedName("slayerTasks")
    private JsonElement slayerTasksDeclaration;
    private transient Map<String, SlayerTask> slayerTasks;
    /** Stage 2: the areas the run's mode frees; null when the bundle doesn't send them, or they aren't a list. */
    @Getter(AccessLevel.NONE)
    @SerializedName("freeAreas")
    private JsonElement freeAreasDeclaration;
    private transient List<String> freeAreas;
    /** Stage 2: the travel table; null when the bundle doesn't send one, or it isn't an object. */
    @Getter(AccessLevel.NONE)
    @SerializedName("travel")
    private JsonElement travelDeclaration;
    private transient TravelTable travel;

    public RuneliteRulesManifest normalized()
    {
        RuneliteRulesManifest copy = new RuneliteRulesManifest();
        copy.rulesVersion = rulesVersion;
        copy.contentVersion = Math.max(0, contentVersion);
        copy.detectorContractVersion = Math.max(0, detectorContractVersion);
        copy.runId = runId;
        copy.runRevision = Math.max(0, runRevision);
        copy.account = account;
        copy.gameModeId = gameModeId;
        copy.exportedAt = exportedAt;
        copy.bankLocks = bankLocks;
        copy.knownMobility = knownMobility == null
            ? immutableStringList(knownMobilityDeclaration)
            : Unlocks.immutableList(knownMobility);
        copy.unlocks = unlocks == null ? new Unlocks().normalized() : unlocks.normalized();
        Map<String, ItemRule> normalizedItems = new TreeMap<>();
        if (itemRules != null)
        {
            for (Map.Entry<String, ItemRule> entry : itemRules.entrySet())
            {
                if (entry.getValue() != null)
                {
                    normalizedItems.put(entry.getKey(), entry.getValue().normalized());
                }
            }
        }
        copy.itemRules = Collections.unmodifiableMap(normalizedItems);

        Map<String, ChunkPermissionSnapshot> normalizedChunks = new LinkedHashMap<>();
        if (chunks != null)
        {
            for (Map.Entry<String, ChunkPermissionSnapshot> entry :
                new TreeMap<>(chunks).entrySet())
            {
                if (entry.getValue() != null)
                {
                    normalizedChunks.put(entry.getKey(),
                        entry.getValue().normalized(entry.getKey()));
                }
            }
        }
        copy.chunks = Collections.unmodifiableMap(normalizedChunks);
        copy.capabilities = capabilities == null ? strings(capabilitiesDeclaration) : capabilities;
        copy.frontier = !copy.capabilities.contains(FRONTIER) ? null
            : frontier != null ? frontier : stringItems(frontierDeclaration);
        copy.chunkEntries = !copy.capabilities.contains(CHUNK_ENTRIES) ? null
            : chunkEntries != null ? chunkEntries : statuses(chunkEntriesDeclaration);
        copy.places = !copy.capabilities.contains(PLACES) ? null
            : places != null ? places : places(placesDeclaration);
        copy.banks = !copy.capabilities.contains(BANKS) ? null
            : banks != null ? banks : banks(banksDeclaration);
        copy.progress = !copy.capabilities.contains(PROGRESS) ? null
            : progress != null ? progress : progress(progressDeclaration);
        copy.slayerTasks = !copy.capabilities.contains(SLAYER_TASKS) ? null
            : slayerTasks != null ? slayerTasks : slayerTasks(slayerTasksDeclaration);
        copy.freeAreas = !copy.capabilities.contains(FREE_AREAS) ? null
            : freeAreas != null ? freeAreas : stringItems(freeAreasDeclaration);
        copy.travel = !copy.capabilities.contains(TRAVEL) ? null
            : travel != null ? travel : TravelTable.parse(travelDeclaration);
        return copy;
    }

    /**
     * Each Slayer task's decision by its key, skipping one that isn't an
     * object with a status string. Null when the section isn't an object.
     */
    private static Map<String, SlayerTask> slayerTasks(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonObject()) return null;
        Map<String, SlayerTask> tasks = new TreeMap<>();
        for (Map.Entry<String, JsonElement> entry : declaration.getAsJsonObject().entrySet())
        {
            if (entry.getValue() == null || !entry.getValue().isJsonObject()) continue;
            JsonObject value = entry.getValue().getAsJsonObject();
            PermissionStatus status = status(value.get("status"));
            if (status == null) continue;
            tasks.put(entry.getKey(), new SlayerTask(status, string(value.get("reason"))));
        }
        return Collections.unmodifiableMap(tasks);
    }

    /**
     * The run's progress: its unit (areas or chunks), unlocked and total, and
     * the land chunks owned. Null unless every part is there and whole, none
     * negative, and nothing unlocked beyond its total.
     */
    private static Progress progress(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonObject()) return null;
        JsonObject value = declaration.getAsJsonObject();
        String unit = string(value.get("unit"));
        JsonElement chunks = value.get("chunks");
        if (!Progress.AREAS.equals(unit) && !Progress.CHUNKS.equals(unit)) return null;
        if (chunks == null || !chunks.isJsonObject()) return null;
        Integer unlocked = count(value.get("unlocked"));
        Integer total = count(value.get("total"));
        Integer chunksUnlocked = count(chunks.getAsJsonObject().get("unlocked"));
        Integer chunksTotal = count(chunks.getAsJsonObject().get("total"));
        if (unlocked == null || total == null || chunksUnlocked == null || chunksTotal == null
            || unlocked > total || chunksUnlocked > chunksTotal)
        {
            return null;
        }
        return new Progress(unit, unlocked, total, chunksUnlocked, chunksTotal);
    }

    /** A whole, non-negative JSON number; null for anything else. */
    private static Integer count(JsonElement value)
    {
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber()) return null;
        double number = value.getAsDouble();
        return number < 0 || number > Integer.MAX_VALUE || number != Math.rint(number) ? null : (int) number;
    }

    /**
     * Each bank by id, skipping one that isn't an object with a name and its
     * chunk. A status this build doesn't know reads UNKNOWN; a bank with no
     * facility chunks is where its chunk is. Null when the table isn't an object.
     */
    private static Map<String, Bank> banks(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonObject()) return null;
        Map<String, Bank> banks = new TreeMap<>();
        for (Map.Entry<String, JsonElement> entry : declaration.getAsJsonObject().entrySet())
        {
            if (entry.getValue() == null || !entry.getValue().isJsonObject()) continue;
            JsonObject value = entry.getValue().getAsJsonObject();
            String name = string(value.get("name"));
            String at = string(value.get("at"));
            if (name == null || at == null) continue;
            PermissionStatus status = status(value.get("status"));
            List<String> physical = stringItems(value.get("physical"));
            banks.put(entry.getKey(), new Bank(name, status == null ? PermissionStatus.UNKNOWN : status,
                string(value.get("reason")), at,
                physical == null || physical.isEmpty() ? Collections.singletonList(at) : physical));
        }
        return Collections.unmodifiableMap(banks);
    }

    /** A JSON string's value; null for anything else. */
    private static String string(JsonElement value)
    {
        return value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString()
            ? value.getAsString() : null;
    }

    /**
     * A JSON object's statuses by key: a status this build doesn't know reads
     * UNKNOWN, and a value that isn't a string is skipped. Null when it isn't an object.
     */
    private static Map<String, PermissionStatus> statuses(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonObject()) return null;
        Map<String, PermissionStatus> statuses = new TreeMap<>();
        for (Map.Entry<String, JsonElement> entry : declaration.getAsJsonObject().entrySet())
        {
            PermissionStatus status = status(entry.getValue());
            if (status != null) statuses.put(entry.getKey(), status);
        }
        return Collections.unmodifiableMap(statuses);
    }

    /** A JSON string's status: one this build doesn't know reads UNKNOWN; null for anything but a string. */
    private static PermissionStatus status(JsonElement value)
    {
        String status = string(value);
        if (status == null) return null;
        try
        {
            return PermissionStatus.valueOf(status);
        }
        catch (IllegalArgumentException unknown)
        {
            return PermissionStatus.UNKNOWN;
        }
    }

    /** Each place by key, skipping a value that isn't an object with a kind. Null when it isn't an object. */
    private static Map<String, Place> places(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonObject()) return null;
        Map<String, Place> places = new TreeMap<>();
        for (Map.Entry<String, JsonElement> entry : declaration.getAsJsonObject().entrySet())
        {
            if (entry.getValue() == null || !entry.getValue().isJsonObject()) continue;
            JsonObject value = entry.getValue().getAsJsonObject();
            String kind = string(value.get("kind"));
            if (kind == null) continue;
            List<String> entrances = stringItems(value.get("entrances"));
            places.put(entry.getKey(), new Place(kind, string(value.get("name")), string(value.get("area")),
                entrances == null ? Collections.emptyList() : entrances));
        }
        return Collections.unmodifiableMap(places);
    }

    /** A JSON array's strings, skipping anything else; nothing when it isn't an array. */
    private static Set<String> strings(JsonElement declaration)
    {
        List<String> items = stringItems(declaration);
        return items == null ? Collections.emptySet() : Collections.unmodifiableSet(new LinkedHashSet<>(items));
    }

    /** A JSON array's strings, skipping anything else; null when it isn't an array. */
    private static List<String> stringItems(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonArray()) return null;
        List<String> values = new ArrayList<>();
        for (JsonElement value : declaration.getAsJsonArray())
        {
            if (value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isString())
            {
                values.add(value.getAsString());
            }
        }
        return Collections.unmodifiableList(values);
    }

    private static List<String> immutableStringList(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonArray())
        {
            return Collections.emptyList();
        }
        List<String> values = new ArrayList<>();
        for (JsonElement value : declaration.getAsJsonArray())
        {
            if (value == null || !value.isJsonPrimitive()
                || !value.getAsJsonPrimitive().isString())
            {
                return Collections.emptyList();
            }
            values.add(value.getAsString());
        }
        return Collections.unmodifiableList(values);
    }

    public boolean hasRequiredFields()
    {
        return rulesVersion != null && !rulesVersion.trim().isEmpty()
            && runId != null && !runId.trim().isEmpty()
            && gameModeId != null && !gameModeId.trim().isEmpty()
            && exportedAt != null && !exportedAt.trim().isEmpty()
            && unlocks != null && chunks != null;
    }

    /** A chunk that isn't land: the ocean, or an interior with its name, area and the chunks it is entered from. */
    @Getter
    public static final class Place
    {
        private final String kind;
        /** The interior's name, such as "Mor Ul Rek · Outer Area"; null when the tracker has none. */
        private final String name;
        /** The named area the interior belongs to; null when it has none. */
        private final String area;
        private final List<String> entrances;

        public Place(String kind, String name, String area, List<String> entrances)
        {
            this.kind = kind;
            this.name = name;
            this.area = area;
            this.entrances = entrances;
        }

        public boolean isOcean()
        {
            return "ocean".equals(kind);
        }
    }

    /** A bank as the tracker decides it: where it is ("cx,cy"), and the chunks its facilities are in. */
    @Getter
    public static final class Bank
    {
        private final String name;
        private final PermissionStatus status;
        /** Why it isn't allowed, in the tracker's words; null when not given. */
        private final String reason;
        /** The bank's chunk: where it is on the surface, or the entrance to it. */
        private final String at;
        private final List<String> physical;

        public Bank(String name, PermissionStatus status, String reason, String at, List<String> physical)
        {
            this.name = name;
            this.status = status;
            this.reason = reason;
            this.at = at;
            this.physical = physical;
        }
    }

    /** A Slayer task as the tracker decides it for the run. */
    @Getter
    public static final class SlayerTask
    {
        private final PermissionStatus status;
        /** Why, in the tracker's words, such as "Area locked" or "Master: Mount Karuulm"; null when not given. */
        private final String reason;

        public SlayerTask(PermissionStatus status, String reason)
        {
            this.status = status;
            this.reason = reason;
        }
    }

    @Getter
    public static final class ItemRule
    {
        private int tier;
        private String slot;

        private ItemRule normalized()
        {
            ItemRule copy = new ItemRule();
            copy.tier = Math.max(0, tier);
            copy.slot = slot;
            return copy;
        }
    }
    @Getter
    public static final class Unlocks
    {
        private List<String> regions;
        private List<String> chunks;
        private Map<String, Integer> skills;
        private Map<String, Integer> levels;
        private Map<String, Integer> equipment;
        private List<String> banks;
        private List<String> merchants;
        private List<String> bosses;
        private List<String> minigames;
        private List<String> mobility;
        private List<String> arcana;
        private List<String> guilds;
        private List<String> farming;
        private List<String> slayer;
        private List<String> quests;

        private Unlocks normalized()
        {
            Unlocks copy = new Unlocks();
            copy.regions = immutableList(regions);
            copy.chunks = immutableList(chunks);
            copy.skills = immutableMap(skills);
            copy.levels = immutableMap(levels);
            copy.equipment = immutableMap(equipment);
            copy.banks = immutableList(banks);
            copy.merchants = immutableList(merchants);
            copy.bosses = immutableList(bosses);
            copy.minigames = immutableList(minigames);
            copy.mobility = immutableList(mobility);
            copy.arcana = immutableList(arcana);
            copy.guilds = immutableList(guilds);
            copy.farming = immutableList(farming);
            copy.slayer = immutableList(slayer);
            copy.quests = immutableList(quests);
            return copy;
        }

        private static List<String> immutableList(List<String> values)
        {
            return values == null
                ? Collections.emptyList()
                : Collections.unmodifiableList(new ArrayList<>(values));
        }

        private static Map<String, Integer> immutableMap(Map<String, Integer> values)
        {
            return values == null
                ? Collections.emptyMap()
                : Collections.unmodifiableMap(new TreeMap<>(values));
        }
    }
}

package com.fatelocked.rules;

/** Whether the loaded rules apply to the character that is logged in. */
public enum Trust
{
    /** No rules are loaded. */
    NO_RULES,
    /** The rules are bound to an account and nobody is logged in to compare. */
    LOGGED_OUT,
    /** The rules are bound to a different account. */
    WRONG_CHARACTER,
    /** The rules apply: bound to this character, or bound to no one. */
    TRUSTED
}

package com.fatelocked.rules;

import com.fatelocked.CanonicalChunk;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import lombok.Getter;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The tracker's travel table (F1), from {@code rules.travel}. Each method is
 * matched by exactly one of a spell (its spellbook and name), item ids,
 * object ids or NPC ids. Each option, keyed by the menu option's exact text,
 * lists the chunks it can go to and the tracker's decision for the run.
 *
 * <p>Read leniently, like {@code knownMobility}: a malformed method or
 * option is dropped, never the bundle. The code sets the outer limits that
 * only a Hub release can widen: an option that is never travel is dropped
 * whatever the table says, and the table, each method and each option have
 * caps.
 */
public final class TravelTable
{
    public static final int MAX_METHODS = 1000;
    public static final int MAX_OPTIONS = 64;
    /** Ids per method: the charter ships match 144 crew ids. */
    public static final int MAX_IDS = 256;
    public static final int MAX_DESTINATIONS = 64;
    /** Labels, option texts and reasons are cut to this. */
    public static final int MAX_TEXT = 120;
    public static final List<String> SPELLBOOKS =
        Collections.unmodifiableList(Arrays.asList("standard", "ancient", "lunar", "arceuus"));
    /**
     * Options that are never travel, whatever a table says: the web's own
     * list (NON_TRAVEL_OPTIONS in data/travelMethods.ts) and a few more.
     */
    public static final Set<String> NON_TRAVEL_OPTIONS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        "walk here", "attack", "talk-to", "trade", "bank", "collect", "deposit", "wear", "wield", "equip",
        "remove", "use", "drop", "examine", "check", "configure", "inspect", "pickpocket", "follow", "cancel",
        "destroy", "take", "eat", "drink")));
    /** A fairy ring code: three dials of four letters. */
    private static final Pattern CODE = Pattern.compile("[A-D][I-L][P-S]");
    /** A fairy ring's option for the last code it was dialled to. */
    private static final Pattern LAST_DESTINATION =
        Pattern.compile("last-destination \\(([a-z]{3})\\)", Pattern.CASE_INSENSITIVE);

    public enum Match
    {
        SPELL, ITEMS, OBJECTS, NPCS
    }

    private final Map<String, Method> methods;
    private final Map<String, List<Method>> spells = new HashMap<>();
    private final Map<Match, Map<Integer, List<Method>>> byId = new HashMap<>();

    private TravelTable(Map<String, Method> methods)
    {
        this.methods = Collections.unmodifiableMap(methods);
        for (Method method : methods.values())
        {
            if (method.match == Match.SPELL)
            {
                spells.computeIfAbsent(spellKey(method.spellbook, method.spell), key -> new ArrayList<>()).add(method);
                continue;
            }
            Map<Integer, List<Method>> index = byId.computeIfAbsent(method.match, match -> new HashMap<>());
            for (Integer id : method.ids) index.computeIfAbsent(id, key -> new ArrayList<>()).add(method);
        }
    }

    /** The table a {@code rules.travel} section holds; null when it isn't an object. */
    public static TravelTable parse(JsonElement declaration)
    {
        if (declaration == null || !declaration.isJsonObject()) return null;
        Map<String, Method> methods = new LinkedHashMap<>();
        for (Map.Entry<String, JsonElement> entry : declaration.getAsJsonObject().entrySet())
        {
            if (methods.size() == MAX_METHODS) break;
            Method method = method(entry.getKey(), entry.getValue());
            if (method != null) methods.put(method.id, method);
        }
        return new TravelTable(methods);
    }

    /** Every method, in the table's order. */
    public Collection<Method> methods()
    {
        return methods.values();
    }

    /** The method with this id; null when the table has none. */
    public Method method(String id)
    {
        return id == null ? null : methods.get(id);
    }

    /** The methods for a spell in a spellbook, its name ignoring case. */
    public List<Method> spell(String spellbook, String name)
    {
        if (spellbook == null || name == null) return Collections.emptyList();
        return Collections.unmodifiableList(spells.getOrDefault(spellKey(spellbook, name), Collections.emptyList()));
    }

    /** The methods matched by an id of this kind: items, objects or NPCs. */
    public List<Method> byId(Match match, int id)
    {
        Map<Integer, List<Method>> index = byId.get(match);
        List<Method> found = index == null ? null : index.get(id);
        return found == null ? Collections.emptyList() : Collections.unmodifiableList(found);
    }

    private static String spellKey(String spellbook, String name)
    {
        return spellbook + "|" + name.trim().toLowerCase(Locale.ROOT);
    }

    private static Method method(String id, JsonElement value)
    {
        if (isBlank(id) || id.length() > MAX_TEXT || value == null || !value.isJsonObject()) return null;
        JsonObject row = value.getAsJsonObject();
        String label = text(row.get("label"));
        if (label == null) return null;
        JsonElement matchValue = row.get("match");
        if (matchValue == null || !matchValue.isJsonObject()) return null;
        JsonObject match = matchValue.getAsJsonObject();
        List<Match> kinds = new ArrayList<>();
        if (match.has("spell")) kinds.add(Match.SPELL);
        if (match.has("items")) kinds.add(Match.ITEMS);
        if (match.has("objects")) kinds.add(Match.OBJECTS);
        if (match.has("npcs")) kinds.add(Match.NPCS);
        if (kinds.size() != 1) return null;
        Match kind = kinds.get(0);

        String spellbook = null;
        String spell = null;
        Set<Integer> ids = Collections.emptySet();
        if (kind == Match.SPELL)
        {
            JsonElement spellValue = match.get("spell");
            if (!spellValue.isJsonObject()) return null;
            spellbook = text(spellValue.getAsJsonObject().get("book"));
            spell = text(spellValue.getAsJsonObject().get("name"));
            if (spellbook == null || spell == null || !SPELLBOOKS.contains(spellbook)) return null;
        }
        else
        {
            ids = ids(match.get(kind.name().toLowerCase(Locale.ROOT)));
            if (ids == null) return null;
        }

        Map<String, Option> options = options(row.get("options"), false);
        Map<String, Option> codes = options(row.get("codes"), true);
        if (options == null || codes == null || options.isEmpty() && codes.isEmpty()) return null;
        return new Method(id, label, strings(row.get("unlocks")), kind, spellbook, spell, ids, options, codes,
            advisory(row.get("advisory")));
    }

    /** At least one id and at most {@link #MAX_IDS}, skipping any that isn't one; null otherwise. */
    private static Set<Integer> ids(JsonElement value)
    {
        if (value == null || !value.isJsonArray() || value.getAsJsonArray().size() > MAX_IDS) return null;
        Set<Integer> ids = new LinkedHashSet<>();
        for (JsonElement item : value.getAsJsonArray())
        {
            Integer id = wholeNumber(item);
            if (id != null) ids.add(id);
        }
        return ids.isEmpty() ? null : Collections.unmodifiableSet(ids);
    }

    /**
     * Each option by its text, dropping one that is malformed or never
     * travel; for codes, only the dials' letters. Empty when there are none,
     * and null when there are too many to choose from.
     */
    private static Map<String, Option> options(JsonElement value, boolean codes)
    {
        if (value == null || !value.isJsonObject()) return Collections.emptyMap();
        if (value.getAsJsonObject().size() > MAX_OPTIONS) return null;
        Map<String, Option> options = new LinkedHashMap<>();
        Set<String> seen = new HashSet<>();
        for (Map.Entry<String, JsonElement> entry : value.getAsJsonObject().entrySet())
        {
            String text = entry.getKey() == null ? "" : entry.getKey().trim();
            if (text.isEmpty() || text.length() > MAX_TEXT) continue;
            if (codes ? !CODE.matcher(text).matches() : NON_TRAVEL_OPTIONS.contains(text.toLowerCase(Locale.ROOT)))
            {
                continue;
            }
            Option option = option(codes ? "code:" + text : text, entry.getValue());
            // Texts are matched ignoring case, so only the first of two that differ in case counts.
            if (option != null && seen.add(text.toLowerCase(Locale.ROOT))) options.put(text, option);
        }
        return Collections.unmodifiableMap(options);
    }

    /**
     * An option with every destination a chunk key and a status. One bad
     * destination drops the option: skipping it could leave one of two
     * places, and one place is what Strict Mode acts on.
     */
    private static Option option(String text, JsonElement value)
    {
        if (value == null || !value.isJsonObject()) return null;
        JsonObject row = value.getAsJsonObject();
        JsonElement to = row.get("to");
        if (to == null || !to.isJsonArray() || to.getAsJsonArray().size() > MAX_DESTINATIONS) return null;
        Set<CanonicalChunk> destinations = new LinkedHashSet<>();
        for (JsonElement key : to.getAsJsonArray())
        {
            CanonicalChunk chunk = chunk(key);
            if (chunk == null) return null;
            destinations.add(chunk);
        }
        PermissionStatus status = status(row.get("status"));
        if (status == null) return null;
        return new Option(text, new ArrayList<>(destinations), status, text(row.get("reason")));
    }

    /** A "cx,cy" chunk key; null when it isn't one. */
    private static CanonicalChunk chunk(JsonElement key)
    {
        String text = string(key);
        if (text == null) return null;
        String[] xy = text.split(",", -1);
        if (xy.length != 2) return null;
        try
        {
            int cx = Integer.parseInt(xy[0].trim());
            int cy = Integer.parseInt(xy[1].trim());
            return cx < 0 || cy < 0 ? null : new CanonicalChunk(cx, cy);
        }
        catch (NumberFormatException notAKey)
        {
            return null;
        }
    }

    /** A status name; an unknown one reads as UNKNOWN, as every reader of the four names does. Null when not a string. */
    private static PermissionStatus status(JsonElement value)
    {
        String name = string(value);
        if (name == null) return null;
        try
        {
            return PermissionStatus.valueOf(name.trim());
        }
        catch (IllegalArgumentException unknown)
        {
            return PermissionStatus.UNKNOWN;
        }
    }

    /** Advisory unless the table says plainly that it isn't. */
    private static boolean advisory(JsonElement value)
    {
        if (value == null || value.isJsonNull()) return false;
        return !(value.isJsonPrimitive() && value.getAsJsonPrimitive().isBoolean() && !value.getAsBoolean());
    }

    private static List<String> strings(JsonElement value)
    {
        if (value == null || !value.isJsonArray()) return Collections.emptyList();
        List<String> strings = new ArrayList<>();
        for (JsonElement item : value.getAsJsonArray())
        {
            String text = text(item);
            if (text != null) strings.add(text);
        }
        return Collections.unmodifiableList(strings);
    }

    private static Integer wholeNumber(JsonElement value)
    {
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber()) return null;
        double number = value.getAsDouble();
        return number < 0 || number > Integer.MAX_VALUE || number != Math.floor(number) ? null : (int) number;
    }

    /** A string trimmed and cut to {@link #MAX_TEXT}; null when blank or not a string. */
    private static String text(JsonElement value)
    {
        String text = string(value);
        if (isBlank(text)) return null;
        text = text.trim();
        return text.length() <= MAX_TEXT ? text : text.substring(0, MAX_TEXT - 1) + "…";
    }

    private static String string(JsonElement value)
    {
        if (value == null || !value.isJsonPrimitive()) return null;
        JsonPrimitive primitive = value.getAsJsonPrimitive();
        return primitive.isString() ? primitive.getAsString() : null;
    }

    private static boolean isBlank(String value)
    {
        return value == null || value.trim().isEmpty();
    }

    /** One way to travel, as the tracker's table has it. */
    @Getter
    public static final class Method
    {
        private final String id;
        private final String label;
        /** The unlocks it needs, as the web names them; its options' decisions already count them. */
        private final List<String> unlocks;
        private final Match match;
        /** A spell's spellbook: "standard", "ancient", "lunar" or "arceuus"; null for anything else. */
        private final String spellbook;
        /** A spell's name; null for anything else. */
        private final String spell;
        /** The item, object or NPC ids that match; empty for a spell. */
        private final Set<Integer> ids;
        /** Each option by its text, in the table's order. */
        private final Map<String, Option> options;
        /** A fairy ring's codes by code ("CKS"); empty for anything else. */
        private final Map<String, Option> codes;
        /** Tagged but never blocked: networks and boats in Stage 2. */
        private final boolean advisory;
        private final Map<String, Option> byText = new HashMap<>();

        Method(String id, String label, List<String> unlocks, Match match, String spellbook, String spell,
            Set<Integer> ids, Map<String, Option> options, Map<String, Option> codes, boolean advisory)
        {
            this.id = id;
            this.label = label;
            this.unlocks = unlocks;
            this.match = match;
            this.spellbook = spellbook;
            this.spell = spell;
            this.ids = ids;
            this.options = options;
            this.codes = codes;
            this.advisory = advisory;
            for (Map.Entry<String, Option> option : options.entrySet())
            {
                byText.put(option.getKey().toLowerCase(Locale.ROOT), option.getValue());
            }
        }

        /**
         * The option with this exact text, ignoring case. A fairy ring's
         * "Last-destination (CKS)" is its code's. Null when there is none.
         */
        public Option option(String text)
        {
            if (text == null) return null;
            String trimmed = text.trim();
            Matcher last = LAST_DESTINATION.matcher(trimmed);
            if (!codes.isEmpty() && last.matches()) return codes.get(last.group(1).toUpperCase(Locale.ROOT));
            return byText.get(trimmed.toLowerCase(Locale.ROOT));
        }
    }

    /** One menu option of a method: where it can go, and the tracker's decision for the run. */
    @Getter
    public static final class Option
    {
        /** Its text as the table keys it: "Edgeville", or "code:CKS" for a fairy ring code. */
        private final String text;
        /** Every chunk it can go to. */
        private final List<CanonicalChunk> to;
        private final PermissionStatus status;
        /** Why, unless allowed, in the tracker's words; null when not given. */
        private final String reason;

        Option(String text, List<CanonicalChunk> to, PermissionStatus status, String reason)
        {
            this.text = text;
            this.to = Collections.unmodifiableList(to);
            this.status = status;
            this.reason = reason;
        }

        /** Its one destination; null when it can go to several places, or the table doesn't say where. */
        public CanonicalChunk destination()
        {
            return to.size() == 1 ? to.get(0) : null;
        }
    }
}

