package com.fatelocked;

import com.fatelocked.rules.PermissionStatus;
import java.util.HashMap;
import java.util.Map;
import lombok.Value;

/**
 * What stepping into a chunk says (U10, decision 6), once per area rather than once per chunk.
 *
 * <ul>
 * <li>A routine line is posted when the area changes, if area changes are announced.</li>
 * <li>The locked alert fires on entering a locked area, from unlocked land or from a different
 *     locked area. Its line follows the alert setting. The sound and the fade are for coming in
 *     from unlocked land; a new locked area next to the last one posts its line only.</li>
 * <li>The same locked area waits a minute before it alerts again, so walking along a border
 *     doesn't repeat it.</li>
 * <li>A place the rules don't decide says nothing. Not ready is owned, so it never alerts.</li>
 * </ul>
 *
 * <p>Everything is forgotten when a session starts or the plugin stops, so the next entry
 * alerts afresh. Client thread only.
 */
final class LockedAreaAlerts
{
    /** The same locked area alerts again after this many game ticks: a minute. */
    static final int QUIET_TICKS = 100;

    /** What one step says: a chat line, and for the locked alert its sound and fade. */
    @Value
    static class Alert
    {
        boolean line;
        boolean sound;
        boolean fade;
    }

    static final Alert NONE = new Alert(false, false, false);
    private static final Alert LINE = new Alert(true, false, false);

    private String lastArea;
    private PermissionStatus lastStatus;
    private final Map<String, Integer> alertedAt = new HashMap<>();

    /**
     * Step into a chunk of this area, on this game tick.
     *
     * @param area what groups chunks: the area's name, else the tracker's reason (the sea is
     *     one area under its reason), else the chunk itself
     */
    Alert enter(PermissionStatus status, String area, int tick, FateLockedConfig.LockedAreaAlert level,
        boolean announce)
    {
        boolean sameArea = area.equals(lastArea);
        boolean fromLocked = lastStatus == PermissionStatus.LOCKED;
        lastArea = area;
        lastStatus = status;
        if (status == PermissionStatus.UNKNOWN || sameArea)
        {
            return NONE;
        }
        if (status != PermissionStatus.LOCKED)
        {
            return announce ? LINE : NONE;
        }
        Integer last = alertedAt.get(area);
        if (last != null && tick - last < QUIET_TICKS)
        {
            return NONE;
        }
        alertedAt.put(area, tick);
        return new Alert(level.chat(), !fromLocked && level.sound(), !fromLocked && level.fade());
    }

    /** A new session, or the plugin stopping: the next entry alerts afresh. */
    void forget()
    {
        lastArea = null;
        lastStatus = null;
        alertedAt.clear();
    }
}

package com.fatelocked;

import java.time.Duration;
import java.time.Instant;

/**
 * Whether the rules in force are recent enough to act on: one answer for Strict Mode,
 * the status card and the HUD. Pure.
 *
 * <p>Tracker rules stay fresh while the relay keeps confirming them. Backups (files and
 * the clipboard), and tracker rules no longer being checked, count from when the
 * tracker exported them, so an old file can never block anything.
 */
final class FreshnessPolicy
{
    /** How long rules stay fresh after the relay's last confirmation, or their export. */
    static final Duration WINDOW = Duration.ofMinutes(15);
    /** How far in the future an export time may be before it can't be trusted. */
    static final Duration CLOCK_SKEW = Duration.ofMinutes(5);

    private FreshnessPolicy()
    {
    }

    /**
     * @param paired     whether online sync is on and paired, so the relay confirms the rules
     * @param lastSync   the relay's last delivery or confirmation, or null
     * @param exportedAt when the tracker exported the rules, or null
     */
    static boolean isFresh(FateLockedPlugin.RulesSource source, boolean paired, Instant lastSync,
        Instant exportedAt, Instant now)
    {
        if (source == FateLockedPlugin.RulesSource.NONE)
        {
            return false;
        }
        if (source == FateLockedPlugin.RulesSource.RELAY && paired)
        {
            return lastSync != null && Duration.between(lastSync, now).compareTo(WINDOW) < 0;
        }
        if (exportedAt == null || exportedAt.isAfter(now.plus(CLOCK_SKEW)))
        {
            return false;
        }
        return Duration.between(exportedAt, now).compareTo(WINDOW) < 0;
    }
}

package com.fatelocked;

import com.fatelocked.rules.Decision;
import com.fatelocked.rules.DecisionService;

/**
 * How the rules tint a chunk for the edges and the locked land drawn in game (B7, U3), from
 * the decision service, so they say what the sidebar and the HUD say. NOT_READY is owned, so
 * it tints as unlocked. Another character's rules and chunks the rules don't map tint as
 * unknown, which draws nothing.
 */
final class TintPolicy
{
    enum Tint { UNLOCKED, LOCKED, UNKNOWN }

    private TintPolicy()
    {
    }

    static Tint of(Decision decision)
    {
        switch (decision.getStatus())
        {
            case ALLOWED:
            case NOT_READY:
                return Tint.UNLOCKED;
            case LOCKED:
                return Tint.LOCKED;
            default:
                return Tint.UNKNOWN;
        }
    }

    static Tint at(DecisionService decisions, CanonicalChunk chunk)
    {
        return of(decisions.chunk(chunk));
    }
}

package com.fatelocked;

import com.fatelocked.rules.RulesSnapshot;
import java.time.Instant;

/**
 * The rules in force and where they came from. Immutable, and swapped as one
 * reference, so nothing ever sees a new bundle with an old source.
 */
final class ActiveRules
{
    static final ActiveRules NONE =
        new ActiveRules(FateLockedBundle.empty(), FateLockedPlugin.RulesSource.NONE);

    private final FateLockedBundle bundle;
    private final RulesSnapshot snapshot;
    private final FateLockedPlugin.RulesSource source;
    private final RulesPrecedence.Arrival arrival;
    private final Instant arrivedAt;

    /** Rules whose snapshot is built here, for callers that parsed on this thread. */
    ActiveRules(FateLockedBundle bundle, FateLockedPlugin.RulesSource source)
    {
        this(bundle, bundle == null ? null : RulesSnapshot.of(bundle), source, null, null);
    }

    /**
     * Rules with the snapshot their parse already built, off the client thread.
     *
     * @param arrival   how they arrived, or null when not known
     * @param arrivedAt when they arrived: now, or when the last start saved them; null when not known
     */
    ActiveRules(FateLockedBundle bundle, RulesSnapshot snapshot, FateLockedPlugin.RulesSource source,
        RulesPrecedence.Arrival arrival, Instant arrivedAt)
    {
        if (bundle == null || snapshot == null || source == null)
        {
            throw new IllegalArgumentException("rules, their snapshot and their source are required");
        }
        this.bundle = bundle;
        this.snapshot = snapshot;
        this.source = source;
        this.arrival = arrival;
        this.arrivedAt = arrivedAt;
    }

    FateLockedBundle getBundle()
    {
        return bundle;
    }

    RulesSnapshot getSnapshot()
    {
        return snapshot;
    }

    FateLockedPlugin.RulesSource getSource()
    {
        return source;
    }

    /** How the rules arrived, so the status card can say "restored from the last start"; null when not known. */
    RulesPrecedence.Arrival getArrival()
    {
        return arrival;
    }

    /** When the rules arrived, or were saved by the last start; null when not known. */
    Instant getArrivedAt()
    {
        return arrivedAt;
    }
}

package com.fatelocked;

import com.fatelocked.ui.Palette;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The in-game HUD (E6), drawing the plugin's {@link HudModel} on RuneLite's own panel: labels
 * plain, values in the palette's tones, headings in the accent. The model is worked out when
 * anything changes, and the panel is built again only when it or the palette does.
 */
public class FateLockedHudOverlay extends OverlayPanel
{
    private static final int WIDTH = 165;
    /** Detailed lists what the place holds, which needs more room. */
    private static final int DETAILED_WIDTH = 210;

    private final FateLockedPlugin plugin;
    // What the panel shows now.
    private HudModel shown;
    private Palette shownIn;

    @Inject
    FateLockedHudOverlay(FateLockedPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
        setResizable(false);
        setClearChildren(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        HudModel model = plugin.hudModel();
        if (model.getLines().isEmpty()) return null;
        Palette palette = plugin.palette();
        if (model != shown || palette != shownIn)
        {
            build(model, palette);
            shown = model;
            shownIn = palette;
        }
        return super.render(graphics);
    }

    private void build(HudModel model, Palette palette)
    {
        panelComponent.getChildren().clear();
        panelComponent.setPreferredSize(new Dimension(model.isDetailed() ? DETAILED_WIDTH : WIDTH, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text("Fate Locked")
            .color(Palette.ACCENT)
            .build());
        for (HudModel.Line line : model.getLines())
        {
            LineComponent.LineComponentBuilder component = LineComponent.builder().left(line.getLabel());
            if (line.getValue() != null)
            {
                component.leftColor(Palette.TITLE)
                    .right(line.getValue())
                    .rightColor(line.getTone() == null ? Palette.TITLE : palette.text(line.getTone()));
            }
            else
            {
                component.leftColor(line.getTone() == null ? Palette.ACCENT : palette.text(line.getTone()));
            }
            panelComponent.getChildren().add(component.build());
        }
    }
}

package com.fatelocked;

import com.fatelocked.ui.Palette;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.Area;
import java.awt.geom.GeneralPath;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import lombok.Value;

/**
 * Draws the scene's chunk edges tile by tile (U3): each run's tile corners near the player,
 * on the exact chunk line. A corner that can't be projected, off the canvas or behind the
 * camera, breaks the line, so a gap is never bridged. The old outline joined four corners,
 * and vanished whole when any one of them couldn't be projected.
 *
 * <p>Locked edges are dashed over a dark underlay, which says "locked" in any colour (U15).
 * Nothing fills a chunk.
 *
 * <p>The dashes are laid on the ground, each a fixed share of a tile, so they stay put as the
 * camera moves; dashes laid along the screen slid as it turned (the owner's review, 28 Sept).
 * And since RuneLite draws this over the finished scene, a piece of line or fog that a
 * player, NPC or object nearer the camera stands in front of is left out ({@link Occlusion}).
 */
final class ChunkBorderRenderer
{
    /** Only corners within this many tiles of the player are drawn, as RuneLite's ground markers do. */
    static final int RANGE = 32;
    /** How deep the fog on the locked side of an edge goes, in tiles. */
    static final int FOG_TILES = 2;
    /** A dash and its gap on the game view, in tiles: three to a tile. */
    static final double GROUND_PERIOD = 1 / 3.0;
    /**
     * A dash and its gap on the minimap, where a tile is a few pixels: three to a chunk's side,
     * about as long as the screen's dashes were. Both periods divide a chunk's eight tiles, so
     * the pattern is the same on every chunk line and stays put when the scene loads again.
     */
    static final double MINIMAP_PERIOD = 8 / 3.0;
    /** The share of each period that is dash, in its middle, with half the gap at either end. */
    static final double DASH = 0.6;
    /** How far either side of the camera's line of sight to the ground something may stand and hide it, in tiles. */
    static final int ASIDE = 2;

    /** A tile corner of the scene on the canvas, or null when it can't be drawn there. */
    interface Projector
    {
        Point2D project(int sceneX, int sceneY);
    }

    /** One kind of edge, cut into pieces: every piece that shows, joined, and its dashes alone. */
    static final class Lines
    {
        final GeneralPath whole = new GeneralPath();
        final GeneralPath dashes = new GeneralPath();
    }

    private ChunkBorderRenderer()
    {
    }

    /**
     * Draw the edges near the player as the settings say: the fog first, under the lines; in
     * All edges, every chunk line thin and faint; and the locked edges on top. None of it is
     * drawn over what stands in front of it.
     */
    static void draw(Graphics2D graphics, List<SceneEdges.Run> runs, FateLockedConfig.ChunkBorders borders,
        boolean fog, Palette palette, int playerX, int playerY, int sizeX, int sizeY, Projector projector,
        double period, Occlusion occlusion)
    {
        if (fog)
        {
            GeneralPath shade = fog(runs, playerX, playerY, sizeX, sizeY, projector);
            Shape open = occlusion.uncovered(shade);
            graphics.setColor(palette.lockedShade());
            if (open == null)
            {
                graphics.fill(shade);
            }
            else
            {
                Shape before = graphics.getClip();
                graphics.clip(open);
                graphics.fill(shade);
                graphics.setClip(before);
            }
        }
        if (borders == FateLockedConfig.ChunkBorders.ALL_EDGES)
        {
            graphics.setStroke(Palette.PLAIN_EDGE_STROKE);
            graphics.setColor(Palette.PLAIN_EDGE);
            graphics.draw(lines(runs, SceneEdges.Kind.PLAIN, playerX, playerY, sizeX, sizeY, projector, period,
                occlusion).whole);
        }
        if (borders != FateLockedConfig.ChunkBorders.OFF)
        {
            Lines locked = lines(runs, SceneEdges.Kind.LOCKED, playerX, playerY, sizeX, sizeY, projector, period,
                occlusion);
            graphics.setStroke(Palette.UNDERLAY_STROKE);
            graphics.setColor(Palette.UNDERLAY);
            graphics.draw(locked.whole);
            graphics.setStroke(Palette.LOCKED_DASH_STROKE);
            graphics.setColor(palette.lockedEdge());
            graphics.draw(locked.dashes);
        }
    }

    /**
     * The edges of one kind near the player, each tile's line cut where its dashes start and
     * end, so the dashes keep their place on the ground. A piece that something stands in front
     * of is left out, and so is a tile with a corner that can't be projected.
     */
    static Lines lines(List<SceneEdges.Run> runs, SceneEdges.Kind kind, int playerX, int playerY, int sizeX,
        int sizeY, Projector projector, double period, Occlusion occlusion)
    {
        Lines lines = new Lines();
        for (SceneEdges.Run run : runs)
        {
            int[] span = run.getKind() == kind ? near(run, playerX, playerY) : null;
            if (span == null)
            {
                continue;
            }
            boolean joined = false;
            boolean dashing = false;
            Point2D from = corner(run, run.getLine(), span[0], sizeX, sizeY, projector);
            for (int along = span[0]; along < span[1]; along++)
            {
                Point2D to = corner(run, run.getLine(), along + 1, sizeX, sizeY, projector);
                if (from == null || to == null)
                {
                    joined = false;
                    dashing = false;
                    from = to;
                    continue;
                }
                double[] cuts = cuts(along, period);
                for (int i = 0; i + 1 < cuts.length; i++)
                {
                    double start = cuts[i] - along;
                    double end = cuts[i + 1] - along;
                    double middle = (start + end) / 2;
                    double sceneAlong = along + middle;
                    if (occlusion.hides(lerp(from.getX(), to.getX(), middle), lerp(from.getY(), to.getY(), middle),
                        run.isVertical() ? run.getLine() : sceneAlong, run.isVertical() ? sceneAlong : run.getLine()))
                    {
                        joined = false;
                        dashing = false;
                        continue;
                    }
                    double x0 = lerp(from.getX(), to.getX(), start);
                    double y0 = lerp(from.getY(), to.getY(), start);
                    double x1 = lerp(from.getX(), to.getX(), end);
                    double y1 = lerp(from.getY(), to.getY(), end);
                    joined = extend(lines.whole, joined, x0, y0, x1, y1);
                    dashing = dash(sceneAlong, period) && extend(lines.dashes, dashing, x0, y0, x1, y1);
                }
                from = to;
            }
        }
        return lines;
    }

    /**
     * Where the line along one tile is cut, in tiles along its run: at the tile's two corners
     * and at each end of a dash between them. The dashes are counted from the scene's corner,
     * so a piece of line always has the same dashes wherever the player stands.
     */
    static double[] cuts(int along, double period)
    {
        double[] cuts = new double[4 + 2 * (int) Math.ceil(1 / period)];
        int count = 0;
        cuts[count++] = along;
        double gap = (1 - DASH) / 2;
        for (long k = (long) Math.floor(along / period); k * period < along + 1; k++)
        {
            double start = (k + gap) * period;
            double end = (k + 1 - gap) * period;
            if (start > along && start < along + 1)
            {
                cuts[count++] = start;
            }
            if (end > along && end < along + 1)
            {
                cuts[count++] = end;
            }
        }
        cuts[count++] = along + 1;
        return Arrays.copyOf(cuts, count);
    }

    /** Whether a point along a run, in tiles, falls on a dash rather than in a gap. */
    static boolean dash(double along, double period)
    {
        double phase = along / period - Math.floor(along / period);
        return phase > (1 - DASH) / 2 && phase < (1 + DASH) / 2;
    }

    /** Add a piece to a path, joined to the one before it when that one was drawn; true after. */
    private static boolean extend(GeneralPath path, boolean joined, double x0, double y0, double x1, double y1)
    {
        if (!joined)
        {
            path.moveTo(x0, y0);
        }
        path.lineTo(x1, y1);
        return true;
    }

    private static double lerp(double from, double to, double share)
    {
        return from + (to - from) * share;
    }

    /**
     * The fog on the locked side of each locked edge near the player, FOG_TILES deep, as one
     * path of strips. A strip ends where a corner on either of its sides can't be projected.
     */
    static GeneralPath fog(List<SceneEdges.Run> runs, int playerX, int playerY, int sizeX, int sizeY,
        Projector projector)
    {
        GeneralPath path = new GeneralPath();
        List<Point2D> edge = new ArrayList<>();
        List<Point2D> deep = new ArrayList<>();
        for (SceneEdges.Run run : runs)
        {
            int[] span = run.getKind() == SceneEdges.Kind.LOCKED ? near(run, playerX, playerY) : null;
            if (span == null)
            {
                continue;
            }
            int inside = run.getLine() + run.getLockedSide() * FOG_TILES;
            for (int along = span[0]; along <= span[1]; along++)
            {
                Point2D onEdge = corner(run, run.getLine(), along, sizeX, sizeY, projector);
                Point2D inFog = onEdge == null ? null : corner(run, inside, along, sizeX, sizeY, projector);
                if (inFog == null)
                {
                    strip(path, edge, deep);
                    continue;
                }
                edge.add(onEdge);
                deep.add(inFog);
            }
            strip(path, edge, deep);
        }
        return path;
    }

    /**
     * Locked land, as one path of blocks. The minimap's projection is flat, so a block's four
     * corners place it exactly; one that can't be placed is left out.
     */
    static GeneralPath blocks(List<SceneEdges.Block> blocks, Projector projector)
    {
        GeneralPath path = new GeneralPath();
        for (SceneEdges.Block block : blocks)
        {
            Point2D a = projector.project(block.getX0(), block.getY0());
            Point2D b = projector.project(block.getX1(), block.getY0());
            Point2D c = projector.project(block.getX1(), block.getY1());
            Point2D d = projector.project(block.getX0(), block.getY1());
            if (a == null || b == null || c == null || d == null)
            {
                continue;
            }
            path.moveTo(a.getX(), a.getY());
            path.lineTo(b.getX(), b.getY());
            path.lineTo(c.getX(), c.getY());
            path.lineTo(d.getX(), d.getY());
            path.closePath();
        }
        return path;
    }

    /**
     * The tiles where something standing could hide part of what is drawn: those on the way
     * from each piece of drawn ground to the camera, and {@link #ASIDE} either side of them.
     * The ground is the locked edges, with the lines on, and the fog behind them, with it on.
     * Only what stands here is looked at, since working out the outline of everything in the
     * scene each frame would cost too much; the faint lines of All edges have no way of their
     * own for the same reason.
     */
    static boolean[][] corridor(List<SceneEdges.Run> runs, boolean lines, boolean fog, int playerX, int playerY,
        int sizeX, int sizeY, double cameraX, double cameraY, Projector projector)
    {
        boolean[][] sight = new boolean[sizeX][sizeY];
        for (SceneEdges.Run run : runs)
        {
            int[] span = run.getKind() == SceneEdges.Kind.LOCKED ? near(run, playerX, playerY) : null;
            if (span == null)
            {
                continue;
            }
            for (int along = span[0]; along < span[1]; along++)
            {
                // A tile behind the camera shows nothing to hide.
                if (corner(run, run.getLine(), along, sizeX, sizeY, projector) == null)
                {
                    continue;
                }
                if (lines)
                {
                    look(sight, run, run.getLine(), along + 0.5, cameraX, cameraY);
                }
                for (int depth = 0; fog && depth < FOG_TILES; depth++)
                {
                    look(sight, run, run.getLine() + run.getLockedSide() * (depth + 0.5), along + 0.5, cameraX,
                        cameraY);
                }
            }
        }
        boolean[][] corridor = new boolean[sizeX][sizeY];
        for (int x = 0; x < sizeX; x++)
        {
            for (int y = 0; y < sizeY; y++)
            {
                if (!sight[x][y])
                {
                    continue;
                }
                for (int aside = Math.max(0, x - ASIDE); aside <= Math.min(sizeX - 1, x + ASIDE); aside++)
                {
                    for (int ahead = Math.max(0, y - ASIDE); ahead <= Math.min(sizeY - 1, y + ASIDE); ahead++)
                    {
                        corridor[aside][ahead] = true;
                    }
                }
            }
        }
        return corridor;
    }

    /** Mark each tile on the way from a point on the ground to below the camera, a tile at a time. */
    private static void look(boolean[][] sight, SceneEdges.Run run, double across, double along, double cameraX,
        double cameraY)
    {
        double x = run.isVertical() ? across : along;
        double y = run.isVertical() ? along : across;
        double distance = Math.hypot(cameraX - x, cameraY - y);
        for (double step = 0; step <= distance; step++)
        {
            double share = step / Math.max(distance, 1);
            int tileX = (int) Math.floor(x + (cameraX - x) * share);
            int tileY = (int) Math.floor(y + (cameraY - y) * share);
            if (tileX >= 0 && tileY >= 0 && tileX < sight.length && tileY < sight[tileX].length)
            {
                sight[tileX][tileY] = true;
            }
        }
    }

    /** Close one strip: along the edge, then back along its far side. */
    private static void strip(GeneralPath path, List<Point2D> edge, List<Point2D> deep)
    {
        if (edge.size() > 1)
        {
            path.moveTo(edge.get(0).getX(), edge.get(0).getY());
            for (int i = 1; i < edge.size(); i++)
            {
                path.lineTo(edge.get(i).getX(), edge.get(i).getY());
            }
            for (int i = deep.size() - 1; i >= 0; i--)
            {
                path.lineTo(deep.get(i).getX(), deep.get(i).getY());
            }
            path.closePath();
        }
        edge.clear();
        deep.clear();
    }

    /** The part of a run within RANGE of the player, as {from, to}, or null when none is. */
    private static int[] near(SceneEdges.Run run, int playerX, int playerY)
    {
        int across = run.getLine() - (run.isVertical() ? playerX : playerY);
        int at = run.isVertical() ? playerY : playerX;
        int from = Math.max(run.getFrom(), at - RANGE);
        int to = Math.min(run.getTo(), at + RANGE);
        return Math.abs(across) > RANGE || from > to ? null : new int[] {from, to};
    }

    /** A corner on a run's line, or on a line beside it; null off the scene, where RuneLite has no ground height. */
    private static Point2D corner(SceneEdges.Run run, int line, int along, int sizeX, int sizeY, Projector projector)
    {
        int x = run.isVertical() ? line : along;
        int y = run.isVertical() ? along : line;
        if (x < 0 || y < 0 || x >= sizeX || y >= sizeY)
        {
            return null;
        }
        return projector.project(x, y);
    }

    /**
     * What stands between the camera and the ground: players, NPCs and objects, each by its
     * outline on the canvas and where it stands in the scene. A piece of ground is behind one
     * when that one stands nearer the camera, going by where each is on the ground, and its
     * outline covers the piece.
     */
    static final class Occlusion
    {
        /** Nothing in front of anything, as on the minimap. */
        static final Occlusion NONE = new Occlusion(0, 0, Collections.emptyList());

        private final double cameraX;
        private final double cameraY;
        /** Nearest the camera first, each with how far it is and the box around its outline. */
        private final Shape[] hulls;
        private final double[] distances;
        private final Rectangle2D[] boxes;

        /** The camera's place over the ground and what stands there, in the scene's tiles. */
        Occlusion(double cameraX, double cameraY, List<Occluder> occluders)
        {
            this.cameraX = cameraX;
            this.cameraY = cameraY;
            List<Occluder> nearest = new ArrayList<>(occluders);
            nearest.sort(Comparator.comparingDouble(o -> distance(o.getSceneX(), o.getSceneY())));
            hulls = new Shape[nearest.size()];
            distances = new double[nearest.size()];
            boxes = new Rectangle2D[nearest.size()];
            for (int i = 0; i < nearest.size(); i++)
            {
                Occluder occluder = nearest.get(i);
                hulls[i] = occluder.getHull();
                distances[i] = distance(occluder.getSceneX(), occluder.getSceneY());
                boxes[i] = occluder.getHull().getBounds2D();
            }
        }

        /** Whether the ground at a scene point, drawn at a canvas point, is behind something. */
        boolean hides(double canvasX, double canvasY, double sceneX, double sceneY)
        {
            if (hulls.length == 0)
            {
                return false;
            }
            double distance = distance(sceneX, sceneY);
            for (int i = 0; i < hulls.length && distances[i] < distance; i++)
            {
                if (boxes[i].contains(canvasX, canvasY) && hulls[i].contains(canvasX, canvasY))
                {
                    return true;
                }
            }
            return false;
        }

        /**
         * The part of the canvas around some ground that nothing stands on or in front of, to
         * draw that ground through; null when nothing reaches it. The fog lies on the ground,
         * so whatever covers it on the canvas stands in it or before it.
         */
        Shape uncovered(Shape ground)
        {
            Rectangle2D bounds = ground.getBounds2D();
            Area open = null;
            for (int i = 0; i < hulls.length; i++)
            {
                if (boxes[i].intersects(bounds) && ground.intersects(boxes[i]))
                {
                    if (open == null)
                    {
                        open = new Area(bounds);
                    }
                    open.subtract(new Area(hulls[i]));
                }
            }
            return open;
        }

        private double distance(double sceneX, double sceneY)
        {
            return Math.hypot(sceneX - cameraX, sceneY - cameraY);
        }
    }

    /** Something standing in the scene: its outline on the canvas, and where it stands, in tiles. */
    @Value
    static class Occluder
    {
        Shape hull;
        double sceneX;
        double sceneY;
    }
}

package com.fatelocked;

import com.fatelocked.sidebar.ConnectionModel;
import com.fatelocked.sidebar.HereModel;
import com.fatelocked.sidebar.RollInboxModel;
import com.fatelocked.sidebar.RunModel;
import com.fatelocked.sidebar.StatusCardModel;
import com.fatelocked.sidebar.StrictModeModel;
import com.fatelocked.ui.Palette;
import java.util.Objects;

/**
 * Hands the sidebar only what changed (A9): the plugin works the models out every tick,
 * and an unchanged one is never posted to the Swing thread again. Client thread only.
 */
final class SidebarPublisher
{
    private final FateLockedPanel panel;
    private StatusCardModel status;
    private HereModel here;
    private StrictModeModel strictMode;
    private RunModel run;
    private ConnectionModel connection;
    private RollInboxModel rollInbox;
    private Palette palette = Palette.defaults();

    SidebarPublisher(FateLockedPanel panel)
    {
        this.panel = panel;
    }

    void palette(Palette next)
    {
        if (next != palette)
        {
            palette = next;
            panel.setPalette(next);
        }
    }

    void status(StatusCardModel next)
    {
        if (!Objects.equals(next, status))
        {
            status = next;
            panel.showStatus(next);
        }
    }

    void here(HereModel next)
    {
        if (!Objects.equals(next, here))
        {
            here = next;
            panel.showHere(next);
        }
    }

    void strictMode(StrictModeModel next)
    {
        if (!Objects.equals(next, strictMode))
        {
            strictMode = next;
            panel.showStrictMode(next);
        }
    }

    void run(RunModel next)
    {
        if (!Objects.equals(next, run))
        {
            run = next;
            panel.showRun(next);
        }
    }

    void connection(ConnectionModel next)
    {
        if (!Objects.equals(next, connection))
        {
            connection = next;
            panel.showConnection(next);
        }
    }

    void rollInbox(RollInboxModel next)
    {
        if (!Objects.equals(next, rollInbox))
        {
            rollInbox = next;
            panel.showRollInbox(next);
        }
    }
}

package com.fatelocked;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.MenuAction;

/**
 * The menu options a " (Locked)" tag could ever go on, by their type alone (F1, A9). The tag
 * reads two things: travel the tracker's table matches by id, on an item or a spell, an object
 * or an NPC; and the chunk something stands in, an NPC, an object or an item on the ground.
 * Walk here, Cancel, Examine, other players and RuneLite's own options have neither, so the menu
 * passes them over before any text is read, and they cost nothing.
 */
final class MenuTagFilter
{
    private static final Set<MenuAction> TAGGABLE = EnumSet.of(
        MenuAction.CC_OP,
        MenuAction.CC_OP_LOW_PRIORITY,
        MenuAction.GAME_OBJECT_FIRST_OPTION,
        MenuAction.GAME_OBJECT_SECOND_OPTION,
        MenuAction.GAME_OBJECT_THIRD_OPTION,
        MenuAction.GAME_OBJECT_FOURTH_OPTION,
        MenuAction.GAME_OBJECT_FIFTH_OPTION,
        MenuAction.GROUND_ITEM_FIRST_OPTION,
        MenuAction.GROUND_ITEM_SECOND_OPTION,
        MenuAction.GROUND_ITEM_THIRD_OPTION,
        MenuAction.GROUND_ITEM_FOURTH_OPTION,
        MenuAction.GROUND_ITEM_FIFTH_OPTION,
        MenuAction.NPC_FIRST_OPTION,
        MenuAction.NPC_SECOND_OPTION,
        MenuAction.NPC_THIRD_OPTION,
        MenuAction.NPC_FOURTH_OPTION,
        MenuAction.NPC_FIFTH_OPTION,
        // An item used, or a spell cast, on an NPC: tagged by where the NPC stands.
        MenuAction.WIDGET_TARGET_ON_NPC);

    private MenuTagFilter()
    {
    }

    /** Whether an option of this type could be tagged; one with no type never is. */
    static boolean mayTag(MenuAction type)
    {
        return TAGGABLE.contains(type);
    }
}

package com.fatelocked;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The fade when a locked area is entered from unlocked land (U20): a frame around the view in
 * the palette's locked colour, fading out once ({@link FlashFade}). It never pulses; the old
 * frame pulsed at about 2.5 Hz. Whether it shows is the locked-area alert's to decide.
 */
public class FateLockedFlashOverlay extends Overlay
{
    private static final int FRAME_THICKNESS = 14;
    private static final BasicStroke FRAME = new BasicStroke(FRAME_THICKNESS);

    private final Client client;
    private final FateLockedPlugin plugin;
    /** The monotonic clock the fade is timed on, in nanoseconds. */
    private final LongSupplier clock;

    @Inject
    FateLockedFlashOverlay(Client client, FateLockedPlugin plugin)
    {
        this(client, plugin, System::nanoTime);
    }

    FateLockedFlashOverlay(Client client, FateLockedPlugin plugin, LongSupplier clock)
    {
        this.client = client;
        this.plugin = plugin;
        this.clock = clock;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        long at = plugin.getLockedFadeAt();
        if (at == FateLockedPlugin.NO_FADE) return null;
        int alpha = FlashFade.alpha((clock.getAsLong() - at) / 1_000_000);
        if (alpha == 0) return null;
        draw(graphics, plugin.palette().flash(), alpha, client.getCanvasWidth(), client.getCanvasHeight());
        return null;
    }

    /** The frame, in this colour at this alpha, around a view this size. */
    static void draw(Graphics2D graphics, Color colour, int alpha, int width, int height)
    {
        Composite before = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha / 255f));
        graphics.setColor(colour);
        graphics.setStroke(FRAME);
        graphics.drawRect(FRAME_THICKNESS / 2, FRAME_THICKNESS / 2, width - FRAME_THICKNESS, height - FRAME_THICKNESS);
        graphics.setComposite(before);
    }
}

package com.fatelocked;

import java.time.Instant;

/** The last rules the plugin accepted, as kept for the next start. */
final class SavedRules
{
    private final String payload;
    private final FateLockedPlugin.RulesSource source;
    private final Instant savedAt;
    private final String relayVersion;
    private final String pairingTag;

    /**
     * @param payload the bundle as the plugin received it, plain or "FLGZ:"
     * @param relayVersion the relay's version of these rules; relay rules only
     * @param pairingTag PairingSupport.tag of the pairing that sent them; relay rules only
     */
    SavedRules(
        String payload,
        FateLockedPlugin.RulesSource source,
        Instant savedAt,
        String relayVersion,
        String pairingTag)
    {
        if (payload == null || payload.trim().isEmpty() || savedAt == null
            || source == null || source == FateLockedPlugin.RulesSource.NONE)
        {
            throw new IllegalArgumentException("saved rules need a payload, a source and a time");
        }
        this.payload = payload;
        this.source = source;
        this.savedAt = savedAt;
        this.relayVersion = relayVersion;
        this.pairingTag = pairingTag;
    }

    String getPayload()
    {
        return payload;
    }

    FateLockedPlugin.RulesSource getSource()
    {
        return source;
    }

    Instant getSavedAt()
    {
        return savedAt;
    }

    String getRelayVersion()
    {
        return relayVersion;
    }

    String getPairingTag()
    {
        return pairingTag;
    }
}

package com.fatelocked.sidebar;

import com.fatelocked.ui.Art;
import com.fatelocked.ui.ArtSlot;
import com.fatelocked.ui.FlatButton;
import com.fatelocked.ui.Hairline;
import com.fatelocked.ui.IconSource;
import com.fatelocked.ui.Palette;
import com.fatelocked.ui.Section;
import com.fatelocked.ui.Space;
import com.fatelocked.ui.Stack;
import com.fatelocked.ui.StatusPill;
import com.fatelocked.ui.Terms;
import com.fatelocked.ui.ToggleSwitch;
import com.fatelocked.ui.Type;
import java.awt.BorderLayout;
import java.awt.GridBagLayout;
import java.util.function.Consumer;
import javax.swing.JPanel;

/**
 * The Strict Mode section, drawn from a {@link StrictModeModel}. The switch in its
 * header is the one setting the sidebar keeps besides online sync (Decision 4). The
 * section is open while Strict Mode is on and closed while it is off.
 */
public class StrictModeView extends Section
{
    static final String INTRO = "Strict Mode stops a teleport only when it can match the trip exactly and"
        + " fresh rules for this character lock where it goes. Walking, NPCs, objects, banks and equipment are"
        + " never stopped; tags and warnings cover those. Pause it for 60 seconds here, or with a hotkey you"
        + " can set in RuneLite's configuration.";

    private final ToggleSwitch toggle = new ToggleSwitch();
    private final IconSource icons;
    private Consumer<Boolean> onToggle = on -> { };
    private Runnable onIntroDismiss = () -> { };
    private boolean introShown;
    private Consumer<CardAction> onAction = action -> { };
    private Palette palette = Palette.defaults();
    private StrictModeModel model;

    public StrictModeView(IconSource icons)
    {
        super(Terms.STRICT_MODE, false);
        this.icons = icons;
        toggle.setToolTipText("Turn Strict Mode on or off");
        toggle.addActionListener(e -> onToggle.accept(toggle.isSelected()));
        setTrailing(toggle);
    }

    /** Called with the switch's new position when the player flips it. */
    public void onToggle(Consumer<Boolean> handler)
    {
        onToggle = handler;
    }

    public void onAction(Consumer<CardAction> handler)
    {
        onAction = handler;
    }

    /** Called when the player dismisses the first-time explanation. */
    public void onIntroDismiss(Runnable handler)
    {
        onIntroDismiss = handler;
    }

    /** Explain Strict Mode once, the first time it is turned on, until dismissed. */
    public void showIntro()
    {
        introShown = true;
        setExpanded(true);
        if (model != null)
        {
            apply(model);
        }
    }

    public boolean isIntroShown()
    {
        return introShown;
    }

    public void setPalette(Palette palette)
    {
        this.palette = palette;
        if (model != null)
        {
            apply(model);
        }
    }

    public ToggleSwitch toggle()
    {
        return toggle;
    }

    public void apply(StrictModeModel model)
    {
        boolean wasOn = this.model != null && this.model.isOn();
        this.model = model;
        toggle.setSelected(model.isOn());
        setCount(model.isOn() ? null : model.getWord());
        JPanel body = body();
        body.removeAll();
        if (introShown)
        {
            body.add(intro());
        }

        JPanel state = new JPanel(new BorderLayout(Space.ICON_GAP, 0));
        state.setOpaque(false);
        ArtSlot teleBlock = new ArtSlot(20);
        icons.load(model.getTone() == Palette.Tone.GOOD ? Art.STRICT_MODE : Art.STRICT_MODE_OFF,
            teleBlock::setImage);
        StatusPill pill = new StatusPill(model.getWord(), model.getTone());
        pill.setPalette(palette);
        JPanel pillCentre = new JPanel(new GridBagLayout());
        pillCentre.setOpaque(false);
        pillCentre.add(pill);
        JPanel pillSlot = new JPanel(new BorderLayout(Space.ICON_GAP, 0));
        pillSlot.setOpaque(false);
        pillSlot.add(teleBlock, BorderLayout.WEST);
        pillSlot.add(pillCentre, BorderLayout.CENTER);
        state.add(pillSlot, BorderLayout.WEST);
        if (model.getAction() != null)
        {
            FlatButton button = new FlatButton(model.getAction().label(), FlatButton.Kind.SECONDARY);
            CardAction action = model.getAction();
            button.addActionListener(e -> onAction.accept(action));
            state.add(button, BorderLayout.EAST);
        }
        body.add(state);
        if (model.getDetail() != null)
        {
            body.add(Sidebar.text(model.getDetail(), Type.small(), Palette.TEXT_MUTED, 0));
        }
        if (!model.getRecent().isEmpty())
        {
            body.add(new Hairline());
            body.add(Sidebar.text("Recently stopped", Type.small(), Palette.TEXT_MUTED, 1));
            for (String line : model.getRecent())
            {
                body.add(Sidebar.text(line, Type.body(), Palette.TEXT, 2));
            }
        }
        if (model.isOn() != wasOn)
        {
            setExpanded(model.isOn());
        }
        body.revalidate();
        body.repaint();
    }

    public StrictModeModel model()
    {
        return model;
    }

    private JPanel intro()
    {
        JPanel intro = new JPanel(new Stack(Space.ROW));
        intro.setOpaque(false);
        intro.add(Sidebar.text(INTRO, Type.small(), Palette.TEXT, 0));
        FlatButton gotIt = new FlatButton("Got it", FlatButton.Kind.LINK);
        gotIt.addActionListener(e -> {
            introShown = false;
            onIntroDismiss.run();
            if (model != null)
            {
                apply(model);
            }
        });
        JPanel left = new JPanel(new BorderLayout());
        left.setOpaque(false);
        left.add(gotIt, BorderLayout.WEST);
        intro.add(left);
        intro.add(new Hairline());
        return intro;
    }
}

package com.fatelocked.sidebar;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * What a row of the Here card points at in the game, when the player clicks it (the owner's
 * review, 28 Sept): the names the thing goes by there, an object's or an NPC's. The tracker
 * names skilling spots, monsters and patches as the game does, but for the fly-fishing spots,
 * which the game calls rod fishing spots. A bank goes by its booths,
 * chests and bankers; a shop by whoever runs it, which its name often gives
 * ("Bob's Brilliant Axes": Bob) or which a general store's shop keeper is.
 */
@Value
public class PointTarget
{
    /** Categories whose rows the card can point at; quests and travel have no one thing to point at. */
    static final Set<String> CATEGORIES = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        "SKILLING", "COMBAT", "BANKS", "SHOPS", "FARMING", "ACTIVITIES")));

    /** What a fishing spot offers, as its options say. */
    private static final Set<String> FISHING = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        "net", "small net", "big net", "bait", "lure", "cage", "harpoon", "use-rod", "fish")));
    private static final String FISHING_SPOT = "fishing spot";
    /** What the game calls the spots fished with a rod: lure and bait. */
    private static final String ROD_FISHING_SPOT = "rod fishing spot";
    private static final Pattern VARIANT = Pattern.compile("^(.*\\S)\\s*\\(([^()]*)\\)$");
    private static final Pattern OWNER = Pattern.compile("^(.+?)'s\\s");
    private static final Pattern INN = Pattern.compile("\\b(inn|arms|bar|pub|tavern)\\b");

    /** The category it's in, as the tracker keys it: SKILLING, SHOPS and so on. */
    String category;
    /** The row as the card shows it. */
    String label;
    /** The names it goes by in the game, lower case. */
    Set<String> names;
    /** Options it must offer, lower case, such as a fishing spot's lure and bait; empty for any. */
    Set<String> actions;

    /** Whether the card can point at a category's rows. */
    public static boolean pointable(String category)
    {
        return CATEGORIES.contains(category);
    }

    /** The target for a row of a category, or null for a category the card can't point in. */
    public static PointTarget of(String category, String row)
    {
        if (!pointable(category) || row == null || row.trim().isEmpty())
        {
            return null;
        }
        String label = row.trim();
        String base = label;
        String variant = null;
        Matcher split = VARIANT.matcher(label);
        if (split.matches())
        {
            base = split.group(1);
            variant = split.group(2);
        }
        String name = key(base);
        Set<String> names = new LinkedHashSet<>();
        Set<String> actions = new LinkedHashSet<>();
        switch (category)
        {
            case "BANKS":
                names.addAll(Arrays.asList("bank booth", "bank chest", "banker"));
                break;
            case "SHOPS":
                names.add(name);
                Matcher owner = OWNER.matcher(base);
                if (owner.find())
                {
                    names.add(key(owner.group(1)));
                }
                if (name.contains("general store"))
                {
                    names.addAll(Arrays.asList("shop keeper", "shop assistant"));
                }
                if (INN.matcher(name).find())
                {
                    names.addAll(Arrays.asList("bartender", "barmaid"));
                }
                break;
            case "FARMING":
                names.add(name);
                if (name.endsWith(" patch"))
                {
                    names.add(name.substring(0, name.length() - " patch".length()));
                }
                break;
            default:
                names.add(name);
                if (name.equals(FISHING_SPOT))
                {
                    names.add(ROD_FISHING_SPOT);
                }
                if (variant != null && name.equals(FISHING_SPOT))
                {
                    for (String option : variant.split(","))
                    {
                        actions.add(key(option));
                    }
                    if (!FISHING.containsAll(actions))
                    {
                        // A bracket that names a place or a kind, not what the spot offers.
                        actions.clear();
                    }
                }
        }
        return new PointTarget(category, label, Collections.unmodifiableSet(names),
            Collections.unmodifiableSet(actions));
    }

    /** Whether a thing in the game, by its name and options, is this target. */
    public boolean matches(String name, String[] options)
    {
        if (name == null || !names.contains(key(name)))
        {
            return false;
        }
        if (actions.isEmpty())
        {
            return true;
        }
        Set<String> offered = new HashSet<>();
        if (options != null)
        {
            for (String option : options)
            {
                if (option != null)
                {
                    offered.add(key(option));
                }
            }
        }
        return offered.containsAll(actions);
    }

    private static String key(String text)
    {
        return text.trim().toLowerCase(Locale.ROOT);
    }
}

