package com.fatelocked.sidebar;

/** What the Here card says about its arrow, after the player clicks a row. */
public final class PointerText
{
    private PointerText()
    {
    }

    /** The arrow is on the nearest one; on the player's floor, or another. */
    public static String pointing(String row, boolean sameFloor)
    {
        return sameFloor ? "The arrow points at the nearest " + row + "."
            : "The nearest " + row + " is on another floor. The arrow marks where.";
    }

    /** None is loaded near the player, and none has been seen in the place they stand in. */
    public static String notFound(String row)
    {
        return "Can't find " + row + " near you here. Once you've been near one, clicking it shows the way back.";
    }

    /**
     * None is loaded near the player: the way to the nearest seen in the place, drawn by
     * Shortest Path. The line stays up as the player crosses other places, so it names this one.
     */
    public static String routed(String row, String place)
    {
        return "Shortest Path shows the way to the nearest " + row + " you've seen " + in(place) + ".";
    }

    /** None is loaded near the player: the game's arrow and a pin point the way to the nearest seen in the place. */
    public static String remembered(String row, String place)
    {
        return "The minimap's arrow points the way to the nearest " + row + " you've seen " + in(place)
            + ", and the world map has a pin.";
    }

    /** At the spot, and nothing there now: that spot is forgotten. */
    public static String gone(String row, String place)
    {
        return "The " + row + " you saw " + in(place) + " has moved or gone, so that spot is forgotten.";
    }

    private static String in(String place)
    {
        return place == null ? "here" : "in " + place;
    }
}

package com.fatelocked.sidebar;

import com.fatelocked.ui.Card;
import com.fatelocked.ui.FlatButton;
import com.fatelocked.ui.Flow;
import com.fatelocked.ui.Palette;
import com.fatelocked.ui.Space;
import com.fatelocked.ui.TextBlock;
import com.fatelocked.ui.Type;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The status card, drawn from a {@link StatusCardModel}. */
public class StatusCardView extends Card
{
    private final TextBlock title = new TextBlock(Type.title(), Palette.TEXT, 2, Sidebar.TEXT_WIDTH);
    private final TextBlock detail = new TextBlock(Type.body(), Palette.TEXT_MUTED, 0, Sidebar.TEXT_WIDTH);
    private final JPanel actions = new JPanel(new Flow(Space.GAP, Space.ROW, Sidebar.TEXT_WIDTH));
    private Consumer<CardAction> onAction = action -> { };
    private Palette palette = Palette.defaults();
    private StatusCardModel model;

    public StatusCardView()
    {
        add(title);
        add(detail);
        actions.setOpaque(false);
        actions.setBorder(new EmptyBorder(Space.ROW, 0, 0, 0));
        add(actions);
    }

    public void onAction(Consumer<CardAction> handler)
    {
        onAction = handler;
    }

    public void setPalette(Palette palette)
    {
        this.palette = palette;
        if (model != null)
        {
            apply(model);
        }
    }

    public void apply(StatusCardModel model)
    {
        this.model = model;
        setAccent(palette.text(model.getTone()));
        title.setForeground(palette.text(model.getTone()));
        title.setText(model.getTitle());
        detail.setText(model.getDetail());
        detail.setVisible(model.getDetail() != null);
        actions.removeAll();
        if (model.getPrimary() != null)
        {
            actions.add(button(model.getPrimary(), FlatButton.Kind.PRIMARY));
        }
        if (model.getSecondary() != null)
        {
            actions.add(button(model.getSecondary(),
                model.getPrimary() == null ? FlatButton.Kind.SECONDARY : FlatButton.Kind.LINK));
        }
        actions.setVisible(actions.getComponentCount() > 0);
        revalidate();
        repaint();
    }

    public StatusCardModel model()
    {
        return model;
    }

    private FlatButton button(CardAction action, FlatButton.Kind kind)
    {
        FlatButton button = new FlatButton(action.label(), kind);
        button.addActionListener(e -> onAction.accept(action));
        return button;
    }
}

package com.fatelocked.sidebar;

import com.fatelocked.ui.FlatButton;
import com.fatelocked.ui.Hairline;
