package com.fatelocked;

import com.fatelocked.storage.LocalFileMerge;
import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * Where the player has seen what the Here card can point at (the owner's review, 28 Sept), so
 * a click can show the way to one that is out of sight: for each chunk and row, the tiles it
 * was seen on. It is kept in the plugin's own folder on this computer, in {@link #FILE}, and
 * never sent anywhere. A row keeps the {@link #PER_ROW} spots found last, and a spot within
 * {@link #SAME_SPOT} tiles of one it has is the same one, as a shopkeeper wanders the shop.
 */
final class SpotMemory
{
    static final String FILE = "spots.json";
    static final int PER_ROW = 8;
    static final int SAME_SPOT = 3;

    /** A tile in the world. */
    @Value
    static class Spot
    {
        int x;
        int y;
        int plane;

        /** Whether another spot is on this one's floor, within {@link #SAME_SPOT} tiles of it. */
        boolean near(Spot other)
        {
            return plane == other.plane && Math.max(Math.abs(x - other.x), Math.abs(y - other.y)) <= SAME_SPOT;
        }
    }

    /** Each row's spots, the first found first, by {@link #key}. */
    private Map<String, List<Spot>> rows = new HashMap<>();
    /** Spots found empty since the last save, so the file loses them too. */
    private final Map<String, List<Spot>> gone = new HashMap<>();
    private boolean changed;

    static String key(CanonicalChunk chunk, String category, String row)
    {
        return chunk.getCx() + "," + chunk.getCy() + "|" + category + "|" + row;
    }

    /** One of a chunk's rows seen at a spot: true when the spot is new. */
    synchronized boolean see(CanonicalChunk chunk, String category, String row, Spot spot)
    {
        String key = key(chunk, category, row);
        if (!add(rows, key, spot))
        {
            return false;
        }
        List<Spot> emptied = gone.get(key);
        if (emptied != null)
        {
            emptied.removeIf(spot::near);
        }
        changed = true;
        return true;
    }

    /** The spot seen nearest a tile, on its floor first; null when none has been seen. */
    synchronized Spot nearest(CanonicalChunk chunk, String category, String row, Spot from)
    {
        List<Spot> spots = chunk == null || from == null ? null : rows.get(key(chunk, category, row));
        Spot best = null;
        for (Spot spot : spots == null ? new ArrayList<Spot>() : spots)
        {
            if (best == null || nearer(spot, best, from))
            {
                best = spot;
            }
        }
        return best;
    }

    /** Nothing at a spot now: it's forgotten, and at the next save the file forgets it too. */
    synchronized void forget(CanonicalChunk chunk, String category, String row, Spot spot)
    {
        String key = key(chunk, category, row);
        List<Spot> spots = rows.get(key);
        if (spots != null)
        {
            spots.removeIf(spot::near);
        }
        gone.computeIfAbsent(key, k -> new ArrayList<>()).add(spot);
        changed = true;
    }

    /** Whether anything has changed since the last save. */
    synchronized boolean changed()
    {
        return changed;
    }

    /** Add what the file holds to what's known. A damaged file is set aside, as the others are. */
    void load(Gson gson, Path path) throws IOException
    {
        LocalFileMerge.update(path, current -> {
            Map<String, List<Spot>> stored = read(gson, current, path);
            synchronized (this)
            {
                for (Map.Entry<String, List<Spot>> row : stored.entrySet())
                {
                    for (Spot spot : row.getValue())
                    {
                        if (!isGone(row.getKey(), spot))
                        {
                            add(rows, row.getKey(), spot);
                        }
                    }
                }
            }
            return null;
        });
    }

    /**
     * Write what's known into the file as it is now, since another RuneLite on this computer
     * may have added to it, and keep what that adds too.
     */
    void save(Gson gson, Path path) throws IOException
    {
        LocalFileMerge.update(path, current -> {
            Map<String, List<Spot>> merged = read(gson, current, path);
            synchronized (this)
            {
                for (Map.Entry<String, List<Spot>> row : rows.entrySet())
                {
                    for (Spot spot : row.getValue())
                    {
                        add(merged, row.getKey(), spot);
                    }
                }
                for (Map.Entry<String, List<Spot>> row : gone.entrySet())
                {
                    List<Spot> spots = merged.get(row.getKey());
                    for (Spot spot : row.getValue())
                    {
                        if (spots != null)
                        {
                            spots.removeIf(spot::near);
                        }
                    }
                }
                merged.values().removeIf(List::isEmpty);
                rows = merged;
                gone.clear();
                changed = false;
                return gson.toJson(stored(merged)).getBytes(StandardCharsets.UTF_8);
            }
        });
    }

    private boolean isGone(String key, Spot spot)
    {
        List<Spot> emptied = gone.get(key);
        return emptied != null && emptied.stream().anyMatch(spot::near);
    }

    /** Add a spot to a row unless it has one there: true when added. Past the limit, the first found goes. */
    private static boolean add(Map<String, List<Spot>> rows, String key, Spot spot)
    {
        List<Spot> spots = rows.computeIfAbsent(key, k -> new ArrayList<>());
        for (Spot known : spots)
        {
            if (known.near(spot))
            {
                return false;
            }
        }
        spots.add(spot);
        if (spots.size() > PER_ROW)
        {
            spots.remove(0);
        }
        return true;
    }

    /** On the tile's floor before another, then nearer. */
    private static boolean nearer(Spot spot, Spot best, Spot from)
    {
        boolean onFloor = spot.getPlane() == from.getPlane();
        if (onFloor != (best.getPlane() == from.getPlane()))
        {
            return onFloor;
        }
        return distance(spot, from) < distance(best, from);
    }

    private static long distance(Spot a, Spot b)
    {
        long dx = a.getX() - b.getX();
        long dy = a.getY() - b.getY();
        return dx * dx + dy * dy;
    }

    /** The file's rows; none when there is no file, or it is damaged, and then it's set aside. */
    private static Map<String, List<Spot>> read(Gson gson, byte[] bytes, Path path) throws IOException
    {
        Map<String, List<Spot>> rows = new HashMap<>();
        if (bytes == null)
        {
            return rows;
        }
        try
        {
            Stored stored = gson.fromJson(new String(bytes, StandardCharsets.UTF_8), Stored.class);
            if (stored == null || stored.rows == null)
            {
                throw new IllegalStateException("no rows");
            }
            for (Map.Entry<String, List<int[]>> row : stored.rows.entrySet())
            {
                for (int[] tile : row.getValue() == null ? new ArrayList<int[]>() : row.getValue())
                {
                    if (row.getKey() != null && tile != null && tile.length == 3)
                    {
                        add(rows, row.getKey(), new Spot(tile[0], tile[1], tile[2]));
                    }
                }
            }
            return rows;
        }
        catch (RuntimeException damaged)
        {
            LocalFileMerge.moveAside(path);
            return new HashMap<>();
        }
    }

    private static Stored stored(Map<String, List<Spot>> rows)
    {
        Stored stored = new Stored();
        stored.rows = new HashMap<>();
        for (Map.Entry<String, List<Spot>> row : rows.entrySet())
        {
            List<int[]> tiles = new ArrayList<>();
            for (Spot spot : row.getValue())
            {
                tiles.add(new int[] {spot.getX(), spot.getY(), spot.getPlane()});
            }
            stored.rows.put(row.getKey(), tiles);
        }
        return stored;
    }

    /** The file: each row's spots as x, y and floor. */
    private static final class Stored
    {
        int version = 1;
        Map<String, List<int[]>> rows;
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.Trust;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The chunk lines around the player on the game scene (U3): locked edges dashed over a dark
 * underlay and, under All edges, every other chunk line thin and faint. With "shade nearby
 * locked", a short fog lies on the locked side of each locked edge. Nothing fills a chunk, and
 * nothing is drawn without rules for the character playing.
 *
 * <p>Where the edges run is worked out once per scene ({@link SceneEdgesCache}); only the
 * projection is done each frame, since the camera moves ({@link ChunkBorderRenderer}). So is
 * what stands in front of the lines, from the players, NPCs and objects between them and the
 * camera: RuneLite draws over the finished scene, and the lines would cover them.
 */
public class FateLockedSceneOverlay extends Overlay
{
    private final Client client;
    private final FateLockedPlugin plugin;
    private final FateLockedConfig config;

    @Inject
    FateLockedSceneOverlay(Client client, FateLockedPlugin plugin, FateLockedConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        FateLockedConfig.ChunkBorders borders = config.chunkBorders();
        boolean fog = config.shadeNearbyLocked();
        if (borders == FateLockedConfig.ChunkBorders.OFF && !fog) return null;
        DecisionService decisions = plugin.decisions();
        // Another character's rules, or none, draw nothing (B6).
        if (decisions.trust() != Trust.TRUSTED) return null;
        WorldView view = client.getTopLevelWorldView();
        Located here = plugin.chunkLocator().playerInScene();
        if (view == null || here == null) return null;

        int plane = here.getPlane();
        SceneEdges scene = plugin.sceneEdges(decisions, view, plane);
        if (scene.edges().isEmpty()) return null;
        ChunkBorderRenderer.Projector projector = (x, y) ->
        {
            Point canvas = Perspective.localToCanvas(client, corner(x, y, view), plane);
            return canvas == null ? null : new Point2D.Double(canvas.getX(), canvas.getY());
        };
        double cameraX = client.getCameraFpX() / Perspective.LOCAL_TILE_SIZE;
        double cameraY = client.getCameraFpY() / Perspective.LOCAL_TILE_SIZE;
        boolean[][] corridor = ChunkBorderRenderer.corridor(scene.edges(),
            borders != FateLockedConfig.ChunkBorders.OFF, fog, here.getSceneX(), here.getSceneY(), view.getSizeX(),
            view.getSizeY(), cameraX, cameraY, projector);
        ChunkBorderRenderer.draw(graphics, scene.edges(), borders, fog, plugin.palette(),
            here.getSceneX(), here.getSceneY(), view.getSizeX(), view.getSizeY(), projector,
            ChunkBorderRenderer.GROUND_PERIOD, occlusion(view, plane, corridor, cameraX, cameraY));
        return null;
    }

    /** A tile corner of the scene, exactly on the tile line, where RuneLite has the ground's height. */
    static LocalPoint corner(int sceneX, int sceneY, WorldView view)
    {
        return new LocalPoint(sceneX << Perspective.LOCAL_COORD_BITS, sceneY << Perspective.LOCAL_COORD_BITS, view);
    }

    /**
     * What stands in the corridor between the camera and the lines, each by its outline: the
     * players and NPCs, and the objects, walls and wall decorations on the player's floor.
     * Nothing elsewhere has its outline worked out.
     */
    static ChunkBorderRenderer.Occlusion occlusion(WorldView view, int plane, boolean[][] corridor, double cameraX,
        double cameraY)
    {
        if (corridor == null)
        {
            return ChunkBorderRenderer.Occlusion.NONE;
        }
        List<ChunkBorderRenderer.Occluder> occluders = new ArrayList<>();
        actors(occluders, corridor, view.players());
        actors(occluders, corridor, view.npcs());
        Scene scene = view.getScene();
        Tile[][][] tiles = scene == null ? null : scene.getTiles();
        if (tiles != null && plane >= 0 && plane < tiles.length)
        {
            Set<GameObject> seen = Collections.newSetFromMap(new IdentityHashMap<>());
            for (int x = 0; x < corridor.length && x < tiles[plane].length; x++)
            {
                for (int y = 0; y < corridor[x].length && y < tiles[plane][x].length; y++)
                {
                    Tile tile = corridor[x][y] ? tiles[plane][x][y] : null;
                    if (tile == null)
                    {
                        continue;
                    }
                    GameObject[] objects = tile.getGameObjects();
                    for (int i = 0; objects != null && i < objects.length; i++)
                    {
                        GameObject object = objects[i];
                        // A player or NPC stands on its tile as an object too; it is counted once, as itself.
                        if (object != null && !(object.getRenderable() instanceof Actor) && seen.add(object))
                        {
                            add(occluders, object.getLocalLocation(), object.getConvexHull());
                        }
                    }
                    WallObject wall = tile.getWallObject();
                    if (wall != null)
                    {
                        add(occluders, wall.getLocalLocation(), wall.getConvexHull());
                        add(occluders, wall.getLocalLocation(), wall.getConvexHull2());
                    }
                    DecorativeObject decoration = tile.getDecorativeObject();
                    if (decoration != null)
                    {
                        add(occluders, decoration.getLocalLocation(), decoration.getConvexHull());
                        add(occluders, decoration.getLocalLocation(), decoration.getConvexHull2());
                    }
                }
            }
        }
        return new ChunkBorderRenderer.Occlusion(cameraX, cameraY, occluders);
    }

    private static void actors(List<ChunkBorderRenderer.Occluder> occluders, boolean[][] corridor,
        Iterable<? extends Actor> actors)
    {
        if (actors == null)
        {
            return;
        }
        for (Actor actor : actors)
        {
            LocalPoint at = actor == null ? null : actor.getLocalLocation();
            if (at != null && at.getSceneX() >= 0 && at.getSceneY() >= 0 && at.getSceneX() < corridor.length
                && at.getSceneY() < corridor[at.getSceneX()].length && corridor[at.getSceneX()][at.getSceneY()])
            {
                add(occluders, at, actor.getConvexHull());
            }
        }
    }

    private static void add(List<ChunkBorderRenderer.Occluder> occluders, LocalPoint at, Shape hull)
    {
        if (at != null && hull != null)
        {
            occluders.add(new ChunkBorderRenderer.Occluder(hull, at.getX() / (double) Perspective.LOCAL_TILE_SIZE,
                at.getY() / (double) Perspective.LOCAL_TILE_SIZE));
        }
    }
}

package com.fatelocked;

import com.fatelocked.panel.LocalTimeText;
import com.fatelocked.rules.Trust;
import com.fatelocked.sidebar.CardAction;
import com.fatelocked.sidebar.StatusCardModel;
import com.fatelocked.ui.Copy;
import com.fatelocked.ui.Palette.Tone;
import com.fatelocked.ui.Terms;
import java.time.Duration;
import java.time.Instant;

/**
 * The status card: whether the rules are current and for this character, and the one
 * thing to do about it (U8, U21). Pure: made from {@link StatusFacts}.
 *
 * <p>The most important fact wins: another character, then a pairing waiting or
 * failing, then the tracker's copy, then the rules' own age.
 */
final class StatusCardPresenter
{
    static final String UP_TO_DATE = "Rules up to date";
    static final String OUT_OF_DATE = "Rules may be out of date";
    static final String STRICT_WAITS = "Strict Mode is inactive until the rules refresh.";

    private StatusCardPresenter()
    {
    }

    static StatusCardModel present(StatusFacts facts)
    {
        TrackerConnectionSnapshot connection = facts.getConnection();
        SyncReason reason = connection.getReason();

        if (facts.getTrust() == Trust.WRONG_CHARACTER)
        {
            return StatusCardModel.of(Tone.BAD, Terms.DIFFERENT_CHARACTER,
                "This run belongs to " + name(facts.getBoundAccount()) + ", and you're logged in as "
                    + name(facts.getLoggedInAs()) + ". Warnings and Strict Mode are off.");
        }

        switch (reason)
        {
            case CONFIRM_IN_BROWSER:
                return StatusCardModel.of(Tone.PENDING, "Waiting for confirmation",
                    "Confirm this profile in the browser tab RuneLite opened. RuneLite checks every few seconds.")
                    .withActions(CardAction.OPEN_PAGE_AGAIN, CardAction.CANCEL_PAIRING);
            case CONFIRM_REPAIR:
                return StatusCardModel.of(Tone.PENDING, "Waiting for confirmation",
                    "Confirm the new profile in the browser tab RuneLite opened. Your current pairing keeps"
                        + " working until it arrives.")
                    .withActions(CardAction.OPEN_PAGE_AGAIN, CardAction.CANCEL_REPAIR);
            case NO_PROFILE:
                return StatusCardModel.of(Tone.BAD, "No profile arrived",
                    "Nothing was confirmed in the browser within 10 minutes.")
                    .withActions(CardAction.CONNECT, null);
            case GONE:
                return StatusCardModel.of(Tone.NEUTRAL, "Disconnected in the tracker",
                    "The web tracker was told to stop sending rules to this pairing. " + keptRules(facts))
                    .withActions(CardAction.CONNECT, null);
            case FUTURE_FORMAT:
                return StatusCardModel.of(Tone.BAD, "Plugin update needed",
                    "Your tracker sent rules in a newer format than this Fate Locked reads. Restart RuneLite to"
                        + " update it from the Plugin Hub. " + keptRules(facts));
            case INVALID_RULES:
                return StatusCardModel.of(Tone.BAD, "Tracker rules not usable",
                    "The tracker sent rules RuneLite couldn't use. Open the web tracker to send them again. "
                        + keptRules(facts))
                    .withActions(CardAction.OPEN_TRACKER, null);
            case NO_RECENT_UPDATE:
                return StatusCardModel.of(Tone.PENDING, "Tracker copy expired",
                    "The tracker hasn't sent your rules in the last 24 hours. Open the web tracker to send them"
                        + " again. " + keptRules(facts))
                    .withActions(CardAction.OPEN_TRACKER, null);
            case OLDER_RULES:
                return StatusCardModel.of(Tone.PENDING, "Tracker has older rules",
                    "The relay sent older rules than yours, so yours stay in use. Open the web tracker to send"
                        + " yours again.")
                    .withActions(CardAction.OPEN_TRACKER, null);
            case REPAIR_ABANDONED:
                return StatusCardModel.of(Tone.NEUTRAL, "Kept your pairing",
                    "No new profile arrived within 10 minutes, so RuneLite kept your current pairing.");
            default:
                break;
        }
        if (connection.getState() == TrackerConnectionState.IMPORT_FAILED)
        {
            return StatusCardModel.of(Tone.BAD, "Couldn't apply the tracker's rules",
                "RuneLite will try again at the next check. " + keptRules(facts))
                .withActions(CardAction.CHECK_NOW, null);
        }

        switch (facts.getSource())
        {
            case FILE:
            case IMPORT:
                return backup(facts, reason);
            case RELAY:
                return tracker(facts, connection, reason);
            default:
                return nothingLoaded(facts, reason);
        }
    }

    /** Rules the relay sent, or saved by the last start from the relay. */
    private static StatusCardModel tracker(StatusFacts facts, TrackerConnectionSnapshot connection, SyncReason reason)
    {
        if (!facts.isPaired())
        {
            StatusCardModel card = StatusCardModel.of(Tone.NEUTRAL, "Using saved rules",
                "Rules from the tracker, exported " + time(facts.getExportedAt(), facts) + ". "
                    + (reason == SyncReason.SYNC_OFF ? "Online sync is off, so nothing checks them."
                        : "Nothing checks them until you connect the tracker."));
            return card.withActions(reason == SyncReason.SYNC_OFF ? CardAction.TURN_ON_SYNC : CardAction.CONNECT,
                null);
        }
        Instant lastSync = connection.getLastSync();
        boolean confirmedSinceStart = lastSync != null
            && (facts.getArrival() != RulesPrecedence.Arrival.SAVED || facts.getArrivedAt() == null
                || !lastSync.isBefore(facts.getArrivedAt()));
        if (!confirmedSinceStart)
        {
            return StatusCardModel.of(Tone.NEUTRAL, "Checking with the tracker",
                "Rules saved " + time(facts.getArrivedAt(), facts) + " are in use until the tracker answers.");
        }
        String failure = failure(connection, facts);
        if (facts.isFresh())
        {
            String detail = "Synced " + ago(lastSync, facts)
                + (facts.isBound() ? " for " + name(facts.getBoundAccount()) + "." : ". These rules name no"
                    + " character, so Strict Mode stays off.");
            return StatusCardModel.of(Tone.GOOD, UP_TO_DATE, failure == null ? detail : detail + " " + failure);
        }
        return StatusCardModel.of(Tone.PENDING, OUT_OF_DATE,
            "Last synced " + ago(lastSync, facts) + ". " + (failure == null ? "" : failure + " ") + STRICT_WAITS)
            .withActions(CardAction.CHECK_NOW, null);
    }

    /** Rules from the clipboard or a backup file. */
    private static StatusCardModel backup(StatusFacts facts, SyncReason reason)
    {
        String from = facts.getSource() == FateLockedPlugin.RulesSource.IMPORT ? "the clipboard" : "a backup file";
        StringBuilder detail = new StringBuilder("Rules from ").append(from);
        if (facts.getExportedAt() != null)
        {
            detail.append(", exported ").append(time(facts.getExportedAt(), facts));
        }
        detail.append(". ");
        if (facts.isLegacy())
        {
            detail.append("It's from an older tracker, so Strict Mode doesn't use it.");
        }
        else if (facts.isFresh())
        {
            detail.append("Strict Mode uses them for 15 minutes after the tracker exported them.");
        }
        else
        {
            detail.append("They're more than 15 minutes old, so Strict Mode doesn't use them.");
        }
        if (facts.isPaired())
        {
            detail.append(" The tracker's copy replaces them at its next check.");
            return StatusCardModel.of(Tone.NEUTRAL, "Using a backup", detail.toString());
        }
        return StatusCardModel.of(Tone.NEUTRAL, "Using a backup", detail.toString())
            .withActions(null, reason == SyncReason.SYNC_OFF ? CardAction.TURN_ON_SYNC : CardAction.CONNECT);
    }

    /** No rules at all yet. */
    private static StatusCardModel nothingLoaded(StatusFacts facts, SyncReason reason)
    {
        if (reason == SyncReason.SYNC_OFF)
        {
            return StatusCardModel.of(Tone.NEUTRAL, "Online sync is off",
                "Your pairing is kept. Turn online sync on to get your rules from the tracker.")
                .withActions(CardAction.TURN_ON_SYNC, CardAction.USE_BACKUP);
        }
        if (facts.isPaired())
        {
            return StatusCardModel.of(Tone.PENDING, "Checking with the tracker",
                "RuneLite is asking the tracker for your run's rules.");
        }
        return StatusCardModel.of(Tone.NEUTRAL, "Not connected", "Connect the tracker to load your run's rules.")
            .withActions(CardAction.CONNECT, CardAction.USE_BACKUP);
    }

    /** Why the last check failed and when the next one is, or null when it didn't fail. */
    private static String failure(TrackerConnectionSnapshot connection, StatusFacts facts)
    {
        String what;
        switch (connection.getReason())
        {
            case UNREACHABLE:
                what = "RuneLite couldn't reach the tracker";
                break;
            case UNREADABLE:
                what = "Something other than the tracker answered, such as a Wi-Fi sign-in page";
                break;
            case BUSY:
                what = "The tracker asked RuneLite to check less often";
                break;
            case UNAVAILABLE:
                what = "The tracker had a problem";
                break;
            default:
                return null;
        }
        Instant next = connection.getNextCheck();
        return next == null ? what + "." : what + "; next check " + time(next, facts) + ".";
    }

    private static String keptRules(StatusFacts facts)
    {
        return facts.getSource() == FateLockedPlugin.RulesSource.NONE
            ? "No rules are loaded." : "Your current rules stay in use.";
    }

    private static String ago(Instant at, StatusFacts facts)
    {
        return Copy.ago(Duration.between(at, facts.getNow()));
    }

    private static String time(Instant at, StatusFacts facts)
    {
        return at == null ? "at an unknown time" : "at " + LocalTimeText.of(at, facts.getNow(), facts.getZone());
    }

    private static String name(String account)
    {
        return account == null || account.isEmpty() ? "another character" : account;
    }
}

package com.fatelocked;

import net.runelite.client.callback.ClientThread;

/**
 * The one way onto the client thread, where all plugin state changes. The
 * sidebar, the config panel, overlay clicks and startUp run on the Swing
 * thread, and file reads and relay replies on other threads; each hands its
 * work over here.
 *
 * Work always goes through ClientThread.invoke(Runnable), which runs it at
 * once on the client thread and on the next tick from anywhere else, never
 * through the BooleanSupplier overload, which re-runs a task that returns
 * false on every tick. One gate belongs to one plugin start: work it queued
 * does nothing once that start has ended.
 */
final class ClientThreadGate
{
    private final ClientThread clientThread;
    private final PluginSession session;

    ClientThreadGate(ClientThread clientThread, PluginSession session)
    {
        this.clientThread = clientThread;
        this.session = session;
    }

    /** The gate of a plugin that is not running: nothing passes it. */
    static ClientThreadGate closed()
    {
        return new ClientThreadGate(null, PluginSession.ended());
    }

    /** Run the task on the client thread: now if already there, else next tick. */
    void run(Runnable task)
    {
        if (!session.isActive())
        {
            return;
        }
        clientThread.invoke(session.guard(task));
    }

    /** Run the task on the next client tick, even when called on the client thread. */
    void runNextTick(Runnable task)
    {
        if (!session.isActive())
        {
            return;
        }
        clientThread.invokeLater(session.guard(task));
    }

    /** The task, for another queue, run only while this gate's start lasts. */
    Runnable guard(Runnable task)
    {
        return session.guard(task);
    }

    /** End this start: work already queued through the gate does nothing. */
    void close()
    {
        session.end();
    }
}

package com.fatelocked;

import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.Progress;
import com.fatelocked.rules.Trust;
import com.fatelocked.sidebar.RunModel;
import com.fatelocked.ui.Copy;
import com.fatelocked.ui.Terms;
import java.util.List;

/**
 * The Run section (R12, U22): whose run it is, beside who is logged in; the run id by
 * its last four characters only; keys, Fate Points and the ritual by the web app's
 * names; and progress in the unit the run counts. Pure.
 */
final class RunPresenter
{
    private RunPresenter()
    {
    }

    static RunModel present(FateLockedBundle bundle, DecisionService decisions, String loggedInAs)
    {
        FateLockedBundle.RunState state = bundle.getState();
        List<String> goals = state == null ? null : state.getPinnedGoals();
        Progress progress = decisions.progress();
        return new RunModel(
            character(AccountBinding.boundAccount(bundle), loggedInAs, decisions.trust()),
            Copy.shortId(bundle.getRunId()),
            state == null ? 0 : state.getKeys(),
            state == null ? 0 : state.getSpecialKeys(),
            state == null ? 0 : state.getChaosKeys(),
            state == null ? 0 : state.getFatePoints(),
            state == null ? null : Terms.ritual(state.getActiveBuff()),
            goals == null || goals.isEmpty() ? null : goals.get(0),
            progress == null || progress.getTotal() <= 0 ? null
                : Copy.unlocked(progress.getUnlocked(), progress.getTotal(), progress.getUnit()),
            progress == null || progress.percent() < 0 ? 0 : progress.percent() / 100.0);
    }

    /** "Nubles (you)", "Nubles, and you're on Zezima", or the run's character alone while logged out. */
    static String character(String bound, String loggedInAs, Trust trust)
    {
        if (bound == null)
        {
            return "No character named";
        }
        if (trust == Trust.WRONG_CHARACTER && loggedInAs != null)
        {
            return bound + ", and you're on " + loggedInAs;
        }
        return trust == Trust.TRUSTED ? bound + " (you)" : bound;
    }
}

package com.fatelocked;

import lombok.Value;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * A Slayer task as a game message states it (B11): "You're assigned to kill
 * goblins; only 20 more to go." and Konar's "...to kill aberrant spectres in
 * the Catacombs of Kourend; only 105 more to go.", with the place kept.
 */
@Value
class SlayerAssignment
{
    /** The monster from "to kill [count] ..." up to "in", ";", ":" or ".", then Konar's place. */
    private static final Pattern TASK = Pattern.compile(
        "to kill\\s+(?:\\d+\\s+)?(?:the\\s+)?(.+?)(?:\\s+in\\s+(?:the\\s+)?([^;:.]+?))?\\s*(?:[;:.]|$)",
        Pattern.CASE_INSENSITIVE);
    /** Only Konar gives a place, and the tracker lists her tasks under this name. */
    static final String KONAR = "konar quo maten";
    /** SLAYER_MASTER values RuneLite's own Slayer plugin relies on; the rest aren't verified. */
    private static final int KRYSTILIA = 7;
    private static final int MORTIMER = 10;

    String task;
    /** Konar's place; null for every other master. */
    String location;
    /** The master, as the tracker names them, when known; null otherwise. */
    String master;

    /** The task a message states, or null when it states none. */
    static SlayerAssignment fromChat(String message, int masterVarbit)
    {
        if (message == null) return null;
        Matcher match = TASK.matcher(message);
        if (!match.find()) return null;
        String task = match.group(1).trim();
        String location = match.group(2) == null ? null : match.group(2).trim();
        if (task.isEmpty()) return null;
        return new SlayerAssignment(task, location, master(masterVarbit, location));
    }

    private static String master(int masterVarbit, String location)
    {
        if (location != null) return KONAR;
        switch (masterVarbit)
        {
            case KRYSTILIA: return "krystilia";
            case MORTIMER: return "mortimer";
            default: return null;
        }
    }
}

package com.fatelocked;

import com.fatelocked.rules.Progress;
import com.fatelocked.ui.Copy;

/**
 * Unlock progress as the HUD and the infobox show it (B10), in the sidebar's words. Null
 * progress (no rules, or another character's) shows nothing.
 */
final class ProgressText
{
    private ProgressText()
    {
    }

    /** The HUD's "Unlocked" line, e.g. "15/187 · 7%"; null when there is none. */
    static String hudLine(Progress progress)
    {
        if (progress == null || progress.getChunksTotal() <= 0) return null;
        return progress.getUnlocked() + "/" + progress.getTotal() + " · " + progress.percent() + "%";
    }

    /** The infobox's count, e.g. "7%"; null when there is none, and the box isn't drawn. */
    static String infoBoxText(Progress progress)
    {
        return progress == null || progress.getChunksTotal() <= 0 ? null : progress.percent() + "%";
    }

    /** "15 of 187 areas unlocked", then the chunks for a run that counts areas; null without progress. */
    static String infoBoxTooltip(Progress progress)
    {
        if (progress == null) return null;
        String unlocked = Copy.unlocked(progress.getUnlocked(), progress.getTotal(), progress.getUnit());
        if (Progress.CHUNKS.equals(progress.getUnit())) return unlocked;
        return unlocked + "</br>" + progress.getChunksUnlocked() + " of " + progress.getChunksTotal() + " chunks";
    }
}

