    private void refreshInfoBoxes()
    {
        infoBoxManager.removeIf(b -> b instanceof FateLockedInfoBox);
        if (!config.showInfoBoxes()) return;
        for (FateLockedInfoBox.Kind kind : FateLockedInfoBox.Kind.values())
        {
