            }
        });
    }

    /**
     * What the game says, for the rows here the tracker leaves undecided: the quests they
     * name, quest points, levels, the world, and what the player carries (RowChecks). Read
     * once a tick, and only where such a row is. Client thread; elsewhere, nothing.
     */
    GameFacts gameFacts(DecisionService ruleDecisions, CanonicalChunk chunk)
    {
        if (chunk == null || !client.isClientThread() || client.getGameState() != GameState.LOGGED_IN)
        {
            return GameFacts.NONE;
        }
        int tick = client.getTickCount();
        if (tick == factsTick && chunk.equals(factsChunk) && ruleDecisions == factsDecisions)
        {
            return lastFacts;
        }
        List<String> undecided = new ArrayList<>();
        ruleDecisions.details(chunk).ifPresent(snapshot -> {
            for (List<ChunkPermissionRow> rows : snapshot.getCategories().values())
            {
                for (ChunkPermissionRow row : rows)
                {
                    if (row.getStatus() == PermissionStatus.UNKNOWN)
                    {
                        undecided.add(row.getDetail());
                    }
                }
            }
        });
        GameFacts facts = GameFacts.NONE;
        if (!undecided.isEmpty())
        {
            Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
            for (Quest quest : RowChecks.questsNamed(undecided))
            {
                quests.put(quest, quest.getState(client));
            }
            Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
            for (Skill skill : Skill.values())
            {
                if (!"Overall".equals(skill.getName()))
                {
                    levels.put(skill, client.getRealSkillLevel(skill));
                }
            }
            Set<String> carried = new HashSet<>();
            boolean light = false;
            for (int id : new int[] {InventoryID.INV, InventoryID.WORN})
            {
                ItemContainer container = client.getItemContainer(id);
                if (container == null)
                {
                    continue;
                }
                for (Item item : container.getItems())
                {
                    if (item.getId() <= 0)
                    {
                        continue;
                    }
                    carried.add(itemManager.getItemComposition(item.getId()).getName().toLowerCase(Locale.ROOT));
                    light |= RowChecks.LIGHT_SOURCES.contains(item.getId());
                }
            }
            java.util.EnumSet<WorldType> world = client.getWorldType();
            facts = new GameFacts(world == null ? null : world.contains(WorldType.MEMBERS),
                client.getVarpValue(VarPlayerID.QP), levels, quests, carried, light);
        }
        factsTick = tick;
        factsChunk = chunk;
        factsDecisions = ruleDecisions;
        lastFacts = facts;
        return facts;
    }

    /**
     * Once a second: at the login screen there are no game ticks, so this keeps ages
     * ("synced 2 min ago") and a pause's countdown current there.
     */
    @Schedule(period = 1, unit = java.time.temporal.ChronoUnit.SECONDS)
    public void refreshSidebarWhileLoggedOut()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            gate.run(this::updateStrictModePanel);
        }
    }

    /**
     * Paired with online sync off: ask for consent, then turn sync on. The
     * saved pairing is picked up again; no new code is made.
     */
    private void turnOnOnlineSync()
    {
        if (!panel.confirmNetworkConnection())
        {
            return;
        }
        gate.run(() -> {
            try
            {
                connectionSettings.allowNetworkAccess();
            }
            catch (RuntimeException error)
            {
                panel.flashStatus(Notices.SYNC_NOT_ON, false);
            }
        });
    }

    private void beginTrackerPairing()
    {
        boolean needsConsent = !connectionSettings.networkAccessAllowed();
        if (needsConsent && !panel.confirmNetworkConnection())
        {
            return;
        }
        ClientThreadGate onClient = gate;
        onClient.run(() -> {
            if (needsConsent)
            {
                try
                {
                    connectionSettings.allowNetworkAccess();
                }
                catch (RuntimeException error)
                {
                    panel.flashStatus(Notices.SYNC_NOT_ON, false);
                    return;
                }
            }
            if (!connectionSettings.networkAccessAllowed()) return;
            String url = connectionController.beginPairing();
            String code = connectionController.activeCode();
            SwingUtilities.invokeLater(onClient.guard(
                () -> openTrackerPairing(url, code)));
        });
    }

    /**
     * RuneLite's LinkBrowser opens the page on its own thread and shows its
     * own copy-the-link dialog if the browser won't open, so there is no
     * failure to report here.
     */
    private void openTrackerPairing(String url, String code)
    {
        if (connectionSettings.networkAccessAllowed()
            && samePairing(code, connectionController.activeCode()))
        {
            launchTrackerBrowser(url);
        }
    }

    void launchTrackerBrowser(String url)
    {
        LinkBrowser.browse(url);
    }

    private static boolean samePairing(String expected, String current)
    {
        return expected != null && expected.equals(current);
    }

    private static NavigationButton buildNavigationButton(FateLockedPanel target)
    {
        return NavigationButton.builder()
            .tooltip("Fate Locked Ironman")
            .icon(navigationIcon())
            .priority(7)
            .panel(target)
            .build();
    }

    /**
     * The sidebar button's icon: the crystal key, the web app's own icon, drawn at the
     * 16 px RuneLite shows it. RuneLite rescales a larger icon smoothly, which blurred the
     * old 24 px key, and game art isn't loaded when the button is added.
     */
    static BufferedImage navigationIcon()
    {
        return ImageUtil.loadImageResource(FateLockedPlugin.class, "nav_icon.png");
    }

    private void startTrackerPoll()
    {
        // The lightweight scheduler tick keeps initial pairing responsive.
        // TrackerConnectionController gates actual relay requests to a
        // one-minute healthy cadence and backs off failures/rate limits.
        trackerPollFuture = executor.scheduleWithFixedDelay(
            gate.guard(this::pollTrackerConnection), 2, 4, TimeUnit.SECONDS);
    }

    private void stopTrackerPoll()
    {
        if (trackerPollFuture != null)
        {
            trackerPollFuture.cancel(false);
            trackerPollFuture = null;
        }
        if (connectionController != null)
        {
            connectionController.stop();
        }
    }

    private boolean trackerPaired()
    {
        return connectionSettings != null
            && connectionSettings.networkAccessAllowed()
            && connectionSettings.isPaired();
    }

    private Instant trackerLastSync()
    {
        return trackerSnapshot().getLastSync();
    }

    /** The connection as the controller last showed it; not connected before it exists. */
    private TrackerConnectionSnapshot trackerSnapshot()
    {
        TrackerConnectionController controller = connectionController;
        TrackerConnectionSnapshot shown = controller == null ? null : controller.snapshot();
        return shown == null ? TrackerConnectionSnapshot.disconnected() : shown;
    }

    /**
     * The sidebar's Check now, on the Swing thread: make a check due, then
     * run the tracker tick at once rather than waiting up to 4 seconds.
     */
    private void checkTrackerNow()
    {
        TrackerConnectionController controller = connectionController;
        if (controller != null && controller.checkNow())
        {
            executor.execute(gate.guard(this::pollTrackerConnection));
        }
    }

    private void pollTrackerConnection()
    {
        TrackerConnectionController controller = connectionController;
        if (controller == null) return;
        try
        {
            controller.pollIfDue();
        }
        catch (RuntimeException error)
        {
            // A scheduled task that throws is never run again: log it and
            // keep checking.
            if (trackerTickFailureLimiter.shouldReport(
                String.valueOf(error), System.currentTimeMillis()))
            {
                log.warn("Tracker check failed", error);
            }
        }
    }

    private void updatePanelRollInbox()
    {
        List<FateEvent> events = eventHistory == null
            ? java.util.Collections.<FateEvent>emptyList()
            : eventHistory.events();
        int needsReview = 0;
        for (FateEvent event : events)
        {
            if (event.getConfidence() == EventConfidence.UNCERTAIN) needsReview++;
        }
        shownWarningCount = activeWarningCount();
        SidebarPublisher models = sidebarModels();
        if (models != null)
        {
            models.rollInbox(new RollInboxModel(events.size(), needsReview, shownWarningCount, historySaveFailed));
        }
    }

    /** Keep the sidebar's Warnings count current as you move, change gear and get tasks. */
    private void refreshWarningCount()
    {
        if (activeWarningCount() != shownWarningCount) updatePanelRollInbox();
    }

    private int activeWarningCount()
    {
        int warnings = 0;
        if (lastStatus == PermissionStatus.LOCKED) warnings++;
        if (slayerTaskWarn != null && !slayerTaskWarn.trim().isEmpty()) warnings++;
        if (overTierSummary != null && !overTierSummary.trim().isEmpty()) warnings++;
        return warnings;
    }
}

package com.fatelocked;

import com.fatelocked.detectors.SlayerTaskDetector;
import com.fatelocked.events.FateEvent;
import com.fatelocked.events.FateEventHistory;
import com.fatelocked.guardian.StrictModeAuditLog;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * The local files one OSRS account owns, in accounts/&lt;account hash&gt;/:
 * its detected-event history, its Strict Mode audit log, its Slayer task
 * and its finished diary tiers. A main account and an ironman played in one RuneLite no longer
 * share them. A file that fails to open leaves its feature off for that
 * account, and never stops the plugin.
 *
 * <p>An account's folder starts from the shared files older versions kept,
 * which are only ever read: the history's events for that character, and,
 * since they name no account, the audit log and Slayer task only for the
 * character the rules are bound to.
 */
@Slf4j
final class AccountFiles
{
    static final String HISTORY = "event-history.json";
    static final String LEGACY_OUTBOX = "event-outbox.json";
    static final String AUDIT_LOG = "strict-mode-events.json";
    static final String SLAYER = "slayer-assignment.json";

    final long accountHash;
    /** Null when it couldn't be opened. */
    final FateEventHistory history;
    /** Null when it couldn't be opened. */
    final StrictModeAuditLog auditLog;
    /** Null when it couldn't be opened. */
    final SlayerTaskDetector slayer;
    /** The diary tiers the account has finished. */
    final DiaryTierMemory diaryTiers;

    private AccountFiles(long accountHash, FateEventHistory history,
        StrictModeAuditLog auditLog, SlayerTaskDetector slayer, DiaryTierMemory diaryTiers)
    {
        this.accountHash = accountHash;
        this.history = history;
        this.auditLog = auditLog;
        this.slayer = slayer;
        this.diaryTiers = diaryTiers;
    }

    static Path folder(Path dataDirectory, long accountHash)
    {
        return dataDirectory.resolve("accounts").resolve(Long.toUnsignedString(accountHash));
    }

    /**
     * @param accountName the character's name, whose events the shared history gives
     * @param boundCharacter whether the rules are bound to this character
     */
    static AccountFiles open(Gson gson, Path dataDirectory, long accountHash,
        String accountName, boolean boundCharacter)
    {
        Path folder = folder(dataDirectory, accountHash);
        FateEventHistory history = openHistory(gson, dataDirectory, folder, accountName);
        StrictModeAuditLog auditLog = null;
        try
        {
            startFromShared(dataDirectory, folder, AUDIT_LOG, boundCharacter);
            auditLog = new StrictModeAuditLog(gson, folder.resolve(AUDIT_LOG));
        }
        catch (IOException | RuntimeException error)
        {
            log.warn("Could not open the Strict Mode audit log", error);
        }
        SlayerTaskDetector slayer = null;
        try
        {
            startFromShared(dataDirectory, folder, SLAYER, boundCharacter);
            slayer = new SlayerTaskDetector(gson, folder.resolve(SLAYER));
        }
        catch (IOException | RuntimeException error)
        {
            log.warn("Could not open the Slayer task state", error);
        }
        return new AccountFiles(accountHash, history, auditLog, slayer,
            new DiaryTierMemory(gson, folder.resolve(DiaryTierMemory.FILE)));
    }

    private static FateEventHistory openHistory(
        Gson gson, Path dataDirectory, Path folder, String accountName)
    {
        Path target = folder.resolve(HISTORY);
        boolean fresh = !Files.exists(target);
        try
        {
            FateEventHistory history = new FateEventHistory(gson, target, null);
            if (fresh)
            {
                List<FateEvent> ours = new ArrayList<>();
                for (FateEvent event : FateEventHistory.readOnly(gson,
                    dataDirectory.resolve(HISTORY), dataDirectory.resolve(LEGACY_OUTBOX)))
                {
                    if (AccountBinding.sameAccount(event.getAccount(), accountName))
                    {
                        ours.add(event);
                    }
                }
                if (!ours.isEmpty())
                {
                    history.adopt(ours);
                }
            }
            return history;
        }
        catch (IOException | RuntimeException error)
        {
            log.warn("Could not open the local Fate event history", error);
            return null;
        }
    }

    /** Copy a shared file into a new folder, for the bound character only; the shared one stays. */
    private static void startFromShared(Path dataDirectory, Path folder, String name,
        boolean boundCharacter) throws IOException
    {
        Path target = folder.resolve(name);
        Path shared = dataDirectory.resolve(name);
        if (boundCharacter && !Files.exists(target) && Files.isRegularFile(shared))
        {
            Files.createDirectories(folder);
            Files.copy(shared, target);
        }
    }
}

package com.fatelocked;

/**
 * Which rules may replace the ones in force. The tracker wins while
 * paired. A player's own import always applies, and the tracker's copy
 * wins again on its next check. Rules found at startup, saved by the last
 * start or read from the newest backup file, only fill an empty slot, so
 * they can never undo anything that arrived since.
 */
final class RulesPrecedence
{
    /** How a rule set arrived. */
    enum Arrival
    {
        /** Saved by the last start (saved-rules.json). */
        SAVED,
        /** The newest backup file, read at startup when nothing was saved. */
        STARTUP_FILE,
        /** Sent by the tracker relay. */
        RELAY,
        /** Imported by the player: the clipboard, its hotkey or "Load newest backup file". */
        IMPORT
    }

    private RulesPrecedence()
    {
    }

    static boolean mayReplace(FateLockedPlugin.RulesSource active, Arrival arrival)
    {
        switch (arrival)
        {
            case SAVED:
            case STARTUP_FILE:
                return active == FateLockedPlugin.RulesSource.NONE;
            case RELAY:
            case IMPORT:
                return true;
            default:
                throw new IllegalArgumentException("Unknown arrival " + arrival);
        }
    }
}

package com.fatelocked;

/**
 * Tracks the two independently fallible registrations used by the travel
 * banner so partial startup and shutdown can be retried safely.
 */
final class TravelGuardianOverlayLifecycle
{
    private final Runnable addOverlay;
    private final Runnable registerMouse;
    private final Runnable unregisterMouse;
    private final Runnable removeOverlay;
    private boolean overlayAdded;
    private boolean mouseRegistered;

    TravelGuardianOverlayLifecycle(
        Runnable addOverlay,
        Runnable registerMouse,
        Runnable unregisterMouse,
        Runnable removeOverlay)
    {
        this.addOverlay = addOverlay;
        this.registerMouse = registerMouse;
        this.unregisterMouse = unregisterMouse;
        this.removeOverlay = removeOverlay;
    }

    synchronized void start()
    {
        if (!overlayAdded)
        {
            overlayAdded = true;
            try
            {
                addOverlay.run();
            }
            catch (RuntimeException addFailure)
            {
                rollbackOverlay(addFailure);
                throw addFailure;
            }
        }
        if (!mouseRegistered)
        {
            mouseRegistered = true;
            try
            {
                registerMouse.run();
            }
            catch (RuntimeException registrationFailure)
            {
                rollbackMouse(registrationFailure);
                rollbackOverlay(registrationFailure);
                throw registrationFailure;
            }
        }
    }

    private void rollbackMouse(RuntimeException startupFailure)
    {
        if (!mouseRegistered) return;
        try
        {
            unregisterMouse.run();
            mouseRegistered = false;
        }
        catch (RuntimeException cleanupFailure)
        {
            startupFailure.addSuppressed(cleanupFailure);
        }
    }

    private void rollbackOverlay(RuntimeException startupFailure)
    {
        if (!overlayAdded) return;
        try
        {
            removeOverlay.run();
            overlayAdded = false;
        }
        catch (RuntimeException cleanupFailure)
        {
            startupFailure.addSuppressed(cleanupFailure);
        }
    }

    synchronized void stop()
    {
        RuntimeException failure = null;
        if (mouseRegistered)
        {
            try
            {
                unregisterMouse.run();
                mouseRegistered = false;
            }
            catch (RuntimeException ex)
            {
                failure = ex;
            }
        }
        if (overlayAdded)
        {
            try
            {
                removeOverlay.run();
                overlayAdded = false;
            }
            catch (RuntimeException ex)
            {
                if (failure == null)
                {
                    failure = ex;
                }
                else
                {
                    failure.addSuppressed(ex);
                }
            }
        }
        if (failure != null) throw failure;
    }
}

package com.fatelocked;

import com.fatelocked.guardian.StrictModeStatusView;
import com.fatelocked.rules.Decision;
import com.fatelocked.rules.DecisionService;
import com.fatelocked.rules.PermissionStatus;
import com.fatelocked.rules.Trust;
import com.fatelocked.sidebar.HereModel;
import com.fatelocked.ui.Palette;
import com.fatelocked.ui.Terms;
import java.util.ArrayList;
import java.util.List;
import lombok.Builder;
import lombok.Value;

/**
 * What the HUD says (U8, E6), from the rules' decisions for where the player stands.
 *
 * <ul>
 * <li>Compact: the place, its status and why, Strict Mode, the nearest bank and shop, and any
 *     rule warnings.</li>
 * <li>Detailed adds progress, the run's Keys and Fate Points, and what the place holds, as the
 *     sidebar's Here card lists it. It replaces the separate content box.</li>
 * </ul>
 *
 * <p>Another character sees only where they are and that the run isn't theirs, in either mode.
 * Words, never marks: the overlay fonts have no ✓ or ⚠.
 */
final class HudPresenter
{
    /** Everything the HUD reads, gathered on the client thread. */
    @Value
    @Builder
    static class Facts
    {
        FateLockedConfig.HudMode mode;
        DecisionService decisions;
        /** The player's rules chunk; null when it can't be known. */
        CanonicalChunk chunk;
        /** Strict Mode's status; null before it is first worked out. */
        StrictModeStatusView strict;
        /** The nearest bank and shop the rules allow; null for none. */
        FateLockedBundle.Nearest bank;
        FateLockedBundle.Nearest shop;
        /** The locked Slayer task, or null. */
        String slayerWarning;
        /** The worn slots above their unlocked tier, or null. */
        String overTier;
        /** The run's Keys and Fate Points; null when the rules carry none. */
        FateLockedBundle.RunState run;
        /** What the place holds, for Detailed; null for nothing. */
        HereModel here;
    }

    private HudPresenter()
    {
    }

    static HudModel present(Facts facts)
    {
        DecisionService decisions = facts.getDecisions();
        Trust trust = decisions.trust();
        if (facts.getMode() == FateLockedConfig.HudMode.OFF
            || trust == Trust.NO_RULES || trust == Trust.LOGGED_OUT)
        {
            return HudModel.NONE;
        }
        boolean detailed = facts.getMode() == FateLockedConfig.HudMode.DETAILED;
        List<HudModel.Line> lines = new ArrayList<>();
        CanonicalChunk chunk = facts.getChunk();
        if (chunk != null)
        {
            String area = decisions.areaName(chunk);
            lines.add(new HudModel.Line("Here",
                shorten(area != null ? area : "Chunk (" + chunk.getCx() + ", " + chunk.getCy() + ")", 22), null));
        }
        if (trust != Trust.TRUSTED)
        {
            // Another character's rules say nothing about this one: two short lines, in either mode.
            lines.add(new HudModel.Line("Status", Terms.DIFFERENT_CHARACTER, Palette.Tone.BAD));
            return new HudModel(lines, false);
        }
        if (chunk != null)
        {
            Decision decision = decisions.chunk(chunk);
            Palette.Tone tone = Palette.tone(decision.getStatus());
            lines.add(new HudModel.Line("Status", Terms.place(decision.getStatus()), tone));
            boolean why = decision.getStatus() == PermissionStatus.LOCKED
                || decision.getStatus() == PermissionStatus.NOT_READY;
            if (why && decision.getReason() != null)
            {
                lines.add(new HudModel.Line("Why", shorten(decision.getReason(), 22), tone));
            }
        }
        StrictModeStatusView strict = facts.getStrict();
        if (strict != null && strict.isShownOnHud())
        {
            lines.add(new HudModel.Line(Terms.STRICT_MODE, strict.getText(),
                strict.getTone() == StrictModeStatusView.Tone.ACTIVE ? Palette.Tone.GOOD : Palette.Tone.PENDING));
        }
        if (chunk != null && decisions.hasNearestData())
        {
            lines.add(nearest("Bank", facts.getBank(), chunk, decisions));
            lines.add(nearest("Shop", facts.getShop(), chunk, decisions));
        }
        if (facts.getSlayerWarning() != null)
        {
            lines.add(new HudModel.Line("Slayer", shorten(facts.getSlayerWarning(), 18), Palette.Tone.BAD));
        }
        if (facts.getOverTier() != null)
        {
            lines.add(new HudModel.Line("Over-tier", shorten(facts.getOverTier(), 20), Palette.Tone.BAD));
        }
        if (detailed)
        {
            detail(lines, facts, decisions);
        }
        // Nothing to say, where the player's chunk can't be found: no HUD.
        return lines.isEmpty() ? HudModel.NONE : new HudModel(lines, detailed);
    }

    /** Detailed's lines: progress, the run, and what the place holds. */
    private static void detail(List<HudModel.Line> lines, Facts facts, DecisionService decisions)
    {
        String progress = ProgressText.hudLine(decisions.progress());
        if (progress != null)
        {
            lines.add(new HudModel.Line(Terms.UNLOCKED, progress, null));
        }
        FateLockedBundle.RunState run = facts.getRun();
        if (run != null)
        {
            lines.add(new HudModel.Line(Terms.KEYS, String.valueOf(run.getKeys()), null));
            if (run.getSpecialKeys() > 0)
            {
                lines.add(new HudModel.Line(Terms.OMNI_KEYS, String.valueOf(run.getSpecialKeys()), null));
            }
            if (run.getChaosKeys() > 0)
            {
                lines.add(new HudModel.Line(Terms.CHAOS_KEYS, String.valueOf(run.getChaosKeys()), null));
            }
            lines.add(new HudModel.Line(Terms.FATE_POINTS, String.valueOf(run.getFatePoints()), null));
            String ritual = Terms.ritual(run.getActiveBuff());
            if (ritual != null)
            {
                lines.add(new HudModel.Line("Ritual", shorten(ritual, 20), Palette.Tone.GOOD));
            }
            if (run.getPinnedGoals() != null && !run.getPinnedGoals().isEmpty())
            {
                lines.add(new HudModel.Line("Goal", shorten(run.getPinnedGoals().get(0), 20), null));
            }
        }
        HereModel here = facts.getHere();
        if (here != null)
        {
            for (HereModel.Group group : here.getGroups())
            {
                lines.add(HudModel.Line.heading(group.getTitle()));
                for (HereModel.Row row : group.shown(false))
                {
                    lines.add(new HudModel.Line(shorten(row.getName(), 18), row.getWord(), row.getTone()));
                }
                if (group.hidden() > 0)
                {
                    lines.add(new HudModel.Line("+" + group.hidden() + " more", null, Palette.Tone.NEUTRAL));
                }
            }
        }
    }

    /** One "Bank" or "Shop" line: here, the nearest one's area, distance and way, or none. */
    private static HudModel.Line nearest(String label, FateLockedBundle.Nearest near, CanonicalChunk from,
        DecisionService decisions)
    {
        if (near == null)
        {
            return new HudModel.Line(label, "None unlocked", Palette.Tone.BAD);
        }
        if (near.getDistanceChunks() == 0)
        {
            return new HudModel.Line(label, "Here", Palette.Tone.GOOD);
        }
        String area = decisions.areaName(near.getChunk());
        String name = area == null
            ? "(" + near.getChunk().getCx() + ", " + near.getChunk().getCy() + ")"
            : area.split(" · ")[0];
        // From inside an interior, the way is from its entrance; none when the bank is right there.
        CanonicalChunk origin = decisions.surfaceOf(from);
        int dx = near.getChunk().getCx() - origin.getCx();
        int dy = near.getChunk().getCy() - origin.getCy();
        String way = dx == 0 && dy == 0 ? "" : " " + compass(dx, dy);
        return new HudModel.Line(label, shorten(name, 13) + " · " + near.getDistanceChunks() + way, null);
    }

    /**
     * The 8-way compass point for a chunk step; a 2:1 dominant axis counts as its cardinal
     * (5 east and 1 north is "E"; 5 east and 4 north is "NE"). World y grows north.
     */
    static String compass(int dx, int dy)
    {
        String ns = dy > 0 ? "N" : "S";
        String ew = dx > 0 ? "E" : "W";
        if (dy == 0 || Math.abs(dx) >= 2 * Math.abs(dy)) return ew;
        if (dx == 0 || Math.abs(dy) >= 2 * Math.abs(dx)) return ns;
        return ns + ew;
    }

    /** Text cut to fit one HUD line, ending in an ellipsis when cut. */
    static String shorten(String text, int max)
    {
        return text.length() <= max ? text : text.substring(0, max - 1) + "…";
    }
}

package com.fatelocked;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Which rules chunk something is in (G11). On the surface that is the tile's
 * own chunk, as before. Inside an instance it is the chunk the instance was
 * copied from, so a raid or a quest cutscene is judged by its real place. On
 * a Sailing boat it is the sea chunk under the boat.
 *
 * <p>Anything it can't place is null, which every surface reads as Unknown:
 * never a guessed lock. That covers a boat whose ship can't be found, an
 * instance zone with no template, and menu options with no tile, such as
 * Walk here, the minimap and a ship's own options.
 *
 * <p>It is the only class that reads where the player or a menu target is
 * (B14); {@code LocationBoundaryTest} keeps it that way.
 */
public final class ChunkLocator
{
    /** Instances are copied in 8-tile zones, 13 across. */
    private static final int ZONE_TILES = 8;
    private static final int INSTANCE_ZONES = 13;
    private static final int NO_TEMPLATE = -1;

    private final Client client;

    public ChunkLocator(Client client)
    {
        this.client = client;
    }

    Client client()
    {
        return client;
    }

    /** The logged-in player's chunk. */
    public CanonicalChunk player()
    {
        Player local = client.getLocalPlayer();
        return local == null ? null : actor(local);
    }

    /** An actor's chunk: the player, or an NPC. */
    public CanonicalChunk actor(Actor actor)
    {
        if (actor == null) return null;
        return locate(actor.getWorldView(), actor.getLocalLocation());
    }

    /**
     * Where the player stands, for overlays that draw: their rules chunk,
     * and the top-level scene chunk and plane under them (the sea under a
     * boat). Null when nobody is logged in or a boat's ship can't be found.
     */
    public Located playerInScene()
    {
        Player local = client.getLocalPlayer();
        if (local == null) return null;
        WorldView view = local.getWorldView();
        LocalPoint point = local.getLocalLocation();
        if (view == null || point == null) return null;
        if (!view.isTopLevel())
        {
            WorldEntity boat = shipOf(view);
            if (boat == null) return null;
            point = boat.transformToMainWorld(point);
            view = client.getTopLevelWorldView();
            if (point == null || view == null) return null;
        }
        int plane = view.getPlane();
        WorldPoint inScene = WorldPoint.fromLocal(view, point.getX(), point.getY(), plane);
        return new Located(locate(view, point), WorldChunks.of(inScene), plane,
            point.getSceneX(), point.getSceneY());
    }

    /**
     * The rules chunk of one 8-tile zone of the top-level scene: the chunk it is a copy of
     * inside an instance, which is copied zone by zone. Zones never straddle a chunk line, so
     * the zone's first tile decides. Null when it isn't loaded or can't be known.
     */
    public CanonicalChunk sceneZone(int zoneX, int zoneY)
    {
        WorldView view = client.getTopLevelWorldView();
        if (view == null || zoneX < 0 || zoneY < 0) return null;
        int x = zoneX * ZONE_TILES;
        int y = zoneY * ZONE_TILES;
        if (x >= view.getSizeX() || y >= view.getSizeY()) return null;
        return locate(view, LocalPoint.fromScene(x, y, view));
    }

    /**
     * Where the player stands in the real world, to show the way from; null when nobody is
     * logged in, inside an instance, whose tiles are copies, or on a boat.
     */
    public WorldPoint playerWorld()
    {
        return world(client.getLocalPlayer());
    }

    /** Where an NPC or player stands in the real world, to find it again; null inside an instance or on a boat. */
    public WorldPoint world(Actor actor)
    {
        return actor == null || !realWorld(actor.getWorldView()) ? null : actor.getWorldLocation();
    }

    /** Where an object stands in the real world, to find it again; null inside an instance or on a boat. */
    public WorldPoint world(TileObject object)
    {
        return object == null || !realWorld(object.getWorldView()) ? null : object.getWorldLocation();
    }

    /** The main scene, loaded from the world itself: not a boat's deck, and not an instance's copies. */
    private static boolean realWorld(WorldView view)
    {
        Scene scene = view == null ? null : view.getScene();
        return scene != null && view.isTopLevel() && !scene.isInstance();
    }

    /** The chunk a menu option points at: its NPC, or its object's or ground item's tile. */
    public CanonicalChunk menuTarget(MenuEntry entry)
    {
        if (entry == null) return null;
        NPC npc = entry.getNpc();
        if (npc != null) return actor(npc);
        return hasSceneTile(entry.getType())
            ? sceneTile(entry.getWorldViewId(), entry.getParam0(), entry.getParam1())
            : null;
    }

    /** A scene tile in a world view, as object and ground-item menu entries give it. */
    public CanonicalChunk sceneTile(int worldViewId, int sceneX, int sceneY)
    {
        WorldView view = client.getWorldView(worldViewId);
        if (view == null
            || sceneX < 0 || sceneY < 0 || sceneX >= view.getSizeX() || sceneY >= view.getSizeY())
        {
            return null;
        }
        return locate(view, LocalPoint.fromScene(sceneX, sceneY, view));
    }

    private CanonicalChunk locate(WorldView view, LocalPoint point)
    {
        if (view == null || point == null) return null;
        if (!view.isTopLevel())
        {
            // A boat's deck is a world view of its own, floating on the main one.
            WorldEntity boat = shipOf(view);
            if (boat == null) return null;
            point = boat.transformToMainWorld(point);
            view = client.getTopLevelWorldView();
            if (point == null || view == null) return null;
        }
        Scene scene = view.getScene();
        if (scene == null) return null;
        int plane = view.getPlane();
        if (scene.isInstance() && !hasTemplate(scene, point, plane)) return null;
        WorldPoint world = WorldPoint.fromLocalInstance(scene, point, plane);
        return world == null ? null : WorldChunks.of(world);
    }

    /**
     * RuneLite decodes a missing template (-1), or a zone outside the grid,
     * into a far-off tile rather than failing, so check before asking.
     */
    private static boolean hasTemplate(Scene scene, LocalPoint point, int plane)
    {
        int zoneX = point.getSceneX() / ZONE_TILES;
        int zoneY = point.getSceneY() / ZONE_TILES;
        if (zoneX < 0 || zoneY < 0 || zoneX >= INSTANCE_ZONES || zoneY >= INSTANCE_ZONES) return false;
        int[][][] templates = scene.getInstanceTemplateChunks();
        return templates != null && plane >= 0 && plane < templates.length
            && templates[plane] != null && zoneX < templates[plane].length
            && templates[plane][zoneX] != null && zoneY < templates[plane][zoneX].length
            && templates[plane][zoneX][zoneY] != NO_TEMPLATE;
    }

    /** The ship whose deck is this world view, among the main view's world entities. */
    private WorldEntity shipOf(WorldView deck)
    {
        WorldView main = client.getTopLevelWorldView();
        if (main == null || main.worldEntities() == null) return null;
        WorldEntity indexed = main.worldEntities().byIndex(deck.getId());
        if (indexed != null && indexed.getWorldView() == deck) return indexed;
        for (WorldEntity entity : main.worldEntities())
        {
            if (entity != null && entity.getWorldView() == deck) return entity;
        }
        return null;
    }

    private static boolean hasSceneTile(MenuAction action)
    {
        if (action == null) return false;
        switch (action)
        {
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
            case GROUND_ITEM_FIRST_OPTION:
            case GROUND_ITEM_SECOND_OPTION:
            case GROUND_ITEM_THIRD_OPTION:
            case GROUND_ITEM_FOURTH_OPTION:
            case GROUND_ITEM_FIFTH_OPTION:
                return true;
            default:
                return false;
        }
    }
}
